from core.models import CustomerDebtPayment


class DebtPaymentSourceFieldTest(TestCase):
    """K1: CustomerDebtPayment.source defaults to 'bar' and accepts 'kitchen'."""

    def setUp(self):
        self.biz = Business.objects.create(name='K1 Biz')
        store = Store.objects.create(business=self.biz, name='Bar')
        self.customer = Customer.objects.create(business=self.biz, name='Kamau')
        self.user = User.objects.create_user(username='k1_owner', password='x')
        UserProfile.objects.create(user=self.user, business=self.biz, role='owner')

    def test_source_defaults_to_bar(self):
        pay = CustomerDebtPayment.objects.create(
            business=self.biz, customer=self.customer, amount_paid=Decimal('100'),
        )
        self.assertEqual(pay.source, 'bar')

    def test_source_accepts_kitchen(self):
        pay = CustomerDebtPayment.objects.create(
            business=self.biz, customer=self.customer, amount_paid=Decimal('200'),
            source='kitchen',
        )
        self.assertEqual(pay.source, 'kitchen')

    def test_filter_by_source_partitions_ledger(self):
        CustomerDebtPayment.objects.create(
            business=self.biz, customer=self.customer, amount_paid=Decimal('300'), source='bar',
        )
        CustomerDebtPayment.objects.create(
            business=self.biz, customer=self.customer, amount_paid=Decimal('150'), source='kitchen',
        )
        bar_total = CustomerDebtPayment.objects.filter(
            business=self.biz, source='bar'
        ).aggregate(t=__import__('django.db.models', fromlist=['Sum']).Sum('amount_paid'))['t']
        kitchen_total = CustomerDebtPayment.objects.filter(
            business=self.biz, source='kitchen'
        ).aggregate(t=__import__('django.db.models', fromlist=['Sum']).Sum('amount_paid'))['t']
        self.assertEqual(bar_total, Decimal('300'))
        self.assertEqual(kitchen_total, Decimal('150'))


class DebtScopeHelperTest(TestCase):
    """K1: _debt_scope() returns correct scope based on staff role and business kitchen flag."""

    def _make_biz(self, has_kitchen=True):
        biz = Business.objects.create(name=f'K1 Scope Biz {has_kitchen}')
        biz.has_kitchen = has_kitchen
        biz.save()
        return biz

    def test_owner_gets_all_scope(self):
        from core.debt_views import _debt_scope
        biz = self._make_biz(has_kitchen=True)
        owner_user = User.objects.create_user(username='k1_scope_owner', password='x')
        profile = UserProfile.objects.create(user=owner_user, business=biz, role='owner')
        self.assertEqual(_debt_scope(profile, biz), 'all')

    def test_kitchen_staff_gets_kitchen_scope(self):
        from core.debt_views import _debt_scope
        biz = self._make_biz(has_kitchen=True)
        staff_user = User.objects.create_user(username='k1_kitch_staff', password='x')
        profile = UserProfile.objects.create(
            user=staff_user, business=biz, role='kitchen',
            can_access_bar=False, can_access_kitchen=True,
        )
        self.assertEqual(_debt_scope(profile, biz), 'kitchen')

    def test_no_kitchen_business_gets_all_scope(self):
        from core.debt_views import _debt_scope
        biz = self._make_biz(has_kitchen=False)
        staff_user = User.objects.create_user(username='k1_nokit_staff', password='x')
        profile = UserProfile.objects.create(user=staff_user, business=biz, role='staff')
        self.assertEqual(_debt_scope(profile, biz), 'all')

    def test_waitress_default_gets_bar_scope(self):
        """2026-08-10 (Roy — waitress debt-tracker access): a plain waitress
        (bar-only by role default, no cross-access flag) sees the bar
        sub-ledger, matching _station_scope()'s own default for her role."""
        from core.debt_views import _debt_scope
        biz = self._make_biz(has_kitchen=True)
        user = User.objects.create_user(username='k1_waitress_bar', password='x')
        profile = UserProfile.objects.create(user=user, business=biz, role='waitress')
        self.assertEqual(_debt_scope(profile, biz), 'bar')

    def test_waitress_with_kitchen_access_gets_all_scope(self):
        """The bug this refactor fixes: the OLD formula gave a waitress
        granted can_access_kitchen=True (she serves both stations, e.g.
        Sarah Mueni's "BAR & KITCHEN" shifts) a 'kitchen'-only scope,
        incorrectly hiding her own bar debts — can_access_bar is never set
        for a waitress (her bar access is implicit via role, exactly like
        _station_scope() already treats it), so the old can_access_bar-AND-
        can_access_kitchen 'all' check could never fire for her."""
        from core.debt_views import _debt_scope
        biz = self._make_biz(has_kitchen=True)
        user = User.objects.create_user(username='k1_waitress_both', password='x')
        profile = UserProfile.objects.create(
            user=user, business=biz, role='waitress', can_access_kitchen=True,
        )
        self.assertEqual(_debt_scope(profile, biz), 'all')

    def test_bar_staff_with_kitchen_access_gets_all_scope(self):
        """The same bug, not waitress-specific: ordinary bar/general staff
        (role='staff') granted cross-station kitchen access used to also
        fall into 'kitchen'-only scope for the identical reason."""
        from core.debt_views import _debt_scope
        biz = self._make_biz(has_kitchen=True)
        user = User.objects.create_user(username='k1_barstaff_both', password='x')
        profile = UserProfile.objects.create(
            user=user, business=biz, role='staff', can_access_kitchen=True,
        )
        self.assertEqual(_debt_scope(profile, biz), 'all')

    def test_kitchen_staff_with_bar_access_gets_all_scope(self):
        """The mirror direction: a kitchen-role staffer correctly granted
        can_access_bar=True (per that field's own documented purpose —
        "Grant if they also serve bar customers") used to still get
        'kitchen'-only scope, since the old formula also required
        can_access_kitchen=True, never set for kitchen-role staff whose
        own kitchen access is implicit via role."""
        from core.debt_views import _debt_scope
        biz = self._make_biz(has_kitchen=True)
        user = User.objects.create_user(username='k1_kitchstaff_bar', password='x')
        profile = UserProfile.objects.create(
            user=user, business=biz, role='kitchen', can_access_bar=True,
        )
        self.assertEqual(_debt_scope(profile, biz), 'all')

    def test_manager_gets_all_scope(self):
        from core.debt_views import _debt_scope
        biz = self._make_biz(has_kitchen=True)
        user = User.objects.create_user(username='k1_manager', password='x')
        profile = UserProfile.objects.create(user=user, business=biz, role='manager')
        self.assertEqual(_debt_scope(profile, biz), 'all')


class WaitressDebtTrackerAccessTest(TestCase):
    """2026-08-10 live request (Roy): the waitress should be able to VIEW
    debts and RECORD PAYMENTS on them, but never GIVE OUT (issue) new
    debt — that stays counter-staff/manager/owner only.

    Investigation found the backend already permitted this: debt_dashboard/
    customer_debt_profile/record_debt_payment are gated by @login_required
    only, no role restriction, and "give out debt" was ALREADY comprehensively
    blocked for waitress across every checkout surface (quick_sell, bar/
    kitchen checkout credit + partial-debt, convert_tab_to_debt,
    bulk_convert_tabs_to_debt — all found with an explicit `role ==
    'waitress'` guard, 2026-08-06). The only real gap was a missing navbar
    link. This locks in the actual end-to-end flow works, and that the
    give-out-debt guards remain intact."""

    def setUp(self):
        self.biz = Business.objects.create(name='Waitress Debt Access Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.owner = User.objects.create_user(username='wda_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.waitress = User.objects.create_user(username='wda_waitress', password='x')
        UserProfile.objects.create(user=self.waitress, business=self.biz, role='waitress')
        self.customer = Customer.objects.create(business=self.biz, name='Wanjiru')
        self.item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='Beer',
            material_no='WDA-01', unit='Bottle', selling_price=Decimal('200'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            payment_method='credit', recipient='Wanjiru', sale_amount=Decimal('200'),
            recorded_by=self.owner,
        )
        Shift.objects.create(
            business=self.biz, store=self.bar_store, staff=self.waitress,
            status='OPEN', station='bar', opening_float=Decimal('0'),
        )
        self.client.force_login(self.waitress)

    def test_waitress_navbar_shows_debt_tracker_link(self):
        resp = self.client.get('/')
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, '/debt/')

    def test_waitress_can_view_debt_dashboard(self):
        resp = self.client.get('/debt/')
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, 'Wanjiru')

    def test_waitress_can_view_customer_profile(self):
        resp = self.client.get(f'/debt/{self.customer.id}/')
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, 'Record Payment')

    def test_waitress_can_record_a_payment(self):
        import uuid
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'cash',
            'idempotency_token': str(uuid.uuid4()),
        })
        self.assertEqual(resp.status_code, 302)
        self.assertTrue(
            CustomerDebtPayment.objects.filter(customer=self.customer, amount_paid=Decimal('200')).exists()
        )

    def test_waitress_still_cannot_issue_new_credit_via_quick_sell(self):
        resp = self.client.post('/quick-sell/', {
            'cart': json.dumps([{'id': self.item.id, 'qty': 1}]),
            'payment_method': 'credit', 'credit_recipient': 'New Debtor',
        })
        self.assertEqual(resp.status_code, 302)
        # Blocked outright — never creates a new credit sale for her.
        self.assertFalse(
            Transaction.objects.filter(
                business=self.biz, recipient='New Debtor', payment_method='credit',
            ).exists()
        )

    def test_waitress_still_cannot_convert_tab_to_debt(self):
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Tab Debtor', status='OPEN',
            source='bar', tab_pin='1234', tab_receipt_token='wda-tab-token',
        )
        resp = self.client.post(f'/bar/tabs/{tab.id}/debt/')
        self.assertEqual(resp.status_code, 403)


class RecordDebtPaymentDebtSourceRequiredTest(TestCase):
    """2026-08-06 live report (Monsoon Inn) — the ledger-selector radio used
    to hard-code "Bar" pre-checked, and the backend's own default
    (request.POST.get('debt_source', 'bar')) silently converted a missing
    choice into 'bar' too — meaning the "please specify" validation could
    never actually fire, and a manager who forgot to switch the radio would
    silently record a genuine kitchen payment against the bar sub-ledger.
    Fixed: only auto-resolve when unambiguous (no kitchen module, or only
    one ledger actually has anything owed); otherwise require an explicit
    debt_source and error out instead of defaulting to 'bar'.
    """

    def setUp(self):
        self.biz = Business.objects.create(name='Debt Source Required Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='dsr_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.customer = Customer.objects.create(business=self.biz, name='Dual Ledger Customer')

        self.bar_item = Item.objects.create(
            business=self.biz, store=self.bar_store, material_no='DSR-1',
            description='Keg Gold', unit='cup', selling_price=Decimal('80'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, material_no='DSR-2',
            description='Chipo', unit='plate', selling_price=Decimal('100'),
        )

    def _credit_txn(self, item, amount):
        Transaction.objects.create(
            business=self.biz, item=item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method='credit',
            recipient=self.customer.name,
        )

    def test_missing_debt_source_errors_when_both_ledgers_owe(self):
        import uuid
        """Both ledgers have real debt — omitting debt_source must be
        rejected outright, never silently recorded as 'bar' (the exact
        Monsoon Inn failure mode: a kitchen payment landing on the bar
        ledger because nobody explicitly switched the radio)."""
        self._credit_txn(self.bar_item, Decimal('80'))
        self._credit_txn(self.kitchen_item, Decimal('100'))
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '50', 'payment_method': 'cash',
            'idempotency_token': f'dsr-{uuid.uuid4()}',
            # debt_source deliberately omitted
        })
        self.assertEqual(resp.status_code, 302)
        self.assertEqual(CustomerDebtPayment.objects.filter(customer=self.customer).count(), 0)

    def test_missing_debt_source_auto_resolves_when_only_kitchen_owes(self):
        import uuid
        """Only kitchen has any debt — the payment can unambiguously be
        auto-tagged 'kitchen' even with no explicit radio choice."""
        self._credit_txn(self.kitchen_item, Decimal('100'))
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '50', 'payment_method': 'cash',
            'idempotency_token': f'dsr-{uuid.uuid4()}',
        })
        self.assertEqual(resp.status_code, 302)
        pay = CustomerDebtPayment.objects.get(customer=self.customer)
        self.assertEqual(pay.source, 'kitchen')

    def test_missing_debt_source_auto_resolves_when_only_bar_owes(self):
        import uuid
        self._credit_txn(self.bar_item, Decimal('80'))
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '30', 'payment_method': 'cash',
            'idempotency_token': f'dsr-{uuid.uuid4()}',
        })
        self.assertEqual(resp.status_code, 302)
        pay = CustomerDebtPayment.objects.get(customer=self.customer)
        self.assertEqual(pay.source, 'bar')

    def test_explicit_debt_source_still_works(self):
        import uuid
        self._credit_txn(self.bar_item, Decimal('80'))
        self._credit_txn(self.kitchen_item, Decimal('100'))
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '50', 'payment_method': 'cash', 'debt_source': 'kitchen',
            'idempotency_token': f'dsr-{uuid.uuid4()}',
        })
        self.assertEqual(resp.status_code, 302)
        pay = CustomerDebtPayment.objects.get(customer=self.customer)
        self.assertEqual(pay.source, 'kitchen')

    def test_no_kitchen_business_still_defaults_to_bar_with_no_source(self):
        import uuid
        biz2 = Business.objects.create(name='No Kitchen Debt Biz', has_kitchen=False)
        store2 = Store.objects.create(business=biz2, name='Shop')
        owner2 = User.objects.create_user(username='dsr_owner2', password='x')
        UserProfile.objects.create(user=owner2, business=biz2, role='owner')
        cust2 = Customer.objects.create(business=biz2, name='Simple Customer')
        item2 = Item.objects.create(
            business=biz2, store=store2, material_no='DSR-3',
            description='Sukari', unit='kg', selling_price=Decimal('100'),
        )
        Transaction.objects.create(
            business=biz2, item=item2, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='credit',
            recipient=cust2.name,
        )
        self.client.force_login(owner2)
        resp = self.client.post(f'/debt/{cust2.id}/payment/', {
            'amount_paid': '50', 'payment_method': 'cash',
            'idempotency_token': f'dsr-{uuid.uuid4()}',
        })
        self.assertEqual(resp.status_code, 302)
        pay = CustomerDebtPayment.objects.get(customer=cust2)
        self.assertEqual(pay.source, 'bar')


