class BackfillTabTokensCommandTest(TestCase):
    """K8-Task2: backfill_tab_tokens fills blank tab_receipt_token/tab_pin on OPEN tabs only."""

    def setUp(self):
        self.biz = Business.objects.create(name='K8 Backfill Biz')

    def test_open_tab_with_blank_token_and_pin_gets_backfilled(self):
        from django.core.management import call_command
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Old Patron', status='OPEN',
            tab_receipt_token='', tab_pin='',
        )
        call_command('backfill_tab_tokens')
        tab.refresh_from_db()
        self.assertTrue(tab.tab_receipt_token)
        self.assertRegex(tab.tab_pin, r'^\d{4}$')

    def test_already_populated_tab_is_left_untouched(self):
        from django.core.management import call_command
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Fresh Patron', status='OPEN',
            tab_receipt_token='already-set-token', tab_pin='1234',
        )
        call_command('backfill_tab_tokens')
        tab.refresh_from_db()
        self.assertEqual(tab.tab_receipt_token, 'already-set-token')
        self.assertEqual(tab.tab_pin, '1234')

    def test_settled_tab_is_not_touched(self):
        from django.core.management import call_command
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Closed Patron', status='SETTLED',
            tab_receipt_token='', tab_pin='',
        )
        call_command('backfill_tab_tokens')
        tab.refresh_from_db()
        self.assertEqual(tab.tab_receipt_token, '')
        self.assertEqual(tab.tab_pin, '')

    def test_backfilled_pins_unique_within_business(self):
        from django.core.management import call_command
        tabs = [
            BarTab.objects.create(
                business=self.biz, customer_name=f'Patron {i}', status='OPEN',
                tab_receipt_token='', tab_pin='',
            )
            for i in range(5)
        ]
        call_command('backfill_tab_tokens')
        pins = [BarTab.objects.get(id=t.id).tab_pin for t in tabs]
        self.assertEqual(len(pins), len(set(pins)), 'PINs backfilled for the same business must be unique')


class FixStaffProfilesCommandTest(TestCase):
    """2026-08-11: fix_staff_profiles runs on every deploy's release phase
    and previously looped over every platform User issuing one extra query
    per user to find the ones missing a profile (N+1). Rewritten to a
    single `userprofile__isnull=True` query — this locks in that the
    rewrite still does exactly the same job."""

    def setUp(self):
        self.biz = Business.objects.create(name='Fix Staff Profiles Biz')
        self.owner_user = User.objects.create_user(username='fsp_owner', password='x')
        UserProfile.objects.create(user=self.owner_user, business=self.biz, role='owner')

    def test_orphaned_user_gets_a_staff_profile_on_the_existing_business(self):
        from django.core.management import call_command
        orphan = User.objects.create_user(username='fsp_orphan', password='x')
        call_command('fix_staff_profiles')
        orphan.refresh_from_db()
        self.assertTrue(hasattr(orphan, 'userprofile'))
        self.assertEqual(orphan.userprofile.business_id, self.biz.id)
        self.assertEqual(orphan.userprofile.role, 'staff')

    def test_user_with_existing_profile_is_left_untouched(self):
        from django.core.management import call_command
        other_biz = Business.objects.create(name='Other Biz')
        staff = User.objects.create_user(username='fsp_staff', password='x')
        UserProfile.objects.create(user=staff, business=other_biz, role='staff')
        call_command('fix_staff_profiles')
        staff.refresh_from_db()
        self.assertEqual(staff.userprofile.business_id, other_biz.id)

    def test_superuser_with_no_profile_is_skipped(self):
        from django.core.management import call_command
        su = User.objects.create_superuser(username='fsp_super', password='x', email='x@x.com')
        call_command('fix_staff_profiles')
        su.refresh_from_db()
        self.assertFalse(hasattr(su, 'userprofile'))

    def test_no_orphans_is_a_clean_no_op(self):
        from django.core.management import call_command
        call_command('fix_staff_profiles')  # must not raise with nothing to do


class BarTabNewCredentialsTest(TestCase):
    """Fix (2026-07-15, post-K8): BarTab.new_credentials is the single source of truth
    for tab_receipt_token/tab_pin generation, used by bar board, kitchen, and Quick Sell
    tab creation alike. Root cause of the live bug: Quick Sell's tab creation
    (core/views.py) never set these fields at all, so every QS tab was invisible to the
    wall-QR PIN lookup (BillScan) until manually backfilled."""

    def setUp(self):
        self.biz = Business.objects.create(name='Credentials Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='cred_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Cred Test Beer',
            material_no='CRED-01', unit='pcs', selling_price=Decimal('50'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('10'),
        )

    def test_generates_nonblank_token_and_four_digit_pin(self):
        token, pin = BarTab.new_credentials(self.biz)
        self.assertTrue(token)
        self.assertRegex(pin, r'^\d{4}$')

    def test_pin_never_collides_with_an_open_tab_in_the_same_business(self):
        # Force the entire PIN space open except one value, then confirm new_credentials
        # avoids every existing open tab's PIN.
        taken = set()
        for i in range(20):
            _token, pin = BarTab.new_credentials(self.biz)
            self.assertNotIn(pin, taken)
            taken.add(pin)
            BarTab.objects.create(
                business=self.biz, customer_name=f'Patron {i}', status='OPEN',
                tab_receipt_token=_token, tab_pin=pin,
            )

    def test_quick_sell_tab_sale_sets_pin_and_token(self):
        """The actual regression: Quick Sell's 'tab' payment method must produce a
        BarTab with a usable PIN/token, exactly like bar board and kitchen do."""
        import json
        self.client.force_login(self.owner)
        cart = json.dumps([{'id': self.item.id, 'qty': 2, 'price': 50}])
        resp = self.client.post('/quick-sell/', {
            'cart': cart,
            'payment_method': 'tab',
            'recipient': 'QS Tab Patron',
        })
        self.assertNotEqual(resp.status_code, 500)
        tab = BarTab.objects.filter(
            business=self.biz, customer_name='QS Tab Patron', source='qs',
        ).first()
        self.assertIsNotNone(tab, 'Quick Sell tab sale must create a BarTab')
        self.assertTrue(tab.tab_receipt_token, 'QS tab must get a receipt token like bar/kitchen tabs')
        self.assertRegex(tab.tab_pin, r'^\d{4}$', 'QS tab must get a 4-digit PIN like bar/kitchen tabs')


class CheckoutIdempotencyTest(TestCase):
    """Fix (2026-07-15): Roy saw a Quick Sell tab entry double (KES 1000 -> KES 2000) in
    the tabs drawer after a possible double-tap / slow-network resubmit. Client-side
    guards (button disable, JS flags) only stop a second click on the SAME live page —
    they do nothing against a real duplicate request reaching the server. This locks in
    the server-side backstop (core/idempotency.py claim_checkout_token): the same
    idempotency_token from the same business can only create a sale once."""

    def setUp(self):
        self.biz = Business.objects.create(name='Idem Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='idem_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Idem Test Beer',
            material_no='IDEM-01', unit='pcs', selling_price=Decimal('1000'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('10'),
        )
        self.client.force_login(self.owner)

    def test_duplicate_token_does_not_double_book_the_sale(self):
        import json
        cart = json.dumps([{'id': self.item.id, 'qty': 1, 'price': 1000}])
        payload = {
            'cart': cart, 'payment_method': 'tab', 'recipient': 'Idem Tab Patron',
            'idempotency_token': 'same-token-123',
        }
        self.client.post('/quick-sell/', payload)
        self.client.post('/quick-sell/', payload)  # simulated resubmit: identical token
        tab = BarTab.objects.filter(business=self.biz, customer_name='Idem Tab Patron').first()
        self.assertIsNotNone(tab)
        self.assertEqual(tab.entries.count(), 1, 'Duplicate token must not create a second entry')
        self.assertEqual(tab.unpaid_total(), Decimal('1000'), 'Duplicate submission must not double the amount')

    def test_different_tokens_are_independent_real_sales(self):
        """Two genuinely separate sales (different tokens) must both go through —
        the guard must not accidentally suppress legitimate repeat purchases."""
        import json
        cart = json.dumps([{'id': self.item.id, 'qty': 1, 'price': 1000}])
        self.client.post('/quick-sell/', {
            'cart': cart, 'payment_method': 'tab', 'recipient': 'Repeat Patron',
            'idempotency_token': 'token-A',
        })
        self.client.post('/quick-sell/', {
            'cart': cart, 'payment_method': 'tab', 'recipient': 'Repeat Patron',
            'idempotency_token': 'token-B',
        })
        tab = BarTab.objects.filter(business=self.biz, customer_name='Repeat Patron').first()
        self.assertEqual(tab.entries.count(), 2, 'Two distinct tokens must both be processed as real sales')


class CashPaymentRequestTest(TestCase):
    """New feature (2026-07-15): customer taps "Lipa Cash" on their live receipt page.
    No money moves — staff get notified (in-app + SMS) and a badge flag is set on the
    tab until staff actually settles it at the counter through the normal flow."""

    def setUp(self):
        # find_tab_search's rate-limit cache key is business_id:ip, and the
        # test cache backend isn't reset between tests — only the DB rolls
        # back. SQLite reuses the lowest free rowid after a rollback, so
        # another test class's Business can easily land on the same id this
        # one gets, silently inheriting its leftover rate-limit count.
        from django.core.cache import cache as _cache
        _cache.clear()
        self.biz = Business.objects.create(name='Cash Request Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='cashreq_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Cash Req Beer',
            material_no='CASHREQ-01', unit='pcs', selling_price=Decimal('200'),
        )
        self.tab = BarTab.objects.create(
            business=self.biz, customer_name='Cash Req Patron', status='OPEN',
            served_by=self.owner,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('200'), payment_method='credit',
        )
        self.entry = BarTabEntry.objects.create(
            tab=self.tab, transaction=txn, description='Cash Req Beer', amount=Decimal('200'),
        )
        self.receipt = Receipt.issue(
            business=self.biz, lines=[{'name': 'Cash Req Beer', 'qty': 1, 'subtotal': 200}],
            payment_method='tab', customer_name='Cash Req Patron',
            meta={'tab_id': self.tab.id},
        )

    def test_cash_request_sets_flag_and_notifies_without_creating_a_payment(self):
        import json
        resp = self.client.post(
            f'/r/{self.receipt.token}/pay/',
            data=json.dumps({'type': 'cash', 'entry_ids': [self.entry.id]}),
            content_type='application/json',
        )
        self.assertEqual(resp.status_code, 200)
        self.assertTrue(resp.json().get('ok'))
        self.tab.refresh_from_db()
        self.assertIsNotNone(self.tab.cash_requested_at)
        self.entry.refresh_from_db()
        self.assertFalse(self.entry.is_paid, 'A cash request must not mark the entry paid')
        self.assertFalse(
            Payment.objects.filter(business=self.biz).exists(),
            'No Payment/STK should be created for a cash request',
        )
        self.assertTrue(Notification.objects.filter(user=self.owner).exists())

    def test_settle_tab_clears_cash_requested_flag(self):
        self.tab.cash_requested_at = timezone.now()
        self.tab.save(update_fields=['cash_requested_at'])
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{self.tab.id}/settle/', {'payment_method': 'cash'})
        self.tab.refresh_from_db()
        self.assertIsNone(self.tab.cash_requested_at)

    def test_tabs_list_exposes_cash_requested_flag(self):
        self.tab.cash_requested_at = timezone.now()
        self.tab.save(update_fields=['cash_requested_at'])
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/tabs/')
        data = resp.json()
        tab_row = next((t for t in data['tabs'] if t['id'] == self.tab.id), None)
        self.assertIsNotNone(tab_row)
        self.assertTrue(tab_row['cash_requested'])

    def test_find_tab_search_pin_redirects_to_receipt_when_available(self):
        self.tab.tab_pin = '4321'
        self.tab.tab_receipt_token = 'legacy-token-abc'
        self.tab.save(update_fields=['tab_pin', 'tab_receipt_token'])
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': '4321'})
        data = resp.json()
        self.assertEqual(data.get('redirect'), f'/r/{self.receipt.token}/')


class FindTabSearchDedupTest(TestCase):
    """2026-07-25 live report: Roy has orders on both Bar Board and Bar
    Orders/Quick Sell under the same name — scanning the wall QR and
    searching "Roy" showed TWO result rows, confusing, even though the
    cross-counter receipt-linking system (resolve_master_receipt) already
    consolidates both tabs into ONE shared receipt. Root cause: find_tab_
    search's name-search loop added one result PER matching BarTab row with
    no de-duplication, so two already-linked tabs still produced two
    identical-destination rows."""

    def setUp(self):
        from django.core.cache import cache as _cache
        _cache.clear()
        self.biz = Business.objects.create(name='Find Tab Dedup Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.qs_store = Store.objects.create(business=self.biz, name='General')
        self.owner = User.objects.create_user(username='ftd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')

    def _make_tab_with_receipt(self, name, source, store, meta_tab_id=None, linked_ids=None):
        tab = BarTab.objects.create(
            business=self.biz, customer_name=name, status='OPEN', source=source, store=store,
        )
        tab.tab_receipt_token = f'tok-{tab.id}'
        tab.tab_pin = str(1000 + tab.id)
        tab.save(update_fields=['tab_receipt_token', 'tab_pin'])
        meta = {}
        if meta_tab_id is not None:
            meta['tab_id'] = meta_tab_id
        if linked_ids is not None:
            meta['linked_tab_ids'] = linked_ids
        rcpt = Receipt.issue(
            business=self.biz, lines=[{'name': 'Item', 'qty': 1, 'subtotal': 100}],
            payment_method='tab', customer_name=name, meta=meta,
        )
        return tab, rcpt

    def test_two_linked_tabs_same_customer_produce_one_search_result(self):
        # Two real BarTab rows for the same customer, on different counters
        # — the exact shape of Roy's report. _resolve_tab_public_url()'s own
        # cross-counter lookup (via _safe_linked_query) is separately tested
        # in CrossCounterReceiptLinkingTest and has a documented, accepted
        # SQLite-only limitation (the linked_tab_ids `contains` lookup only
        # works on Postgres — production is unaffected, see core/tab_
        # receipts.py's Known Issues note); mocking it here isolates what
        # THIS fix actually changed — the dedup-by-resolved-URL step in
        # find_tab_search's name-search loop — from that unrelated,
        # already-documented constraint.
        from unittest.mock import patch
        bar_tab, bar_rcpt = self._make_tab_with_receipt('Roy', 'bar', self.bar_store)
        bar_rcpt.meta = {'tab_id': bar_tab.id}
        bar_rcpt.save(update_fields=['meta'])
        qs_tab = BarTab.objects.create(
            business=self.biz, customer_name='Roy', status='OPEN', source='qs', store=self.qs_store,
        )
        same_url = f'/r/{bar_rcpt.token}/'
        with patch('core.keg_views._resolve_tab_public_url', return_value=same_url):
            resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': 'Roy'})
        data = resp.json()
        self.assertEqual(len(data['tabs']), 1, 'Two tabs resolving to the same receipt must show as ONE result')
        self.assertEqual(data['tabs'][0]['url'], same_url)

    def test_two_genuinely_separate_receipts_both_still_shown(self):
        # Sanity check: dedup must not over-collapse two customers whose
        # names both match the search query but have real, separate bills.
        _tab1, rcpt1 = self._make_tab_with_receipt('Roy', 'bar', self.bar_store)
        rcpt1.meta = {'tab_id': _tab1.id}
        rcpt1.save(update_fields=['meta'])
        _tab2, rcpt2 = self._make_tab_with_receipt('Royce', 'qs', self.qs_store)
        rcpt2.meta = {'tab_id': _tab2.id}
        rcpt2.save(update_fields=['meta'])

        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': 'Roy'})
        data = resp.json()
        self.assertEqual(len(data['tabs']), 2)
        urls = {t['url'] for t in data['tabs']}
        self.assertEqual(urls, {f'/r/{rcpt1.token}/', f'/r/{rcpt2.token}/'})


class FindTabDebtStateTest(TestCase):
    """Bug found auditing BillScan end-to-end (2026-07-22): find_tab_search
    only ever matched status='OPEN' tabs. A tab converted to debt (shift-
    close auto-convert, or manual "Geuza Deni") flips to status='SETTLED'
    but keeps its PIN and its unpaid balance — the customer could no longer
    find their own bill by scanning the wall QR and typing that same still-
    valid-looking PIN. A fully-paid SETTLED tab, or a VOID tab, must stay
    unfindable — nothing left to view or pay."""

    def setUp(self):
        # See CashPaymentRequestTest.setUp for why this matters — the
        # rate-limit cache for find_tab_search isn't reset between tests.
        from django.core.cache import cache as _cache
        _cache.clear()
        self.biz = Business.objects.create(name='Find Tab Debt Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='findtabdebt_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Find Tab Debt Beer',
            material_no='FINDTABDEBT-01', unit='pcs', selling_price=Decimal('200'),
        )

    def _make_tab(self, name, pin, paid):
        tab = BarTab.objects.create(
            business=self.biz, customer_name=name, status='SETTLED',
            tab_pin=pin, tab_receipt_token=f'token-{pin}', served_by=self.owner,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('200'),
            payment_method='credit' if not paid else 'cash', recipient=name,
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Find Tab Debt Beer',
            amount=Decimal('200'), is_paid=paid,
        )
        Receipt.issue(
            business=self.biz, lines=[{'name': 'Find Tab Debt Beer', 'qty': 1, 'subtotal': 200}],
            payment_method='tab', customer_name=name, meta={'tab_id': tab.id},
        )
        return tab

    def test_debt_converted_tab_still_found_by_pin(self):
        tab = self._make_tab('Debt Patron', '7711', paid=False)
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': '7711'})
        data = resp.json()
        rcpt = Receipt.objects.get(meta__tab_id=tab.id)
        self.assertEqual(data.get('redirect'), f'/r/{rcpt.token}/')

    def test_debt_converted_tab_still_found_by_name(self):
        self._make_tab('Debt Patron Two', '7722', paid=False)
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': 'Debt Patron Two'})
        data = resp.json()
        self.assertEqual(len(data.get('tabs', [])), 1)
        self.assertEqual(data['tabs'][0]['name'], 'Debt Patron Two')

    def test_fully_paid_settled_tab_now_found_by_pin(self):
        """2026-08-09 live request (Roy) — a customer whose tab is already
        fully paid off had no way to find their own receipt again. PIN
        search (unlike name search) was widened to reach a customer's full
        history — see _findable_tabs_qs_for_pin's own docstring for why
        that's safe (a PIN is a private credential, not a guessable name)."""
        tab = self._make_tab('Paid Patron', '7733', paid=True)
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': '7733'})
        data = resp.json()
        rcpt = Receipt.objects.get(meta__tab_id=tab.id)
        self.assertEqual(data.get('redirect'), f'/r/{rcpt.token}/')
        self.assertNotIn('pin_not_found', data)

    def test_recently_paid_settled_tab_now_found_by_name(self):
        """2026-08-09, same-day follow-up (Roy): "customers just want to
        search their names... that is just it" — a recently-paid tab
        (opened within FINDABLE_BY_NAME_DAYS) must now be findable by name
        too, not just PIN."""
        self._make_tab('Paid Name Patron', '7736', paid=True)
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': 'Paid Name Patron'})
        data = resp.json()
        self.assertEqual(len(data.get('tabs', [])), 1)
        self.assertEqual(data['tabs'][0]['name'], 'Paid Name Patron')

    def test_old_paid_settled_tab_ages_out_of_name_search(self):
        """The bounded middle ground: unlike PIN (no date bound at all),
        name search still ages out after FINDABLE_BY_NAME_DAYS — the
        mitigation that makes re-widening name search safe at all."""
        from core.keg_views import FINDABLE_BY_NAME_DAYS
        tab = self._make_tab('Old Paid Name Patron', '7737', paid=True)
        tab.opened_at = timezone.now() - timedelta(days=FINDABLE_BY_NAME_DAYS + 5)
        tab.save(update_fields=['opened_at'])
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': 'Old Paid Name Patron'})
        data = resp.json()
        self.assertEqual(data.get('tabs', []), [])

    def test_void_tab_not_found(self):
        tab = self._make_tab('Void Patron', '7744', paid=False)
        tab.status = 'VOID'
        tab.save(update_fields=['status'])
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': '7744'})
        data = resp.json()
        self.assertTrue(data.get('pin_not_found'))

    def test_open_tab_still_found(self):
        tab = self._make_tab('Open Patron', '7755', paid=False)
        tab.status = 'OPEN'
        tab.save(update_fields=['status'])
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': '7755'})
        data = resp.json()
        self.assertIn('redirect', data)
        self.assertNotIn('pin_not_found', data)

    def test_reused_pin_resolves_to_most_recent_match(self):
        """BarTab's PIN-uniqueness constraint only applies to OPEN rows, so
        an old, already-settled tab's PIN can legitimately be reused by a
        later, different tab. Once fully-paid tabs became PIN-findable, a
        naive .first() with no ordering would return an arbitrary one of
        several matches — .order_by('-opened_at') must prefer the newest."""
        older = self._make_tab('Old Owner Of 9001', '9001', paid=True)
        older.opened_at = timezone.now() - timedelta(days=10)
        older.save(update_fields=['opened_at'])
        newer = self._make_tab('New Owner Of 9001', '9001', paid=False)
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': '9001'})
        data = resp.json()
        newer_rcpt = Receipt.objects.get(meta__tab_id=newer.id)
        self.assertEqual(data.get('redirect'), f'/r/{newer_rcpt.token}/')


class FindTabSearchSplitRateLimitTest(TestCase):
    """2026-08-09 live report (Roy): a busy bar's shared WiFi/NAT means
    several genuinely different customers can search by name from the same
    public IP within a minute — they shouldn't have to fight each other (or
    an unrelated PIN lookup) for one shared rate-limit budget. PIN lookups
    keep a tighter budget since they now reach a customer's full history
    (see _findable_tabs_qs_for_pin) — a brute-force PIN guesser has a
    bigger payoff per successful guess than before."""

    def setUp(self):
        from django.core.cache import cache as _cache
        _cache.clear()
        self.biz = Business.objects.create(name='Split Rate Limit Biz')

    def test_pin_budget_exhausting_does_not_block_name_search(self):
        for _i in range(5):
            self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': '1234'})
        blocked = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': '1234'})
        self.assertEqual(blocked.status_code, 429)
        still_ok = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': 'Roy'})
        self.assertEqual(still_ok.status_code, 200)

    def test_name_budget_exhausting_does_not_block_pin_search(self):
        for _i in range(20):
            self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': 'Roy'})
        blocked = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': 'Roy'})
        self.assertEqual(blocked.status_code, 429)
        still_ok = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': '1234'})
        self.assertEqual(still_ok.status_code, 200)

    def test_name_search_limit_is_higher_than_pin(self):
        for _i in range(6):
            resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/', {'q': 'Bosco'})
        # 6 name-search calls must still succeed — the old shared 5/min
        # budget would have blocked the 6th one.
        self.assertEqual(resp.status_code, 200)


class ReceiptShowsTabPinTest(TestCase):
    """2026-08-09 live request (Roy): PIN search was widened to reach a
    customer's full history, but the PIN was never actually shown to the
    customer themselves — only to staff in the tabs drawer. Surfaced on the
    customer's own receipt page so they have something to note down and use
    for the widened lookup later."""

    def setUp(self):
        from django.core.cache import cache as _cache
        _cache.clear()
        self.biz = Business.objects.create(name='Receipt Pin Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='rcptpin_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Rcpt Pin Beer',
            material_no='RCPTPIN-01', unit='pcs', selling_price=Decimal('150'),
        )

    def test_tab_linked_receipt_shows_its_pin(self):
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Pin Customer', status='OPEN',
            tab_pin='4560', tab_receipt_token='rcptpin-tok', served_by=self.owner,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('150'),
            payment_method='credit', recipient='Pin Customer',
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Rcpt Pin Beer',
            amount=Decimal('150'), is_paid=False,
        )
        rcpt = Receipt.issue(
            business=self.biz, lines=[{'name': 'Rcpt Pin Beer', 'qty': 1, 'subtotal': 150}],
            payment_method='tab', customer_name='Pin Customer', meta={'tab_id': tab.id},
        )
        resp = self.client.get(f'/r/{rcpt.token}/')
        self.assertContains(resp, '4560')

    def test_direct_sale_receipt_with_no_tab_shows_no_pin_block(self):
        rcpt = Receipt.issue(
            business=self.biz, lines=[{'name': 'Rcpt Pin Beer', 'qty': 1, 'subtotal': 150}],
            payment_method='cash', customer_name='Walk-in',
        )
        resp = self.client.get(f'/r/{rcpt.token}/')
        self.assertNotContains(resp, 'PIN:')

    def test_tab_live_page_also_shows_pin(self):
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Bare Page Customer', status='OPEN',
            tab_pin='4561', tab_receipt_token='rcptpin-tok2', served_by=self.owner,
        )
        resp = self.client.get(f'/tab/{tab.tab_receipt_token}/')
        self.assertContains(resp, '4561')


class TabServedByLabelTest(TestCase):
    """2026-08-09 live request (Roy): "add a served by who in the tabs
    drawer against each tab to enhance accountability." BarTab.server_name
    is a free-text field meant only for a waitress with no login — for the
    common case (a real logged-in staff member), it was always blank, so
    the tabs drawer's existing "via {server_name}" line never actually
    showed anyone for most tabs. _tab_served_by_label() prefers the real
    served_by FK, falling back to server_name only when that's unset."""

    def setUp(self):
        self.biz = Business.objects.create(name='Served By Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='servedby_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(
            username='servedby_staff', password='x', first_name='Susan', last_name='Namayan',
        )
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Served By Beer',
            material_no='SVDBY-01', unit='pcs', selling_price=Decimal('100'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Served By Chipo',
            material_no='SVDBY-02', unit='pcs', selling_price=Decimal('100'),
        )

    def test_helper_prefers_served_by_over_server_name(self):
        from core.keg_views import _tab_served_by_label
        tab = BarTab.objects.create(
            business=self.biz, customer_name='X', status='OPEN',
            served_by=self.staff, server_name='Should Not Show',
        )
        self.assertEqual(_tab_served_by_label(tab), 'Susan Namayan')

    def test_helper_falls_back_to_server_name_when_no_login(self):
        from core.keg_views import _tab_served_by_label
        tab = BarTab.objects.create(
            business=self.biz, customer_name='X', status='OPEN',
            server_name='Waitress No Login',
        )
        self.assertEqual(_tab_served_by_label(tab), 'Waitress No Login')

    def test_helper_blank_when_neither_set(self):
        from core.keg_views import _tab_served_by_label
        tab = BarTab.objects.create(business=self.biz, customer_name='X', status='OPEN')
        self.assertEqual(_tab_served_by_label(tab), '')

    def test_bar_tabs_list_api_shows_real_staff_name(self):
        BarTab.objects.create(
            business=self.biz, customer_name='Bar Customer', status='OPEN',
            source='bar', served_by=self.staff,
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/tabs/')
        data = resp.json()
        self.assertEqual(len(data['tabs']), 1)
        self.assertEqual(data['tabs'][0]['server_name'], 'Susan Namayan')

    def test_kitchen_tabs_list_api_shows_real_staff_name(self):
        BarTab.objects.create(
            business=self.biz, customer_name='Kitchen Customer', status='OPEN',
            source='kitchen', served_by=self.staff,
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/kitchen/tabs/')
        data = resp.json()
        self.assertEqual(len(data['tabs']), 1)
        self.assertEqual(data['tabs'][0]['server_name'], 'Susan Namayan')

    def test_quick_sell_tabs_list_api_shows_real_staff_name(self):
        BarTab.objects.create(
            business=self.biz, customer_name='QS Customer', status='OPEN',
            source='qs', served_by=self.staff,
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/tabs/?ctx=qs')
        data = resp.json()
        self.assertEqual(len(data['tabs']), 1)
        self.assertEqual(data['tabs'][0]['server_name'], 'Susan Namayan')


class WallTabQrVisibilityTest(TestCase):
    """The Wall Tab QR card in Payment Settings was gated on
    biz_profile.modules.keg only — a kitchen-only business (has_kitchen=True,
    no bar/keg business type) can generate real BarTab rows via kitchen
    board's "Food Tab" checkout (source='kitchen') just like a bar can, but
    had no way to print the matching wall QR for their own counter."""

    def setUp(self):
        self.biz = Business.objects.create(name='Kitchen Only Biz', has_kitchen=True)
        self.owner = User.objects.create_user(username='kitchenonlyqr_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.client.force_login(self.owner)

    def test_kitchen_only_business_sees_wall_qr_card(self):
        # id="wallQrBox" only renders inside the gated card — unlike the
        # literal text "Wall Tab QR", which also appears in an unconditional
        # JS comment in extra_js and would false-positive either way.
        resp = self.client.get('/business/payment-settings/')
        self.assertIn(b'id="wallQrBox"', resp.content)

    def test_business_with_neither_module_does_not_see_wall_qr_card(self):
        self.biz.has_kitchen = False
        self.biz.save(update_fields=['has_kitchen'])
        resp = self.client.get('/business/payment-settings/')
        self.assertNotIn(b'id="wallQrBox"', resp.content)


class WallQrPrintPageTest(TestCase):
    """Standalone /stock/wall-qr/print/ page (2026-07-23, live report: printing
    the QR straight from payment_settings.html produced 4 blank pages then a
    tiny QR on the 5th — the visibility/absolute-position trick used there
    anchored the QR box to a positioned ancestor deep in a very long page
    instead of the page's top). The standalone page must render one clean
    page with nothing else on it."""

    def setUp(self):
        self.biz = Business.objects.create(name='Wall QR Print Biz', has_kitchen=True)
        self.owner = User.objects.create_user(username='wallqrprint_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='wallqrprint_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')

    def test_owner_can_view_print_page(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/stock/wall-qr/print/')
        self.assertEqual(resp.status_code, 200)
        self.assertIn(b'Scan To View Your Bill', resp.content)
        # escapejs renders '-' as the unicode escape - inside the JS string.
        self.assertIn(f'/bar/find\\u002Dtab/{self.biz.id}/'.encode(), resp.content)

    def test_header_and_footer_both_present(self):
        """User's explicit ask: bold text at both the top AND bottom of the page."""
        self.client.force_login(self.owner)
        resp = self.client.get('/stock/wall-qr/print/')
        self.assertEqual(resp.content.count(b'Scan To View Your Bill'), 2)

    def test_print_param_triggers_auto_print(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/stock/wall-qr/print/?print=1')
        self.assertIn(b'window.print()', resp.content)
        # Without ?print=1, no auto-print call should be emitted.
        resp2 = self.client.get('/stock/wall-qr/print/')
        self.assertNotIn(b'setTimeout(function () { window.print(); }, 500);', resp2.content)

    def test_staff_redirected_away(self):
        self.client.force_login(self.staff)
        resp = self.client.get('/stock/wall-qr/print/')
        self.assertEqual(resp.status_code, 302)

    def test_unauthenticated_redirected_to_login(self):
        resp = self.client.get('/stock/wall-qr/print/')
        self.assertEqual(resp.status_code, 302)
        self.assertIn('/login', resp.url)

    def test_payment_settings_links_to_print_page(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/business/payment-settings/')
        self.assertIn(b'/stock/wall-qr/print/?print=1', resp.content)


class CrossCounterReceiptLinkingTest(TestCase):
    """Fix (2026-07-16): a customer's running tab must resolve to ONE shared receipt/PIN
    regardless of which counter (Bar, Kitchen, Quick Sell) rings up their next item.

    Root cause of the gap: each counter had its own hand-copied version of the
    master-receipt lookup and they'd drifted — Bar Board checked everything
    (own receipt, linked_tab_ids, kitchen tabs, any same-day receipt), Kitchen only
    checked Bar (not Quick Sell), and Quick Sell's tab flow checked nothing beyond its
    own tab. core/tab_receipts.py:resolve_master_receipt() is now the single source of
    truth all three call. These tests cover the two directions that were previously
    broken (Bar/Kitchen tab exists first, Quick Sell rings up second) plus a direct
    unit test of the priority chain."""

    def setUp(self):
        self.biz = Business.objects.create(name='Cross Counter Biz')
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='xcounter_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='XCounter Soda',
            material_no='XCTR-01', unit='pcs', selling_price=Decimal('100'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('20'),
        )
        self.client.force_login(self.owner)

    def _make_tab_with_receipt(self, source, customer_name='Cross Patron'):
        tab = BarTab.objects.create(
            business=self.biz, customer_name=customer_name, status='OPEN', source=source,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='credit',
        )
        BarTabEntry.objects.create(tab=tab, transaction=txn, description='XCounter Soda', amount=Decimal('100'))
        rcpt = Receipt.issue(
            business=self.biz, lines=[{'name': 'XCounter Soda', 'qty': 1, 'subtotal': 100}],
            payment_method='tab', customer_name=customer_name, meta={'tab_id': tab.id},
        )
        return tab, rcpt

    def test_resolver_finds_own_receipt_first(self):
        from core.tab_receipts import resolve_master_receipt
        tab, rcpt = self._make_tab_with_receipt('bar')
        found, freshly_linked = resolve_master_receipt(self.biz, tab)
        self.assertEqual(found.id, rcpt.id)
        self.assertFalse(freshly_linked)

    def test_resolver_links_to_another_open_tabs_receipt_any_source(self):
        from core.tab_receipts import resolve_master_receipt
        bar_tab, bar_rcpt = self._make_tab_with_receipt('bar')
        qs_tab = BarTab.objects.create(
            business=self.biz, customer_name='Cross Patron', status='OPEN', source='qs',
        )
        found, freshly_linked = resolve_master_receipt(self.biz, qs_tab)
        self.assertEqual(found.id, bar_rcpt.id)
        self.assertTrue(freshly_linked)
        bar_rcpt.refresh_from_db()
        self.assertIn(qs_tab.id, bar_rcpt.meta.get('linked_tab_ids', []))

    def test_resolver_falls_back_to_any_todays_receipt_for_customer(self):
        from core.tab_receipts import resolve_master_receipt
        # A receipt with no live OPEN tab attached (e.g. a settled/standalone credit sale)
        rcpt = Receipt.issue(
            business=self.biz, lines=[{'name': 'XCounter Soda', 'qty': 1, 'subtotal': 100}],
            payment_method='credit', customer_name='Cross Patron',
        )
        new_tab = BarTab.objects.create(
            business=self.biz, customer_name='Cross Patron', status='OPEN', source='kitchen',
        )
        found, freshly_linked = resolve_master_receipt(self.biz, new_tab)
        self.assertEqual(found.id, rcpt.id)
        self.assertTrue(freshly_linked)

    def test_quick_sell_tab_links_into_existing_bar_tab_receipt(self):
        """The actual regression: previously Quick Sell's tab flow never looked for a
        pre-existing Bar tab receipt — it always issued a second, separate receipt."""
        import json
        bar_tab, bar_rcpt = self._make_tab_with_receipt('bar', customer_name='QS Link Patron')
        cart = json.dumps([{'id': self.item.id, 'qty': 1, 'price': 100}])
        self.client.post('/quick-sell/', {
            'cart': cart, 'payment_method': 'tab', 'recipient': 'QS Link Patron',
        })
        qs_tab = BarTab.objects.filter(
            business=self.biz, customer_name='QS Link Patron', source='qs',
        ).first()
        self.assertIsNotNone(qs_tab)
        self.assertEqual(
            Receipt.objects.filter(business=self.biz, customer_name__iexact='QS Link Patron').count(),
            1,
            'Quick Sell must reuse the existing Bar tab receipt, not create a second one',
        )
        bar_rcpt.refresh_from_db()
        self.assertIn(qs_tab.id, bar_rcpt.meta.get('linked_tab_ids', []))

    def test_two_different_customers_sharing_a_name_are_never_merged_priority3(self):
        """2026-08-16 live report (Roy, Monsoon Inn), confirmed via
        diagnose_receipt: Receipt #705 ended up linked to two BarTabs
        resolving to two DIFFERENT Customer records (both named 'Peter').
        Priority 3's name-string fallback (used when a tab's own
        customer_id is unresolved) must never match a candidate tab that
        DOES have a resolved, different Customer identity."""
        from core.tab_receipts import resolve_master_receipt
        peter_a = Customer.objects.create(business=self.biz, name='Peter')
        peter_b = Customer.objects.create(business=self.biz, name='Peter')
        bar_tab = BarTab.objects.create(
            business=self.biz, customer_name='Peter', customer=peter_a, status='OPEN', source='bar',
        )
        Receipt.issue(
            business=self.biz, lines=[{'name': 'Chrome Gin', 'qty': 1, 'subtotal': 150}],
            payment_method='mpesa', customer_name='Peter', meta={'tab_id': bar_tab.id},
        )
        new_tab = BarTab.objects.create(
            business=self.biz, customer_name='Peter', customer=peter_b, status='OPEN', source='bar',
        )
        found, freshly_linked = resolve_master_receipt(self.biz, new_tab)
        self.assertIsNone(found)
        self.assertFalse(freshly_linked)

    def test_two_different_customers_sharing_a_name_are_never_merged_priority4(self):
        """Same live bug, the actual root-cause branch: an earlier,
        already-SETTLED (no live tab) receipt for one 'Peter' must not be
        silently reused for a brand-new tab belonging to a DIFFERENT
        'Peter' just because the name string matches."""
        from core.tab_receipts import resolve_master_receipt
        peter_a = Customer.objects.create(business=self.biz, name='Peter')
        peter_b = Customer.objects.create(business=self.biz, name='Peter')
        old_tab = BarTab.objects.create(
            business=self.biz, customer_name='Peter', customer=peter_a, status='SETTLED',
        )
        Receipt.issue(
            business=self.biz, lines=[{'name': 'Chrome Gin', 'qty': 1, 'subtotal': 150}],
            payment_method='mpesa', customer_name='Peter', meta={'tab_id': old_tab.id},
        )
        new_tab = BarTab.objects.create(
            business=self.biz, customer_name='Peter', customer=peter_b, status='OPEN',
        )
        found, freshly_linked = resolve_master_receipt(self.biz, new_tab)
        self.assertIsNone(found)
        self.assertFalse(freshly_linked)

    def test_two_anonymous_walkins_sharing_a_name_still_merge(self):
        """Regression lock: two tabs with NO resolved Customer at all, just
        the same typed name, is the one case that must keep merging — the
        lowest-stakes case, since neither side is tied to any real
        Customer/debt record yet (matches every pre-existing test in this
        class, none of which attach a `customer=` FK)."""
        from core.tab_receipts import resolve_master_receipt
        bar_tab, bar_rcpt = self._make_tab_with_receipt('bar', customer_name='Anon Patron')
        new_tab = BarTab.objects.create(
            business=self.biz, customer_name='Anon Patron', status='OPEN', source='kitchen',
        )
        found, freshly_linked = resolve_master_receipt(self.biz, new_tab)
        self.assertEqual(found.id, bar_rcpt.id)
        self.assertTrue(freshly_linked)

    def test_same_resolved_customer_still_merges_across_counters(self):
        """Regression lock: when BOTH tabs genuinely resolve to the SAME
        Customer record, merging must still work exactly as before —
        this fix only blocks a mismatch, never a real match."""
        from core.tab_receipts import resolve_master_receipt
        peter = Customer.objects.create(business=self.biz, name='Peter')
        bar_tab = BarTab.objects.create(
            business=self.biz, customer_name='Peter', customer=peter, status='OPEN', source='bar',
        )
        bar_rcpt = Receipt.issue(
            business=self.biz, lines=[{'name': 'XCounter Soda', 'qty': 1, 'subtotal': 100}],
            payment_method='tab', customer_name='Peter', meta={'tab_id': bar_tab.id},
        )
        qs_tab = BarTab.objects.create(
            business=self.biz, customer_name='Peter', customer=peter, status='OPEN', source='qs',
        )
        found, freshly_linked = resolve_master_receipt(self.biz, qs_tab)
        self.assertEqual(found.id, bar_rcpt.id)
        self.assertTrue(freshly_linked)


class NetProfitWastageDeductionTest(TestCase):
    """K8 audit (Task 1, deferred): regression-locks the current, intentional net_profit
    formula — wastage_loss must be deducted exactly once (added in the 2026-07-13 sprint
    to fix wastage being invisible to P&L). A future change must not re-break this."""

    def setUp(self):
        self.biz = Business.objects.create(name='K8 PnL Biz')
        self.store = Store.objects.create(business=self.biz, name='Main')
        self.owner = User.objects.create_user(username='k8_pnl_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='K8 Item', unit='Pcs',
            material_no='K8-ITEM-01', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )

    def test_wastage_reduces_net_profit_but_not_gross_profit(self):
        today = timezone.localdate()
        # One sale: revenue 100, cost 40 -> gross profit 60
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'),
            payment_method='cash', date=today,
        )
        # One wastage event: 2 units at cost 40 each = 80 loss, zero revenue impact
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Wastage',
            qty=Decimal('-2'), date=today,
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/analytics/?period=30')
        self.assertEqual(resp.status_code, 200)
        ctx = resp.context
        self.assertEqual(ctx['cur_profit'], 60.0, 'Wastage must not appear in gross profit (COGS-of-sold only)')
        self.assertEqual(ctx['wastage_loss'], 80.0)
        self.assertEqual(
            ctx['net_profit'], ctx['cur_profit'] - ctx['total_losses'],
            'net_profit must deduct wastage_loss exactly once via total_losses',
        )
        self.assertEqual(ctx['net_profit'], -20.0)


class TransactionLossValueFixTest(TestCase):
    """2026-08-11 live report (Roy, with screenshots): the Analytics "Hasara/
    Losses" tile showed "Voids: 10,020,600" on a business doing ~KES 150k of
    revenue for the period — an obviously impossible figure. Root cause:
    analytics_views.py's wastage_loss/void_loss/owner_drawings_cost each
    reimplemented a naive `abs(qty) * item.cost_price` formula instead of
    reusing Transaction.cost()'s own keg/bunch/batch/preset-aware
    proportional logic. For a keg pour specifically, qty is stored in ml
    while item.cost_price is priced per WHOLE KEG (thousands of KES) — a
    single voided ~500ml pour naively priced as `500 * cost_per_keg`
    inflates by roughly 1000x, more than enough to produce a multi-million-
    shilling phantom loss from a handful of voided pours. Fixed by
    extracting Transaction.cost()'s branch logic into
    _stock_movement_cost(), reused by both cost() (Issue only, unchanged)
    and the new loss_value() (Wastage/OwnerConsumption)."""

    def setUp(self):
        _make_keg_setup(self, 'lossval')

    def test_plain_item_wastage_unchanged(self):
        """Regression lock — the ordinary, most common case (no keg/bunch/
        batch/preset FK) must compute exactly as before."""
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Plain Item',
            material_no='LV-PLAIN-01', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )
        txn = Transaction.objects.create(
            business=self.biz, item=item, type='Wastage', qty=Decimal('-2'),
        )
        self.assertEqual(txn.loss_value(), 80.0)

    def test_voided_keg_pour_is_small_proportional_value_not_millions(self):
        """The literal reported bug: a voided keg pour must cost a few
        shillings (proportional to the barrel's own cost/target), never
        qty(ml) * item.cost_price(per-keg, thousands of KES)."""
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-500'), sale_amount=Decimal('50'),
            payment_method='void', keg_barrel=self.barrel,
        )
        # Naive (buggy) formula would give abs(-500) * 12000 = 6,000,000.
        naive_buggy_value = abs(float(txn.qty)) * float(self.item.cost_price)
        self.assertGreater(naive_buggy_value, 1_000_000)
        # Correct: sale_amount(50) * barrel.cost_price(12000) / barrel.target_revenue(18000)
        expected = 50.0 * 12000.0 / 18000.0
        self.assertAlmostEqual(txn.cost(), expected, places=2)
        self.assertLess(txn.cost(), 100)  # sane, small, proportional value

    def test_produce_bunch_discard_uses_bunch_cost_not_item_cost(self):
        from core.models import ProduceBunch
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Sukuma',
            material_no='LV-BUNCH-01', is_produce=True, produce_mode='BUNCH',
            selling_price=Decimal('10'), cost_price=Decimal('9999'),  # deliberately wrong/stale
        )
        bunch = ProduceBunch.objects.create(
            business=self.biz, item=item, size='MEDIUM',
            cost_price=Decimal('50'), target_revenue=Decimal('80'),
            status='OPEN',
        )
        bunch.record_sale(Decimal('20'), 'cash')  # 20 of 80 sold
        txn = bunch.discard('Wilted')
        self.assertIsNotNone(txn)
        # leftover = 60/80 of the bunch remaining -> 0.75 * cost_price(50) = 37.5
        self.assertAlmostEqual(txn.loss_value(), 37.5, places=2)
        # Definitely NOT using item.cost_price (9999) in any way
        self.assertNotAlmostEqual(txn.loss_value(), abs(float(txn.qty)) * 9999.0, places=2)

    def test_kitchen_batch_discard_after_prior_sales_correctly_computes_unrecovered_value(self):
        """Edge case caught while writing the fix: discard()'s Wastage row
        has sale_amount=0 (not None) — `is not None` would wrongly take the
        proportional-sale branch (0 * cost_total / revenue_collected = 0)
        instead of falling through to the correct item.cost_price(==
        cost_total) * qty(unrecovered fraction) computation."""
        from core.models import KitchenBatch
        kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        batch_item = Item.objects.create(
            business=self.biz, store=kitchen_store, description='Chipo',
            material_no='LV-BATCH-01', cost_price=Decimal('1000'),
        )
        batch = KitchenBatch.objects.create(
            business=self.biz, store=kitchen_store, item=batch_item,
            cost_total=Decimal('1000'), status='OPEN',
        )
        batch.record_sale(Decimal('600'))  # 600 of 1000 recovered — revenue_collected > 0
        txn = batch.discard('End of day')
        self.assertIsNotNone(txn)
        self.assertEqual(txn.sale_amount, Decimal('0'))
        # unrecovered = 1000 - 600 = 400
        self.assertAlmostEqual(txn.loss_value(), 400.0, places=2)

    def test_kitchen_batch_real_sale_still_proportional_unchanged(self):
        from core.models import KitchenBatch
        kitchen_store = Store.objects.create(business=self.biz, name='Kitchen2', is_kitchen=True)
        batch_item = Item.objects.create(
            business=self.biz, store=kitchen_store, description='Chipo2',
            material_no='LV-BATCH-02', cost_price=Decimal('1000'),
        )
        batch = KitchenBatch.objects.create(
            business=self.biz, store=kitchen_store, item=batch_item,
            cost_total=Decimal('1000'), status='OPEN',
        )
        txn = batch.record_sale(Decimal('500'))  # first sale: 500 of 1000
        # proportional: 500 * 1000 / 500 = 1000 (whole cost attributed to this,
        # the only sale so far) — same formula .cost() always used, unchanged.
        self.assertAlmostEqual(txn.cost(), 1000.0, places=2)

    def test_owner_consumption_uses_loss_value(self):
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Plain Item 2',
            material_no='LV-PLAIN-02', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )
        txn = Transaction.objects.create(
            business=self.biz, item=item, type='OwnerConsumption', qty=Decimal('-1'),
        )
        self.assertEqual(txn.loss_value(), 40.0)

    def test_loss_value_returns_zero_for_issue_type(self):
        """loss_value() is only meaningful for Wastage/OwnerConsumption —
        must never double-count an ordinary sale."""
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Plain Item 3',
            material_no='LV-PLAIN-03', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )
        txn = Transaction.objects.create(
            business=self.biz, item=item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash',
        )
        self.assertEqual(txn.loss_value(), 0)


class AnalyticsVoidLossIntegrationTest(TestCase):
    """End-to-end: the /analytics/ page itself must show a sane void_loss
    for a voided keg pour, not a multi-million-shilling phantom figure —
    the exact scenario from Roy's live screenshots."""

    def setUp(self):
        _make_keg_setup(self, 'analyticsvoid')

    def test_voided_keg_pour_does_not_inflate_net_profit_loss(self):
        # One real sale so the page has ordinary revenue to compare against.
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-500'), sale_amount=Decimal('50'),
            payment_method='cash', keg_barrel=self.barrel,
        )
        # One VOIDED keg pour — the literal bug scenario.
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-500'), sale_amount=Decimal('50'),
            payment_method='void', keg_barrel=self.barrel,
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/analytics/?period=30')
        self.assertEqual(resp.status_code, 200)
        ctx = resp.context
        # Correct: 50 * 12000 / 18000 ≈ 33.33 — nowhere near a million.
        self.assertLess(ctx['void_loss'], 100)
        self.assertGreater(ctx['void_loss'], 0)
        self.assertLess(abs(ctx['net_profit']), 10_000)


class AnalyticsUnitsFloatRoundingTest(TestCase):
    """2026-08-11 live report (Roy, screenshots): "Blue Ice 32.69999999999997
    units" and "Liquor Store 700.2000000000004 units" — ordinary binary-
    float summation noise (classic `0.1+0.1+0.1 == 0.30000000000000004`)
    from adding many small fractional preset amounts, never rounded before
    display in top_products/store_list, unlike every other accumulated-
    units figure already rounded elsewhere on the same page."""

    def setUp(self):
        self.biz = Business.objects.create(name='Float Rounding Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='floatround_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Blue Ice',
            material_no='FR-01', selling_price=Decimal('80'), cost_price=Decimal('20'),
        )

    def test_top_products_units_never_show_float_noise(self):
        today = timezone.localdate()
        # Three quarter-bottle sales — 0.1 + 0.1 + 0.1 in raw Python floats
        # is 0.30000000000000004, not 0.3.
        for _ in range(3):
            Transaction.objects.create(
                business=self.biz, item=self.item, type='Issue',
                qty=Decimal('-0.1'), sale_amount=Decimal('20'),
                payment_method='cash', date=today,
            )
        self.client.force_login(self.owner)
        resp = self.client.get('/analytics/?period=30')
        self.assertEqual(resp.status_code, 200)
        top = resp.context['top_products']
        self.assertEqual(len(top), 1)
        units = top[0]['units']
        self.assertEqual(units, round(units, 2), 'units must already be exactly 2dp-rounded')
        self.assertEqual(units, 0.3)

    def test_store_list_units_never_show_float_noise(self):
        today = timezone.localdate()
        for _ in range(3):
            Transaction.objects.create(
                business=self.biz, item=self.item, type='Issue',
                qty=Decimal('-0.1'), sale_amount=Decimal('20'),
                payment_method='cash', date=today,
            )
        self.client.force_login(self.owner)
        resp = self.client.get('/analytics/?period=30')
        store_list = resp.context['store_list']
        self.assertEqual(len(store_list), 1)
        units = store_list[0]['units']
        self.assertEqual(units, round(units, 2))
        self.assertEqual(units, 0.3)


class SalesDashboardUnitsFloatAndOwnerDrawingsTest(TestCase):
    """2026-08-21 live report (Roy, screenshots): "Blue Ice" showed
    "55.60000000000003" units on /sales/ (Sales by Item) while "KC Ginger"
    showed a clean "40.25" — the exact same binary-float summation noise
    already fixed for analytics_views.py's top_products/store_list on
    2026-08-11 (AnalyticsUnitsFloatRoundingTest above), but sales_dashboard()
    in core/views.py is a completely separate, never-audited view with its
    own copy of the same unrounded accumulation. Same screenshots also
    showed "Owner Drawings -11,702,202" and "Net Profit -11,633,993" on a
    business doing ~KES 212k of revenue — the naive `abs(qty) *
    item.cost_price` formula misprices a keg pour by ~1000x (qty in ml vs
    cost_price per whole keg), the identical bug already fixed for
    analytics_views.py's wastage_loss/void_loss/owner_drawings_cost on
    2026-08-11 via Transaction.loss_value(), never applied to this sibling
    view either."""

    def setUp(self):
        self.biz = Business.objects.create(name='Sales Dash Float Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='salesdash_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Blue Ice',
            material_no='SDF-01', selling_price=Decimal('80'), cost_price=Decimal('20'),
        )

    def test_units_sold_never_shows_float_noise(self):
        today = timezone.localdate()
        for _ in range(3):
            Transaction.objects.create(
                business=self.biz, item=self.item, type='Issue',
                qty=Decimal('-0.1'), sale_amount=Decimal('20'),
                payment_method='cash', date=today,
            )
        self.client.force_login(self.owner)
        resp = self.client.get('/sales/?period=month')
        self.assertEqual(resp.status_code, 200)
        rows = resp.context['item_sales_list']
        self.assertEqual(len(rows), 1)
        units = rows[0]['units_sold']
        self.assertEqual(units, round(units, 2), 'units_sold must already be exactly 2dp-rounded')
        self.assertEqual(units, 0.3)

    def test_owner_drawings_from_keg_pour_uses_proportional_cost_not_naive_formula(self):
        """A single ~500ml owner draw from a keg costing 12000 with a
        20000 target must price at the same proportional share cost()
        already uses for a real sale — NOT abs(qty) * item.cost_price
        (500 * 12000 = 6,000,000, the exact bug reported)."""
        keg_item = Item.objects.create(
            business=self.biz, store=self.store, description='Keg Gold',
            material_no='SDF-KEG', is_keg=True,
            selling_price=Decimal('50'), cost_price=Decimal('12000'),
        )
        barrel = KegBarrel.objects.create(
            business=self.biz, store=self.store, item=keg_item,
            cost_price=Decimal('12000'), target_revenue=Decimal('20000'),
            status='TAPPED',
        )
        Transaction.objects.create(
            business=self.biz, item=keg_item, type='OwnerConsumption',
            qty=Decimal('-500'), sale_amount=Decimal('200'),
            keg_barrel=barrel, date=timezone.localdate(),
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/sales/?period=month')
        self.assertEqual(resp.status_code, 200)
        # Correct proportional cost: 200 * 12000 / 20000 = 120
        self.assertEqual(resp.context['owner_drawings_cost'], 120.0)
        self.assertLess(
            abs(resp.context['owner_drawings_cost']), 10000,
            "must never reach the naive-formula scale of millions of KES",
        )

    def test_owner_drawings_from_plain_item_unaffected(self):
        """A plain (non-keg/non-bunch/non-batch/non-preset) owner draw must
        still price exactly as before — abs(qty) * item.cost_price, now via
        loss_value() instead of the removed inline formula."""
        Transaction.objects.create(
            business=self.biz, item=self.item, type='OwnerConsumption',
            qty=Decimal('-3'), date=timezone.localdate(),
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/sales/?period=month')
        self.assertEqual(resp.context['owner_drawings_cost'], 60.0)  # 3 * 20


class AnalyticsDashboardKitchenBatchPresetQueryCountTest(TestCase):
    """2026-08-19 live incident (Roy, correlated with a real Render
    "HTTP health check failed" 502): "the period filter... is not
    responding or taking too long to respond when selecting a period
    other than 30 days". Root cause — current_sales/prev_sales/all_sales/
    _kitchen_txns in analytics_dashboard() were missing kitchen_batch and
    preset from select_related(), while Transaction.cost()'s proportional
    logic (_stock_movement_cost()) lazily fetches exactly those FKs for
    any kitchen-batch or preset-attributed sale — a real N+1, one extra
    query per affected transaction, scaling directly with how many
    transactions fall in the selected period (longer period = more
    transactions = more extra queries), exactly matching the report."""

    def setUp(self):
        self.biz = Business.objects.create(name='Analytics NPlus1 Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='ana_nplus1_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.batch_item = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            unit='Batch', material_no='ANP1-01', selling_price=Decimal('100'),
            is_kitchen_batch=True,
        )
        self.preset_item = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            unit='Pcs', material_no='ANP1-02',
        )
        self.preset = ItemPortionPreset.objects.create(
            item=self.preset_item, label='Paja', price=Decimal('150'),
            quantity_consumed=Decimal('1'), cost_price=Decimal('80'),
        )

    def _make_transactions(self, count):
        today = timezone.localdate()
        batch = KitchenBatch.objects.create(
            business=self.biz, store=self.store, item=self.batch_item,
            cost_total=Decimal('1500'),
        )
        for i in range(count):
            batch.record_sale(Decimal('50'), payment_method='cash')
            Transaction.objects.create(
                business=self.biz, item=self.preset_item, type='Issue',
                qty=-self.preset.quantity_consumed, sale_amount=self.preset.price,
                payment_method='cash', date=today, preset=self.preset,
            )

    def test_query_count_does_not_scale_with_kitchen_batch_and_preset_txn_count(self):
        self._make_transactions(25)
        self.client.force_login(self.owner)
        from django.db import connection
        from django.test.utils import CaptureQueriesContext
        with CaptureQueriesContext(connection) as ctx:
            resp = self.client.get('/analytics/?period=90')
        self.assertEqual(resp.status_code, 200)
        self.assertLess(
            len(ctx.captured_queries), 150,
            f"analytics_dashboard() issued {len(ctx.captured_queries)} queries for "
            "50 kitchen_batch/preset-linked transactions — select_related must keep "
            "this roughly constant, not one extra query per transaction.",
        )

    def test_cost_figures_still_correct_with_full_select_related(self):
        """The fix must not change what the numbers actually are — only
        how many queries it takes to compute them."""
        self._make_transactions(3)
        self.client.force_login(self.owner)
        resp = self.client.get('/analytics/?period=90')
        self.assertEqual(resp.status_code, 200)
        kitchen_rows = {row['name']: row for row in resp.context['kitchen_rows']}
        self.assertIn('Chipo', kitchen_rows)
        self.assertIn('Kuku — Paja', kitchen_rows)
        # 3 batch sales of 50 each = 150 revenue; cost is proportional
        # (sale_amount * cost_total / revenue_collected) = 50 * 1500/150 = 500 each.
        self.assertAlmostEqual(kitchen_rows['Chipo']['revenue'], 150.0, places=2)
        self.assertAlmostEqual(kitchen_rows['Chipo']['cost'], 1500.0, places=2)
        # 3 preset sales at 150 revenue / 80 cost each.
        self.assertAlmostEqual(kitchen_rows['Kuku — Paja']['revenue'], 450.0, places=2)
        self.assertAlmostEqual(kitchen_rows['Kuku — Paja']['cost'], 240.0, places=2)


class AnalyticsTileBreakdownTest(TestCase):
    """2026-08-11 live request (Roy): tap-to-expand breakdowns for Revenue,
    Gross Profit, Net Profit, Total Expenses, Owner Drawings, and Hasara/
    Losses tiles, so any figure can be checked against the real line items
    behind it instead of taken on faith — the concrete tool for "how do we
    figure out whether revenue is really exaggerated or not"."""

    def setUp(self):
        self.biz = Business.objects.create(name='Breakdown Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='breakdown_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Breakdown Item',
            material_no='BD-01', selling_price=Decimal('100'), cost_price=Decimal('40'),
        )
        self.client.force_login(self.owner)

    def test_revenue_daily_breakdown_matches_real_sales(self):
        today = timezone.localdate()
        yesterday = today - timedelta(days=1)
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash', date=today,
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('50'), payment_method='cash', date=yesterday,
        )
        resp = self.client.get('/analytics/?period=30')
        breakdown = {str(d['date']): d['revenue'] for d in resp.context['revenue_daily_breakdown']}
        self.assertEqual(breakdown[str(today)], 100.0)
        self.assertEqual(breakdown[str(yesterday)], 50.0)

    def test_prev_period_revenue_shown_for_comparison(self):
        today = timezone.localdate()
