        self.assertEqual(self.bid.status, 'accepted')
        self.assertEqual(
            self.PurchaseOrder.objects.filter(business=self.buyer, supplier=self.supplier_biz).count(), 1,
            'Duplicate award POST must not create a second draft PurchaseOrder',
        )

