class RecordDebtPaymentIdempotencyTest(TestCase):
    """record_debt_payment is a real <form> POST/redirect with no prior server-side
    duplicate-submission guard — a double-click on "Record Payment" or a back-button
    resubmission could create a second, real CustomerDebtPayment for the same cash/
    mpesa payment. Locks in the core.idempotency.claim_checkout_token backstop."""

    def setUp(self):
        self.biz = Business.objects.create(name='Debt Idem Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='debtidem_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Debt Idem Item',
            material_no='DEBTIDEM-01', selling_price=Decimal('50'),
        )
        self.customer = Customer.objects.create(
            business=self.biz, name='Debt Idem Patron', credit_approved=True,
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-4'), recipient=self.customer.name,
            payment_method='credit', sale_amount=Decimal('400'),
        )
        self.client.force_login(self.owner)

    def test_duplicate_token_does_not_double_record_payment(self):
        from core.models import CustomerDebtPayment
        payload = {
            'amount_paid': '100', 'payment_method': 'cash', 'debt_source': 'bar',
            'idempotency_token': 'debt-pay-same-token',
        }
        self.client.post(f'/debt/{self.customer.id}/payment/', payload)
        self.client.post(f'/debt/{self.customer.id}/payment/', payload)
        self.assertEqual(
            CustomerDebtPayment.objects.filter(customer=self.customer).count(), 1,
            'Duplicate token must not create a second CustomerDebtPayment',
        )

    def test_different_tokens_both_go_through_once_confirmed(self):
        """2026-07-31: a second payment matching the same customer/amount
        within 24h is now flagged and held for one explicit confirmation
        (see DebtPaymentDuplicateConfirmationTest) rather than recorded
        immediately — but a genuinely separate second payment must still
        be ABLE to go through once confirmed, not permanently blocked."""
        from core.models import CustomerDebtPayment
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '100', 'payment_method': 'cash', 'debt_source': 'bar',
            'idempotency_token': 'debt-pay-token-a',
        })
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '100', 'payment_method': 'cash', 'debt_source': 'bar',
            'idempotency_token': 'debt-pay-token-b',
        })
        self.assertEqual(
            CustomerDebtPayment.objects.filter(customer=self.customer).count(), 1,
            'The second matching payment is flagged and held, not recorded yet',
        )
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'confirm_duplicate': '1', 'idempotency_token': 'debt-pay-confirm-1',
        })
        self.assertEqual(
            CustomerDebtPayment.objects.filter(customer=self.customer).count(), 2,
            'Once explicitly confirmed, the second genuine payment must go through',
        )

    def test_blank_token_still_works(self):
        """Backward compat: claim_checkout_token treats a blank token as unprotected,
        not blocked — existing callers with no token must not break."""
        from core.models import CustomerDebtPayment
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '100', 'payment_method': 'cash', 'debt_source': 'bar',
        })
        self.assertEqual(CustomerDebtPayment.objects.filter(customer=self.customer).count(), 1)
        self.assertNotEqual(resp.status_code, 400)


class DuplicateDebtPaymentFlagTest(TestCase):
    """2026-07-30 urgent live request: Roy wasn't sure if a KES 200 debt
    payment was a genuine duplicate ("I remember ticking off the 200 in the
    tabs drawer... fix it in a way that the system could identify if there
    was a double entry"). record_debt_payment flags a second payment for
    the same customer+amount within 24 hours and holds it pending one
    explicit confirmation (2026-07-31 follow-up: "I would like for the
    system to ask the user if that double payment detection... is true or
    not, just a small confirmation just to be sure") — never silently
    auto-records it, and never permanently blocks it either, since a real
    second payment of the same round amount is not implausible (see
    RecordDebtPaymentIdempotencyTest.
    test_different_tokens_both_go_through_once_confirmed, which this fix
    must not regress). See DebtPaymentDuplicateConfirmationTest for the
    full confirm/cancel mechanics."""

    def setUp(self):
        self.biz = Business.objects.create(name='Dup Debt Pay Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='dupdebt_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='dupdebt_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Dup Debt Item',
            material_no='DUPDEBT-01', selling_price=Decimal('50'),
        )
        self.customer = Customer.objects.create(
            business=self.biz, name='Dup Debt Patron', credit_approved=True,
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-10'), recipient=self.customer.name,
            payment_method='credit', sale_amount=Decimal('1000'),
        )
        self.client.force_login(self.owner)

    def test_second_matching_payment_is_held_not_auto_recorded(self):
        from core.models import CustomerDebtPayment
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'mpesa', 'debt_source': 'bar',
            'idempotency_token': 'dup-1',
        })
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'mpesa', 'debt_source': 'bar',
            'idempotency_token': 'dup-2',
        })
        self.assertEqual(resp.status_code, 302)
        self.assertEqual(
            CustomerDebtPayment.objects.filter(customer=self.customer, amount_paid=Decimal('200')).count(), 1,
            'The second matching payment must be held pending confirmation, not auto-recorded',
        )

    def test_second_matching_payment_notifies_owner_manager(self):
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'mpesa', 'debt_source': 'bar',
            'idempotency_token': 'dup-3',
        })
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'mpesa', 'debt_source': 'bar',
            'idempotency_token': 'dup-4',
        })
        self.assertTrue(
            Notification.objects.filter(user=self.owner, title__icontains='Malipo Yanayofanana').exists()
        )
        self.assertTrue(
            Notification.objects.filter(user=self.manager, title__icontains='Malipo Yanayofanana').exists()
        )

    def test_first_payment_of_its_kind_does_not_flag(self):
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '150', 'payment_method': 'cash', 'debt_source': 'bar',
            'idempotency_token': 'dup-5',
        })
        self.assertFalse(
            Notification.objects.filter(user=self.owner, title__icontains='Malipo Yanayofanana').exists()
        )

    def test_different_amounts_do_not_flag(self):
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'cash', 'debt_source': 'bar',
            'idempotency_token': 'dup-6',
        })
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '300', 'payment_method': 'cash', 'debt_source': 'bar',
            'idempotency_token': 'dup-7',
        })
        self.assertFalse(
            Notification.objects.filter(user=self.owner, title__icontains='Malipo Yanayofanana').exists()
        )

    def test_old_matching_payment_outside_24h_does_not_flag(self):
        from core.models import CustomerDebtPayment
        CustomerDebtPayment.objects.create(
            business=self.biz, customer=self.customer, amount_paid=Decimal('200'),
            paid_at=timezone.now() - timedelta(hours=30),
        )
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'cash', 'debt_source': 'bar',
            'idempotency_token': 'dup-8',
        })
        self.assertFalse(
            Notification.objects.filter(user=self.owner, title__icontains='Malipo Yanayofanana').exists()
        )


class DebtPaymentDuplicateConfirmationTest(TestCase):
    """2026-07-31 live follow-up: "I would like for the system to ask the
    user if that double payment detection... is true or not, basically just
    a small confirmation just to be sure." The flag from
    DuplicateDebtPaymentFlagTest stashes the pending payment in the session
    (never writes it) and record_debt_payment only completes the write once
    confirm_duplicate=1 is posted — at which point it trusts the STASHED
    session values, not whatever the confirm form itself resubmits, so a
    tampered hidden field can't record a different amount than what was
    actually flagged."""

    def setUp(self):
        self.biz = Business.objects.create(name='Dup Confirm Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='dupconfirm_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='dupconfirm_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Dup Confirm Item',
            material_no='DUPCONFIRM-01', selling_price=Decimal('50'),
        )
        self.customer = Customer.objects.create(
            business=self.biz, name='Dup Confirm Patron', credit_approved=True,
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-10'), recipient=self.customer.name,
            payment_method='credit', sale_amount=Decimal('1000'),
        )
        self.client.force_login(self.owner)

    def _flag_first_then_second(self, amount='200', method='mpesa', notes=''):
        # claim_checkout_token uses Django's process-global cache, never reset
        # between test methods — a hardcoded literal token reused across every
        # test in this class would collide (the second test to claim it sees
        # a false "already recorded"), so each call gets its own uuid4 tokens.
        import uuid
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': amount, 'payment_method': method, 'debt_source': 'bar',
            'idempotency_token': f'dc-first-{uuid.uuid4()}',
        })
        return self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': amount, 'payment_method': method, 'notes': notes,
            'debt_source': 'bar', 'idempotency_token': f'dc-second-{uuid.uuid4()}',
        })

    def test_flagged_payment_creates_no_record_until_confirmed(self):
        from core.models import CustomerDebtPayment
        self._flag_first_then_second()
        self.assertEqual(
            CustomerDebtPayment.objects.filter(customer=self.customer, amount_paid=Decimal('200')).count(),
            1, 'Only the first payment should exist — the second is held pending confirmation',
        )

    def test_confirm_records_the_stashed_payment(self):
        import uuid
        from core.models import CustomerDebtPayment
        self._flag_first_then_second()
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'confirm_duplicate': '1', 'idempotency_token': f'dc-confirm-{uuid.uuid4()}',
        })
        self.assertEqual(resp.status_code, 302)
        self.assertEqual(
            CustomerDebtPayment.objects.filter(customer=self.customer, amount_paid=Decimal('200')).count(),
            2, 'Confirming must record the second, genuinely separate payment',
        )

    def test_confirm_uses_stashed_values_not_resubmitted_ones(self):
        """The confirm form only ever needs to POST confirm_duplicate=1 — even
        if a tampered/mismatched amount_paid is resubmitted alongside it, the
        server must use the trusted session-stashed amount, not the resubmit."""
        import uuid
        from core.models import CustomerDebtPayment
        self._flag_first_then_second(amount='200', method='mpesa')
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'confirm_duplicate': '1', 'amount_paid': '99999', 'payment_method': 'cash',
            'idempotency_token': f'dc-confirm-{uuid.uuid4()}',
        })
        second = CustomerDebtPayment.objects.filter(
            customer=self.customer, amount_paid=Decimal('200'),
        )
        self.assertEqual(second.count(), 2, 'The confirmed payment must use the stashed KES 200, not the tampered 99999')

    def test_cancel_clears_session_and_records_nothing(self):
        import uuid
        from core.models import CustomerDebtPayment
        self._flag_first_then_second()
        resp = self.client.get(f'/debt/{self.customer.id}/?clear_dup_confirm=1')
        self.assertEqual(resp.status_code, 302)
        self.assertEqual(
            CustomerDebtPayment.objects.filter(customer=self.customer, amount_paid=Decimal('200')).count(),
            1, 'Cancelling must never record the flagged payment',
        )
        # Confirming after cancel must no-op (session key already cleared) rather
        # than resurrecting the discarded payment.
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'confirm_duplicate': '1', 'idempotency_token': f'dc-confirm-{uuid.uuid4()}',
        })
        self.assertEqual(
            CustomerDebtPayment.objects.filter(customer=self.customer, amount_paid=Decimal('200')).count(),
            1, 'Confirming with no stashed session data must not create a payment',
        )

    def test_pending_confirmation_appears_in_debt_profile_context(self):
        self._flag_first_then_second()
        resp = self.client.get(f'/debt/{self.customer.id}/')
        self.assertIsNotNone(resp.context['pending_dup_confirm'])
        self.assertEqual(resp.context['pending_dup_confirm']['amount_paid'], '200')

    def test_no_pending_confirmation_by_default(self):
        resp = self.client.get(f'/debt/{self.customer.id}/')
        self.assertIsNone(resp.context['pending_dup_confirm'])

    def test_confirmation_notifies_owner_and_manager_excluding_confirmer(self):
        import uuid
        self._flag_first_then_second()
        Notification.objects.all().delete()
        self.client.post(f'/debt/{self.customer.id}/payment/', {
            'confirm_duplicate': '1', 'idempotency_token': f'dc-confirm-{uuid.uuid4()}',
        })
        self.assertFalse(
            Notification.objects.filter(user=self.owner, title__icontains='Yamethibitishwa').exists(),
            'The confirming user (owner) should not be notified about their own confirmation',
        )
        self.assertTrue(
            Notification.objects.filter(user=self.manager, title__icontains='Yamethibitishwa').exists(),
        )


class DebtStkPushIdempotencyTest(TestCase):
    """debt_stk_push had no client-side button-disable AND no server-side guard at
    all — a rapid double-tap on "Send STK" could fire two separate STK Push prompts
    to the customer's phone for the same debt; if the customer approved both, that's
    a real double-charge, not just a duplicate record. Locks in the
    core.idempotency.claim_checkout_token backstop added to debt_stk_push."""

    def setUp(self):
        self.biz = Business.objects.create(
            name='Debt STK Idem Biz', mpesa_till='555444',
            daraja_consumer_key='key', daraja_consumer_secret='secret', daraja_passkey='pass',
        )
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='debtstkidem_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Debt STK Idem Item',
            material_no='DEBTSTKIDEM-01', selling_price=Decimal('50'),
        )
        self.customer = Customer.objects.create(
            business=self.biz, name='Debt STK Patron', phone='0712345678', credit_approved=True,
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-10'), recipient=self.customer.name,
            payment_method='credit', sale_amount=Decimal('1000'),
        )
        self.client.force_login(self.owner)

    def _mock_stk_ok(self, mock_requests, checkout_id):
        token_resp = MagicMock()
        token_resp.json.return_value = {'access_token': 'tok'}
        token_resp.raise_for_status.return_value = None
        mock_requests.get.return_value = token_resp

        push_resp = MagicMock()
        push_resp.json.return_value = {'ResponseCode': '0', 'CheckoutRequestID': checkout_id}
        push_resp.raise_for_status.return_value = None
        mock_requests.post.return_value = push_resp

    @patch('core.mpesa.requests')
    def test_duplicate_token_sends_only_one_stk_push(self, mock_requests):
        self._mock_stk_ok(mock_requests, 'ws_debt_dup')
        payload = {
            'amount': '100', 'phone': '0712345678', 'source': 'bar',
            'idempotency_token': 'debt-stk-same-token',
        }
        r1 = self.client.post(f'/debt/{self.customer.id}/stk-push/', payload)
        r2 = self.client.post(f'/debt/{self.customer.id}/stk-push/', payload)
        self.assertEqual(r1.json().get('ok'), True)
        self.assertEqual(r2.status_code, 409)
        self.assertEqual(Payment.objects.filter(business=self.biz, debt_customer=self.customer).count(), 1)
        self.assertEqual(mock_requests.post.call_count, 1)

    @patch('core.mpesa.requests')
    def test_different_tokens_both_send_stk_push(self, mock_requests):
        self._mock_stk_ok(mock_requests, 'ws_debt_a')
        r1 = self.client.post(f'/debt/{self.customer.id}/stk-push/', {
            'amount': '100', 'phone': '0712345678', 'source': 'bar',
            'idempotency_token': 'debt-stk-token-a',
        })
        self._mock_stk_ok(mock_requests, 'ws_debt_b')
        r2 = self.client.post(f'/debt/{self.customer.id}/stk-push/', {
            'amount': '100', 'phone': '0712345678', 'source': 'bar',
            'idempotency_token': 'debt-stk-token-b',
        })
        self.assertEqual(r1.json().get('ok'), True)
        self.assertEqual(r2.json().get('ok'), True)
        self.assertEqual(Payment.objects.filter(business=self.biz, debt_customer=self.customer).count(), 2)


class DebtSettlementFromPaymentIdempotencyTest(TestCase):
    """The three debt-adjacent STK settlement functions in mpesa_views.py
    (_create_debt_payment_from_receipt, _settle_debt_customer_from_payment,
    _settle_receipt_entries_from_payment) are each called from BOTH the Daraja
    webhook (mpesa_callback) and the JS status poll (payment_status) — a realistic
    race, not just a double-tap. Their prior guard (skip if a CustomerDebtPayment
    already exists with this mpesa_ref in its notes) was skipped entirely when
    mpesa_ref was blank. Payment.debt_settled + select_for_update, mirroring
    kitchen_settled/qs_settled, closes this for all three."""

    def setUp(self):
        self.biz = Business.objects.create(name='Debt Settle Idem Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='debtsettleidem_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Debt Settle Idem Item',
            material_no='DEBTSETTLEIDEM-01', selling_price=Decimal('50'),
        )
        self.customer = Customer.objects.create(
            business=self.biz, name='Debt Settle Patron', credit_approved=True,
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-10'), recipient=self.customer.name,
            payment_method='credit', sale_amount=Decimal('1000'),
        )

    def test_settle_debt_customer_from_payment_runs_once(self):
        from core.mpesa_views import _settle_debt_customer_from_payment
        from core.models import CustomerDebtPayment
        payment = Payment.objects.create(
            business=self.biz, source='bar', amount=Decimal('300'), method='mpesa',
            status='completed', debt_customer=self.customer,
        )
        _settle_debt_customer_from_payment(payment)
        _settle_debt_customer_from_payment(payment)  # simulated callback/poll race
        self.assertEqual(CustomerDebtPayment.objects.filter(customer=self.customer).count(), 1)
        payment.refresh_from_db()
        self.assertTrue(payment.debt_settled)

    def test_create_debt_payment_from_receipt_runs_once(self):
        from core.mpesa_views import _create_debt_payment_from_receipt
        from core.models import CustomerDebtPayment, BarTab
        tab = BarTab.objects.create(
            business=self.biz, customer_name=self.customer.name,
            customer=self.customer, status='SETTLED',
        )
        receipt = Receipt.issue(
            business=self.biz, lines=[{'name': 'Debt Settle Idem Item', 'qty': 10, 'subtotal': 1000}],
            payment_method='credit', customer_name=self.customer.name,
            meta={'tab_id': tab.id},
        )
        payment = Payment.objects.create(
            business=self.biz, source='bar', amount=Decimal('300'), method='mpesa',
            status='completed', receipt_token=receipt.token,
        )
        _create_debt_payment_from_receipt(payment)
        _create_debt_payment_from_receipt(payment)  # simulated callback/poll race
        self.assertEqual(CustomerDebtPayment.objects.filter(customer=self.customer).count(), 1)
        payment.refresh_from_db()
        self.assertTrue(payment.debt_settled)

    def test_settle_receipt_entries_from_payment_runs_once(self):
        from core.mpesa_views import _settle_receipt_entries_from_payment
        tab = BarTab.objects.create(
            business=self.biz, customer_name=self.customer.name,
            customer=self.customer, status='OPEN', served_by=self.owner,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-2'), recipient=self.customer.name,
            payment_method='credit', sale_amount=Decimal('200'),
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Debt Settle Idem Item', amount=Decimal('200'),
        )
        payment = Payment.objects.create(
            business=self.biz, source='bar', amount=Decimal('200'), method='mpesa',
            status='completed', tab_entry_ids=[entry.id],
        )
        _settle_receipt_entries_from_payment(payment)
        entry.refresh_from_db()
        self.assertTrue(entry.is_paid)
        # Reset is_paid to simulate a race where both calls started before either
        # committed — the flag alone (not the is_paid filter) must block the retry.
        entry.is_paid = False
        entry.payment_method = 'credit'
        entry.save(update_fields=['is_paid', 'payment_method'])
        _settle_receipt_entries_from_payment(payment)  # simulated callback/poll race
        entry.refresh_from_db()
        self.assertFalse(entry.is_paid, 'debt_settled flag must block reprocessing on the second call')
        payment.refresh_from_db()
        self.assertTrue(payment.debt_settled)


