class RevertTabFromDebtTest(TestCase):
    """2026-07-30 urgent live request: "a way of reverting tabs sent to
    debt back to the tab drawers they came from in case of a mistake, more
    so on the owner's and manager's side... across all counters."
    convert_tab_to_debt only ever changes recipient (blank -> customer
    name) on still-unpaid entries plus the tab's own status/settled_at —
    payment_method was already 'credit' on every ordinary open-tab charge
    from the moment it was added. Reverting is the precise inverse."""

    def setUp(self):
        self.biz = Business.objects.create(name='Revert Debt Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='rd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='rd_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.staff = User.objects.create_user(username='rd_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='Revert Debt Item',
            material_no='RD-01', selling_price=Decimal('480'), cost_price=Decimal('200'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Chips',
            material_no='RD-02', selling_price=Decimal('150'), cost_price=Decimal('60'),
        )

    def _make_tab(self, name, amount, item=None, source='bar'):
        item = item or self.item
        store = self.kitchen_store if item is self.kitchen_item else self.bar_store
        tab = BarTab.objects.create(
            business=self.biz, customer_name=name, status='OPEN', source=source, store=store,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method='credit',
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description=item.description, amount=amount, is_paid=False,
        )
        return tab, entry

    def test_owner_reverts_fully_converted_tab(self):
        tab, entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        tab.refresh_from_db()
        entry.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')
        self.assertEqual(entry.transaction.recipient, 'Roy')

        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        data = resp.json()
        self.assertTrue(data['ok'], data)
        tab.refresh_from_db()
        entry.refresh_from_db()
        self.assertEqual(tab.status, 'OPEN')
        self.assertIsNone(tab.settled_at)
        self.assertEqual(entry.transaction.recipient, '')
        self.assertFalse(entry.is_paid)
        self.assertEqual(entry.transaction.payment_method, 'credit')  # untouched — correct baseline

    def test_reverted_tab_no_longer_in_debt_tracker(self):
        from core.debt_views import _get_customer_debt_data
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        customer = Customer.objects.get(business=self.biz, name='Roy')
        before = _get_customer_debt_data(customer, self.biz)
        self.assertEqual(before['outstanding'], 480.0)

        self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        after = _get_customer_debt_data(customer, self.biz)
        self.assertEqual(after['outstanding'], 0.0)

    def test_partial_settle_then_convert_then_revert_only_touches_unpaid_portion(self):
        """Roy's bug-2 scenario, exercised end to end: 480 bill, 200 paid
        via mpesa (a real settle_tab call, splitting the entry), then the
        remaining 280 converted to debt, then reverted — the already-paid
        200 must be untouched throughout."""
        tab, entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        settle_resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {
            'entry_ids': [entry.id], 'payment_method': 'mpesa', 'amount': '200',
        })
        self.assertTrue(settle_resp.json()['ok'], settle_resp.json())
        self.assertEqual(tab.unpaid_total(), Decimal('280'))

        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        tab.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')
        paid_entry = tab.entries.filter(is_paid=True).first()
        self.assertEqual(paid_entry.amount, Decimal('200'))
        self.assertEqual(paid_entry.payment_method, 'mpesa')

        revert_resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertTrue(revert_resp.json()['ok'], revert_resp.json())
        tab.refresh_from_db()
        paid_entry.refresh_from_db()
        self.assertEqual(tab.status, 'OPEN')
        self.assertEqual(tab.unpaid_total(), Decimal('280'))
        self.assertTrue(paid_entry.is_paid)
        self.assertEqual(paid_entry.amount, Decimal('200'))
        self.assertEqual(paid_entry.payment_method, 'mpesa')

    def test_manager_can_revert(self):
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        self.client.force_login(self.manager)
        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertTrue(resp.json()['ok'])

    def test_staff_cannot_revert(self):
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertEqual(resp.status_code, 403)
        tab.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')

    def test_blocked_once_customer_has_already_paid_against_it(self):
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        customer = Customer.objects.get(business=self.biz, name='Roy')
        CustomerDebtPayment.objects.create(
            business=self.biz, customer=customer, amount_paid=Decimal('100'),
        )
        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertEqual(resp.status_code, 409)
        tab.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')

    def test_fully_paid_tab_has_nothing_to_revert(self):
        tab, entry = self._make_tab('Roy', Decimal('480'))
        entry.is_paid = True
        entry.payment_method = 'cash'
        entry.save()
        tab.status = 'SETTLED'
        tab.settled_at = timezone.now()
        tab.save()
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        self.assertEqual(resp.status_code, 400)

    def test_debt_converted_tabs_api_lists_it_station_scoped(self):
        bar_tab, _e1 = self._make_tab('Roy', Decimal('480'), source='bar')
        kitchen_tab, _e2 = self._make_tab('Kim', Decimal('150'), item=self.kitchen_item, source='kitchen')
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{bar_tab.id}/debt/', {'customer_name': 'Roy'})
        self.client.post(f'/bar/tabs/{kitchen_tab.id}/debt/', {'customer_name': 'Kim'})

        resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        ids = [t['id'] for t in resp.json()['tabs']]
        self.assertIn(bar_tab.id, ids)
        self.assertNotIn(kitchen_tab.id, ids)

        resp = self.client.get('/bar/tabs/debt-converted/?station=kitchen')
        ids = [t['id'] for t in resp.json()['tabs']]
        self.assertIn(kitchen_tab.id, ids)
        self.assertNotIn(bar_tab.id, ids)

    def test_revert_does_not_touch_stock_or_qty(self):
        """Money-position-only correction — the item was genuinely served
        and stock genuinely left the shelf when it was added to the tab,
        completely independent of debt conversion or its reversal."""
        tab, entry = self._make_tab('Roy', Decimal('480'))
        original_qty = entry.transaction.qty
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Roy'})
        self.client.post(f'/bar/tabs/{tab.id}/revert-debt/')
        entry.refresh_from_db()
        self.assertEqual(entry.transaction.qty, original_qty)


class SettleTabRedirectsToDebtPaymentTest(TestCase):
    """2026-08-10 live report (Roy): "when a tab is still in the tabs
    drawer... and the customer had a debt when the auto conversion is
    happening... when the tab is paid and cleared from the tabs drawer, the
    debt tracker still shows it as debt and unpaid one as a matter of
    fact." Root cause: settle_tab()'s `if tab.status != 'OPEN':` branch
    unconditionally returned {ok:True, already_settled:True} the moment a
    tab was no longer OPEN — including a tab that was SETTLED via debt
    conversion (Geuza Deni / shift-close auto-convert) and still had a full
    unpaid balance. A staffer tapping "Lipa Yote" on such a tab (e.g. a
    stale client render, or simply not realizing conversion already
    happened) got a success-shaped response with ZERO record of the real
    cash/mpesa the customer just handed over — the tab vanished from the
    drawer via the caller's own loadTabs() refresh, looking exactly like a
    normal successful settle, while the debt tracker's own figure never
    moved. Fixed by redirecting such a payment into a REAL debt payment via
    the same canonical _do_settle_debt_payment() the debt tracker page and
    the M-Pesa debt-payment callback both already use."""

    def setUp(self):
        self.biz = Business.objects.create(name='Settle Redirect Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='sr_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kitchen_staff = User.objects.create_user(username='sr_kstaff', password='x')
        UserProfile.objects.create(user=self.kitchen_staff, business=self.biz, role='kitchen')
        self.item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='Settle Redirect Item',
            material_no='SR-01', selling_price=Decimal('480'), cost_price=Decimal('200'),
        )

    def _make_tab(self, name, amount, source='bar'):
        tab = BarTab.objects.create(
            business=self.biz, customer_name=name, status='OPEN', source=source, store=self.bar_store,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method='credit',
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description=self.item.description, amount=amount, is_paid=False,
        )
        return tab, entry

    def _convert(self, tab, name='Roy'):
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': name})
        tab.refresh_from_db()
        self.assertEqual(tab.status, 'SETTLED')

    def test_settle_on_debt_converted_tab_records_real_debt_payment(self):
        from core.debt_views import _get_customer_debt_data
        tab, entry = self._make_tab('Roy', Decimal('480'))
        self._convert(tab)
        customer = Customer.objects.get(business=self.biz, name='Roy')
        self.assertEqual(_get_customer_debt_data(customer, self.biz)['outstanding'], 480.0)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertTrue(data.get('redirected_to_debt'))
        self.assertIn('receipt_url', data)

        self.assertEqual(CustomerDebtPayment.objects.filter(customer=customer).count(), 1)
        payment = CustomerDebtPayment.objects.get(customer=customer)
        self.assertEqual(payment.amount_paid, Decimal('480'))
        self.assertEqual(payment.payment_method, 'cash')
        self.assertEqual(_get_customer_debt_data(customer, self.biz)['outstanding'], 0.0)

        # _do_settle_debt_payment's own FIFO reconciliation should flip the
        # underlying BarTabEntry to paid once fully covered — same mechanism
        # a normal debt-tracker-page payment already relies on.
        entry.refresh_from_db()
        self.assertTrue(entry.is_paid)
        # 2026-08-14 fix regression lock: the entry's own Transaction must be
        # synced too, not just the entry — this assertion is the one this
        # test was missing before the bug was found, which is exactly why a
        # widespread, real-money mismatch (dozens of transactions across
        # many customers, confirmed via audit_debt_ledger_integrity
        # --all-customers) went undetected for so long.
        entry.transaction.refresh_from_db()
        self.assertEqual(
            entry.transaction.payment_method, 'cash',
            "the underlying Transaction must be synced off 'credit' too, "
            "not just the BarTabEntry — otherwise the debt tracker keeps "
            "counting an already-paid transaction as still-owed credit",
        )

    def test_settle_on_debt_converted_tab_honors_partial_amount(self):
        from core.debt_views import _get_customer_debt_data
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self._convert(tab)
        customer = Customer.objects.get(business=self.biz, name='Roy')

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'mpesa', 'amount': '200'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertTrue(data.get('redirected_to_debt'))

        payment = CustomerDebtPayment.objects.get(customer=customer)
        self.assertEqual(payment.amount_paid, Decimal('200'))
        self.assertEqual(payment.payment_method, 'mpesa')
        self.assertEqual(_get_customer_debt_data(customer, self.biz)['outstanding'], 280.0)

    def test_settle_on_genuinely_fully_paid_tab_stays_idempotent_noop(self):
        """Regression lock: the original no-op branch must keep working for
        a tab that's SETTLED with NOTHING unpaid left (no customer, or a
        genuine fully-paid-off tab) — no debt payment should ever be
        fabricated for a tab that never carried real debt."""
        tab, entry = self._make_tab('Roy', Decimal('480'))
        entry.is_paid = True
        entry.payment_method = 'cash'
        entry.save()
        tab.status = 'SETTLED'
        tab.settled_at = timezone.now()
        tab.save()
        self.client.force_login(self.owner)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertTrue(data.get('already_settled'))
        self.assertFalse(data.get('redirected_to_debt'))
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

    def test_settle_on_void_tab_stays_idempotent_noop(self):
        tab, entry = self._make_tab('Roy', Decimal('480'))
        entry.is_paid = True
        entry.payment_method = 'void'
        entry.transaction.payment_method = 'void'
        entry.transaction.save()
        entry.save()
        tab.status = 'VOID'
        tab.settled_at = timezone.now()
        tab.save()
        self.client.force_login(self.owner)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertTrue(data.get('already_settled'))
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

    def test_settle_redirect_respects_station_scoping(self):
        """A kitchen-only staffer must not be able to redirect a payment
        into a BAR customer's debt via this endpoint, mirroring the
        pre-existing station gate on every other tab-write endpoint."""
        tab, _entry = self._make_tab('Roy', Decimal('480'), source='bar')
        self._convert(tab)
        self.client.force_login(self.kitchen_staff)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        self.assertEqual(resp.status_code, 403)
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

    def test_settle_redirect_rejects_invalid_amount(self):
        tab, _entry = self._make_tab('Roy', Decimal('480'))
        self._convert(tab)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash', 'amount': '0'})
        self.assertEqual(resp.status_code, 400)
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

        resp = self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash', 'amount': 'abc'})
        self.assertEqual(resp.status_code, 400)
        self.assertEqual(CustomerDebtPayment.objects.count(), 0)

    def test_settle_redirect_does_not_touch_stock_or_qty(self):
        """Money-position-only correction, same guarantee as
        revert_tab_from_debt — the item already left the shelf when it was
        first sold on the tab, completely independent of debt conversion
        or how that debt later gets paid off."""
        tab, entry = self._make_tab('Roy', Decimal('480'))
        original_qty = entry.transaction.qty
        self._convert(tab)
        self.client.post(f'/bar/tabs/{tab.id}/settle/', {'payment_method': 'cash'})
        entry.refresh_from_db()
        self.assertEqual(entry.transaction.qty, original_qty)


class DoSettleDebtPaymentTransactionSyncTest(TestCase):
    """2026-08-14 live report (Roy, via `audit_debt_ledger_integrity
    --all-customers` against real production data): dozens of real
    transactions across many real customers, all `payment_method='credit'`
    despite their own `BarTabEntry.is_paid=True` (settled via mpesa/cash on
    a real, dated tab). Root cause: `_do_settle_debt_payment()`'s "FIFO
    BarTabEntry reconciliation" block — which fires whenever a debt payment
    fully covers an entry on a tab that's already been converted to debt —
    used a bulk `BarTabEntry.objects.filter(...).update(...)` that only
    ever touched the `BarTabEntry` row, never the `Transaction` it points
    at. Every OTHER settle path in this app (`tick_entry`, `settle_tab`,
    `BarTab.settle_entries_amount_locked`, `_settle_tab_from_payment`,
    `_settle_receipt_entries_from_payment`) syncs both together — this was
    the one place that didn't, and it's the single most heavily-used path
    for a business that relies on shift-close auto-convert + later debt-
    tracker payments to close out tabs.

    These tests exercise `_do_settle_debt_payment()` directly (the shared
    core also used by `record_debt_payment`, the M-Pesa debt-payment
    callback, and `settle_tab`'s/`_settle_tab_from_payment`'s own debt-
    redirects — fixing it here covers all of them at once)."""

    def setUp(self):
        self.biz = Business.objects.create(name='Debt Sync Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='ds_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Keg Gold',
            material_no='DS-01', unit='Pcs', selling_price=Decimal('80'),
            cost_price=Decimal('40'),
        )
        self.customer = Customer.objects.create(
            business=self.biz, name='Roy', credit_approved=True,
        )

    def _debt_converted_tab_with_entry(self, amount, date=None):
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Roy', customer=self.customer,
            status='SETTLED', source='bar',
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=amount, payment_method='credit', recipient='Roy',
            **({'date': date} if date else {}),
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Keg Gold', amount=amount,
            is_paid=False,
        )
        return tab, entry, txn

    def test_fully_covered_entry_syncs_transaction_off_credit(self):
        from core.debt_views import _do_settle_debt_payment
        _tab, entry, txn = self._debt_converted_tab_with_entry(Decimal('80'))
        _do_settle_debt_payment(self.customer, self.biz, Decimal('80'), 'mpesa', 'bar')
        entry.refresh_from_db()
        txn.refresh_from_db()
        self.assertTrue(entry.is_paid)
        self.assertEqual(
            txn.payment_method, 'mpesa',
            'a fully-covered entry must sync its own Transaction to the real '
            'payment method, not leave it stuck on credit',
        )

    def test_partially_covered_entry_is_never_marked_paid_or_synced(self):
        from core.debt_views import _do_settle_debt_payment
        _tab, entry, txn = self._debt_converted_tab_with_entry(Decimal('80'))
        _do_settle_debt_payment(self.customer, self.biz, Decimal('50'), 'cash', 'bar')
        entry.refresh_from_db()
        txn.refresh_from_db()
        self.assertFalse(entry.is_paid, 'a partial payment must never mark the entry fully paid')
        self.assertEqual(txn.payment_method, 'credit', 'an uncovered entry must stay credit')

    def test_fifo_across_multiple_entries_syncs_only_the_covered_ones(self):
        # Reproduces the real pattern from Roy's own data: several separate
        # debt-converted tabs/entries for one customer, one payment that
        # covers the oldest ones (FIFO, by date) but not all of them.
        from core.debt_views import _do_settle_debt_payment
        _t1, e1, txn1 = self._debt_converted_tab_with_entry(Decimal('80'), date=date(2026, 8, 1))
        _t2, e2, txn2 = self._debt_converted_tab_with_entry(Decimal('80'), date=date(2026, 8, 5))
        _t3, e3, txn3 = self._debt_converted_tab_with_entry(Decimal('80'), date=date(2026, 8, 9))

        _do_settle_debt_payment(self.customer, self.biz, Decimal('160'), 'mpesa', 'bar')

        e1.refresh_from_db(); e2.refresh_from_db(); e3.refresh_from_db()
        txn1.refresh_from_db(); txn2.refresh_from_db(); txn3.refresh_from_db()

        self.assertTrue(e1.is_paid)
        self.assertEqual(txn1.payment_method, 'mpesa')
        self.assertTrue(e2.is_paid)
        self.assertEqual(txn2.payment_method, 'mpesa')
        # The 08-09 entry (newest, oldest-first FIFO leaves it for last) must
        # stay genuinely unpaid and untouched — exactly Roy's own real KES
        # 320 outstanding, dated 08-09, from the live report.
        self.assertFalse(e3.is_paid)
        self.assertEqual(txn3.payment_method, 'credit')

    def test_open_tab_entry_never_touched_by_debt_reconciliation(self):
        # Only SETTLED (debt-converted) tabs are in scope for this
        # reconciliation — a still-OPEN tab's entries are a completely
        # separate, unrelated running bill and must never be marked paid by
        # someone else's debt payment.
        from core.debt_views import _do_settle_debt_payment
        open_tab = BarTab.objects.create(
            business=self.biz, customer_name='Roy', customer=self.customer,
            status='OPEN', source='bar',
        )
        open_txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('80'), payment_method='credit', recipient='Roy',
        )
        open_entry = BarTabEntry.objects.create(
            tab=open_tab, transaction=open_txn, description='Keg Gold',
            amount=Decimal('80'), is_paid=False,
        )
        _do_settle_debt_payment(self.customer, self.biz, Decimal('1000'), 'cash', 'bar')
        open_entry.refresh_from_db()
        self.assertFalse(open_entry.is_paid, "an OPEN tab's own entries are not debt yet")


class RevertDebtPaymentTest(TestCase):
    """2026-08-18 live request (Roy): "create a way for the business user
    ... to revert recorded debt back to the status it was before ... staff
    recorded a debt mistakenly when it was not paid for ... make sure the
    accounts for that day adjust accordingly." A recorded CustomerDebtPayment
    can now be soft-reverted (never hard-deleted — matches this app's
    correction convention) by the owner, or by a manager/staff member
    explicitly granted can_revert_debt_payment. Restores the customer's
    outstanding balance and rebuilds tab-linked entry state by replaying
    every remaining payment, which then automatically flows through to
    every live-computed accounting figure (till_expected_cash,
    shift_views._reconcile, credit_policy scoring, haki contribution) since
    none of them cache — see revert_debt_payment()'s own docstring for the
    full swept list."""

    def setUp(self):
        from core.models import CustomerDebtPayment
        self.CustomerDebtPayment = CustomerDebtPayment
        self.biz = Business.objects.create(name='Revert Debt Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='rdp_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='rdp_manager', password='x')
        self.manager_profile = UserProfile.objects.create(
            user=self.manager, business=self.biz, role='manager',
        )
        self.staff = User.objects.create_user(username='rdp_staff', password='x')
        self.staff_profile = UserProfile.objects.create(
            user=self.staff, business=self.biz, role='staff',
        )
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Keg Gold',
            material_no='RDP-01', unit='Pcs', selling_price=Decimal('80'),
            cost_price=Decimal('40'),
        )
        self.customer = Customer.objects.create(
            business=self.biz, name='Roy', credit_approved=True,
        )

    def _debt_converted_tab_with_entry(self, amount, day=None):
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Roy', customer=self.customer,
            status='SETTLED', source='bar',
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=amount, payment_method='credit', recipient='Roy',
            **({'date': day} if day else {}),
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Keg Gold', amount=amount,
            is_paid=False,
        )
        return tab, entry, txn

    # ── Permission gate ──────────────────────────────────────────────────

    def test_owner_always_allowed(self):
        from core.debt_views import _do_settle_debt_payment
        _do_settle_debt_payment(self.customer, self.biz, Decimal('100'), 'cash', 'bar')
        payment = self.CustomerDebtPayment.objects.get(customer=self.customer)
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/payment/{payment.id}/revert/', {'reason': 'mistake'})
        self.assertTrue(resp.json()['ok'], resp.json())

    def test_staff_without_toggle_blocked(self):
        from core.debt_views import _do_settle_debt_payment
        _do_settle_debt_payment(self.customer, self.biz, Decimal('100'), 'cash', 'bar')
        payment = self.CustomerDebtPayment.objects.get(customer=self.customer)
        self.client.force_login(self.staff)
        resp = self.client.post(f'/debt/payment/{payment.id}/revert/', {'reason': 'mistake'})
        self.assertEqual(resp.status_code, 403)
        payment.refresh_from_db()
        self.assertFalse(payment.reverted)

    def test_manager_without_toggle_blocked(self):
        from core.debt_views import _do_settle_debt_payment
        _do_settle_debt_payment(self.customer, self.biz, Decimal('100'), 'cash', 'bar')
        payment = self.CustomerDebtPayment.objects.get(customer=self.customer)
        self.client.force_login(self.manager)
