class ItemBalanceJourneyTest(TestCase):
    """2026-08-21 urgent live request (Roy, Monsoon Inn): "I need to see
    balances standing at a certain point when a specific transactional
    function was happening, and 2 the user responsible per action" — the
    same Dallas-bottle investigation, widened into a permanent, per-item
    capability rather than a one-off diagnostic. Item.balance_journey() is
    the single canonical computation; item_detail() (/stock/<id>/) is the
    UI surface."""

    def setUp(self):
        self.biz = Business.objects.create(name='Journey Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='jrn_owner', password='x', first_name='Roy')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='jrn_staff', password='x', first_name='Bosco')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Dallas',
            material_no='JRN-01', unit='250ml', selling_price=Decimal('200'),
            cost_price=Decimal('80'), opening_bin_balance=0,
        )

    def test_running_balance_matches_current_balance_at_the_end(self):
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('16'),
            recorded_by=self.owner, created_at=timezone.now() - timedelta(hours=2),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-3'),
            recorded_by=self.staff, payment_method='cash', created_at=timezone.now() - timedelta(hours=1),
        )
        journey = self.item.balance_journey()
        self.assertEqual(len(journey), 2)
        self.assertEqual(journey[0]['running_balance'], Decimal('16'))
        self.assertEqual(journey[1]['running_balance'], Decimal('13'))
        self.assertEqual(journey[-1]['running_balance'], self.item.current_balance())

    def test_journey_ordered_chronologically_regardless_of_creation_order(self):
        later = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            created_at=timezone.now(),
        )
        earlier = Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('5'),
            created_at=timezone.now() - timedelta(hours=5),
        )
        journey = self.item.balance_journey()
        self.assertEqual(journey[0]['txn'].id, earlier.id)
        self.assertEqual(journey[1]['txn'].id, later.id)

    def test_item_detail_shows_running_balance_and_recorded_by(self):
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('16'),
            recorded_by=self.owner,
        )
        self.client.force_login(self.owner)
        resp = self.client.get(f'/item/{self.item.id}/')
        self.assertContains(resp, 'Roy')
        self.assertContains(resp, '16')
        self.assertContains(resp, 'Safari ya Bidhaa')

    def test_item_detail_default_order_is_newest_first(self):
        first = Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('16'),
            created_at=timezone.now() - timedelta(hours=2),
        )
        second = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-3'),
            created_at=timezone.now() - timedelta(hours=1), payment_method='cash',
        )
        self.client.force_login(self.owner)
        resp = self.client.get(f'/item/{self.item.id}/')
        # Newest (second) should render before the oldest (first) in the
        # default (desc) order — check ordering via the journey context list.
        journey = resp.context['journey']
        self.assertEqual(journey[0]['txn'].id, second.id)
        self.assertEqual(journey[1]['txn'].id, first.id)

    def test_item_detail_order_asc_reverses_to_oldest_first(self):
        first = Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('16'),
            created_at=timezone.now() - timedelta(hours=2),
        )
        second = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-3'),
            created_at=timezone.now() - timedelta(hours=1), payment_method='cash',
        )
        self.client.force_login(self.owner)
        resp = self.client.get(f'/item/{self.item.id}/?order=asc')
        journey = resp.context['journey']
        self.assertEqual(journey[0]['txn'].id, first.id)
        self.assertEqual(journey[1]['txn'].id, second.id)

    def test_no_transactions_shows_empty_state(self):
        self.client.force_login(self.owner)
        resp = self.client.get(f'/item/{self.item.id}/')
        self.assertEqual(resp.context['journey'], [])
        self.assertContains(resp, 'No transactions recorded')

    def test_null_recorded_by_shows_dash(self):
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('16'),
            recorded_by=None,
        )
        self.client.force_login(self.owner)
        resp = self.client.get(f'/item/{self.item.id}/')
        self.assertEqual(resp.status_code, 200)

    def test_cross_business_item_not_reachable(self):
        other_biz = Business.objects.create(name='Other Journey Biz')
        other_store = Store.objects.create(business=other_biz, name='Bar')
        other_item = Item.objects.create(
            business=other_biz, store=other_store, description='Foreign',
            material_no='OJ-01', unit='Pcs', selling_price=Decimal('100'),
        )
        self.client.force_login(self.owner)
        resp = self.client.get(f'/item/{other_item.id}/')
        self.assertEqual(resp.status_code, 404)


class DiagnoseReceiptCommandTest(TestCase):
    """2026-08-16 live report (Roy, Monsoon Inn) — a customer's live receipt
    showed an item ('Chrome Gin') they never ordered, already struck through
    as paid. resolve_master_receipt() (core/tab_receipts.py) can link a
    brand-new tab into an EXISTING receipt purely by customer-name string
    match (Priority 3's fallback + all of Priority 4) with no check that the
    two are the same physical person — two different real customers sharing
    a first name can be silently merged onto one shared receipt/PIN. This
    read-only diagnostic dumps a receipt's real linked-tab data so that can
    be confirmed from facts rather than guessed at. Must never mutate."""

    def setUp(self):
        self.biz = Business.objects.create(name='Diagnose Receipt Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Chrome Gin 250ML',
            material_no='DRB-01', unit='Pcs', selling_price=Decimal('150'), cost_price=Decimal('80'),
        )

    def _make_tab_with_entry(self, customer_name, customer=None, is_paid=False, amount='150'):
        tab = BarTab.objects.create(
            business=self.biz, customer_name=customer_name, customer=customer, status='OPEN',
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal(amount), payment_method=('mpesa' if is_paid else 'credit'),
            recipient=customer_name,
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description=self.item.description,
            amount=Decimal(amount), is_paid=is_paid,
        )
        return tab

    def test_flags_two_different_customer_records_linked_to_one_receipt(self):
        """Reproduces the exact live scenario: an earlier, already-paid,
        unrelated 'Peter' sale and a brand-new 'Peter' tab end up sharing one
        receipt because they merely share a name string — the command must
        surface this as the likely cause, not stay silent."""
        peter_a = Customer.objects.create(business=self.biz, name='Peter')
        peter_b = Customer.objects.create(business=self.biz, name='Peter')
        old_tab = self._make_tab_with_entry('Peter', customer=peter_a, is_paid=True)
        new_tab = self._make_tab_with_entry('Peter', customer=peter_b, is_paid=False)

        from core.models import Receipt
        receipt = Receipt.objects.create(
            business=self.biz, receipt_number=705, token='dr-tok-1',
            total=Decimal('150'), customer_name='Peter', payment_method='mpesa',
            meta={'tab_id': old_tab.id, 'linked_tab_ids': [new_tab.id]},
        )

        from io import StringIO
        from django.core.management import call_command
        before_txn_count = Transaction.objects.count()
        before_tab_count = BarTab.objects.count()

        out = StringIO()
        call_command('diagnose_receipt', business='Diagnose Receipt', receipt=705, stdout=out)
        output = out.getvalue()

        self.assertIn('DIFFERENT Customer records', output)
        self.assertIn(str(old_tab.id), output)
        self.assertIn(str(new_tab.id), output)
        self.assertIn('Chrome Gin', output)
        self.assertEqual(Transaction.objects.count(), before_txn_count)
        self.assertEqual(BarTab.objects.count(), before_tab_count)

    def test_single_genuine_customer_does_not_flag_a_mismatch(self):
        """Both tabs resolve to the SAME Customer record — must not be
        flagged as a merge error."""
        peter = Customer.objects.create(business=self.biz, name='Peter')
        tab1 = self._make_tab_with_entry('Peter', customer=peter, is_paid=True)
        tab2 = self._make_tab_with_entry('Peter', customer=peter, is_paid=False)

        from core.models import Receipt
        Receipt.objects.create(
            business=self.biz, receipt_number=706, token='dr-tok-2',
            total=Decimal('150'), customer_name='Peter', payment_method='mpesa',
            meta={'tab_id': tab1.id, 'linked_tab_ids': [tab2.id]},
        )

        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command('diagnose_receipt', business='Diagnose Receipt', receipt=706, stdout=out)
        output = out.getvalue()
        self.assertNotIn('DIFFERENT Customer records', output)

    def test_lookup_by_token(self):
        from core.models import Receipt
        Receipt.objects.create(
            business=self.biz, receipt_number=707, token='dr-tok-3',
            total=Decimal('0'), customer_name='Solo',
        )
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command('diagnose_receipt', business='Diagnose Receipt', token='dr-tok-3', stdout=out)
        self.assertIn('#707', out.getvalue())

    def test_no_matching_receipt_does_not_crash(self):
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command('diagnose_receipt', business='Diagnose Receipt', receipt=999, stdout=out)
        self.assertIn('No matching receipt', out.getvalue())

    def test_neither_receipt_nor_token_errors_cleanly(self):
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command('diagnose_receipt', business='Diagnose Receipt', stdout=out)
        self.assertIn('--receipt', out.getvalue())


class UnlinkTabFromReceiptCommandTest(TestCase):
    """2026-08-16 correction tool, requested by Roy right after the
    resolve_master_receipt/_sync_master_receipt_customer_name fixes shipped
    — those stop FUTURE merges but do nothing for an already-wrongly-linked
    receipt like the real, confirmed Receipt #705 (Monsoon Inn). Detaches
    one BarTab from a receipt's linked_tab_ids and gives it a fresh
    standalone receipt built from its own real entries."""

    def setUp(self):
        self.biz = Business.objects.create(name='Unlink Tab Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.chrome_gin = Item.objects.create(
            business=self.biz, store=self.store, description='Chrome Gin 250ML',
            material_no='UTB-01', unit='Pcs', selling_price=Decimal('150'),
        )
        self.kc = Item.objects.create(
            business=self.biz, store=self.store, description='KC Smooth 750ML',
            material_no='UTB-02', unit='Pcs', selling_price=Decimal('1100'),
        )

        self.peter_a = Customer.objects.create(business=self.biz, name='Peter')
        self.peter_b = Customer.objects.create(business=self.biz, name='Peter')

        self.old_tab = BarTab.objects.create(
            business=self.biz, customer_name='Peter', customer=self.peter_a,
            status='SETTLED', tab_pin='8054',
        )
        old_txn = Transaction.objects.create(
            business=self.biz, item=self.chrome_gin, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('150'), payment_method='mpesa', recipient='Peter',
        )
        BarTabEntry.objects.create(
            tab=self.old_tab, transaction=old_txn, description='Chrome Gin 250ML',
            amount=Decimal('150'), is_paid=True, payment_method='mpesa',
        )
        self.old_receipt = Receipt.objects.create(
            business=self.biz, receipt_number=705, token='ut-old-tok',
            customer_name='Peter', payment_method='mpesa', total=Decimal('150'),
            meta={'tab_id': self.old_tab.id, 'linked_tab_ids': []},
        )

        self.new_tab = BarTab.objects.create(
            business=self.biz, customer_name='Peter', customer=self.peter_b,
            status='OPEN', tab_pin='5407',
        )
        new_txn = Transaction.objects.create(
            business=self.biz, item=self.kc, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('1100'), payment_method='', recipient='Peter',
        )
        BarTabEntry.objects.create(
            tab=self.new_tab, transaction=new_txn, description='KC Smooth 750ML',
            amount=Decimal('1100'), is_paid=False,
        )
        # The wrongful merge itself — exactly what the old, unfixed code did.
        self.old_receipt.meta['linked_tab_ids'] = [self.new_tab.id]
        self.old_receipt.save(update_fields=['meta'])

    def test_dry_run_writes_nothing(self):
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command(
            'unlink_tab_from_receipt', business='Unlink Tab', receipt=705,
            tab=self.new_tab.id, dry_run=True, stdout=out,
        )
        self.assertIn('DRY RUN', out.getvalue())
        self.old_receipt.refresh_from_db()
        self.assertIn(self.new_tab.id, self.old_receipt.meta.get('linked_tab_ids', []))
        self.assertEqual(Receipt.objects.filter(business=self.biz).count(), 1)

    def test_unlink_detaches_tab_and_creates_standalone_receipt(self):
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command(
            'unlink_tab_from_receipt', business='Unlink Tab', receipt=705,
            tab=self.new_tab.id, stdout=out,
        )
        self.assertIn('unlinked', out.getvalue())

        self.old_receipt.refresh_from_db()
        self.assertNotIn(self.new_tab.id, self.old_receipt.meta.get('linked_tab_ids', []))
        self.assertEqual(self.old_receipt.meta.get('tab_id'), self.old_tab.id)
        # The old receipt itself must be completely untouched otherwise.
        self.assertEqual(self.old_receipt.total, Decimal('150'))
        self.assertEqual(self.old_receipt.customer_name, 'Peter')

        new_rcpt = Receipt.objects.filter(business=self.biz).exclude(id=self.old_receipt.id).first()
        self.assertIsNotNone(new_rcpt)
        self.assertEqual(new_rcpt.meta.get('tab_id'), self.new_tab.id)
        self.assertEqual(new_rcpt.customer_name, 'Peter')
        self.assertEqual(new_rcpt.payment_method, 'tab')
        self.assertEqual(new_rcpt.total, Decimal('1100'))
        self.assertEqual(len(new_rcpt.lines), 1)
        self.assertEqual(new_rcpt.lines[0]['name'], 'KC Smooth 750ML')

    def test_public_url_resolution_now_points_to_the_new_receipt(self):
        from django.core.management import call_command
        from core.keg_views import _resolve_tab_public_url
        call_command('unlink_tab_from_receipt', business='Unlink Tab', receipt=705, tab=self.new_tab.id)
        new_rcpt = Receipt.objects.filter(business=self.biz).exclude(id=self.old_receipt.id).first()
        self.assertEqual(_resolve_tab_public_url(self.new_tab), f'/r/{new_rcpt.token}/')
        # The old tab's own resolution is completely unaffected.
        self.assertEqual(_resolve_tab_public_url(self.old_tab), f'/r/{self.old_receipt.token}/')

    def test_refuses_to_unlink_the_receipts_own_primary_tab(self):
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command(
            'unlink_tab_from_receipt', business='Unlink Tab', receipt=705,
            tab=self.old_tab.id, stdout=out,
        )
        self.assertIn('OWN primary tab', out.getvalue())
        self.old_receipt.refresh_from_db()
        self.assertEqual(self.old_receipt.meta.get('tab_id'), self.old_tab.id)
        self.assertEqual(Receipt.objects.filter(business=self.biz).count(), 1)

    def test_refuses_when_tab_not_linked_at_all(self):
        from io import StringIO
        from django.core.management import call_command
        unrelated_tab = BarTab.objects.create(business=self.biz, customer_name='Nobody', status='OPEN')
        out = StringIO()
        call_command(
            'unlink_tab_from_receipt', business='Unlink Tab', receipt=705,
            tab=unrelated_tab.id, stdout=out,
        )
        self.assertIn('not in this receipt', out.getvalue())
        self.assertEqual(Receipt.objects.filter(business=self.biz).count(), 1)

    def test_lookup_by_token(self):
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command(
            'unlink_tab_from_receipt', business='Unlink Tab', token='ut-old-tok',
            tab=self.new_tab.id, stdout=out,
        )
        self.assertIn('unlinked', out.getvalue())

    def test_no_matching_receipt_does_not_crash(self):
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command(
            'unlink_tab_from_receipt', business='Unlink Tab', receipt=999,
            tab=self.new_tab.id, stdout=out,
        )
        self.assertIn('No matching receipt', out.getvalue())

    def test_ambiguous_business_match_refused(self):
        Business.objects.create(name='Unlink Tab Biz Two')
        from io import StringIO
        from django.core.management import call_command
        out = StringIO()
        call_command(
            'unlink_tab_from_receipt', business='Unlink Tab', receipt=705,
            tab=self.new_tab.id, stdout=out,
        )
        self.assertIn('Ambiguous', out.getvalue())
        self.old_receipt.refresh_from_db()
        self.assertIn(self.new_tab.id, self.old_receipt.meta.get('linked_tab_ids', []))


class BackfillWasCreditRetiredTest(TestCase):
    """2026-08-15, same day it shipped — RETIRED. Live report (Roy, with
    screenshots): running this command resurrected EVERY customer's ENTIRE
    historical tab total as currently owed, including Bosco's own tab
    (already transferred to his Mmiliki section) and every genuinely
    already-cleared debt. Root cause: `tab.customer_id is not null` is NOT
    a reliable "was this genuinely debt" signal — BarTab settle code
    auto-attaches a Customer record to ANY tab the moment it fully settles,
    completely unrelated to real debt conversion (see the 'auto-create
    Customer record on any settlement, not just credit' comment in
    keg_views.py). The command is now a documented no-op; see
    revert_bad_was_credit_backfill for the undo."""

    def setUp(self):
        self.biz = Business.objects.create(name='Retired Backfill Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Keg Gold',
            material_no='RB-01', unit='Pcs', selling_price=Decimal('80'), cost_price=Decimal('40'),
        )
        self.customer = Customer.objects.create(business=self.biz, name='Eugene')

    def test_command_is_a_documented_noop(self):
        from io import StringIO
        from django.core.management import call_command

        tab = BarTab.objects.create(
            business=self.biz, customer_name='Eugene', customer=self.customer,
            status='SETTLED', source='bar',
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('80'), payment_method='cash', recipient='Eugene',
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Keg Gold', amount=Decimal('80'), is_paid=True,
        )

        out = StringIO()
        call_command('backfill_was_credit', stdout=out)
        txn.refresh_from_db()
        self.assertFalse(txn.was_credit, 'retired command must never touch anything')
        self.assertIn('retired', out.getvalue().lower())


class RevertBadWasCreditBackfillTest(TestCase):
    """2026-08-15 emergency undo, built and shipped the same session the
    over-broad backfill was caught doing real damage on Roy's live
    production data. Clears was_credit for every transaction matching the
    same over-broad signal the retired command used, restoring the debt
    tracker to a sane state."""

    def setUp(self):
        self.biz = Business.objects.create(name='Revert Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Keg Gold',
            material_no='RV-01', unit='Pcs', selling_price=Decimal('80'), cost_price=Decimal('40'),
        )
        self.customer = Customer.objects.create(business=self.biz, name='Eugene')

    def _ordinary_settled_tab_txn(self):
        """The exact shape the bad backfill wrongly resurrected: a tab that
        settled completely normally (cash, same visit) — never real debt —
        but STILL ends up with tab.customer set, per BarTab's own
        auto-create-Customer-on-any-settlement behavior."""
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Eugene', customer=self.customer,
            status='SETTLED', source='bar',
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('80'), payment_method='cash', recipient='Eugene',
            was_credit=True,  # simulates the bad backfill's damage directly
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Keg Gold', amount=Decimal('80'), is_paid=True,
        )
        return txn

    def test_reverts_the_wrongly_stamped_ordinary_tab_transaction(self):
        from io import StringIO
        from django.core.management import call_command

        txn = self._ordinary_settled_tab_txn()
        self.assertTrue(txn.was_credit)

        out = StringIO()
        call_command('revert_bad_was_credit_backfill', stdout=out)
        txn.refresh_from_db()
        self.assertFalse(txn.was_credit)
        self.assertIn('Reverted', out.getvalue())

    def test_reverting_clears_the_field_even_though_a_second_fix_also_protects_outstanding(self):
        """The debt tracker's own outstanding computation was independently
        hardened the same day (is_paid is now authoritative for a tab-linked
        transaction, see _get_customer_debt_data) — an is_paid=True entry is
        correctly excluded regardless of was_credit, so 'outstanding' reads
        0.0 even BEFORE this revert runs. This test locks in what the revert
        command itself is actually responsible for: clearing the was_credit
        field, which still matters on its own (e.g. for a tab-less direct
        credit sale, where no is_paid flag exists to fall back on)."""
        from io import StringIO
        from django.core.management import call_command
        from core.debt_views import _get_customer_debt_data

        txn = self._ordinary_settled_tab_txn()
        data_before = _get_customer_debt_data(self.customer, self.biz)
        self.assertEqual(data_before['outstanding'], 0.0, 'is_paid=True already protects this independently')
        self.assertTrue(txn.was_credit)

        call_command('revert_bad_was_credit_backfill', stdout=StringIO())
        txn.refresh_from_db()
        self.assertFalse(txn.was_credit)
        data_after = _get_customer_debt_data(self.customer, self.biz)
        self.assertEqual(data_after['outstanding'], 0.0)

    def test_dry_run_changes_nothing(self):
        from io import StringIO
        from django.core.management import call_command

        txn = self._ordinary_settled_tab_txn()
        out = StringIO()
        call_command('revert_bad_was_credit_backfill', '--dry-run', stdout=out)
        txn.refresh_from_db()
        self.assertTrue(txn.was_credit)
        self.assertIn('DRY RUN', out.getvalue())

    def test_leaves_a_tab_less_direct_credit_sale_untouched(self):
        """Population-B (no tab at all) was_credit=True stamps are NEVER
        touched by this revert — they were never part of the bad backfill's
        query (which required a tab_entry) and remain correctly protected."""
        from io import StringIO
        from django.core.management import call_command

        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash', recipient='Eugene',
            was_credit=True,
        )
        call_command('revert_bad_was_credit_backfill', stdout=StringIO())
        txn.refresh_from_db()
        self.assertTrue(txn.was_credit)

    def test_idempotent_rerun_is_safe(self):
        from io import StringIO
        from django.core.management import call_command

        self._ordinary_settled_tab_txn()
        call_command('revert_bad_was_credit_backfill', stdout=StringIO())
        out2 = StringIO()
        call_command('revert_bad_was_credit_backfill', stdout=out2)
        self.assertIn('Reverted was_credit on 0 transaction', out2.getvalue())


class DebtConvertedTabsPanelPaymentExclusionTest(TestCase):
    """2026-07-31 live report (Roy): "when the debt payment is recorded,
    the order goes back to the tabs drawer it came from... showing that
    payment was not recorded, or as if it was not just from the debt
    tracker." Root cause: BarTab.unpaid_total() reads only
    BarTabEntry.is_paid, a per-LINE-ITEM flag that only flips once a
    payment has cumulatively covered a line's FULL original amount (see
    _get_customer_debt_data's FIFO walk in core/debt_views.py). A real
    debt-tracker payment (partial OR — depending on timing — even full)
    reduces the customer's TRUE aggregate outstanding balance immediately,
    but the "↩️ Marejesho ya Deni" (revert-from-debt) panel kept showing
    the tab with its stale, un-reduced unpaid_total() regardless, because
    its query (_debt_converted_tabs_qs) only checked for the EXISTENCE of
    an unpaid entry, never whether a payment had actually landed against
    it. Fixed by excluding any tab with a CustomerDebtPayment recorded
    since settled_at — the same condition revert_tab_from_debt itself
    already uses to refuse a revert, so panel visibility and revert
    possibility can never drift apart again."""

    def setUp(self):
        self.biz = Business.objects.create(name='Debt Panel Exclusion Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='dpe_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Debt Panel Item',
            material_no='DPE-01', selling_price=Decimal('500'), cost_price=Decimal('200'),
        )
        self.tab = BarTab.objects.create(
            business=self.biz, customer_name='Roy', status='OPEN', source='bar', store=self.store,
        )
        self.txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('500'), payment_method='credit',
        )
        self.entry = BarTabEntry.objects.create(
            tab=self.tab, transaction=self.txn, description=self.item.description,
            amount=Decimal('500'), is_paid=False,
        )
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{self.tab.id}/debt/', {'customer_name': 'Roy'})
        self.tab.refresh_from_db()
        self.assertEqual(self.tab.status, 'SETTLED')

    def test_panel_shows_freshly_converted_tab(self):
        resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        ids = [t['id'] for t in resp.json()['tabs']]
        self.assertIn(self.tab.id, ids)

    def test_partial_debt_payment_drops_tab_from_panel_immediately(self):
        """The exact live scenario Roy reported: a genuine partial payment
        recorded via the debt tracker — before this fix, the panel kept
        showing the tab with its FULL original 500, unchanged."""
        customer = Customer.objects.get(business=self.biz, name='Roy')
        resp = self.client.post(f'/debt/{customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'cash',
            'idempotency_token': 'dpe-partial-1',
        })
        self.assertEqual(resp.status_code, 302)

        panel_resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        ids = [t['id'] for t in panel_resp.json()['tabs']]
        self.assertNotIn(
            self.tab.id, ids,
            "tab still shown as revertible/unpaid after a real partial payment",
        )

        # The debt tracker's own aggregate is correctly reduced — proves
        # the payment really was recorded, it just wasn't reflected in the
        # per-line is_paid flag this panel used to rely on.
        from core.debt_views import _get_customer_debt_data
        data = _get_customer_debt_data(customer, self.biz)
        self.assertEqual(data['outstanding'], 300.0)

    def test_full_debt_payment_drops_tab_from_panel(self):
        customer = Customer.objects.get(business=self.biz, name='Roy')
        resp = self.client.post(f'/debt/{customer.id}/payment/', {
            'amount_paid': '500', 'payment_method': 'mpesa',
            'idempotency_token': 'dpe-full-1',
        })
        self.assertEqual(resp.status_code, 302)

        panel_resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        ids = [t['id'] for t in panel_resp.json()['tabs']]
        self.assertNotIn(self.tab.id, ids)

        self.entry.refresh_from_db()
        self.assertTrue(self.entry.is_paid)

    def test_unpaid_tab_still_correctly_blocks_revert_after_exclusion_fix(self):
        """Sanity check the two mechanisms stay in sync: a tab with no
        payment yet is still both listed AND revertible."""
        panel_resp = self.client.get('/bar/tabs/debt-converted/?station=bar')
        self.assertIn(self.tab.id, [t['id'] for t in panel_resp.json()['tabs']])
        revert_resp = self.client.post(f'/bar/tabs/{self.tab.id}/revert-debt/')
        self.assertTrue(revert_resp.json()['ok'])


class TabToDebtConversionCreditRiskNotificationTest(TestCase):
    """New: a tab-to-debt conversion that adds MORE debt for an already
    credit-risky customer (revoked/permanent defaulter/etc.) now fires a
    non-blocking heads-up Notification to owners/managers — previously this
    was completely invisible, at all three conversion sites (single tab,
    bulk, and shift-close auto-convert)."""

    def setUp(self):
        self.biz = Business.objects.create(
            name='Convert Debt Risk Biz', credit_policy_enabled=True, defaulter_permanent=True,
        )
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='convrisk_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Convert Risk Item',
            material_no='CONVRISK-01', selling_price=Decimal('100'),
        )
        self.risky = Customer.objects.create(
            business=self.biz, name='Risky Patron', credit_approved=True, is_defaulter=True,
        )
        self.client.force_login(self.owner)

    def _make_tab(self, customer_name):
        tab = BarTab.objects.create(business=self.biz, customer_name=customer_name, status='OPEN')
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='tab',
        )
        BarTabEntry.objects.create(tab=tab, transaction=txn, description='Convert Risk Item', amount=Decimal('100'))
        return tab

    def test_single_tab_conversion_notifies_owner_for_risky_customer(self):
        tab = self._make_tab('Risky Patron')
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Risky Patron'})
        self.assertTrue(
            Notification.objects.filter(user=self.owner, title__icontains='Hatari ya mkopo').exists()
        )

    def test_bulk_conversion_notifies_owner_for_risky_customer(self):
        import json
        tab = self._make_tab('Risky Patron')
        self.client.post('/bar/tabs/bulk-convert-to-debt/', {'tab_ids': json.dumps([tab.id])})
        self.assertTrue(
            Notification.objects.filter(user=self.owner, title__icontains='Hatari ya mkopo').exists()
        )

    def test_shift_close_auto_convert_notifies_owner_for_risky_customer(self):
        from core.shift_views import _convert_open_tabs_to_debt_for_shift
        tab = self._make_tab('Risky Patron')
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.owner,
            status='OPEN', opening_float=Decimal('0'),
        )
        _convert_open_tabs_to_debt_for_shift(shift, self.biz, True)
        self.assertTrue(
            Notification.objects.filter(user=self.owner, title__icontains='Hatari ya mkopo').exists()
        )

    def test_no_notification_for_clean_customer(self):
        clean = Customer.objects.create(business=self.biz, name='Clean Patron', credit_approved=True)
        tab = self._make_tab('Clean Patron')
        self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': 'Clean Patron'})
        self.assertFalse(
            Notification.objects.filter(user=self.owner, title__icontains='Hatari ya mkopo').exists()
        )


class ApproveWriteOffSetsDefaulterTest(TestCase):
    """approve_write_off (an unrecoverable, uncollectable credit loss — the
    business eats it) never set Customer.is_defaulter=True, unlike the
    equally-final void_tab path. Both mean the same thing for the customer's
    future credit standing: this debt was never repaid."""

    def setUp(self):
        self.biz = Business.objects.create(name='WO Defaulter Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='wodef_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='WO Defaulter Item',
            material_no='WODEF-01', selling_price=Decimal('100'),
        )
        self.customer = Customer.objects.create(business=self.biz, name='WO Patron', credit_approved=True)
        self.txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), recipient='WO Patron',
            payment_method='credit', sale_amount=Decimal('100'),
        )
        from core.models import WriteOffRequest
        self.wo = WriteOffRequest.objects.create(
            transaction=self.txn, requested_by=self.owner, reason='test',
            customer_name_cache='WO Patron',
        )
        self.client.force_login(self.owner)

    def test_approval_marks_customer_as_defaulter(self):
        self.client.post(f'/debt/write-off/{self.wo.id}/approve/')
        self.customer.refresh_from_db()
        self.assertTrue(self.customer.is_defaulter)


class WriteOffApprovalExplainsItselfTest(TestCase):
    """2026-07-24 wording/accountability audit: approve_write_off()'s JSON response
    was missing a `message` key entirely (reject_write_off already had one — the
    owner-facing JS already did `d.message || 'Imeidhinishwa.'` and was silently
    falling back to the generic text on every single approval). Separately,
    _mark_receipt_write_off() used to just hide the matching receipt line with
    zero trace — now it's marked with a written_off_at timestamp so the customer's
    own receipt can explain, not just erase, what happened to that item."""

    def setUp(self):
        from core.models import WriteOffRequest, Receipt
        self.WriteOffRequest = WriteOffRequest

        self.biz = Business.objects.create(name='WO Explains Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='woexpl_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='WO Explains Item',
            material_no='WOEXPL-01', selling_price=Decimal('250'),
        )
        self.txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), recipient='WO Explains Patron',
            payment_method='credit', sale_amount=Decimal('250'),
        )
        self.wo = WriteOffRequest.objects.create(
            transaction=self.txn, requested_by=self.owner, reason='test',
            customer_name_cache='WO Explains Patron',
        )
        self.receipt = Receipt.issue(
            business=self.biz,
            lines=[{'name': 'WO Explains Item', 'subtotal': 250.0, 'qty': 1}],
            payment_method='credit', customer_name='WO Explains Patron',
        )
        self.client.force_login(self.owner)

    def test_approve_response_includes_reasoning_message(self):
        resp = self.client.post(f'/debt/write-off/{self.wo.id}/approve/')
        data = resp.json()
        self.assertTrue(data['ok'])
        self.assertIn('message', data)
        self.assertIn('250', data['message'])
        self.assertIn('WO Explains Item', data['message'])
        self.assertIn('WO Explains Patron', data['message'])

    def test_receipt_write_off_marker_includes_timestamp(self):
        self.client.post(f'/debt/write-off/{self.wo.id}/approve/')
        self.receipt.refresh_from_db()
        wo_list = self.receipt.meta.get('write_offs', [])
        self.assertEqual(len(wo_list), 1)
        self.assertIn('written_off_at', wo_list[0])
        self.assertTrue(wo_list[0]['written_off_at'])


class RecordBreakageExplainsItselfTest(TestCase):
    """2026-07-24 wording/accountability audit: record_breakage() used to return a
    bare {"ok": True} with no reasoning trail and never notified the owner/manager
    at all — a real stock/money loss event visible only to the staffer who
    recorded it. Also fixed: 'Item not found' / 'Invalid quantity' were English-only
    in an otherwise all-Swahili flow."""

    def setUp(self):
        self.biz = Business.objects.create(name='Breakage Wording Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='brkword_owner', password='x')
