class TransferAcceptClosesEmptySourceTabTest(TestCase):
    """2026-07-25 live report (Monsoon Inn): after a split-bill or whole-tab
    transfer was accepted AND paid, the source tab (nothing left to collect)
    stayed status=OPEN forever with a zero balance, lingering in the tabs
    drawer indefinitely. accept() now closes it as VOID (matching the
    existing _merge_tab_into() precedent for an emptied-out tab shell) the
    moment it has no unpaid entries left — but only then, never while a
    genuinely unrelated unpaid entry remains."""

    def setUp(self):
        self.biz = Business.objects.create(name='Transfer Close Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='tc_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='tc_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        Shift.objects.create(business=self.biz, staff=self.staff, status='OPEN')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Close Tusker',
            material_no='TC-01', unit='Pcs', selling_price=Decimal('250'),
        )
        self.roy_tab = BarTab.objects.create(
            business=self.biz, customer_name='Roy', status='OPEN', source='bar', store=self.store,
        )
        self.bosco_tab = BarTab.objects.create(
            business=self.biz, customer_name='Bosco', status='OPEN', source='bar', store=self.store,
        )

    def _make_entry(self, tab, amount):
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method='',
        )
        return BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Close Tusker', amount=amount, is_paid=False,
        )

    def test_full_item_transfer_accept_closes_now_empty_source_tab(self):
        entry = self._make_entry(self.roy_tab, Decimal('250'))
        _e, tfr = BarTabEntry.split_and_transfer_locked(
            entry_id=entry.id, business=self.biz, paid_amount=Decimal('0'),
            paid_method='cash', dest_tab_id=self.bosco_tab.id, staff_user=self.staff,
        )
        tfr.accept()
        self.roy_tab.refresh_from_db()
        self.assertEqual(self.roy_tab.status, 'VOID')
        self.assertIn('Bosco', self.roy_tab.void_reason)

    def test_partial_split_transfer_accept_closes_source_tab_when_paid_portion_covers_rest(self):
        # Roy pays 400 of a 600 entry himself (marked paid, stays on his tab);
        # Bosco covers the remaining 200. Once Bosco accepts, Roy's tab has
        # nothing left UNPAID — it should close even though it still has one
        # (already-paid) entry sitting on it.
        entry = self._make_entry(self.roy_tab, Decimal('600'))
        _new_entry, tfr = BarTabEntry.split_and_transfer_locked(
            entry_id=entry.id, business=self.biz, paid_amount=Decimal('400'),
            paid_method='cash', dest_tab_id=self.bosco_tab.id, staff_user=self.staff,
        )
        tfr.accept()
        self.roy_tab.refresh_from_db()
        self.assertEqual(self.roy_tab.status, 'VOID')

    def test_source_tab_stays_open_when_unrelated_unpaid_entry_remains(self):
        transferred = self._make_entry(self.roy_tab, Decimal('250'))
        unrelated = self._make_entry(self.roy_tab, Decimal('100'))  # a different item, untouched
        _e, tfr = BarTabEntry.split_and_transfer_locked(
            entry_id=transferred.id, business=self.biz, paid_amount=Decimal('0'),
            paid_method='cash', dest_tab_id=self.bosco_tab.id, staff_user=self.staff,
        )
        tfr.accept()
        self.roy_tab.refresh_from_db()
        self.assertEqual(self.roy_tab.status, 'OPEN', 'Must stay open — an unrelated unpaid entry is still there')
        unrelated.refresh_from_db()
        self.assertFalse(unrelated.is_paid)

    def test_whole_tab_transfer_accept_closes_source_tab(self):
        e1 = self._make_entry(self.roy_tab, Decimal('250'))
        e2 = self._make_entry(self.roy_tab, Decimal('150'))
        batch_id, requests = TabTransferRequest.propose_whole_tab_locked(
            source_tab_id=self.roy_tab.id, dest_tab_id=self.bosco_tab.id,
            business=self.biz, staff_user=self.staff,
        )
        requests[0].accept()
        self.roy_tab.refresh_from_db()
        self.assertEqual(self.roy_tab.status, 'VOID')
        self.bosco_tab.refresh_from_db()
        self.assertEqual(
            set(self.bosco_tab.entries.values_list('id', flat=True)), {e1.id, e2.id},
        )

    def test_reject_does_not_close_source_tab(self):
        entry = self._make_entry(self.roy_tab, Decimal('250'))
        _e, tfr = BarTabEntry.split_and_transfer_locked(
            entry_id=entry.id, business=self.biz, paid_amount=Decimal('0'),
            paid_method='cash', dest_tab_id=self.bosco_tab.id, staff_user=self.staff,
        )
        tfr.reject()
        self.roy_tab.refresh_from_db()
        self.assertEqual(self.roy_tab.status, 'OPEN')


class RecentPaymentsSurfacesOpenTabEntryTest(TestCase):
    """2026-07-25 live report (Monsoon Inn): a single entry mistakenly paid
    within an otherwise-still-OPEN, multi-item tab was invisible everywhere
    — renderTabs() hides is_paid=True entries from the tab card by design,
    and the old recent_settled_tabs_api only looked at status='SETTLED'
    tabs, which this one never became (other entries are still unpaid).
    recent_settled_tabs_api now queries paid ENTRIES directly, regardless
    of the parent tab's status."""

    def setUp(self):
        self.biz = Business.objects.create(name='Recent Open Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='ro_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Recent Item',
            material_no='RO-01', unit='Pcs', selling_price=Decimal('100'),
        )
        self.tab = BarTab.objects.create(
            business=self.biz, customer_name='Wanjiku', status='OPEN', source='bar', store=self.store,
        )
        txn_paid = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
        )
        self.paid_entry = BarTabEntry.objects.create(
            tab=self.tab, transaction=txn_paid, description='Recent Item',
            amount=Decimal('100'), is_paid=True, payment_method='cash',
            paid_at=timezone.now(),
        )
        txn_unpaid = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='',
        )
        self.unpaid_entry = BarTabEntry.objects.create(
            tab=self.tab, transaction=txn_unpaid, description='Recent Item',
            amount=Decimal('100'), is_paid=False,
        )
        self.client.force_login(self.owner)

    def test_paid_entry_on_still_open_tab_is_surfaced(self):
        resp = self.client.get('/bar/tabs/recent-settled/')
        data = resp.json()
        self.assertEqual(len(data['tabs']), 1)
        bucket = data['tabs'][0]
        self.assertEqual(bucket['tab_id'], self.tab.id)
        self.assertTrue(bucket['tab_open'])
        entry_ids = {e['id'] for e in bucket['entries']}
        self.assertEqual(entry_ids, {self.paid_entry.id}, 'Only the PAID entry, not the still-unpaid one')

    def test_fully_settled_tab_shows_tab_open_false(self):
        self.tab.status = 'SETTLED'
        self.tab.settled_at = timezone.now()
        self.tab.save(update_fields=['status', 'settled_at'])
        self.unpaid_entry.is_paid = True
        self.unpaid_entry.paid_at = timezone.now()
        self.unpaid_entry.payment_method = 'cash'
        self.unpaid_entry.save(update_fields=['is_paid', 'paid_at', 'payment_method'])

        resp = self.client.get('/bar/tabs/recent-settled/')
        data = resp.json()
        bucket = data['tabs'][0]
        self.assertFalse(bucket['tab_open'])
        self.assertEqual(len(bucket['entries']), 2)

    def test_revoke_still_works_on_the_surfaced_open_tab_entry(self):
        resp = self.client.post(
            f'/bar/tabs/{self.tab.id}/entries/{self.paid_entry.id}/revoke-payment/',
            {'reason': 'Test revoke'},
        )
        self.assertTrue(resp.json()['ok'])
        self.paid_entry.refresh_from_db()
        self.assertFalse(self.paid_entry.is_paid)


class RecentPaymentsDatePickerTest(TestCase):
    """2026-07-25 same-day follow-up (Monsoon Inn): the old rolling 6-hour
    window plus a hard cap of 20 tabs / 100 entries meant staff could only
    ever see "just now" payments, and Roy's own report was "I am only seeing
    a few... unable to see all the paid transactions." recent_settled_tabs_api
    now takes an explicit ?date=YYYY-MM-DD (default: today, LOCAL calendar
    day) with no artificial cap."""

    def setUp(self):
        self.biz = Business.objects.create(name='Recent Date Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='rd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Recent Date Item',
            material_no='RD-01', unit='Pcs', selling_price=Decimal('100'),
        )
        self.client.force_login(self.owner)

    def _paid_entry(self, name, paid_at, amount=Decimal('100')):
        tab = BarTab.objects.create(
            business=self.biz, customer_name=name, status='SETTLED', source='bar', store=self.store,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method='cash',
        )
        return BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Recent Date Item',
            amount=amount, is_paid=True, payment_method='cash', paid_at=paid_at,
        )

    def test_default_date_is_today_not_a_rolling_window(self):
        """An entry paid near the start of today (likely outside the old
        6-hour rolling window) must still show up with no date param, since
        it's still today's calendar day."""
        early_today = timezone.localtime().replace(hour=0, minute=0, second=1, microsecond=0)
        self._paid_entry('EarlyToday', early_today)
        resp = self.client.get('/bar/tabs/recent-settled/')
        data = resp.json()
        self.assertEqual(data['date'], timezone.localdate().isoformat())
        self.assertEqual(len(data['tabs']), 1)

    def test_explicit_date_filters_to_that_calendar_day(self):
        import datetime as dt
        yesterday = timezone.localdate() - timezone.timedelta(days=1)
        yesterday_dt = timezone.make_aware(dt.datetime.combine(yesterday, dt.time(14, 0)))
        self._paid_entry('Yesterday', yesterday_dt)
        self._paid_entry('Today', timezone.now())

        resp_today = self.client.get('/bar/tabs/recent-settled/?date=' + timezone.localdate().isoformat())
        self.assertEqual(len(resp_today.json()['tabs']), 1)
        self.assertEqual(resp_today.json()['tabs'][0]['customer_name'], 'Today')

        resp_yday = self.client.get('/bar/tabs/recent-settled/?date=' + yesterday.isoformat())
        self.assertEqual(len(resp_yday.json()['tabs']), 1)
        self.assertEqual(resp_yday.json()['tabs'][0]['customer_name'], 'Yesterday')

    def test_no_artificial_cap_more_than_twenty_tabs_all_returned(self):
        for i in range(25):
            self._paid_entry(f'Customer{i}', timezone.now())
        resp = self.client.get('/bar/tabs/recent-settled/')
        self.assertEqual(len(resp.json()['tabs']), 25)

    def test_invalid_date_param_falls_back_to_today(self):
        self._paid_entry('Today', timezone.now())
        resp = self.client.get('/bar/tabs/recent-settled/?date=not-a-date')
        data = resp.json()
        self.assertEqual(data['date'], timezone.localdate().isoformat())
        self.assertEqual(len(data['tabs']), 1)


class RecentPaymentsKegServingFieldsTest(TestCase):
    """2026-08-05 live request: "item search... can see how many keg cups
    she sold or bar orders sold in order to assist with posting in the
    system." recent_settled_tabs_api now surfaces raw keg_qty/keg_serving
    (already stored per-Transaction by KegBarrel.record_sale) on both tab
    entries and direct sales, so the frontend can search/group by preset
    without parsing "×N" out of the free-text description."""

    def setUp(self):
        self.business, self.store, self.owner, self.item, self.barrel, self.preset, self.shift = (
            _make_keg_fixtures_with_shift('Recent Serving Fields Biz')
        )
        self.client.force_login(self.owner)

    def test_tab_entry_carries_keg_serving_fields(self):
        tab = BarTab.objects.create(
            business=self.business, customer_name='Serving Fields Tab',
            status='SETTLED', source='bar', store=self.store,
        )
        txn = self.barrel.record_sale(self.preset, 2, 'credit', self.owner, tab=tab)
        entry = tab.entries.get(transaction=txn)
        entry.is_paid = True
        entry.payment_method = 'cash'
        entry.paid_at = timezone.now()
        entry.save(update_fields=['is_paid', 'payment_method', 'paid_at'])

        resp = self.client.get('/bar/tabs/recent-settled/?station=bar')
        data = resp.json()
        found = data['tabs'][0]['entries'][0]
        self.assertEqual(found['keg_serving'], 'pint')
        self.assertEqual(found['keg_qty'], 2)

    def test_direct_sale_carries_keg_serving_fields(self):
        Transaction.objects.create(
            business=self.business, item=self.item, type='Issue',
            qty=Decimal('-500'), sale_amount=Decimal('200'), payment_method='cash',
            keg_barrel=self.barrel, keg_serving='cup', keg_qty=3,
        )
        resp = self.client.get('/bar/tabs/recent-settled/?station=bar')
        found = resp.json()['direct'][0]
        self.assertEqual(found['keg_serving'], 'cup')
        self.assertEqual(found['keg_qty'], 3)

    def test_non_keg_direct_sale_has_blank_serving(self):
        plain_item = Item.objects.create(
            business=self.business, store=self.store, description='Plain Snack',
            material_no='RSF-PLAIN', selling_price=Decimal('50'),
        )
        Transaction.objects.create(
            business=self.business, item=plain_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('50'), payment_method='cash',
        )
        resp = self.client.get('/bar/tabs/recent-settled/?station=bar')
        found = [d for d in resp.json()['direct'] if d['description'] == 'Plain Snack'][0]
        self.assertEqual(found['keg_serving'], '')
        self.assertIsNone(found['keg_qty'])


class DirectSalePaymentCorrectionTest(TestCase):
    """2026-07-25 same-day follow-up (Monsoon Inn): Roy could see a
    "Viceroy" sale in Receipts and Transaction History but NOT in the
    Recent Payments/revoke panel — that panel only ever queried
    BarTabEntry, which doesn't exist for a direct (non-tab) Quick Sell /
    bar board / kitchen board cash-or-mpesa checkout. recent_settled_tabs_api
    now also returns these as a separate 'direct' list, and
    correct_transaction_payment_method lets staff relabel cash<->mpesa on
    one directly (no BarTabEntry involved, so no 'revert to unpaid' — the
    sale is genuinely complete, only the channel label can be wrong)."""

    def setUp(self):
        self.biz = Business.objects.create(name='Direct Sale Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='ds_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')

        self.staff = User.objects.create_user(username='ds_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        Shift.objects.create(business=self.biz, staff=self.staff, status='OPEN')

        self.bar_item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='Viceroy',
            material_no='DS-BAR-01', unit='Pcs', selling_price=Decimal('300'),
            cost_price=Decimal('200'), opening_bin_balance=Decimal('20'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Chips',
            material_no='DS-KIT-01', unit='Pcs', selling_price=Decimal('100'),
            cost_price=Decimal('60'), opening_bin_balance=Decimal('20'),
        )

    def _direct_txn(self, item, payment_method='cash', amount=Decimal('300')):
        return Transaction.objects.create(
            business=self.biz, item=item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method=payment_method,
        )

    def test_direct_sale_surfaced_in_recent_settled_api(self):
        self._direct_txn(self.bar_item, 'cash')
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/tabs/recent-settled/')
        data = resp.json()
        self.assertEqual(len(data['direct']), 1)
        self.assertEqual(data['direct'][0]['description'], 'Viceroy')
        self.assertEqual(data['direct'][0]['payment_method'], 'cash')

    def test_tab_based_sale_still_not_in_direct_list(self):
        txn = self._direct_txn(self.bar_item, 'cash')
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Tab Customer', status='OPEN',
            source='bar', store=self.bar_store,
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Viceroy',
            amount=Decimal('300'), is_paid=True, payment_method='cash', paid_at=timezone.now(),
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/tabs/recent-settled/')
        data = resp.json()
        self.assertEqual(len(data['direct']), 0, 'A tab-based sale must appear in tabs, not direct')
        self.assertEqual(len(data['tabs']), 1)

    def test_correct_payment_method_cash_to_mpesa(self):
        txn = self._direct_txn(self.bar_item, 'cash')
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {
            'new_method': 'mpesa', 'reason': 'Ilikuwa mpesa',
        })
        data = resp.json()
        self.assertTrue(data.get('ok'), data)
        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'mpesa')

    def test_correction_never_touches_qty_or_sale_amount(self):
        txn = self._direct_txn(self.bar_item, 'cash', amount=Decimal('300'))
        original_qty = txn.qty
        self.client.force_login(self.owner)
        self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {'new_method': 'mpesa'})
        txn.refresh_from_db()
        self.assertEqual(txn.qty, original_qty)
        self.assertEqual(txn.sale_amount, Decimal('300'))

    def test_same_method_is_a_no_op(self):
        txn = self._direct_txn(self.bar_item, 'cash')
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {'new_method': 'cash'})
        self.assertTrue(resp.json().get('ok'))
        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'cash')

    def test_invalid_new_method_rejected(self):
        txn = self._direct_txn(self.bar_item, 'cash')
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {'new_method': 'credit'})
        self.assertFalse(resp.json().get('ok'))
        self.assertEqual(resp.status_code, 400)

    def test_credit_transaction_cannot_be_corrected(self):
        txn = self._direct_txn(self.bar_item, 'credit')
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {'new_method': 'cash'})
        self.assertFalse(resp.json().get('ok'))

    def test_tab_transaction_rejected_not_a_direct_sale(self):
        """A Transaction that DOES have a tab_entry must be corrected via
        revoke_entry_payment, not this endpoint."""
        txn = self._direct_txn(self.bar_item, 'cash')
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Tab Customer', status='OPEN',
            source='bar', store=self.bar_store,
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Viceroy',
            amount=Decimal('300'), is_paid=True, payment_method='cash', paid_at=timezone.now(),
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {'new_method': 'mpesa'})
        self.assertEqual(resp.status_code, 404)

    def test_staff_with_open_shift_can_correct(self):
        txn = self._direct_txn(self.bar_item, 'cash')
        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {'new_method': 'mpesa'})
        self.assertTrue(resp.json().get('ok'), resp.json())

    def test_staff_without_shift_blocked(self):
        no_shift_staff = User.objects.create_user(username='ds_noshift', password='x')
        UserProfile.objects.create(user=no_shift_staff, business=self.biz, role='staff')
        txn = self._direct_txn(self.bar_item, 'cash')
        self.client.force_login(no_shift_staff)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {'new_method': 'mpesa'})
        data = resp.json()
        self.assertFalse(data.get('ok'))
        self.assertTrue(data.get('shift_required'))

    def test_bar_only_staff_blocked_from_kitchen_direct_sale(self):
        txn = self._direct_txn(self.kitchen_item, 'cash', amount=Decimal('100'))
        self.client.force_login(self.staff)  # bar-only, no can_access_kitchen
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {'new_method': 'mpesa'})
        self.assertFalse(resp.json().get('ok'))
        self.assertEqual(resp.status_code, 403)

    def test_cross_business_transaction_returns_404(self):
        other_biz = Business.objects.create(name='Other DS Biz')
        other_store = Store.objects.create(business=other_biz, name='Bar')
        other_item = Item.objects.create(
            business=other_biz, store=other_store, description='Foreign Item',
            material_no='DS-FOREIGN', unit='Pcs', selling_price=Decimal('300'),
        )
        other_txn = Transaction.objects.create(
            business=other_biz, item=other_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('300'), payment_method='cash',
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/transactions/{other_txn.id}/correct-payment/', {'new_method': 'mpesa'})
        self.assertEqual(resp.status_code, 404)


class CorrectTransactionDateTest(TestCase):
    """2026-08-21 urgent live request (Roy, Monsoon Inn): "the staff was
    backdating yesterday's sales today and she made an error where she
    put some as if they were today's sales and she has no idea how she
    would rectify them so that the app knows they were meant to be
    backdated to yesterday." Sibling of correct_transaction_payment_method
    — same scope (a direct, non-tab sale), same permission tier."""

    def setUp(self):
        self.biz = Business.objects.create(name='Correct Date Biz', has_kitchen=True)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='cd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')

        self.staff = User.objects.create_user(username='cd_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='kitchen', can_access_kitchen=True)
        Shift.objects.create(business=self.biz, store=self.kitchen_store, staff=self.staff, status='OPEN')

        self.item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Chips',
            material_no='CD-KIT-01', unit='Pcs', selling_price=Decimal('100'),
            cost_price=Decimal('60'), opening_bin_balance=Decimal('20'),
        )
        self.today = timezone.localdate()

    def _direct_txn(self, created_at=None):
        created_at = created_at or timezone.now()
        return Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
            created_at=created_at, date=timezone.localtime(created_at).date(),
        )

    def test_owner_moves_date_and_created_at_together(self):
        txn = self._direct_txn()
        yesterday = self.today - timedelta(days=1)
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-date/', {
            'new_date': yesterday.isoformat(), 'reason': 'Ilisahaulika backdate',
        })
        data = resp.json()
        self.assertTrue(data.get('ok'), data)
        txn.refresh_from_db()
        self.assertEqual(txn.date, yesterday)
        self.assertEqual(timezone.localtime(txn.created_at).date(), yesterday)

    def test_preserves_original_time_of_day(self):
        from datetime import datetime as _dt, time as _time
        original = timezone.make_aware(_dt.combine(self.today, _time(14, 37)))
        txn = self._direct_txn(created_at=original)
        yesterday = self.today - timedelta(days=1)
        self.client.force_login(self.owner)
        self.client.post(f'/bar/transactions/{txn.id}/correct-date/', {'new_date': yesterday.isoformat()})
        txn.refresh_from_db()
        moved = timezone.localtime(txn.created_at)
        self.assertEqual(moved.date(), yesterday)
        self.assertEqual(moved.time().hour, 14)
        self.assertEqual(moved.time().minute, 37)

    def test_never_touches_qty_sale_amount_or_payment_method(self):
        txn = self._direct_txn()
        self.client.force_login(self.owner)
        self.client.post(f'/bar/transactions/{txn.id}/correct-date/', {
            'new_date': (self.today - timedelta(days=1)).isoformat(),
        })
        txn.refresh_from_db()
        self.assertEqual(txn.qty, Decimal('-1'))
        self.assertEqual(txn.sale_amount, Decimal('100'))
        self.assertEqual(txn.payment_method, 'cash')

    def test_future_date_rejected(self):
        txn = self._direct_txn()
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-date/', {
            'new_date': (self.today + timedelta(days=1)).isoformat(),
        })
        self.assertFalse(resp.json().get('ok'))
        txn.refresh_from_db()
        self.assertEqual(txn.date, self.today)

