class EditShiftOpeningFloatTest(TestCase):
    """2026-07-30 live request: "a way of editing counter float cash across
    all counters assuming the staff opened shift and forgot to input the
    cash at hand." open_shift() silently defaults opening_float to 0 when
    nothing is typed — this is a genuine data-entry correction (the float
    really was some amount, staff just forgot to type it), distinct from
    the opening-variance acknowledge flow (which explains why 0 IS correct).
    One shared view backs both /bar/shift/<id>/edit-float/ and
    /kitchen/shift/<id>/edit-float/ since Shift isn't split by station
    beyond the station field itself."""

    def setUp(self):
        self.biz = Business.objects.create(name='Edit Float Biz')
        self.owner = User.objects.create_user(username='ef_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='ef_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.staff = User.objects.create_user(username='ef_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.other_staff = User.objects.create_user(username='ef_other', password='x')
        UserProfile.objects.create(user=self.other_staff, business=self.biz, role='staff')
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')

        self.open_shift = Shift.objects.create(
            business=self.biz, store=self.bar_store, staff=self.staff,
            opening_float=Decimal('0'), status='OPEN', station='bar',
            expected_opening_cash=Decimal('1000'), opening_variance=Decimal('-1000'),
        )

    def test_staff_can_fix_their_own_open_shift(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {
            'opening_float': '2000', 'reason': 'Nilisahau kuweka float',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.open_shift.refresh_from_db()
        self.assertEqual(self.open_shift.opening_float, Decimal('2000'))
        self.assertIn('KES 0', self.open_shift.notes)
        self.assertIn('KES 2,000', self.open_shift.notes)
        notif = Notification.objects.filter(user=self.owner, title__icontains='Float ya Ufunguzi').first()
        self.assertIsNotNone(notif)

    def test_recomputes_opening_variance(self):
        self.client.force_login(self.staff)
        self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '900'})
        self.open_shift.refresh_from_db()
        self.assertEqual(self.open_shift.opening_variance, Decimal('-100'))

    def test_owner_can_fix_any_open_shift(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/kitchen/shift/{self.open_shift.id}/edit-float/', {'opening_float': '1000'})
        self.assertTrue(resp.json()['ok'])
        self.open_shift.refresh_from_db()
        self.assertEqual(self.open_shift.opening_float, Decimal('1000'))

    def test_manager_can_fix_any_open_shift(self):
        self.client.force_login(self.manager)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '500'})
        self.assertTrue(resp.json()['ok'])

    def test_unrelated_staff_cannot_edit(self):
        self.client.force_login(self.other_staff)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '2000'})
        self.assertEqual(resp.status_code, 403)
        self.open_shift.refresh_from_db()
        self.assertEqual(self.open_shift.opening_float, Decimal('0'))

    def test_closed_shift_needs_owner_or_manager(self):
        self.open_shift.status = 'CLOSED'
        self.open_shift.closing_cash_counted = Decimal('500')
        self.open_shift.save()

        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '2000'})
        self.assertEqual(resp.status_code, 403)

        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '2000'})
        self.assertTrue(resp.json()['ok'])

    def test_confirmed_shift_is_not_editable(self):
        self.open_shift.status = 'CONFIRMED'
        self.open_shift.closing_cash_counted = Decimal('500')
        self.open_shift.save()
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '2000'})
        self.assertEqual(resp.status_code, 403)

    def test_resets_stale_opening_variance_review(self):
        self.open_shift.opening_variance_review_status = 'acknowledged'
        self.open_shift.opening_variance_reviewed_by = self.owner
        self.open_shift.opening_variance_reviewed_at = timezone.now()
        self.open_shift.save()

        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '750'})
        self.assertTrue(resp.json()['ok'])
        self.open_shift.refresh_from_db()
        self.assertEqual(self.open_shift.opening_variance_review_status, '')
        self.assertIsNone(self.open_shift.opening_variance_reviewed_by)

    def test_resets_stale_closing_variance_review_once_closed(self):
        self.open_shift.status = 'CLOSED'
        self.open_shift.closing_cash_counted = Decimal('500')
        self.open_shift.variance_review_status = 'acknowledged'
        self.open_shift.variance_reviewed_by = self.owner
        self.open_shift.variance_reviewed_at = timezone.now()
        self.open_shift.save()

        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '750'})
        self.assertTrue(resp.json()['ok'])
        self.open_shift.refresh_from_db()
        self.assertEqual(self.open_shift.variance_review_status, '')

    def test_unchanged_value_is_a_no_op(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '0'})
        data = resp.json()
        self.assertTrue(data['ok'])
        self.assertTrue(data.get('unchanged'))
        self.assertEqual(
            Notification.objects.filter(user=self.owner, title__icontains='Float ya Ufunguzi').count(), 0,
        )

    def test_negative_amount_rejected(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '-50'})
        self.assertEqual(resp.status_code, 400)

    def test_invalid_amount_rejected(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': 'abc'})
        self.assertEqual(resp.status_code, 400)

    def test_till_expected_cash_unaffected_by_editing_a_past_shift(self):
        """opening_float only feeds this shift's OWN _reconcile() figure —
        till_expected_cash()'s anchor is closing_cash_counted, never
        opening_float, so correcting a closed shift's float must not
        retroactively move the live running till."""
        from core.shift_views import till_expected_cash
        closed = Shift.objects.create(
            business=self.biz, store=self.bar_store, staff=self.staff,
            opening_float=Decimal('0'), status='CONFIRMED', station='bar',
            started_at=timezone.now() - timedelta(hours=5),
            ended_at=timezone.now() - timedelta(hours=4),
            closing_cash_counted=Decimal('1500'),
        )
        before = till_expected_cash(self.biz, 'bar')

        # Correct an even older, already-CLOSED shift's opening float.
        older = Shift.objects.create(
            business=self.biz, store=self.bar_store, staff=self.staff,
            opening_float=Decimal('0'), status='CLOSED', station='bar',
            started_at=timezone.now() - timedelta(hours=8),
            ended_at=timezone.now() - timedelta(hours=7),
            closing_cash_counted=Decimal('300'),
        )
        self.client.force_login(self.owner)
        self.client.post(f'/bar/shift/{older.id}/edit-float/', {'opening_float': '999'})

        after = till_expected_cash(self.biz, 'bar')
        self.assertEqual(before['expected_cash'], after['expected_cash'])

    def test_correction_applies_correctly_regardless_of_sales_already_made(self):
        """2026-07-30 follow-up: "ensure that once I correct it, it will
        adjust accordingly irrespective of cash sales made for that
        counter." _reconcile()'s formula is
        opening_float + cash_sales_for_the_whole_shift — cash_sales is
        summed over the entire shift window regardless of WHEN within it
        the float gets corrected, so fixing the float after several sales
        have already happened must still land on the same total as if it
        had been entered correctly from the start."""
        item = Item.objects.create(
            business=self.biz, store=self.bar_store, material_no='EF-ITEM-1',
            description='Beer', unit='bottle', selling_price=Decimal('100'),
        )
        # Three cash sales happen BEFORE anyone notices the float was never entered.
        for _i in range(3):
            Transaction.objects.create(
                business=self.biz, item=item, type='Issue', qty=Decimal('-1'),
                sale_amount=Decimal('100'), payment_method='cash',
            )

        from core.shift_views import _reconcile
        stale = _reconcile(self.open_shift)
        self.assertEqual(stale['expected_cash'], 300.0)  # 0 (wrong float) + 300 sales

        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/shift/{self.open_shift.id}/edit-float/', {'opening_float': '2000'})
        self.assertTrue(resp.json()['ok'])

        corrected = _reconcile(Shift.objects.get(id=self.open_shift.id))
        self.assertEqual(corrected['expected_cash'], 2300.0)  # 2000 + the same 300 sales

        # A FOURTH sale made AFTER the correction must still add on top cleanly.
        Transaction.objects.create(
            business=self.biz, item=item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('50'), payment_method='cash',
        )
        final = _reconcile(Shift.objects.get(id=self.open_shift.id))
        self.assertEqual(final['expected_cash'], 2350.0)


class TillCountTest(TestCase):
    """2026-07-30 live request: "ensure the owner can confirm cash at
    counters at any given moment for the system to know." Before this, the
    only way to reset till_expected_cash()'s running ledger was a shift
    CLOSE — TillCount is a second, independent anchor source an owner/
    manager can create at any time, from either counter, with no shift
    involved at all."""

    def setUp(self):
        from core.shift_views import till_expected_cash
        self.till_expected_cash = till_expected_cash
        self.biz = Business.objects.create(name='Till Count Biz', has_kitchen=True)
        self.owner = User.objects.create_user(username='tc_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='tc_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.staff = User.objects.create_user(username='tc_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)

    def test_first_ever_confirmation_bootstraps_tracking(self):
        """No shift has ever closed for this station — before this feature
        that meant 'Bado haijawekwa' forever until someone closes a shift.
        A spot confirmation must establish tracking immediately."""
        before = self.till_expected_cash(self.biz, 'bar')
        self.assertFalse(before['anchor_established'])

        self.client.force_login(self.owner)
        resp = self.client.post('/till/confirm/', {'station': 'bar', 'counted_amount': '1500'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertIsNone(data['expected_amount'])  # nothing to compare against yet

        after = self.till_expected_cash(self.biz, 'bar')
        self.assertTrue(after['anchor_established'])
        self.assertEqual(after['expected_cash'], 1500.0)

    def test_confirmation_becomes_new_anchor_over_an_older_shift_close(self):
        Shift.objects.create(
            business=self.biz, store=self.bar_store, staff=self.staff,
            opening_float=Decimal('0'), status='CONFIRMED', station='bar',
            started_at=timezone.now() - timedelta(hours=5),
            ended_at=timezone.now() - timedelta(hours=4),
            closing_cash_counted=Decimal('1000'),
        )
        item = Item.objects.create(
            business=self.biz, store=self.bar_store, material_no='TC-BAR-1',
            description='Beer', unit='bottle', selling_price=Decimal('100'),
        )
        # Two cash sales since that close — expected would be 1000 + 300 = 1300.
        Transaction.objects.create(
            business=self.biz, item=item, type='Issue', qty=Decimal('-3'),
            sale_amount=Decimal('300'), payment_method='cash',
            created_at=timezone.now() - timedelta(hours=1),
        )
        before = self.till_expected_cash(self.biz, 'bar')
        self.assertEqual(before['expected_cash'], 1300.0)

        # Owner physically counts and finds only 1250 — confirms it now.
        self.client.force_login(self.owner)
        resp = self.client.post('/till/confirm/', {'station': 'bar', 'counted_amount': '1250', 'note': 'Ilihesabiwa sasa'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertEqual(data['expected_amount'], 1300.0)
        self.assertEqual(data['variance'], -50.0)

        # Going forward, the till must reflect the fresh 1250 baseline —
        # NOT the stale 1300 the old shift-close anchor implied — regardless
        # of the cash sales that already happened before the confirmation.
        after = self.till_expected_cash(self.biz, 'bar')
        self.assertEqual(after['expected_cash'], 1250.0)
        self.assertIn('Thibitisho la Pesa', after['anchor_label'])

        # A NEW cash sale after the confirmation still adds on top correctly.
        Transaction.objects.create(
            business=self.biz, item=item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash',
        )
        final = self.till_expected_cash(self.biz, 'bar')
        self.assertEqual(final['expected_cash'], 1350.0)

    def test_later_shift_close_supersedes_an_older_confirmation(self):
        self.client.force_login(self.owner)
        self.client.post('/till/confirm/', {'station': 'bar', 'counted_amount': '500'})
        TillCount.objects.filter(business=self.biz).update(
            counted_at=timezone.now() - timedelta(hours=3),
        )
        Shift.objects.create(
            business=self.biz, store=self.bar_store, staff=self.staff,
            opening_float=Decimal('0'), status='CONFIRMED', station='bar',
            started_at=timezone.now() - timedelta(hours=2),
            ended_at=timezone.now() - timedelta(hours=1),
            closing_cash_counted=Decimal('900'),
        )
        after = self.till_expected_cash(self.biz, 'bar')
        self.assertEqual(after['expected_cash'], 900.0)

    def test_stations_are_independent(self):
        self.client.force_login(self.owner)
        self.client.post('/till/confirm/', {'station': 'bar', 'counted_amount': '400'})
        bar_till = self.till_expected_cash(self.biz, 'bar')
        kitchen_till = self.till_expected_cash(self.biz, 'kitchen')
        self.assertEqual(bar_till['expected_cash'], 400.0)
        self.assertFalse(kitchen_till['anchor_established'])

    def test_manager_can_confirm(self):
        self.client.force_login(self.manager)
        resp = self.client.post('/till/confirm/', {'station': 'kitchen', 'counted_amount': '250'})
        self.assertTrue(resp.json()['ok'])

    def test_staff_cannot_confirm(self):
        self.client.force_login(self.staff)
        resp = self.client.post('/till/confirm/', {'station': 'bar', 'counted_amount': '250'})
        self.assertEqual(resp.status_code, 403)
        self.assertFalse(TillCount.objects.filter(business=self.biz).exists())

    def test_invalid_station_rejected(self):
        self.client.force_login(self.owner)
        resp = self.client.post('/till/confirm/', {'station': 'lounge', 'counted_amount': '250'})
        self.assertEqual(resp.status_code, 400)

    def test_negative_amount_rejected(self):
        self.client.force_login(self.owner)
        resp = self.client.post('/till/confirm/', {'station': 'bar', 'counted_amount': '-10'})
        self.assertEqual(resp.status_code, 400)

    def test_notifies_station_scoped_staff_and_owner_not_other_station(self):
        bar_staff = User.objects.create_user(username='tc_barstaff', password='x')
        UserProfile.objects.create(user=bar_staff, business=self.biz, role='staff')
        Shift.objects.create(business=self.biz, staff=bar_staff, status='OPEN', station='bar')
        kitchen_staff = User.objects.create_user(username='tc_kstaff', password='x')
        UserProfile.objects.create(user=kitchen_staff, business=self.biz, role='kitchen')
        Shift.objects.create(business=self.biz, staff=kitchen_staff, status='OPEN', station='kitchen')

        self.client.force_login(self.owner)
        self.client.post('/till/confirm/', {'station': 'bar', 'counted_amount': '600'})

        self.assertTrue(Notification.objects.filter(user=bar_staff, title__icontains='Pesa ya Counter').exists())
        self.assertFalse(Notification.objects.filter(user=kitchen_staff).exists())


class NotificationStationScopingSweepTest(TestCase):
    """2026-07-30 live report: "notifications are not pushed to their
    respective counters, kitchen staff is getting bar notifications and
    vice versa, only the business owner is supposed to get them all."

    Root cause: several correction-fan-out helpers each independently
    looped over EVERY on-shift staffer for the whole business with no
    station filter at all — _notify_tab_correction/_notify_direct_
    correction (core/keg_views.py), _settle_receipt_entries_from_payment
    (core/mpesa_views.py), _notify_tab_transfer_resolved
    (core/receipt_views.py). One correct reference implementation already
    existed (_fire_cash_payment_request, 2026-07-25) — fixed by factoring
    that logic into core.views.scoped_on_shift_targets() and routing every
    caller through it. Owner (and manager) are unaffected — they always
    see both stations, matching Roy's own framing."""

    def setUp(self):
        self.biz = Business.objects.create(name='Notif Scope Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='ns_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')

        self.bar_staff = User.objects.create_user(username='ns_barstaff', password='x')
        UserProfile.objects.create(user=self.bar_staff, business=self.biz, role='staff')
        Shift.objects.create(business=self.biz, staff=self.bar_staff, status='OPEN', station='bar')

        self.kitchen_staff = User.objects.create_user(username='ns_kstaff', password='x')
        UserProfile.objects.create(user=self.kitchen_staff, business=self.biz, role='kitchen')
        Shift.objects.create(business=self.biz, staff=self.kitchen_staff, status='OPEN', station='kitchen')

        self.bar_item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='Tusker',
            material_no='NS-BAR-01', unit='Pcs', selling_price=Decimal('200'),
            cost_price=Decimal('120'), opening_bin_balance=Decimal('50'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Chapati',
            material_no='NS-KIT-01', unit='Pcs', selling_price=Decimal('50'),
            cost_price=Decimal('20'), opening_bin_balance=Decimal('30'),
        )

    def _make_tab_with_entry(self, item, source):
        store = self.kitchen_store if item is self.kitchen_item else self.bar_store
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Roy', status='OPEN', source=source, store=store,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('200'), payment_method='',
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description=item.description,
            amount=Decimal('200'), is_paid=False,
        )
        return tab, entry

    def test_scoped_on_shift_targets_unit(self):
        from core.views import scoped_on_shift_targets
        bar_only = scoped_on_shift_targets(self.biz, {'bar'})
        self.assertIn(self.bar_staff.id, bar_only)
        self.assertNotIn(self.kitchen_staff.id, bar_only)

        kitchen_only = scoped_on_shift_targets(self.biz, {'kitchen'})
        self.assertIn(self.kitchen_staff.id, kitchen_only)
        self.assertNotIn(self.bar_staff.id, kitchen_only)

        unscoped = scoped_on_shift_targets(self.biz, None)
        self.assertIn(self.bar_staff.id, unscoped)
        self.assertIn(self.kitchen_staff.id, unscoped)

    def test_remove_tab_entry_bar_does_not_notify_kitchen_staff(self):
        tab, entry = self._make_tab_with_entry(self.bar_item, source='bar')
        self.client.force_login(self.bar_staff)
        resp = self.client.post(f'/bar/tabs/{tab.id}/entries/{entry.id}/remove/', {'reason': 'test'})
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertFalse(Notification.objects.filter(user=self.kitchen_staff).exists())
        self.assertTrue(Notification.objects.filter(user=self.owner).exists())

    def test_remove_tab_entry_kitchen_does_not_notify_bar_staff(self):
        tab, entry = self._make_tab_with_entry(self.kitchen_item, source='kitchen')
        self.client.force_login(self.kitchen_staff)
        resp = self.client.post(f'/bar/tabs/{tab.id}/entries/{entry.id}/remove/', {'reason': 'test'})
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertFalse(Notification.objects.filter(user=self.bar_staff).exists())
        self.assertTrue(Notification.objects.filter(user=self.owner).exists())

    def test_correct_transaction_payment_method_bar_does_not_notify_kitchen(self):
        txn = Transaction.objects.create(
            business=self.biz, item=self.bar_item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('200'), payment_method='cash',
        )
        self.client.force_login(self.bar_staff)
        resp = self.client.post(f'/bar/transactions/{txn.id}/correct-payment/', {'new_method': 'mpesa'})
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertFalse(Notification.objects.filter(user=self.kitchen_staff).exists())
        self.assertTrue(Notification.objects.filter(user=self.owner).exists())

    def test_notify_tab_transfer_resolved_scopes_by_both_sides(self):
        from core.receipt_views import _notify_tab_transfer_resolved
        source_tab, source_entry = self._make_tab_with_entry(self.bar_item, source='bar')
        dest_tab, _unused_entry = self._make_tab_with_entry(self.bar_item, source='bar')
        transfer = TabTransferRequest.objects.create(
            business=self.biz, entry=source_entry, source_tab=source_tab, dest_tab=dest_tab,
            amount=Decimal('100'), paid_amount=Decimal('100'), status='ACCEPTED',
            requested_by=self.bar_staff, resolved_at=timezone.now(),
        )
        _notify_tab_transfer_resolved(transfer)
        self.assertFalse(Notification.objects.filter(user=self.kitchen_staff).exists())
        self.assertTrue(Notification.objects.filter(user=self.owner).exists())


class LowStockReorderNotificationTest(TestCase):
    """2026-08-11 live report (Roy — Bosco, an owner-role account on this
    business, never received a beer reorder alert despite the reorder
    level being set correctly): notify_reorder_alert() (called from
    notify_transaction() whenever item.needs_reorder() goes True) used to
    resolve a SINGLE recipient via business.users.filter(role="owner")
    .first() — silently dropping every OTHER owner-role user on the
    account (a business can legitimately have more than one). Rewritten
    to fan out to every owner-role profile — deliberately NOT widened to
    managers, per Roy's own explicit correction: "only the owner should
    get stock alerts no one else." """

    def setUp(self):
        self.biz = Business.objects.create(name='Reorder Notif Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        # Two owner-role accounts on the same business — the literal live
        # scenario: Roy (created first) and Bosco (added later), both
        # role='owner'. .first() would only ever reach Roy.
        self.roy = User.objects.create_user(username='rn_roy', password='x', email='roy@x.com')
        UserProfile.objects.create(user=self.roy, business=self.biz, role='owner', phone='0711111111')
        self.bosco = User.objects.create_user(username='rn_bosco', password='x', email='bosco@x.com')
        UserProfile.objects.create(user=self.bosco, business=self.biz, role='owner', phone='0722222222')
        self.manager = User.objects.create_user(username='rn_manager', password='x', email='mgr@x.com')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager', phone='0733333333')
        self.staff = User.objects.create_user(username='rn_staff', password='x', email='staff@x.com')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff', phone='0744444444')

        self.beer = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker Lager',
            material_no='RN-BEER-01', unit='Pcs', selling_price=Decimal('200'),
            cost_price=Decimal('120'), reorder_level=Decimal('10'),
            reorder_quantity=Decimal('48'), opening_bin_balance=Decimal('12'),
        )

    def _sell_below_reorder(self):
        txn = Transaction.objects.create(
            business=self.biz, item=self.beer, type='Issue',
            qty=Decimal('-5'), sale_amount=Decimal('1000'), payment_method='cash',
        )
        from core.notifications import notify_transaction
        notify_transaction(txn, self.biz)
        return txn

    def test_every_owner_role_account_notified_not_just_first(self):
        """The literal live scenario: Bosco (a second owner-role account)
        must be notified, not silently skipped in favour of Roy."""
        self._sell_below_reorder()
        self.assertTrue(self.beer.needs_reorder())
        self.assertTrue(
            Notification.objects.filter(user=self.roy, title__icontains='Low Stock').exists()
        )
        self.assertTrue(
            Notification.objects.filter(user=self.bosco, title__icontains='Low Stock').exists()
        )

    def test_manager_not_notified(self):
        """Roy's explicit correction: "only the owner should get stock
        alerts no one else" — deliberately NOT widened to managers here,
        unlike several other notification fixes in this app."""
        self._sell_below_reorder()
        self.assertFalse(
            Notification.objects.filter(user=self.manager, title__icontains='Low Stock').exists()
        )

    def test_plain_staff_not_notified(self):
        self._sell_below_reorder()
        self.assertFalse(
            Notification.objects.filter(user=self.staff, title__icontains='Low Stock').exists()
        )

    def test_no_alert_when_stock_still_above_reorder_level(self):
        healthy = Item.objects.create(
            business=self.biz, store=self.store, description='White Cap',
            material_no='RN-BEER-02', unit='Pcs', selling_price=Decimal('200'),
            reorder_level=Decimal('10'), opening_bin_balance=Decimal('100'),
        )
        txn = Transaction.objects.create(
            business=self.biz, item=healthy, type='Issue',
            qty=Decimal('-2'), sale_amount=Decimal('400'), payment_method='cash',
        )
        from core.notifications import notify_transaction
        notify_transaction(txn, self.biz)
        self.assertFalse(
            Notification.objects.filter(user=self.roy, title__icontains='Low Stock').exists()
        )


class RecentSettledTabsStationScopingTest(TestCase):
    """2026-07-27 live report: "recent sales in the tabs drawer for either
    bar board or bar orders are showing kitchen sales... each counter
    should be accountable to its own sales." Root cause: bar_board.html,
    kitchen_board.html, and quick_sell.html all hit the exact same
    /bar/tabs/recent-settled/ URL with no indication of which counter was
    asking, so the endpoint fell back to _allowed_tab_sources(up) (an
    IDENTITY check — what this viewer is PERMITTED to see) as if it were
    also a DISPLAY-SCOPE check. For an owner/manager both stations are
    always permitted, so nothing was ever actually excluded. The fix adds
    an explicit ?station= param, now sent by all three templates."""

    def setUp(self):
        self.biz = Business.objects.create(name='Recent Payments Scope Biz', has_kitchen=True)
        self.owner = User.objects.create_user(username='rps_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.bar_item = Item.objects.create(
            business=self.biz, store=self.bar_store, material_no='RPS-1',
            description='Tusker', unit='bottle', selling_price=Decimal('250'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, material_no='RPS-2',
            description='Chips', unit='plate', selling_price=Decimal('150'),
        )

        bar_tab = BarTab.objects.create(business=self.biz, customer_name='Bar Cust', status='SETTLED', source='bar')
        bar_txn = Transaction.objects.create(
            business=self.biz, item=self.bar_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('250'), payment_method='cash',
        )
        BarTabEntry.objects.create(
            tab=bar_tab, transaction=bar_txn, description='Tusker',
            amount=Decimal('250'), is_paid=True, paid_at=timezone.now(), payment_method='cash',
        )

        kitchen_tab = BarTab.objects.create(business=self.biz, customer_name='Kitchen Cust', status='SETTLED', source='kitchen')
        kitchen_txn = Transaction.objects.create(
            business=self.biz, item=self.kitchen_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('150'), payment_method='cash',
        )
        BarTabEntry.objects.create(
            tab=kitchen_tab, transaction=kitchen_txn, description='Chips',
            amount=Decimal('150'), is_paid=True, paid_at=timezone.now(), payment_method='cash',
        )

        # Direct (non-tab) sales, one per station, same coverage as the
        # tab-entry case above.
        Transaction.objects.create(
            business=self.biz, item=self.bar_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('250'), payment_method='mpesa',
        )
        Transaction.objects.create(
            business=self.biz, item=self.kitchen_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('150'), payment_method='mpesa',
        )

    def test_bar_station_param_excludes_kitchen_sales(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/tabs/recent-settled/?station=bar')
        data = resp.json()
        names = [t['customer_name'] for t in data['tabs']]
        self.assertIn('Bar Cust', names)
        self.assertNotIn('Kitchen Cust', names)
        direct_descs = [d['description'] for d in data['direct']]
        self.assertIn('Tusker', direct_descs)
        self.assertNotIn('Chips', direct_descs)

    def test_kitchen_station_param_excludes_bar_sales(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/tabs/recent-settled/?station=kitchen')
        data = resp.json()
        names = [t['customer_name'] for t in data['tabs']]
        self.assertIn('Kitchen Cust', names)
        self.assertNotIn('Bar Cust', names)
        direct_descs = [d['description'] for d in data['direct']]
        self.assertIn('Chips', direct_descs)
        self.assertNotIn('Tusker', direct_descs)

    def test_no_station_param_falls_back_to_permission_only(self):
        """Defensive backward-compat path for a stale cached page — owner is
        permitted both, so both still show when no station is specified."""
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/tabs/recent-settled/')
        data = resp.json()
        names = [t['customer_name'] for t in data['tabs']]
        self.assertIn('Bar Cust', names)
        self.assertIn('Kitchen Cust', names)


class OfflinePageTest(TestCase):
    """2026-08-11 live report — Roy: the app showed "You're Offline / lost
    your internet connection" while YouTube streamed fine on the same
    phone — proving the message was actively wrong, since a `fetch()` to
    THIS server can fail (DNS/TLS hiccup, timeout reaching Render) for
    reasons that have nothing to do with the phone's general internet
    being down. The offline page no longer confidently blames "no
    internet"; it also now polls /health/ in the background and
    auto-reloads once a real connection succeeds instead of requiring a
    manual tap."""

    def test_offline_page_renders_and_no_longer_blames_internet(self):
        resp = self.client.get('/offline/')
        self.assertEqual(resp.status_code, 200)
        body = resp.content.decode()
        self.assertNotIn("lost your internet connection", body)
        self.assertIn("Couldn", body)  # "Couldn't Reach Duka Mwecheche"

    def test_offline_page_polls_health_endpoint_for_auto_retry(self):
        resp = self.client.get('/offline/')
        body = resp.content.decode()
        self.assertIn('/health/', body)
        self.assertIn('setInterval', body)

    def test_health_endpoint_is_unauthenticated_and_lightweight(self):
        """The offline page's background poll must never require login —
        that's exactly the state a user hitting this page is often in."""
        resp = self.client.get('/health/')
        self.assertEqual(resp.status_code, 200)


class CsrfFailureViewTest(TestCase):
    """2026-07-28 live report — Roy: ~80% of client logins hit Django's raw,
    unrecoverable default CSRF-failure page, with "clear phone cache" as the
    only known workaround. CSRF_FAILURE_VIEW now bounces the user straight
    back to a working page (login for anonymous, home for authenticated)
    with a friendly explanation instead of a dead end — see core.views.
    csrf_failure_view's docstring for the full root-cause analysis."""

    def test_csrf_failure_redirects_to_login_for_anonymous_user(self):
        from django.test import Client
        client = Client(enforce_csrf_checks=True)
        resp = client.post('/accounts/login/', {'username': 'nobody', 'password': 'x'})
        self.assertEqual(resp.status_code, 302)
        self.assertIn('/accounts/login/', resp.url)

    def test_csrf_failure_redirects_to_home_for_authenticated_user(self):
        from django.test import Client
        biz = Business.objects.create(name='Csrf Test Biz')
        user = User.objects.create_user(username='csrf_user', password='x')
        UserProfile.objects.create(user=user, business=biz, role='owner')
        client = Client(enforce_csrf_checks=True)
        client.force_login(user)
        # No csrfmiddlewaretoken in the POST body — enforce_csrf_checks=True
        # means this must fail CSRF (not some other validation) and hit our
        # custom failure view rather than a raw 403 page.
        resp = client.post('/petty-cash/record/', {'amount': '100', 'reason': 'other'})
        self.assertEqual(resp.status_code, 302)
        self.assertNotIn('accounts/login', resp.url)


class LoginPageNeverCachedTest(TestCase):
    """2026-08-10 live report (Roy): the CSRF "session expired, try again"
    message kept appearing on EVERY login, not just leftover debris from an
    earlier outage — a genuinely reproducible, ongoing symptom. Traced to a
    gap in the SAME fix class that already protects home() (2026-07-28):
    home() got @never_cache specifically because a dashboard this volatile
    must never be served stale by ANY caching layer between the browser and
    the view — the phone's own HTTP disk cache, or (explicitly documented
    in that fix's own docstring) a mobile carrier's transparent compression
    proxy, common on Kenyan mobile data. The login PAGE itself never got
    the same treatment — a stale cached copy of /accounts/login/ carries a
    CSRF token baked into its hidden form field at the time it was cached,
    which fails validation the moment it's submitted, regardless of what
    the CSRF_FAILURE_VIEW safety net (built the same day as this docstring
    references) or the service worker's own /accounts/ network-only guard
    (2026-07-27) do — neither of those addresses an upstream cache serving
    a stale page BEFORE the service worker or Django's CSRF check ever gets
    involved. Fixed by wrapping login/logout with the same @never_cache
    used on home(), so no intermediate cache can ever hold a stale copy
    with a stale token in the first place."""

    def test_login_page_has_never_cache_headers(self):
        resp = self.client.get('/accounts/login/')
        self.assertEqual(resp.status_code, 200)
        cache_control = resp.get('Cache-Control', '')
        self.assertIn('no-store', cache_control)
        self.assertIn('no-cache', cache_control)

    def test_logout_has_never_cache_headers(self):
        biz = Business.objects.create(name='Logout NeverCache Biz')
        user = User.objects.create_user(username='logout_nc_user', password='x')
        UserProfile.objects.create(user=user, business=biz, role='owner')
        self.client.force_login(user)
        resp = self.client.post('/accounts/logout/')
        cache_control = resp.get('Cache-Control', '')
        self.assertIn('no-store', cache_control)

    def test_login_still_works_normally(self):
        """The never_cache wrap must not break the ordinary login flow."""
        biz = Business.objects.create(name='Login Still Works Biz')
        user = User.objects.create_user(username='login_works_user', password='x')
        UserProfile.objects.create(user=user, business=biz, role='owner')
        resp = self.client.post(
            '/accounts/login/', {'username': 'login_works_user', 'password': 'x'},
            follow=True,
        )
        self.assertEqual(resp.status_code, 200)
        self.assertTrue(resp.context['user'].is_authenticated)


# ── Shift Station Misattribution Fix (2026-07-28 live report) ──────────────
# Monsoon Inn's till showed KES 1400 attributed to Bar with ZERO bar sales
# that day, while kitchen sales had happened. Root cause: station was
# inferred from staff.userprofile.role everywhere (_shift_station,
# _reconcile, till_expected_cash's anchor/banked queries,
# _convert_open_tabs_to_debt_for_shift, shift_history's — separately broken
# — Shift.store filter) — which breaks for a MANAGER or any cross-access
# staffer (can_access_kitchen/can_access_bar) working the counter that
# ISN'T their nominal role. Shift.station is now captured explicitly from
# the request path at open_shift() time — 100% reliable regardless of role.

class ShiftStationMisattributionTest(TestCase):
    def setUp(self):
        from core.shift_views import till_expected_cash, _shift_station
        self.till_expected_cash = till_expected_cash
        self._shift_station = _shift_station

        self.biz = Business.objects.create(name='Station Misattribution Biz', has_kitchen=True)
        self.owner = User.objects.create_user(username='smt_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        # A MANAGER — not role='kitchen' — who actually works the kitchen
        # counter. This is exactly the real-world shape of the bug: role
        # alone says "not kitchen", but this shift is genuinely a kitchen shift.
        self.manager = User.objects.create_user(username='smt_manager', password='x')
        UserProfile.objects.create(
            user=self.manager, business=self.biz, role='manager',
            can_access_kitchen=True, can_access_bar=True,
        )
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, material_no='SMT-1',
            description='Chipo', unit='plate', selling_price=Decimal('100'),
        )

    def test_manager_shift_opened_from_kitchen_board_stores_kitchen_station(self):
        self.client.force_login(self.manager)
        resp = self.client.post('/kitchen/shift/open/', {'opening_float': '0'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        shift = Shift.objects.get(id=data['shift_id'])
        self.assertEqual(shift.station, 'kitchen')
        self.assertEqual(self._shift_station(shift), 'kitchen')

    def test_manager_kitchen_shift_anchors_kitchen_till_not_bar(self):
        """The exact live bug: a manager's KITCHEN shift close must never be
        picked up as the BAR till's anchor."""
        self.client.force_login(self.manager)
        open_resp = self.client.post('/kitchen/shift/open/', {'opening_float': '0'})
        shift_id = open_resp.json()['shift_id']

        Transaction.objects.create(
            business=self.biz, item=self.kitchen_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
        )
        close_resp = self.client.post(f'/kitchen/shift/{shift_id}/close/', {
            'closing_cash_counted': '100',
        })
        self.assertTrue(close_resp.json()['ok'])

        bar_till = self.till_expected_cash(self.biz, 'bar')
        kitchen_till = self.till_expected_cash(self.biz, 'kitchen')
        self.assertFalse(
            bar_till['anchor_established'],
            "bar till must NOT pick up the manager's kitchen close as its own anchor",
        )
        self.assertIsNone(bar_till['expected_cash'])
        self.assertEqual(kitchen_till['expected_cash'], 100.0)

    def test_manager_kitchen_shift_reconcile_scopes_to_kitchen_items_only(self):
        self.client.force_login(self.manager)
        open_resp = self.client.post('/kitchen/shift/open/', {'opening_float': '0'})
        shift = Shift.objects.get(id=open_resp.json()['shift_id'])

        bar_item = Item.objects.create(
            business=self.biz, store=self.bar_store, material_no='SMT-2',
            description='Beer', unit='bottle', selling_price=Decimal('200'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.kitchen_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
            created_at=shift.started_at,
        )
        # A bar sale happening concurrently must NOT bleed into this manager's
        # kitchen shift reconciliation.
        Transaction.objects.create(
            business=self.biz, item=bar_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('200'), payment_method='cash',
            created_at=shift.started_at,
        )
        from core.shift_views import _reconcile
        rec = _reconcile(shift)
        self.assertEqual(rec['cash_sales'], 100.0)

    def test_shift_history_shows_manager_kitchen_shift_under_kitchen_filter(self):
        """Separate pre-existing bug found in the same investigation:
        shift_history()'s station filter relied on Shift.store, which is
        ALWAYS the business's first store regardless of actual counter — a
        kitchen-only viewer's filter (store__is_kitchen=True) could never
        match ANY shift. Now uses the same station predicate as till/reconcile."""
        self.client.force_login(self.manager)
        self.client.post('/kitchen/shift/open/', {'opening_float': '0'})

        kitchen_only = User.objects.create_user(username='smt_kitchen_only', password='x')
        UserProfile.objects.create(user=kitchen_only, business=self.biz, role='kitchen')
        # kitchen_only staff only sees their OWN shifts, so log in as owner to
        # confirm the manager's shift is correctly bucketed under "kitchen".
        self.client.force_login(self.owner)
        resp = self.client.get('/kitchen/shift/history/')
        self.assertEqual(resp.status_code, 200)
        rows = resp.context['rows']
        self.assertTrue(
            any(r['shift'].staff_id == self.manager.id for r in rows),
            'manager kitchen shift must appear in the kitchen-filtered history',
        )


class KitchenDirectSalePaymentSplitTest(TestCase):
    """2026-07-28 live report: kitchen board's Recent Payments panel had no
    split-payment (✂️ Gawanya) button/JS at all — only the bar board and
    Quick Sell got it in the 2026-07-26 sprint. The backend endpoint
    (split_transaction_payment_method) was already station-agnostic and
    correctly gated via _allowed_tab_sources per-item station — this locks
    that in for a kitchen item specifically, confirming the gap really was
    frontend-only (template fix), not a missing backend capability."""

    def setUp(self):
        self.biz = Business.objects.create(name='Kitchen Split Biz', has_kitchen=True)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.staff = User.objects.create_user(username='kbsp_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='kitchen')
        Shift.objects.create(business=self.biz, staff=self.staff, status='OPEN', station='kitchen')
        self.item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Chipo',
            material_no='KBSP-1', unit='Plate', selling_price=Decimal('100'),
        )
        self.txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='mpesa',
        )

    def test_kitchen_staff_can_split_kitchen_direct_sale(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/transactions/{self.txn.id}/split-payment/', {
            'new_method': 'cash', 'split_amount': '40',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.txn.refresh_from_db()
        self.assertEqual(float(self.txn.sale_amount), 60.0)
        self.assertEqual(self.txn.payment_method, 'mpesa')


# ── Checkout-time split payment for direct (non-tab) sales (2026-07-28) ──────
# Roy's live report: "across all counters for orders been paid straight up
# cash or mpesa and not going to tabs... there is no payment split modal we
# only have it in tabs... if chipo is 100 the customer may pay 40 cash and 60
# mpesa, this is important because at the end of the day physical cash and
# mpesa should be exactly accurate to what is in the system." Transaction.
# apply_split_payment_locked() is the shared model-layer entry point wired
# into Quick Sell, Bar Board, and Kitchen Board checkout — never blocks the
# sale itself (the goods/pours already happened by the time this runs), only
# recolors the payment_method(s) on the transaction(s) just created.

class ApplySplitPaymentLockedTest(TestCase):
    def setUp(self):
        self.biz = Business.objects.create(name='Split Model Biz')
        self.store = Store.objects.create(business=self.biz, name='Main')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Split Test Item',
            material_no='SPLIT-01', unit='pcs', selling_price=Decimal('100'),
        )

    def test_single_transaction_split_creates_sibling_with_correct_amounts(self):
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
        )
        Transaction.apply_split_payment_locked([txn.id], self.biz, Decimal('60'), 'mpesa')
        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'cash')
        self.assertEqual(float(txn.sale_amount), 40.0)
        sibling = Transaction.objects.filter(
            business=self.biz, item=self.item, payment_method='mpesa',
        ).exclude(id=txn.id).first()
        self.assertIsNotNone(sibling, 'Split must create a sibling transaction for the split portion')
        self.assertEqual(float(sibling.sale_amount), 60.0)
        self.assertEqual(sibling.qty, Decimal('0'), 'Split sibling must not double-deduct stock')

    def test_split_amount_gte_total_raises(self):
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
        )
        with self.assertRaises(ValueError):
            Transaction.apply_split_payment_locked([txn.id], self.biz, Decimal('100'), 'mpesa')
        with self.assertRaises(ValueError):
            Transaction.apply_split_payment_locked([txn.id], self.biz, Decimal('150'), 'mpesa')

    def test_zero_or_blank_split_amount_is_a_no_op(self):
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
        )
        Transaction.apply_split_payment_locked([txn.id], self.biz, Decimal('0'), 'mpesa')
        Transaction.apply_split_payment_locked([txn.id], self.biz, None, 'mpesa')
        self.assertEqual(
            Transaction.objects.filter(business=self.biz, item=self.item).count(), 1,
            'A zero/blank split amount must not create any sibling transaction',
        )

    def test_split_across_multiple_cart_lines_recolors_whole_lines_first(self):
        # Two lines of 100 each (cart total 200), customer pays 120 mpesa / 80 cash.
        # The split amount (80) should fully recolor the first whole transaction to
        # 'mpesa' rather than being spread proportionally.
        txn1 = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
        )
        txn2 = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
        )
        Transaction.apply_split_payment_locked(
            [txn1.id, txn2.id], self.biz, Decimal('120'), 'mpesa',
        )
        txn1.refresh_from_db()
        txn2.refresh_from_db()
        mpesa_total = sum(
            float(t.sale_amount) for t in Transaction.objects.filter(
                business=self.biz, item=self.item, payment_method='mpesa',
            )
        )
        cash_total = sum(
            float(t.sale_amount) for t in Transaction.objects.filter(
                business=self.biz, item=self.item, payment_method='cash',
            )
        )
        self.assertEqual(mpesa_total, 120.0)
        self.assertEqual(cash_total, 80.0)

    def test_ignores_transactions_already_on_the_split_method(self):
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='mpesa',
        )
        # Splitting into the SAME method as the original must not touch it.
        Transaction.apply_split_payment_locked([txn.id], self.biz, Decimal('50'), 'mpesa')
        self.assertEqual(
            Transaction.objects.filter(business=self.biz, item=self.item).count(), 1,
        )

    def test_no_txn_ids_is_a_no_op(self):
        Transaction.apply_split_payment_locked([], self.biz, Decimal('50'), 'mpesa')
        self.assertEqual(Transaction.objects.filter(business=self.biz).count(), 0)


