# ── Home dashboard till breakdown disclosure (2026-07-28) ──────────────────
# Roy's live follow-up after the anchor-established fix + cache-hardening
# still showed KES 1400 for Bar with no bar sales that day, and cache
# clearing on his end made no difference — strong evidence the figure was a
# genuine, correctly-computed number from a real (if surprising/forgotten)
# historical anchor, not a caching bug at all. Rather than keep guessing
# without database access, the home dashboard now surfaces
# till_expected_cash()'s own breakdown (anchor label + each component)
# directly on the card, owner-only, so a live "where did this number come
# from" question is self-answerable on screen.

class HomeDashboardTillBreakdownTest(TestCase):
    def setUp(self):
        from core.models import BusinessType
        bar_type, _created = BusinessType.objects.get_or_create(name='Bar / Pub (Local Joint)')
        self.biz = Business.objects.create(
            name='Breakdown Biz', has_kitchen=True, business_type=bar_type,
        )
        self.owner = User.objects.create_user(username='bd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='bd_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.bar_store = Store.objects.create(business=self.biz, name='Bar')
        self.bar_item = Item.objects.create(
            business=self.biz, store=self.bar_store, material_no='BD-1',
            description='Beer', unit='bottle', selling_price=Decimal('200'), is_keg=True,
        )
        Shift.objects.create(
            business=self.biz, store=self.bar_store, staff=self.staff,
            opening_float=Decimal('500'), status='CLOSED', station='bar',
            started_at=timezone.now() - timedelta(hours=6),
            ended_at=timezone.now() - timedelta(hours=5),
            closing_cash_counted=Decimal('1000'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.bar_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('400'), payment_method='cash',
            created_at=timezone.now() - timedelta(hours=4),
        )

    def test_owner_sees_bar_breakdown_with_correct_figures(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/')
        self.assertEqual(resp.status_code, 200)
        content = resp.content.decode()
        self.assertIn('vipi hesabu hii ilipatikana', content)
        self.assertIn('KES 1000', content)  # base
        self.assertIn('KES 400', content)   # cash sales since anchor
        self.assertIn('KES 1400', content)  # total shown in the summary tile

    def test_staff_does_not_see_breakdown_disclosure(self):
        self.client.force_login(self.staff)
        resp = self.client.get('/')
        self.assertEqual(resp.status_code, 200)
        self.assertNotIn('vipi hesabu hii ilipatikana', resp.content.decode())


class HomeDashboardStaleTabsBannerTest(TestCase):
    """2026-08-02 live request (Monsoon Inn) — Roy: instead of relying
    purely on the (now activity-based) auto-close sweep to silently
    resolve a tab left open from a previous day, surface it "right there
    on the first view of the dashboard" so staff/manager/owner can act
    deliberately. Station-scoped the same way every other tab surface in
    this app is."""

    def setUp(self):
        self.biz = Business.objects.create(name='Stale Banner Biz', has_kitchen=True)
        self.owner = User.objects.create_user(username='sbb_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.bar_staff = User.objects.create_user(username='sbb_barstaff', password='x')
        UserProfile.objects.create(user=self.bar_staff, business=self.biz, role='staff')
        self.kitchen_staff = User.objects.create_user(username='sbb_kitchenstaff', password='x')
        UserProfile.objects.create(user=self.kitchen_staff, business=self.biz, role='kitchen')

        # BarTab.opened_at is auto_now_add=True — any value passed at
        # .create() time is silently ignored by Django, so backdate via a
        # queryset .update() afterward, which bypasses that.
        yesterday_open = timezone.now() - timedelta(days=1)
        self.stale_bar_tab = BarTab.objects.create(
            business=self.biz, customer_name='Jana Bar Customer', status='OPEN', source='bar',
        )
        BarTab.objects.filter(id=self.stale_bar_tab.id).update(opened_at=yesterday_open)
        self.stale_kitchen_tab = BarTab.objects.create(
            business=self.biz, customer_name='Jana Kitchen Customer', status='OPEN', source='kitchen',
        )
        BarTab.objects.filter(id=self.stale_kitchen_tab.id).update(opened_at=yesterday_open)
        self.todays_tab = BarTab.objects.create(
            business=self.biz, customer_name='Leo Customer', status='OPEN', source='bar',
        )

    def test_owner_sees_both_stale_tabs(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/')
        self.assertEqual(resp.status_code, 200)
        content = resp.content.decode()
        self.assertIn('Jana Bar Customer', content)
        self.assertIn('Jana Kitchen Customer', content)

    def test_todays_tab_not_flagged_as_stale(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/')
        self.assertNotIn('Leo Customer', resp.content.decode())

    def test_bar_staff_sees_only_bar_stale_tab(self):
        self.client.force_login(self.bar_staff)
        resp = self.client.get('/')
        content = resp.content.decode()
        self.assertIn('Jana Bar Customer', content)
        self.assertNotIn('Jana Kitchen Customer', content)

    def test_kitchen_staff_sees_only_kitchen_stale_tab(self):
        self.client.force_login(self.kitchen_staff)
        resp = self.client.get('/')
        content = resp.content.decode()
        self.assertIn('Jana Kitchen Customer', content)
        self.assertNotIn('Jana Bar Customer', content)

    def test_no_banner_when_nothing_stale(self):
        self.stale_bar_tab.delete()
        self.stale_kitchen_tab.delete()
        self.client.force_login(self.owner)
        resp = self.client.get('/')
        self.assertNotIn('bado wazi tangu siku iliyopita', resp.content.decode())


class HomeDashboardStaleTabsQsStationFilterTest(TestCase):
    """2026-08-06 live report (Monsoon Inn) — Roy: "geuza deni reminder or
    unpaid bar tabs are being sent to the kitchen staff." Quick Sell ('qs')
    tabs have no station of their own and are always in the candidate set
    regardless of viewer station (Quick Sell is a general POS, unrestricted
    by design for write access) — but a purely-bar-drinks 'qs' tab reminder
    has no business showing up on a kitchen-only staffer's dashboard, and
    vice versa. Only a 'qs' tab whose entries actually touch the viewer's
    own station should surface here."""

    def setUp(self):
        self.biz = Business.objects.create(name='QS Station Filter Biz', has_kitchen=True)
        self.owner = User.objects.create_user(username='qssf_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.bar_staff = User.objects.create_user(username='qssf_barstaff', password='x')
        UserProfile.objects.create(user=self.bar_staff, business=self.biz, role='staff')
        self.kitchen_staff = User.objects.create_user(username='qssf_kitchenstaff', password='x')
        UserProfile.objects.create(user=self.kitchen_staff, business=self.biz, role='kitchen')

        self.bar_store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.bar_item = Item.objects.create(
            business=self.biz, store=self.bar_store, material_no='QSSF-1',
            description='Keg Gold', unit='cup', selling_price=Decimal('80'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, material_no='QSSF-2',
            description='Chipo', unit='plate', selling_price=Decimal('100'),
        )

        yesterday_open = timezone.now() - timedelta(days=1)

        self.qs_bar_only_tab = BarTab.objects.create(
            business=self.biz, customer_name='Dush', status='OPEN', source='qs',
        )
        BarTab.objects.filter(id=self.qs_bar_only_tab.id).update(opened_at=yesterday_open)
        bar_txn = Transaction.objects.create(
            business=self.biz, item=self.bar_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('80'), payment_method='credit',
            recipient='Dush',
        )
        BarTabEntry.objects.create(
            tab=self.qs_bar_only_tab, transaction=bar_txn, description='Keg Gold',
            amount=Decimal('80'), payment_method='credit',
        )

        self.qs_kitchen_only_tab = BarTab.objects.create(
            business=self.biz, customer_name='Matai', status='OPEN', source='qs',
        )
        BarTab.objects.filter(id=self.qs_kitchen_only_tab.id).update(opened_at=yesterday_open)
        kitchen_txn = Transaction.objects.create(
            business=self.biz, item=self.kitchen_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='credit',
            recipient='Matai',
        )
        BarTabEntry.objects.create(
            tab=self.qs_kitchen_only_tab, transaction=kitchen_txn, description='Chipo',
            amount=Decimal('100'), payment_method='credit',
        )

        self.qs_empty_tab = BarTab.objects.create(
            business=self.biz, customer_name='Mugambi', status='OPEN', source='qs',
        )
        BarTab.objects.filter(id=self.qs_empty_tab.id).update(opened_at=yesterday_open)

    def test_bar_only_staff_sees_bar_qs_tab_not_kitchen_qs_tab(self):
        self.client.force_login(self.bar_staff)
        content = self.client.get('/').content.decode()
        self.assertIn('Dush', content)
        self.assertNotIn('Matai', content)

    def test_kitchen_only_staff_sees_kitchen_qs_tab_not_bar_qs_tab(self):
        self.client.force_login(self.kitchen_staff)
        content = self.client.get('/').content.decode()
        self.assertIn('Matai', content)
        self.assertNotIn('Dush', content)

    def test_owner_sees_both_qs_tabs(self):
        self.client.force_login(self.owner)
        content = self.client.get('/').content.decode()
        self.assertIn('Dush', content)
        self.assertIn('Matai', content)

    def test_empty_qs_tab_visible_to_both_stations(self):
        self.client.force_login(self.bar_staff)
        self.assertIn('Mugambi', self.client.get('/').content.decode())
        self.client.force_login(self.kitchen_staff)
        self.assertIn('Mugambi', self.client.get('/').content.decode())


# ── Per-preset sale-time cost attribution + custom-price presets (2026-07-28) ──
# Roy's live design question: one shared "Kuku" item sells wings/legs/drumsticks
# via presets, but a chicken LEG split in half and sold at the SAME price as a
# drumstick (KES 150) does NOT cost the same as a drumstick. Before this,
# Transaction.cost() had no way to know WHICH preset made a sale — it only knew
# the item — so every preset sale was costed against one blended
# item.cost_price, which breaks the instant two presets share a price but not
# a cost. Transaction.preset (new FK) plus this cost() branch close that gap,
# reusing the existing preset.cost_price already written by Kitchen Stock
# Receipt (built 2026-07-25). Also introduces the "price=0 means ask staff for
# the amount at sale time" convention (for a small leg sold whole at a
# variable 150-200 depending on size) — deliberately a sentinel on the
# existing required `price` field rather than a new UI/model addition, to
# avoid touching item_form.html's already-fragile multi-mode preset table.

class TransactionPresetCostTest(TestCase):
    def setUp(self):
        self.biz = Business.objects.create(name='Preset Cost Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='PCOST-KUKU', unit='Pcs', selling_price=Decimal('0'),
            cost_price=Decimal('120'),  # stale/blended item-level cost
        )
        self.paja_nusu = ItemPortionPreset.objects.create(
            item=self.kuku, label='Paja Nusu', price=Decimal('150'),
            quantity_consumed=Decimal('0.5'), cost_price=Decimal('100'),  # per whole leg piece
        )
        self.bawa = ItemPortionPreset.objects.create(
            item=self.kuku, label='Bawa', price=Decimal('70'),
            quantity_consumed=Decimal('1'),  # no cost_price of its own yet
        )

    def test_preset_with_its_own_cost_overrides_blended_item_cost(self):
        txn = Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Issue',
            qty=Decimal('-0.5'), sale_amount=Decimal('150'), payment_method='cash',
            preset=self.paja_nusu,
        )
        # 0.5 (half leg) x KES 100 (cost per whole leg piece) = KES 50 — NOT
        # 0.5 x item.cost_price (120) = 60, and NOT the full 100.
        self.assertEqual(txn.cost(), 50.0)

    def test_preset_without_its_own_cost_falls_back_to_item_cost(self):
        txn = Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('70'), payment_method='cash',
            preset=self.bawa,
        )
        self.assertEqual(txn.cost(), 120.0)  # unchanged, ordinary item.cost_price path

    def test_no_preset_at_all_is_unaffected_regression_lock(self):
        txn = Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('100'), payment_method='cash',
        )
        self.assertEqual(txn.cost(), 120.0)

    def test_drumstick_and_half_leg_share_a_price_but_not_a_cost(self):
        """The exact scenario Roy described: two presets both sell at KES 150,
        but must never be costed the same."""
        drumstick = ItemPortionPreset.objects.create(
            item=self.kuku, label='Mguu', price=Decimal('150'),
            quantity_consumed=Decimal('1'), cost_price=Decimal('60'),
        )
        leg_txn = Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Issue',
            qty=Decimal('-0.5'), sale_amount=Decimal('150'), payment_method='cash',
            preset=self.paja_nusu,
        )
        drumstick_txn = Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('150'), payment_method='cash',
            preset=drumstick,
        )
        self.assertEqual(leg_txn.revenue(), drumstick_txn.revenue())  # same price
        self.assertNotEqual(leg_txn.cost(), drumstick_txn.cost())     # different cost
        self.assertEqual(leg_txn.cost(), 50.0)
        self.assertEqual(drumstick_txn.cost(), 60.0)


class KitchenBoardPresetCheckoutTest(TestCase):
    """End-to-end: Kitchen Board checkout must attach the preset that was
    actually sold to the Transaction, and support a custom ('price=0') preset
    where the amount comes from the cart entry, not a fixed preset price."""

    def setUp(self):
        self.biz = Business.objects.create(name='KB Preset Checkout Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='kbpc_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='KBPC-KUKU', unit='Pcs', selling_price=Decimal('0'),
        )
        self.paja_nusu = ItemPortionPreset.objects.create(
            item=self.kuku, label='Paja Nusu', price=Decimal('150'),
            quantity_consumed=Decimal('0.5'), cost_price=Decimal('100'),
        )
        self.paja_ndogo = ItemPortionPreset.objects.create(
            item=self.kuku, label='Paja Ndogo', price=Decimal('0'),  # custom-price sentinel
            quantity_consumed=Decimal('1'), cost_price=Decimal('100'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('20'),
        )
        self.client.force_login(self.owner)

    def test_fixed_price_preset_sale_attaches_preset_and_uses_its_cost(self):
        import json
        cart = json.dumps([{
            'item_id': self.kuku.id, 'preset_id': self.paja_nusu.id,
            'qty': 0.5, 'amount': 150, 'description': 'Kuku — Paja Nusu',
        }])
        resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        self.assertEqual(resp.status_code, 200)
        self.assertTrue(resp.json().get('ok'), resp.json())
        txn = Transaction.objects.filter(business=self.biz, item=self.kuku, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.preset_id, self.paja_nusu.id)
        self.assertEqual(txn.cost(), 50.0)

    def test_custom_price_preset_uses_the_amount_staff_entered(self):
        """Paja Ndogo has price=0 (custom) — the frontend prompts staff for the
        real amount and sends it as the cart entry's amount; the backend must
        trust that amount (it already does for every preset, this locks it in
        specifically for the custom-price case) and still attribute cost via
        the preset's own cost_price."""
        import json
        cart = json.dumps([{
            'item_id': self.kuku.id, 'preset_id': self.paja_ndogo.id,
            'qty': 1, 'amount': 180, 'description': 'Kuku — Paja Ndogo',
        }])
        resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'mpesa'})
        self.assertEqual(resp.status_code, 200)
        self.assertTrue(resp.json().get('ok'), resp.json())
        txn = Transaction.objects.filter(business=self.biz, item=self.kuku, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.preset_id, self.paja_ndogo.id)
        self.assertEqual(float(txn.sale_amount), 180.0)
        self.assertEqual(txn.cost(), 100.0)

    def test_preset_id_from_a_different_item_is_rejected(self):
        other_item = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='KBPC-CHIPO', unit='Plate', selling_price=Decimal('100'),
        )
        other_preset = ItemPortionPreset.objects.create(
            item=other_item, label='Kubwa', price=Decimal('100'), quantity_consumed=Decimal('1'),
        )
        import json
        cart = json.dumps([{
            'item_id': self.kuku.id, 'preset_id': other_preset.id,
            'qty': 0.5, 'amount': 150, 'description': 'Kuku — Paja Nusu',
        }])
        resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        self.assertEqual(resp.status_code, 200)
        txn = Transaction.objects.filter(business=self.biz, item=self.kuku, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertIsNone(txn.preset_id, "a preset belonging to a different item must never attach")


