class PresetAttributionLatentGapFixesTest(TestCase):
    """Four call sites already RESOLVED a preset (via preset_id) for some
    other purpose but silently dropped it instead of attaching it to the
    Transaction they created — found during the 2026-07-28 preset-cost sweep.
    None of these change behavior for a preset with no cost_price of its own
    (backward compatible); each locks in that the resolved preset is now
    actually recorded."""

    def setUp(self):
        self.biz = Business.objects.create(name='Latent Gap Biz', has_kitchen=True)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Main')
        self.owner = User.objects.create_user(username='lg_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kuku = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Kuku',
            material_no='LG-KUKU', unit='Pcs', selling_price=Decimal('100'),
        )
        self.preset = ItemPortionPreset.objects.create(
            item=self.kuku, label='Paja Nusu', price=Decimal('150'),
            quantity_consumed=Decimal('0.5'), cost_price=Decimal('100'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('20'),
        )

    def test_settle_qs_from_payment_attaches_preset(self):
        from core.mpesa_views import _settle_qs_from_payment
        from core.models import Payment
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Gin',
            material_no='LG-GIN', unit='Bottle', selling_price=Decimal('600'),
        )
        preset = ItemPortionPreset.objects.create(
            item=item, label='Half', price=Decimal('600'), quantity_consumed=Decimal('0.5'),
            cost_price=Decimal('800'),
        )
        Transaction.objects.create(
            business=self.biz, item=item, type='Receipt', qty=Decimal('10'),
        )
        payment = Payment.objects.create(
            business=self.biz, amount=Decimal('600'), phone='0700000000',
            status='completed',
            qs_cart=[{'item_id': item.id, 'qty': 0.5, 'amount': 600, 'preset_id': preset.id}],
        )
        from core.mpesa_views import _settle_qs_from_payment as settle
        settle(payment)
        txn = Transaction.objects.filter(business=self.biz, item=item, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.preset_id, preset.id)

    def test_settle_kitchen_order_from_payment_attaches_preset(self):
        from core.mpesa_views import _settle_kitchen_order_from_payment
        from core.models import Payment
        payment = Payment.objects.create(
            business=self.biz, amount=Decimal('150'), phone='0700000000',
            status='completed',
            kitchen_cart=[{
                'item_id': self.kuku.id, 'qty': 0.5, 'amount': 150,
                'preset_id': self.preset.id, 'description': 'Kuku — Paja Nusu',
            }],
        )
        _settle_kitchen_order_from_payment(payment)
        txn = Transaction.objects.filter(business=self.biz, item=self.kuku, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.preset_id, self.preset.id)

    def test_confirm_prompt_attaches_preset(self):
        from core.models import PendingTransactionPrompt
        prompt = PendingTransactionPrompt.objects.create(
            business=self.biz, phone='0700000000', amount=Decimal('150'), status='pending',
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/mpesa/prompt/{prompt.id}/confirm/', {
            'item_id': self.kuku.id, 'preset_id': self.preset.id,
        })
        self.assertEqual(resp.status_code, 200)
        txn = Transaction.objects.filter(business=self.biz, item=self.kuku, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.preset_id, self.preset.id)

    def test_served_table_order_attaches_preset(self):
        from core.models import TableOrder, TableOrderItem
        from accounts.models import UserProfile as _UP
        waitress = User.objects.create_user(username='lg_waitress', password='x')
        _UP.objects.create(user=waitress, business=self.biz, role='waitress')
        order = TableOrder.objects.create(
            business=self.biz, table_label='Table 3', waitress=waitress,
            status='ACCEPTED', payment_method='cash',
        )
        TableOrderItem.objects.create(
            order=order, item=self.kuku, preset=self.preset,
            quantity=Decimal('0.5'), unit_price=Decimal('150'),
            preset_label='Paja Nusu', item_name='Kuku',
        )
        from core.order_views import _create_transactions_for_order
        up = _UP.objects.get(user=waitress)
        _create_transactions_for_order(order, up)
        txn = Transaction.objects.filter(business=self.biz, item=self.kuku, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.preset_id, self.preset.id)


class AuthoritativePresetStockDeductionTest(TestCase):
    """2026-07-31 live urgent report (Roy, KC Ginger 250ml — physical count
    4.25 bottles, system showed 4.75, a discrepancy of exactly one
    half-bottle preset tap): every sale-recording path that accepts a
    preset_id from the client also accepted a client-supplied stock
    quantity for that same line, with no server-side check against the
    preset's own quantity_consumed — a stale cached preset in the browser,
    or any future client bug, could silently under- or over-deduct real
    stock. Bar Board's keg path (KegBarrel.record_sale) already derived ml
    server-side from the DB preset; this class locks in the same guarantee
    for Quick Sell, Kitchen Board, both STK settlement callbacks, and
    SERVED table-order conversion — in each case the TEST sends a wrong
    stock_qty/qty on purpose and asserts the preset's real
    quantity_consumed wins."""

    def setUp(self):
        self.biz = Business.objects.create(name='Authoritative Preset Biz', has_kitchen=True)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Liquor Store')
        self.owner = User.objects.create_user(username='apsd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='KC Ginger 250ML',
            material_no='APSD-KCG-01', unit='250ml', selling_price=Decimal('400'),
        )
        self.preset = ItemPortionPreset.objects.create(
            item=self.item, label='Nusu', price=Decimal('200'), quantity_consumed=Decimal('0.5'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('20'),
        )
        self.client.force_login(self.owner)

    def test_quick_sell_checkout_ignores_wrong_client_stock_qty(self):
        import json
        cart = json.dumps([{
            'id': self.item.id, 'qty': 1, 'price': 200,
            'stock_qty': 5,  # wildly wrong — real deduction must be 0.5, not 5
            'preset_id': self.preset.id,
        }])
        before = self.item.current_balance()
        self.client.post('/quick-sell/', {'cart': cart, 'payment_method': 'cash'})
        self.assertEqual(self.item.current_balance(), before - Decimal('0.5'))

    def test_quick_sell_checkout_multiplies_preset_qty_by_cart_taps(self):
        """Two taps of the same preset (cart qty=2) must deduct 2 × 0.5 = 1.0,
        not 2 × the (wrong) client stock_qty."""
        import json
        cart = json.dumps([{
            'id': self.item.id, 'qty': 2, 'price': 200,
            'stock_qty': 5, 'preset_id': self.preset.id,
        }])
        before = self.item.current_balance()
        self.client.post('/quick-sell/', {'cart': cart, 'payment_method': 'cash'})
        self.assertEqual(self.item.current_balance(), before - Decimal('1.0'))

    def test_kitchen_checkout_ignores_wrong_client_qty(self):
        import json
        kuku = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Kuku',
            material_no='APSD-KUKU-01', unit='Pcs', selling_price=Decimal('150'),
        )
        preset = ItemPortionPreset.objects.create(
            item=kuku, label='Paja Nusu', price=Decimal('150'), quantity_consumed=Decimal('0.5'),
        )
        Transaction.objects.create(business=self.biz, item=kuku, type='Receipt', qty=Decimal('20'))
        before = kuku.current_balance()
        cart = json.dumps([{
            'item_id': kuku.id, 'qty': 5, 'amount': 150,  # wrong — real is 0.5
            'preset_id': preset.id, 'description': 'Kuku — Paja Nusu',
        }])
        self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        self.assertEqual(kuku.current_balance(), before - Decimal('0.5'))

    def test_settle_qs_from_payment_ignores_wrong_client_qty(self):
        from core.mpesa_views import _settle_qs_from_payment
        from core.models import Payment
        before = self.item.current_balance()
        payment = Payment.objects.create(
            business=self.biz, amount=Decimal('200'), phone='0700000000',
            status='completed',
            qs_cart=[{
                'item_id': self.item.id, 'qty': 5, 'amount': 200,  # wrong — real is 0.5
                'preset_id': self.preset.id, 'description': 'KC Ginger — Nusu',
            }],
        )
        _settle_qs_from_payment(payment)
        self.assertEqual(self.item.current_balance(), before - Decimal('0.5'))

    def test_settle_kitchen_order_from_payment_ignores_wrong_client_qty(self):
        from core.mpesa_views import _settle_kitchen_order_from_payment
        from core.models import Payment
        kuku = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Kuku 2',
            material_no='APSD-KUKU-02', unit='Pcs', selling_price=Decimal('150'),
        )
        preset = ItemPortionPreset.objects.create(
            item=kuku, label='Paja Nusu', price=Decimal('150'), quantity_consumed=Decimal('0.5'),
        )
        Transaction.objects.create(business=self.biz, item=kuku, type='Receipt', qty=Decimal('20'))
        before = kuku.current_balance()
        payment = Payment.objects.create(
            business=self.biz, amount=Decimal('150'), phone='0700000000',
            status='completed',
            kitchen_cart=[{
                'item_id': kuku.id, 'qty': 5, 'amount': 150,  # wrong — real is 0.5
                'preset_id': preset.id, 'description': 'Kuku — Paja Nusu',
            }],
        )
        _settle_kitchen_order_from_payment(payment)
        self.assertEqual(kuku.current_balance(), before - Decimal('0.5'))

    def test_served_table_order_multiplies_count_by_preset_quantity(self):
        """A waitress order line's quantity is a COUNT of preset taps (e.g.
        '2 half-portions'), not the fractional stock amount directly — the
        real stock deduction must be count × quantity_consumed."""
        from core.models import TableOrder, TableOrderItem
        from core.order_views import _create_transactions_for_order
        kuku = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Kuku 3',
            material_no='APSD-KUKU-03', unit='Pcs', selling_price=Decimal('150'),
        )
        preset = ItemPortionPreset.objects.create(
            item=kuku, label='Paja Nusu', price=Decimal('150'), quantity_consumed=Decimal('0.5'),
        )
        Transaction.objects.create(business=self.biz, item=kuku, type='Receipt', qty=Decimal('20'))
        before = kuku.current_balance()
        waitress = User.objects.create_user(username='apsd_waitress', password='x')
        up = UserProfile.objects.create(user=waitress, business=self.biz, role='waitress')
        order = TableOrder.objects.create(
            business=self.biz, table_label='Table 9', waitress=waitress,
            status='ACCEPTED', payment_method='cash',
        )
        TableOrderItem.objects.create(
            order=order, item=kuku, preset=preset,
            quantity=Decimal('2'), unit_price=Decimal('150'),
            preset_label='Paja Nusu', item_name='Kuku',
        )
        _create_transactions_for_order(order, up)
        self.assertEqual(kuku.current_balance(), before - Decimal('1.0'))

    def test_served_table_order_does_not_crash_when_recording(self):
        """Regression lock for a real NameError: _create_transactions_for_
        order(order, up) used to reference an undefined `request` variable
        in its recorded_by fallback — caught silently by the loop's own
        try/except, which would have skipped the whole Transaction (zero
        stock effect) for that order line. Locked in by asserting the
        Transaction actually gets created with a real recorded_by."""
        from core.models import TableOrder, TableOrderItem
        from core.order_views import _create_transactions_for_order
        regular_item = Item.objects.create(
            business=self.biz, store=self.store, description='Soda',
            material_no='APSD-SODA-01', unit='Bottle', selling_price=Decimal('50'),
        )
        Transaction.objects.create(business=self.biz, item=regular_item, type='Receipt', qty=Decimal('10'))
        waitress = User.objects.create_user(username='apsd_waitress2', password='x')
        up = UserProfile.objects.create(user=waitress, business=self.biz, role='waitress')
        order = TableOrder.objects.create(
            business=self.biz, table_label='Table 10', waitress=waitress,
            status='ACCEPTED', payment_method='cash',
        )
        TableOrderItem.objects.create(
            order=order, item=regular_item, preset=None,
            quantity=Decimal('2'), unit_price=Decimal('50'),
            item_name='Soda',
        )
        _create_transactions_for_order(order, up)
        txn = Transaction.objects.filter(business=self.biz, item=regular_item, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.recorded_by_id, waitress.id)


class KitchenCustomPriceTest(TestCase):
    """2026-07-31 live request: "in the kitchen section... kitchen staff can
    input a custom selling price of a commodity in situations where the
    item been sold does not physically meet the quantity or size needed to
    sell at set price" (e.g. a chicken leg cut smaller than usual). The
    frontend ✏️ Bei Maalum affordance (kitchen_board.html) submits the exact
    same cart shape _kitchen_checkout() already parses for a normal preset
    tap — no backend change was needed, only a UI path that always prompts
    for the price instead of using the preset's configured one. These tests
    lock in the contract the frontend now relies on: the submitted `amount`
    becomes sale_amount verbatim (even when it doesn't match the preset's
    own price), while stock deduction still comes from the preset's own
    quantity_consumed regardless of the custom price entered — proving the
    two are correctly decoupled."""

    def setUp(self):
        self.biz = Business.objects.create(name='Kitchen Custom Price Biz', has_kitchen=True)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='kcp_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kuku = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Kuku',
            material_no='KCP-KUKU-01', unit='Pcs', selling_price=Decimal('150'),
        )
        self.preset = ItemPortionPreset.objects.create(
            item=self.kuku, label='Paja Nusu', price=Decimal('150'), quantity_consumed=Decimal('0.5'),
        )
        Transaction.objects.create(business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('20'))
        self.client.force_login(self.owner)

    def test_custom_price_overrides_configured_preset_price(self):
        """A smaller-than-usual leg sold via Bei Maalum for KES 100 instead
        of the configured KES 150 — sale_amount must reflect the entered
        100, not the preset's own 150."""
        import json
        cart = json.dumps([{
            'item_id': self.kuku.id, 'preset_id': self.preset.id,
            'description': 'Kuku — Paja Nusu (Bei Maalum)', 'amount': 100, 'qty': 0.5,
        }])
        self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        txn = Transaction.objects.filter(business=self.biz, item=self.kuku, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.sale_amount, Decimal('100'))

    def test_custom_price_does_not_change_stock_deduction(self):
        """The custom price must never influence how much stock the sale
        deducts — that still comes solely from the preset's own
        quantity_consumed, exactly like an ordinary preset tap."""
        import json
        before = self.kuku.current_balance()
        cart = json.dumps([{
            'item_id': self.kuku.id, 'preset_id': self.preset.id,
            'description': 'Kuku — Paja Nusu (Bei Maalum)', 'amount': 100, 'qty': 0.5,
        }])
        self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        self.assertEqual(self.kuku.current_balance(), before - Decimal('0.5'))

    def test_custom_price_with_no_preset_deducts_whole_item(self):
        """An item with no presets at all (customPriceTileClick's p=None
        branch) sells as a plain qty=1 custom-price line."""
        import json
        soda = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Soda Maalum',
            material_no='KCP-SODA-01', unit='Bottle', selling_price=Decimal('50'),
        )
        Transaction.objects.create(business=self.biz, item=soda, type='Receipt', qty=Decimal('10'))
        before = soda.current_balance()
        cart = json.dumps([{
            'item_id': soda.id, 'description': 'Soda Maalum (Bei Maalum)', 'amount': 70, 'qty': 1,
        }])
        self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        txn = Transaction.objects.filter(business=self.biz, item=soda, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.sale_amount, Decimal('70'))
        self.assertEqual(soda.current_balance(), before - Decimal('1'))


class KitchenBatchCustomPriceTest(TestCase):
    """2026-07-31 follow-up live report: the ✏️ Bei Maalum feature above only
    covered PORTION-mode items (Kuku cuts) — Roy's actual example was Chipo,
    a KitchenBatch revenue-envelope item ("sometimes the fries left by the
    day's end might be so little that it cannot be sold at 100"), which had
    no custom-price affordance at all. Fixed with a new "✏️ Bei Maalum"
    button on the batch tile's action row (kitchen_board.html), calling
    kbBatchSell() with preset_id=null and a staff-entered amount — no
    backend change needed, since KitchenBatch.record_sale() already accepts
    any amount with an optional preset purely for khaki-label bookkeeping.
    These tests lock in that a batch sale with no preset_id still correctly
    credits the exact custom amount to the envelope, including an amount
    BELOW every configured preset price (the actual scenario reported)."""

    def setUp(self):
        self.biz = Business.objects.create(name='KB Custom Price Biz', has_kitchen=True)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='kbcp_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.chipo = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Chipo',
            material_no='KBCP-CHIPO-01', unit='Batch', selling_price=Decimal('100'),
            is_kitchen_batch=True,
        )
        self.preset = ItemPortionPreset.objects.create(
            item=self.chipo, label='Ya 100', price=Decimal('100'), quantity_consumed=Decimal('1'),
        )
        self.batch = KitchenBatch.objects.create(
            business=self.biz, store=self.kitchen_store, item=self.chipo, cost_total=Decimal('1083'),
        )
        self.client.force_login(self.owner)

    def test_custom_price_below_every_preset_price_is_accepted(self):
        """The literal reported scenario: a near-empty batch sold for KES 40
        — below the KES 100 preset — must credit exactly 40, not be blocked
        or clamped to the preset's price."""
        import json
        cart = json.dumps([{
            'batch_id': self.batch.id, 'amount': 40,
            'description': 'Chipo (Bei Maalum)',
        }])
        resp = self.client.post('/kitchen/', {
            'cart': cart, 'payment_method': 'cash', 'idempotency_token': 'kbcp-below-1',
        })
        self.assertEqual(resp.status_code, 200)
        self.batch.refresh_from_db()
        self.assertEqual(self.batch.revenue_collected, Decimal('40'))

    def test_custom_price_sale_has_no_preset_and_no_khaki_count(self):
        """No preset_id sent means no khaki/label bookkeeping — must not
        silently attach or increment a preset's counters."""
        import json
        cart = json.dumps([{
            'batch_id': self.batch.id, 'amount': 40,
            'description': 'Chipo (Bei Maalum)',
        }])
        self.client.post('/kitchen/', {
            'cart': cart, 'payment_method': 'cash', 'idempotency_token': 'kbcp-nopreset-1',
        })
        txn = Transaction.objects.filter(business=self.biz, kitchen_batch=self.batch, type='Issue').first()
        self.assertIsNotNone(txn)
        self.assertIsNone(txn.preset)
        self.batch.refresh_from_db()
        self.assertEqual(self.batch.khaki_small_used, 0)
        self.assertEqual(self.batch.khaki_large_used, 0)

    def test_custom_price_sale_combines_correctly_with_normal_preset_sales(self):
        """A mix of ordinary Ya 100 taps and a reduced Bei Maalum sale on
        the same batch must accumulate to the correct total, exactly as if
        the reduced sale were just another preset tap at a different price."""
        import json
        normal_cart = json.dumps([{
            'batch_id': self.batch.id, 'preset_id': self.preset.id,
            'amount': 100, 'description': 'Ya 100',
        }])
        self.client.post('/kitchen/', {
            'cart': normal_cart, 'payment_method': 'cash', 'idempotency_token': 'kbcp-mix-1',
        })
        custom_cart = json.dumps([{
            'batch_id': self.batch.id, 'amount': 40,
            'description': 'Chipo (Bei Maalum)',
        }])
        self.client.post('/kitchen/', {
            'cart': custom_cart, 'payment_method': 'cash', 'idempotency_token': 'kbcp-mix-2',
        })
        self.batch.refresh_from_db()
        self.assertEqual(self.batch.revenue_collected, Decimal('140'))


# ── Manager-only delegated oversight toggles (2026-07-30) ──────────────────
# Roy's request: a per-manager toggle for petty cash review and shift-closing
# confirmation — both off by default, owner grants explicitly per manager.
# Shift confirmation has an extra rule Roy was explicit about: a manager's
# own shift close (and any other manager's) always needs the OWNER, no
# matter the toggle — only staff/waitress/kitchen shifts are delegable.

class OwnerSelfReviewPettyCashTillDeductionTest(TestCase):
    """2026-07-31 live urgent report: "petty cash confirmation when the
    owner was the one selling throughout the whole day of which he has a
    shift bypass so he just sells, ensure that the petty cash deducts
    accordingly ... and that the petty cash review section disappear once
    the owner confirms his petty cash withdrawals." review_petty_cash() has
    ALWAYS allowed the owner to self-review (only a manager is blocked from
    reviewing their own entry) — the actual gap was petty_cash_list.html,
    which unconditionally routed the owner's OWN entries into the
    staff-only edit/explain branch, rendering no approve/reject button at
    all. Since till_expected_cash() only ever counts status='approved'
    petty cash, an owner working solo had no way to ever get his own
    withdrawal out of 'pending' — the till stayed permanently inflated by
    that amount."""

    def setUp(self):
        from core.shift_views import till_expected_cash
        self.till_expected_cash = till_expected_cash
        self.biz = Business.objects.create(name='Owner Self Review PC Biz')
        self.owner = User.objects.create_user(username='osrpc_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.client.force_login(self.owner)
        # Bootstrap a till anchor via the spot-confirm endpoint (2026-07-30
        # feature) so till_expected_cash() has something to deduct from.
        self.client.post('/till/confirm/', {'station': 'bar', 'counted_amount': '1000'})
        self.entry = PettyCash.objects.create(
            business=self.biz, amount=Decimal('150'), reason='transport',
            recorded_by=self.owner, date=timezone.localdate(), station='bar',
        )

    def test_owners_own_pending_entry_renders_approve_button(self):
        """Regression lock for the template gap itself — the page must
        actually offer the owner a way to confirm his own entry."""
        resp = self.client.get('/petty-cash/')
        self.assertContains(resp, 'Thibitisha (wewe mwenyewe)')
        self.assertContains(resp, f"reviewEntry({self.entry.id}, 'approve')")

    def test_owner_can_approve_own_entry(self):
        resp = self.client.post(f'/petty-cash/{self.entry.id}/review/', {'action': 'approve'})
        self.assertEqual(resp.status_code, 200)
        self.assertTrue(resp.json().get('ok'), resp.json())
        self.entry.refresh_from_db()
        self.assertEqual(self.entry.status, 'approved')

    def test_approving_own_entry_deducts_from_till(self):
        before = self.till_expected_cash(self.biz, 'bar')
        self.assertEqual(before['expected_cash'], 1000.0)

        self.client.post(f'/petty-cash/{self.entry.id}/review/', {'action': 'approve'})

        after = self.till_expected_cash(self.biz, 'bar')
        self.assertEqual(
            after['expected_cash'], 850.0,
            'Approving the owner\'s own petty cash must deduct it from the running till, '
            'exactly like any other approved entry — the shift-bypass sale path is not special.',
        )

    def test_pending_review_indicator_disappears_once_confirmed(self):
        resp = self.client.get('/petty-cash/')
        self.assertIn(b'1 pending review', resp.content)

        self.client.post(f'/petty-cash/{self.entry.id}/review/', {'action': 'approve'})

        resp = self.client.get('/petty-cash/')
        self.assertNotIn(b'pending review', resp.content)
        # The Kubali/Kataa buttons stay in the markup (so "↺ Badilisha uamuzi"
        # can re-show them for the undo feature) but are rendered hidden —
        # the badge now reads Imekubaliwa instead of Inasubiri.
        self.assertContains(resp, '✓ Imekubaliwa')
        self.assertNotContains(resp, '⏳ Inasubiri')

    def test_owner_can_still_reject_own_mistaken_entry(self):
        resp = self.client.post(f'/petty-cash/{self.entry.id}/review/', {'action': 'reject'})
        self.assertEqual(resp.status_code, 200)
        self.entry.refresh_from_db()
        self.assertEqual(self.entry.status, 'rejected')
        # A rejected entry was never approved, so it must never be deducted.
        after = self.till_expected_cash(self.biz, 'bar')
        self.assertEqual(after['expected_cash'], 1000.0)


class ManagerPettyCashReviewToggleTest(TestCase):
    def setUp(self):
        self.biz = Business.objects.create(name='Manager PC Review Biz')
        self.owner = User.objects.create_user(username='mpcr_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='mpcr_manager', password='x')
        self.manager_profile = UserProfile.objects.create(
            user=self.manager, business=self.biz, role='manager',
        )
        self.staff = User.objects.create_user(username='mpcr_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')

        self.staff_entry = PettyCash.objects.create(
            business=self.biz, amount=Decimal('200'), recorded_by=self.staff,
        )
        self.manager_own_entry = PettyCash.objects.create(
            business=self.biz, amount=Decimal('300'), recorded_by=self.manager,
        )

    def _review(self, user, entry, action='approve'):
        self.client.force_login(user)
        return self.client.post(f'/petty-cash/{entry.id}/review/', {'action': action})

    def test_manager_without_toggle_cannot_review(self):
        resp = self._review(self.manager, self.staff_entry)
        self.assertEqual(resp.status_code, 403)
        self.staff_entry.refresh_from_db()
        self.assertEqual(self.staff_entry.status, 'pending')

    def test_manager_with_toggle_can_review_others_entry(self):
        self.manager_profile.can_review_petty_cash = True
        self.manager_profile.save(update_fields=['can_review_petty_cash'])
        resp = self._review(self.manager, self.staff_entry)
        self.assertEqual(resp.status_code, 200)
        self.assertTrue(resp.json().get('ok'), resp.json())
        self.staff_entry.refresh_from_db()
        self.assertEqual(self.staff_entry.status, 'approved')

    def test_manager_with_toggle_cannot_review_own_entry(self):
        self.manager_profile.can_review_petty_cash = True
        self.manager_profile.save(update_fields=['can_review_petty_cash'])
        resp = self._review(self.manager, self.manager_own_entry)
        self.assertEqual(resp.status_code, 403)
        self.manager_own_entry.refresh_from_db()
        self.assertEqual(self.manager_own_entry.status, 'pending')

    def test_owner_can_always_review_anything(self):
        resp = self._review(self.owner, self.manager_own_entry)
        self.assertEqual(resp.status_code, 200)
        self.assertTrue(resp.json().get('ok'), resp.json())

    def test_petty_cash_list_business_wide_only_with_toggle(self):
        # Without the toggle, a manager only sees their own entries.
        self.client.force_login(self.manager)
        resp = self.client.get('/petty-cash/')
        self.assertNotContains(resp, 'mpcr_staff')

        self.manager_profile.can_review_petty_cash = True
        self.manager_profile.save(update_fields=['can_review_petty_cash'])
        resp = self.client.get('/petty-cash/')
        # Business-wide view now includes the staff entry's amount.
        self.assertContains(resp, '200')


