class QuickSellCatchUpBackdateTest(TestCase):
    """2026-08-07 live request — "no time for [Add Transaction's] long
    process when the items are too many": one backdated timestamp applied
    to a WHOLE Quick Sell cart at checkout, reusing the fast search-and-tap
    flow instead of one item at a time. Must correctly land in the right
    day's shift/revenue window, not today's. Originally excluded Tab sales
    (2026-08-07); widened to include them 2026-08-21 (see
    test_backdated_tab_sale_uses_the_given_timestamp) once Roy's real usage
    made clear the SALE's own date still needs correcting even for a tab
    round — only the BarTab record's own creation moment stays "now"."""

    def setUp(self):
        self.biz = Business.objects.create(name='QS Backdate Biz', has_kitchen=False)
        self.store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.owner = User.objects.create_user(username='qsbd_owner', password='x')
        self.owner_up = UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, material_no='QSBD-1',
            description='Beer', unit='Pcs', selling_price=Decimal('200'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('50'),
        )
        self.yesterday = timezone.now() - timedelta(days=1)

    def _iso(self, dt):
        return timezone.localtime(dt).strftime('%Y-%m-%dT%H:%M')

    def test_backdated_cash_sale_uses_the_given_timestamp(self):
        self.client.force_login(self.owner)
        resp = self.client.post('/quick-sell/', {
            'cart': json.dumps([{'id': self.item.id, 'qty': 2}]),
            'payment_method': 'cash',
            'backdated_at': self._iso(self.yesterday),
            'idempotency_token': 'qsbd-1',
        })
        self.assertEqual(resp.status_code, 200)
        txn = Transaction.objects.get(business=self.biz, item=self.item, type='Issue')
        self.assertEqual(timezone.localtime(txn.created_at).strftime('%Y-%m-%d %H:%M'),
                          timezone.localtime(self.yesterday).strftime('%Y-%m-%d %H:%M'))

    def test_no_backdate_uses_now(self):
        self.client.force_login(self.owner)
        before = timezone.now()
        resp = self.client.post('/quick-sell/', {
            'cart': json.dumps([{'id': self.item.id, 'qty': 1}]),
            'payment_method': 'cash',
            'idempotency_token': 'qsbd-2',
        })
        self.assertEqual(resp.status_code, 200)
        txn = Transaction.objects.get(business=self.biz, item=self.item, type='Issue')
        self.assertGreaterEqual(txn.created_at, before)

    def test_backdated_direct_credit_sale_uses_the_given_timestamp(self):
        # 2026-08-12 live request — "ensure that for backdating i can put
        # customer in debt for that day... right there on the selling part":
        # a direct Deni (credit) checkout must now honor backdated_at too,
        # not just cash/mpesa.
        self.client.force_login(self.owner)
        resp = self.client.post('/quick-sell/', {
            'cart': json.dumps([{'id': self.item.id, 'qty': 1}]),
            'payment_method': 'credit', 'recipient': 'Mteja X',
            'backdated_at': self._iso(self.yesterday),
            'idempotency_token': 'qsbd-3',
        })
        self.assertEqual(resp.status_code, 200)
        txn = Transaction.objects.get(business=self.biz, item=self.item, type='Issue')
        self.assertEqual(txn.payment_method, 'credit')
        self.assertEqual(txn.recipient, 'Mteja X')
        self.assertEqual(timezone.localtime(txn.created_at).strftime('%Y-%m-%d %H:%M'),
                          timezone.localtime(self.yesterday).strftime('%Y-%m-%d %H:%M'))

    def test_backdated_tab_sale_uses_the_given_timestamp(self):
        # 2026-08-21 live report (Roy, re-entering a two-day paper sales
        # log): "quick sell/bar orders has no back date when the item is in
        # tabs drawer" — Tab was previously excluded (an open running bill
        # isn't "already happened"), but the SALE's own revenue/stock/debt-
        # aging impact still needs the real historical date, same as every
        # other payment method. The BarTab record itself is still created
        # "now" (the true moment it's entered into the system) — only its
        # underlying Transaction gets backdated.
        self.client.force_login(self.owner)
        resp = self.client.post('/quick-sell/', {
            'cart': json.dumps([{'id': self.item.id, 'qty': 1}]),
            'payment_method': 'tab', 'recipient': 'Tab Customer',
            'backdated_at': self._iso(self.yesterday),
            'idempotency_token': 'qsbd-3b',
        })
        self.assertEqual(resp.status_code, 200)
        txn = Transaction.objects.get(business=self.biz, item=self.item, type='Issue')
        self.assertEqual(txn.payment_method, 'credit')
        self.assertEqual(timezone.localtime(txn.created_at).strftime('%Y-%m-%d %H:%M'),
                          timezone.localtime(self.yesterday).strftime('%Y-%m-%d %H:%M'))
        from core.models import BarTab
        tab = BarTab.objects.get(business=self.biz, customer_name='Tab Customer')
        self.assertTrue(tab.entries.filter(transaction=txn).exists())

    def test_backdated_sale_split_payment_remainder_inherits_timestamp(self):
        self.client.force_login(self.owner)
        resp = self.client.post('/quick-sell/', {
            'cart': json.dumps([{'id': self.item.id, 'qty': 1}]),
            'payment_method': 'cash',
            'backdated_at': self._iso(self.yesterday),
            'split_amount': '80', 'split_method': 'mpesa',
            'idempotency_token': 'qsbd-4',
        })
        self.assertEqual(resp.status_code, 200)
        txns = Transaction.objects.filter(business=self.biz, item=self.item, type='Issue').order_by('id')
        self.assertEqual(txns.count(), 2)
        for t in txns:
            self.assertEqual(timezone.localtime(t.created_at).strftime('%Y-%m-%d %H:%M'),
                              timezone.localtime(self.yesterday).strftime('%Y-%m-%d %H:%M'))

    def test_backdated_sale_excluded_from_todays_revenue_window(self):
        from core.shift_views import station_revenue_window_start, _window_revenue
        self.client.force_login(self.owner)
        self.client.post('/quick-sell/', {
            'cart': json.dumps([{'id': self.item.id, 'qty': 1}]),
            'payment_method': 'cash',
            'backdated_at': self._iso(self.yesterday),
            'idempotency_token': 'qsbd-5',
        })
        window_start = station_revenue_window_start(self.biz, is_kitchen=False)
        today_revenue = _window_revenue(self.biz, is_kitchen=False, start=window_start, end=timezone.now())
        self.assertEqual(today_revenue, 0)


class OwnerConsumptionCorrectionAndSettlementTest(TestCase):
    """2026-08-07 live request — Roy: "no trail for mmiliki alichukuwa
    whereby in the instance a staff made a mistake they cannot correct or
    follow up on it and then there is no way for the owner to pay for what
    he was given." Covers the new list page, void (correction), and settle
    (repayment) actions."""

    def setUp(self):
        self.biz = Business.objects.create(name='OC Correction Biz')
        self.store = Store.objects.create(business=self.biz, name='Shop')
        self.owner = User.objects.create_user(username='occ_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='occ_staff', password='x')
        self.staff_up = UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.other_staff = User.objects.create_user(username='occ_other', password='x')
        UserProfile.objects.create(user=self.other_staff, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Whisky',
            material_no='OCC-01', unit='pcs', selling_price=Decimal('500'),
            cost_price=Decimal('300'),
        )
        Transaction.objects.create(business=self.biz, item=self.item, type='Receipt', qty=Decimal('20'))
        Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff,
            status='OPEN', opening_float=Decimal('0'), station='bar',
        )

    def _record(self, actor, qty='2'):
        import uuid
        self.client.force_login(actor)
        self.client.post('/stock/owner-consumption/', {
            'item_id': self.item.id, 'qty': qty, 'note': 'test',
            'idempotency_token': f'occ-rec-{uuid.uuid4()}',
        })
        return Transaction.objects.filter(
            business=self.biz, item=self.item, type='OwnerConsumption',
        ).exclude(invoice_no='[OC-VOID]').latest('id')

    def test_list_page_loads_and_shows_entry(self):
        self._record(self.staff)
        self.client.force_login(self.owner)
        resp = self.client.get('/stock/owner-consumption/list/')
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, 'Whisky')

    def test_recorder_can_void_own_mistake(self):
        before_balance = self.item.current_balance()
        txn = self._record(self.staff)
        self.client.force_login(self.staff)
        resp = self.client.post(f'/stock/owner-consumption/{txn.id}/void/', {'reason': 'Nilikosea item'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        txn.refresh_from_db()
        self.assertEqual(txn.qty, Decimal('0'))
        self.assertEqual(txn.invoice_no, '[OC-VOID]')
        self.assertEqual(self.item.current_balance(), before_balance)

    def test_other_staff_cannot_void_someone_elses_entry(self):
        txn = self._record(self.staff)
        self.client.force_login(self.other_staff)
        resp = self.client.post(f'/stock/owner-consumption/{txn.id}/void/', {'reason': 'x'})
        self.assertEqual(resp.status_code, 403)
        txn.refresh_from_db()
        self.assertNotEqual(txn.qty, Decimal('0'))

    def test_owner_can_void_any_entry(self):
        txn = self._record(self.staff)
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/owner-consumption/{txn.id}/void/', {'reason': 'Owner correction'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        txn.refresh_from_db()
        self.assertEqual(txn.qty, Decimal('0'))

    def test_staff_cannot_settle_payment(self):
        import uuid
        txn = self._record(self.staff)
        self.client.force_login(self.staff)
        resp = self.client.post(f'/stock/owner-consumption/{txn.id}/settle/', {
            'amount': '1000', 'payment_method': 'cash', 'idempotency_token': f'occ-settle-{uuid.uuid4()}',
        })
        self.assertEqual(resp.status_code, 403)

    def test_owner_can_settle_payment_and_it_counts_as_revenue(self):
        import uuid
        txn = self._record(self.staff)
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/owner-consumption/{txn.id}/settle/', {
            'amount': '1000', 'payment_method': 'cash', 'idempotency_token': f'occ-settle-{uuid.uuid4()}',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        settlement = Transaction.objects.get(settles_transaction=txn)
        self.assertEqual(settlement.type, 'Issue')
        self.assertEqual(settlement.qty, Decimal('0'))
        self.assertEqual(settlement.sale_amount, Decimal('1000'))
        self.assertEqual(settlement.payment_method, 'cash')
        # Real revenue — flows through revenue() like any ordinary sale.
        self.assertEqual(settlement.revenue(), 1000.0)
        # No additional stock movement — it already left at consumption time.
        self.assertEqual(settlement.cost(), 0)

    def test_cannot_settle_twice(self):
        import uuid
        txn = self._record(self.staff)
        self.client.force_login(self.owner)
        self.client.post(f'/stock/owner-consumption/{txn.id}/settle/', {
            'amount': '1000', 'payment_method': 'cash', 'idempotency_token': f'occ-settle-{uuid.uuid4()}',
        })
        resp = self.client.post(f'/stock/owner-consumption/{txn.id}/settle/', {
            'amount': '1000', 'payment_method': 'cash', 'idempotency_token': f'occ-settle-{uuid.uuid4()}',
        })
        self.assertEqual(resp.status_code, 409)
        self.assertEqual(Transaction.objects.filter(settles_transaction=txn).count(), 1)

    def test_cannot_void_a_settled_entry(self):
        import uuid
        txn = self._record(self.staff)
        self.client.force_login(self.owner)
        self.client.post(f'/stock/owner-consumption/{txn.id}/settle/', {
            'amount': '1000', 'payment_method': 'cash', 'idempotency_token': f'occ-settle-{uuid.uuid4()}',
        })
        resp = self.client.post(f'/stock/owner-consumption/{txn.id}/void/', {'reason': 'x'})
        self.assertEqual(resp.status_code, 409)
        txn.refresh_from_db()
        self.assertNotEqual(txn.qty, Decimal('0'))

    def test_void_is_idempotent(self):
        txn = self._record(self.staff)
        self.client.force_login(self.owner)
        r1 = self.client.post(f'/stock/owner-consumption/{txn.id}/void/', {'reason': 'x'})
        r2 = self.client.post(f'/stock/owner-consumption/{txn.id}/void/', {'reason': 'x'})
        self.assertTrue(r1.json()['ok'])
        self.assertTrue(r2.json()['ok'])
        self.assertTrue(r2.json().get('already_void'))


class OwnerConsumptionPriceCaptureTest(TestCase):
    """2026-08-12 live request (Roy) — "he gets to see every item, the
    price, the quantities": record_owner_consumption() now captures a
    price (auto-filled from item.selling_price × qty, editable), stored on
    sale_amount — verified never to leak into revenue() since it gates on
    type != 'Issue' first."""

    def setUp(self):
        self.biz = Business.objects.create(name='OCP Biz')
        self.store = Store.objects.create(business=self.biz, name='Shop')
        self.owner = User.objects.create_user(username='ocp_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Gin 750ml',
            material_no='OCP-01', unit='pcs', selling_price=Decimal('1200'),
        )
        Transaction.objects.create(business=self.biz, item=self.item, type='Receipt', qty=Decimal('10'))
        self.client.force_login(self.owner)

    def test_price_auto_fills_from_selling_price(self):
        import uuid
        self.client.post('/stock/owner-consumption/', {
            'item_id': self.item.id, 'qty': '2',
            'idempotency_token': f'ocp-{uuid.uuid4()}',
        })
        txn = Transaction.objects.filter(business=self.biz, item=self.item, type='OwnerConsumption').latest('id')
        self.assertEqual(txn.sale_amount, Decimal('2400'))

    def test_price_editable(self):
        import uuid
        self.client.post('/stock/owner-consumption/', {
            'item_id': self.item.id, 'qty': '1', 'price': '900',
            'idempotency_token': f'ocp-{uuid.uuid4()}',
        })
        txn = Transaction.objects.filter(business=self.biz, item=self.item, type='OwnerConsumption').latest('id')
        self.assertEqual(txn.sale_amount, Decimal('900'))

    def test_revenue_never_counts_owner_consumption(self):
        import uuid
        self.client.post('/stock/owner-consumption/', {
            'item_id': self.item.id, 'qty': '3',
            'idempotency_token': f'ocp-{uuid.uuid4()}',
        })
        txn = Transaction.objects.filter(business=self.biz, item=self.item, type='OwnerConsumption').latest('id')
        self.assertEqual(txn.revenue(), 0)
        self.assertEqual(txn.cost(), 0)


class OwnerConsumptionTransferTest(TestCase):
    """2026-08-12 live request (Roy) — the owner's own accountability
    section, with transfers to/from a real customer's tab/debt, each side
    needing an accept before anything moves. Verifies: in-place Transaction.
    type reclassification (no new row, no double stock deduction), reject
    leaves everything untouched, and both directions correctly appear/
    disappear from the debt tracker and the owner's own ledger."""

    def setUp(self):
        self.biz, self.store, self.staff, self.item, self.barrel, self.preset = _make_keg_fixtures(
            'OCT Biz'
        )
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.owner = User.objects.create_user(username='oct_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='oct_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff,
            status='OPEN', opening_float=Decimal('0'), station='bar',
        )

    def _make_debt_txn(self, customer_name='Mary', amount='500'):
        return Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal(amount), payment_method='credit', recipient=customer_name,
            date=timezone.localdate(),
        )

    def _make_owner_draw(self, amount='300'):
        return Transaction.objects.create(
            business=self.biz, item=self.item, type='OwnerConsumption', qty=Decimal('-1'),
            sale_amount=Decimal(amount), payment_method='', recipient='Mmiliki',
            date=timezone.localdate(),
        )

    # ── to_owner direction ──────────────────────────────────────────────

    def test_propose_to_owner_and_accept_reclassifies_transaction(self):
        txn = self._make_debt_txn()
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn.id})
        self.assertTrue(resp.json()['ok'], resp.json())
        req_id = resp.json()['request_ids'][0]

        self.client.force_login(self.owner)
        resp2 = self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'accept'})
        self.assertTrue(resp2.json()['ok'], resp2.json())

        txn.refresh_from_db()
        self.assertEqual(txn.type, 'OwnerConsumption')
        self.assertEqual(txn.payment_method, '')
        self.assertEqual(txn.recipient, 'Mmiliki')
        # Disappeared from revenue/debt aggregates by construction.
        self.assertEqual(txn.revenue(), 0)

    def test_reject_to_owner_leaves_debt_untouched(self):
        txn = self._make_debt_txn()
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn.id})
        req_id = resp.json()['request_ids'][0]

        self.client.force_login(self.owner)
        resp2 = self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'reject'})
        self.assertTrue(resp2.json()['ok'], resp2.json())

        txn.refresh_from_db()
        self.assertEqual(txn.type, 'Issue')
        self.assertEqual(txn.payment_method, 'credit')
        self.assertEqual(txn.recipient, 'Mary')

    def test_to_owner_never_double_deducts_stock(self):
        before = self.item.current_balance()
        txn = self._make_debt_txn()
        after_sale = self.item.current_balance()
        self.assertEqual(before - after_sale, Decimal('1'))  # the original sale deducted once

        self.client.force_login(self.staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn.id})
        req_id = resp.json()['request_ids'][0]
        self.client.force_login(self.owner)
        self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'accept'})

        self.assertEqual(self.item.current_balance(), after_sale)  # unchanged by reclassification

    def test_staff_cannot_accept_to_owner_transfer(self):
        txn = self._make_debt_txn()
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn.id})
        req_id = resp.json()['request_ids'][0]
        resp2 = self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'accept'})
        self.assertEqual(resp2.status_code, 403)
        txn.refresh_from_db()
        self.assertEqual(txn.type, 'Issue')

    def test_manager_can_accept_to_owner_transfer(self):
        txn = self._make_debt_txn()
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn.id})
        req_id = resp.json()['request_ids'][0]
        self.client.force_login(self.manager)
        resp2 = self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'accept'})
        self.assertTrue(resp2.json()['ok'], resp2.json())

    def test_cannot_propose_duplicate_pending_transfer(self):
        txn = self._make_debt_txn()
        self.client.force_login(self.staff)
        self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn.id})
        resp2 = self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn.id})
        self.assertFalse(resp2.json()['ok'])

    # ── from_owner direction ────────────────────────────────────────────

    def test_propose_from_owner_and_accept_creates_tab_entry(self):
        txn = self._make_owner_draw()
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/owner-consumption/transfer/from-owner/', {
            'txn_ids': str(txn.id), 'dest_customer_name': 'Bosco',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        req_id = resp.json()['request_ids'][0]

        resp2 = self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'accept'})
        self.assertTrue(resp2.json()['ok'], resp2.json())

        txn.refresh_from_db()
        self.assertEqual(txn.type, 'Issue')
        self.assertEqual(txn.payment_method, 'credit')
        self.assertEqual(txn.recipient, 'Bosco')
        tab = BarTab.objects.filter(business=self.biz, customer_name='Bosco', status='OPEN').first()
        self.assertIsNotNone(tab)
        self.assertTrue(BarTabEntry.objects.filter(tab=tab, transaction=txn).exists())

    def test_from_owner_reuses_existing_open_tab_by_name(self):
        existing_tab = BarTab.create_with_credentials(
            business=self.biz, customer_name='Bosco', status='OPEN', source='bar',
        )
        txn = self._make_owner_draw()
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/owner-consumption/transfer/from-owner/', {
            'txn_ids': str(txn.id), 'dest_customer_name': 'Bosco',
        })
        req_id = resp.json()['request_ids'][0]
        self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'accept'})

        self.assertEqual(BarTab.objects.filter(business=self.biz, customer_name='Bosco').count(), 1)
        self.assertTrue(BarTabEntry.objects.filter(tab=existing_tab, transaction=txn).exists())

    def test_reject_from_owner_leaves_it_on_owner_ledger(self):
        txn = self._make_owner_draw()
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/owner-consumption/transfer/from-owner/', {
            'txn_ids': str(txn.id), 'dest_customer_name': 'Bosco',
        })
        req_id = resp.json()['request_ids'][0]
        resp2 = self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'reject'})
        self.assertTrue(resp2.json()['ok'], resp2.json())
        txn.refresh_from_db()
        self.assertEqual(txn.type, 'OwnerConsumption')
        self.assertFalse(BarTabEntry.objects.filter(transaction=txn).exists())

    def test_whole_bill_transfer_resolves_as_one_decision(self):
        txn1 = self._make_owner_draw('200')
        txn2 = self._make_owner_draw('150')
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/owner-consumption/transfer/from-owner/', {
            'txn_ids': f'{txn1.id},{txn2.id}', 'dest_customer_name': 'Bosco',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        req_ids = resp.json()['request_ids']
        self.assertEqual(len(req_ids), 2)

        # Accepting ONE row in the batch resolves both.
        self.client.post(f'/stock/owner-consumption/transfer/{req_ids[0]}/respond/', {'action': 'accept'})
        txn1.refresh_from_db()
        txn2.refresh_from_db()
        self.assertEqual(txn1.type, 'Issue')
        self.assertEqual(txn2.type, 'Issue')

    def test_owner_consumption_list_shows_pending_to_owner_section(self):
        txn = self._make_debt_txn()
        self.client.force_login(self.staff)
        self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn.id})
        self.client.force_login(self.owner)
        resp = self.client.get('/stock/owner-consumption/list/')
        self.assertContains(resp, 'Vinavyosubiri Uamuzi Wako')
        self.assertContains(resp, 'Mary')

    def test_propose_to_owner_bulk_multiple_ids_batched(self):
        """2026-08-13 — propose_to_owner_locked widened to accept several
        ids at once, batched under one batch_id so accept/reject resolves
        them all as one decision (mirroring the from_owner direction's
        existing whole-bill behaviour)."""
        txn1 = self._make_debt_txn('Bosco', '500')
        txn2 = self._make_debt_txn('Bosco', '300')
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/', {
            'txn_ids': f'{txn1.id},{txn2.id}',
        })
        d = resp.json()
        self.assertTrue(d['ok'], d)
        self.assertEqual(len(d['request_ids']), 2)

        req_id = d['request_ids'][0]
        resp2 = self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'accept'})
        self.assertTrue(resp2.json()['ok'], resp2.json())
        txn1.refresh_from_db()
        txn2.refresh_from_db()
        self.assertEqual(txn1.type, 'OwnerConsumption')
        self.assertEqual(txn2.type, 'OwnerConsumption')

    def test_propose_to_owner_bulk_skips_already_pending_not_errors(self):
        """A resync call that includes an id already proposed must silently
        skip it (not error the whole batch) — only errors when NOTHING in
        the set is eligible."""
        txn1 = self._make_debt_txn('Bosco', '500')
        txn2 = self._make_debt_txn('Bosco', '300')
        self.client.force_login(self.owner)
        self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn1.id})
        # Resync call includes BOTH — txn1 already pending, txn2 is new.
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/', {
            'txn_ids': f'{txn1.id},{txn2.id}',
        })
        d = resp.json()
        self.assertTrue(d['ok'], d)
        self.assertEqual(len(d['request_ids']), 1)  # only txn2's new request

    def test_propose_to_owner_bulk_all_already_pending_errors(self):
        txn = self._make_debt_txn('Bosco', '500')
        self.client.force_login(self.owner)
        self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_id': txn.id})
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/', {'txn_ids': str(txn.id)})
        self.assertFalse(resp.json()['ok'])


class OwnerConsumptionPartialTransferTest(TestCase):
    """2026-08-16 live request (Roy): "customer acquisition of an item and
    partial payment is going to the owner" — a customer pays PART of a
    credit item/debt themselves, right now, and only the REMAINDER is
    proposed to the owner (still needs his accept). Mirrors the customer-
    to-customer split-transfer feature's paid_amount>0 shape, but for
    both a plain non-tab debt AND a tab-linked debt-converted entry."""

    def setUp(self):
        self.biz, self.store, self.staff, self.item, self.barrel, self.preset = _make_keg_fixtures(
            'OCPT Biz'
        )
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.owner = User.objects.create_user(username='ocpt_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff,
            status='OPEN', opening_float=Decimal('0'), station='bar',
        )

    def _make_debt_txn(self, customer_name='Mary', amount='500'):
        if not Customer.objects.filter(business=self.biz, name=customer_name).exists():
            Customer.objects.create(business=self.biz, name=customer_name, credit_approved=True)
        return Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal(amount), payment_method='credit', recipient=customer_name,
            date=timezone.localdate(),
        )

    def test_non_tab_partial_transfer_splits_correctly(self):
        txn = self._make_debt_txn('Mary', '500')
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/partial/', {
            'txn_id': txn.id, 'paid_amount': '200', 'paid_method': 'mpesa',
        })
        d = resp.json()
        self.assertTrue(d['ok'], d)

        txn.refresh_from_db()
        self.assertEqual(txn.payment_method, 'mpesa')
        self.assertEqual(float(txn.sale_amount), 200.0)
        self.assertTrue(txn.was_credit)  # genuinely paid off, must self-heal from the debt tracker

        from core.models import OwnerConsumptionTransferRequest
        req = OwnerConsumptionTransferRequest.objects.get(id=d['request_id'])
        self.assertEqual(req.status, 'PENDING')
        self.assertEqual(float(req.source_txn.sale_amount), 300.0)
        self.assertEqual(req.source_txn.payment_method, 'credit')
        self.assertEqual(req.source_txn.recipient, 'Mary')

        from core.debt_views import _get_customer_debt_data
        customer = Customer.objects.get(business=self.biz, name='Mary')
        data = _get_customer_debt_data(customer, self.biz)
        # 300 still shows as owed by Mary until the owner accepts.
        self.assertEqual(data['outstanding'], 300.0)

    def test_accepting_partial_transfer_reclassifies_only_the_remainder(self):
        txn = self._make_debt_txn('Mary', '500')
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/partial/', {
            'txn_id': txn.id, 'paid_amount': '200', 'paid_method': 'cash',
        })
        req_id = resp.json()['request_id']

        self.client.force_login(self.owner)
        resp2 = self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'accept'})
        self.assertTrue(resp2.json()['ok'], resp2.json())

        from core.models import OwnerConsumptionTransferRequest
        req = OwnerConsumptionTransferRequest.objects.get(id=req_id)
        remainder_txn = req.source_txn
        remainder_txn.refresh_from_db()
        self.assertEqual(remainder_txn.type, 'OwnerConsumption')
        self.assertEqual(remainder_txn.recipient, 'Mmiliki')

        from core.debt_views import _get_customer_debt_data
        customer = Customer.objects.get(business=self.biz, name='Mary')
        data = _get_customer_debt_data(customer, self.biz)
        self.assertEqual(data['outstanding'], 0.0)  # 200 paid + 300 now the owner's

    def test_rejecting_partial_transfer_leaves_remainder_as_ordinary_debt(self):
        txn = self._make_debt_txn('Mary', '500')
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/partial/', {
            'txn_id': txn.id, 'paid_amount': '200', 'paid_method': 'cash',
        })
        req_id = resp.json()['request_id']

        self.client.force_login(self.owner)
        resp2 = self.client.post(f'/stock/owner-consumption/transfer/{req_id}/respond/', {'action': 'reject'})
        self.assertTrue(resp2.json()['ok'], resp2.json())

        from core.models import OwnerConsumptionTransferRequest
        req = OwnerConsumptionTransferRequest.objects.get(id=req_id)
        req.source_txn.refresh_from_db()
        self.assertEqual(req.source_txn.type, 'Issue')
        self.assertEqual(req.source_txn.payment_method, 'credit')

        from core.debt_views import _get_customer_debt_data
        customer = Customer.objects.get(business=self.biz, name='Mary')
        data = _get_customer_debt_data(customer, self.biz)
        self.assertEqual(data['outstanding'], 300.0)  # still owed by Mary, nothing moved

    def test_paid_amount_must_be_less_than_total(self):
        txn = self._make_debt_txn('Mary', '500')
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/partial/', {
            'txn_id': txn.id, 'paid_amount': '500', 'paid_method': 'cash',
        })
        self.assertFalse(resp.json()['ok'])
        resp2 = self.client.post('/stock/owner-consumption/transfer/to-owner/partial/', {
            'txn_id': txn.id, 'paid_amount': '0', 'paid_method': 'cash',
        })
        self.assertFalse(resp2.json()['ok'])

    def test_tab_linked_partial_transfer(self):
        """Same feature, but starting from a debt-converted tab item (an
        BarTabEntry) instead of a plain non-tab credit sale — splits via
        BarTabEntry.split_paid_unpaid_locked, remainder stays on the SAME
        tab (an ordinary unpaid entry) until the owner accepts."""
        customer = Customer.objects.create(business=self.biz, name='Roy', credit_approved=True)
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Roy', customer=customer,
            status='SETTLED', source='bar',
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('480'), payment_method='credit', recipient='Roy',
        )
        entry = BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Keg Gold', amount=Decimal('480'),
            is_paid=False,
        )
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/partial/', {
            'txn_id': txn.id, 'paid_amount': '180', 'paid_method': 'mpesa',
        })
        d = resp.json()
        self.assertTrue(d['ok'], d)

        entry.refresh_from_db()
        self.assertTrue(entry.is_paid)
        self.assertEqual(float(entry.amount), 180.0)
        entry.transaction.refresh_from_db()
        self.assertEqual(entry.transaction.payment_method, 'mpesa')

        from core.models import OwnerConsumptionTransferRequest
        req = OwnerConsumptionTransferRequest.objects.get(id=d['request_id'])
        remainder_entry = req.source_txn.tab_entry
        self.assertEqual(remainder_entry.tab_id, tab.id)  # stays on the SAME tab
        self.assertFalse(remainder_entry.is_paid)
        self.assertEqual(float(req.source_txn.sale_amount), 300.0)

        self.client.force_login(self.owner)
        self.client.post(f'/stock/owner-consumption/transfer/{req.id}/respond/', {'action': 'accept'})
        remainder_entry.refresh_from_db()
        self.assertTrue(remainder_entry.is_paid)  # closed out — moved to the owner
        remainder_entry.transaction.refresh_from_db()
        self.assertEqual(remainder_entry.transaction.type, 'OwnerConsumption')

    def test_staff_needs_open_shift(self):
        txn = self._make_debt_txn('Mary', '500')
        no_shift_staff = User.objects.create_user(username='ocpt_noshift', password='x')
        UserProfile.objects.create(user=no_shift_staff, business=self.biz, role='staff')
        self.client.force_login(no_shift_staff)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/partial/', {
            'txn_id': txn.id, 'paid_amount': '200', 'paid_method': 'cash',
        })
        self.assertEqual(resp.status_code, 403)


class OwnerConsumptionBackdateTest(TestCase):
    """2026-08-16 live request (Roy): "bar board has no back dating, same
    as mmiliki alichukua modal" — a catch-up entry for something the owner
    took on an earlier day had no way to land on that day, on either
    surface. Covers both record_owner_consumption's new backdated_at param
    (Quick Sell's non-keg modal) and the new keg-specific draw endpoint
    (Bar Board, previously had NO way to record a keg draw at all)."""

    def setUp(self):
        self.biz, self.store, self.staff, self.item, self.barrel, self.preset = _make_keg_fixtures(
            'OC Backdate Biz'
        )
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.owner = User.objects.create_user(username='ocbd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff,
            status='OPEN', opening_float=Decimal('0'), station='bar',
        )
        self.plain_item = Item.objects.create(
            business=self.biz, store=self.store, description='Sprite 500ml',
            material_no='OCBD-01', unit='Bottle', selling_price=Decimal('100'),
            cost_price=Decimal('60'),
        )

    def test_record_owner_consumption_honors_backdated_at(self):
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/owner-consumption/', {
            'item_id': self.plain_item.id, 'qty': '1', 'price': '100',
            'backdated_at': '2026-08-01T14:30',
            'idempotency_token': 'ocbd-1',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        txn = Transaction.objects.get(business=self.biz, item=self.plain_item, type='OwnerConsumption')
        self.assertEqual(txn.date, date(2026, 8, 1))
        self.assertEqual(timezone.localtime(txn.created_at).hour, 14)

    def test_record_owner_consumption_no_backdate_uses_today(self):
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/owner-consumption/', {
            'item_id': self.plain_item.id, 'qty': '1', 'price': '100',
            'idempotency_token': 'ocbd-2',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        txn = Transaction.objects.get(business=self.biz, item=self.plain_item, type='OwnerConsumption')
        self.assertEqual(txn.date, timezone.localdate())

    def test_keg_owner_draw_creates_owner_consumption_transaction(self):
        self.client.force_login(self.staff)
        before_balance = self.item.current_balance()
        before_revenue = self.barrel.revenue_collected
        resp = self.client.post('/stock/bar/owner-draw/', {
            'barrel_id': self.barrel.id, 'preset_id': self.preset.id, 'qty': '2',
            'idempotency_token': 'kegdraw-1',
        })
        d = resp.json()
        self.assertTrue(d['ok'], d)

        txn = Transaction.objects.get(business=self.biz, item=self.item, type='OwnerConsumption')
        self.assertEqual(txn.qty, Decimal('-1000'))  # 500ml Pint × 2
        self.assertEqual(txn.payment_method, '')
        self.assertEqual(txn.recipient, 'Mmiliki')
        self.assertEqual(txn.keg_barrel_id, self.barrel.id)

        # Item balance deducted exactly like a real pour.
        self.assertEqual(self.item.current_balance(), before_balance - Decimal('1000'))
        # Barrel's own envelope tracks it exactly like a real pour would —
        # so "how much is physically left" stays accurate.
        self.barrel.refresh_from_db()
        self.assertEqual(self.barrel.revenue_collected, before_revenue + Decimal('400'))
        # But it's invisible to real revenue (type != 'Issue').
        self.assertEqual(txn.revenue(), 0)

    def test_keg_owner_draw_honors_backdated_at(self):
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/bar/owner-draw/', {
            'barrel_id': self.barrel.id, 'preset_id': self.preset.id, 'qty': '1',
            'backdated_at': '2026-08-05T09:00',
            'idempotency_token': 'kegdraw-2',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        txn = Transaction.objects.get(business=self.biz, item=self.item, type='OwnerConsumption')
        self.assertEqual(txn.date, date(2026, 8, 5))
        self.assertEqual(timezone.localtime(txn.created_at).hour, 9)

    def test_keg_owner_draw_rejects_untapped_barrel(self):
        self.barrel.status = 'SEALED'
        self.barrel.save(update_fields=['status'])
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/bar/owner-draw/', {
            'barrel_id': self.barrel.id, 'preset_id': self.preset.id, 'qty': '1',
            'idempotency_token': 'kegdraw-3',
        })
        self.assertFalse(resp.json()['ok'])

    def test_keg_owner_draw_rejects_preset_from_another_item(self):
        other_item = Item.objects.create(
            business=self.biz, store=self.store, description='Other Keg',
            material_no='OCBD-02', unit='ml', is_keg=True,
            selling_price=Decimal('50'), cost_price=Decimal('9000'),
        )
        other_preset = ItemPortionPreset.objects.create(
            item=other_item, label='Cup', price=Decimal('50'), quantity_consumed=Decimal('300'),
        )
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/bar/owner-draw/', {
            'barrel_id': self.barrel.id, 'preset_id': other_preset.id, 'qty': '1',
            'idempotency_token': 'kegdraw-4',
        })
        self.assertFalse(resp.json()['ok'])

    def test_keg_owner_draw_requires_open_shift_for_staff(self):
        no_shift_staff = User.objects.create_user(username='ocbd_noshift', password='x')
        UserProfile.objects.create(user=no_shift_staff, business=self.biz, role='staff')
        self.client.force_login(no_shift_staff)
        resp = self.client.post('/stock/bar/owner-draw/', {
            'barrel_id': self.barrel.id, 'preset_id': self.preset.id, 'qty': '1',
            'idempotency_token': 'kegdraw-5',
        })
        self.assertEqual(resp.status_code, 403)

    def test_keg_owner_draw_cross_business_barrel_rejected(self):
        other_biz, other_store, other_staff, other_item, other_barrel, other_preset = _make_keg_fixtures(
            'OC Backdate Other Biz'
        )
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/bar/owner-draw/', {
            'barrel_id': other_barrel.id, 'preset_id': other_preset.id, 'qty': '1',
            'idempotency_token': 'kegdraw-6',
        })
        self.assertFalse(resp.json()['ok'])


class CustomerLinkAsOwnerTest(TestCase):
    """2026-08-13 live request (Roy) — "the system can be able to know that
    a certain name in either orders/tabs/debt tracker is the owner" (e.g.
    a debt customer named "Bosco" IS the owner Bosco). Explicit, owner/
    manager-confirmed link (never automatic name-matching); doubles as a
    "resync" action once linked — bulk-proposes whatever's currently
    unpaid under that Customer to Mmiliki Alichukua, always via the
    normal pending/accept step (per Roy's explicit confirmation this must
    never auto-post)."""

    def setUp(self):
        self.biz, self.store, self.staff, self.item, self.barrel, self.preset = _make_keg_fixtures(
            'CLAO Biz'
        )
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.owner = User.objects.create_user(username='clao_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='clao_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.customer = Customer.objects.create(business=self.biz, name='Bosco')

    def _make_debt_txn(self, amount='500', customer_name='Bosco'):
        return Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal(amount), payment_method='credit', recipient=customer_name,
            date=timezone.localdate(),
        )

    def test_link_sets_flag_and_bulk_proposes_unpaid_debt(self):
        txn1 = self._make_debt_txn('500')
        txn2 = self._make_debt_txn('300')
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/{self.customer.id}/link-owner/')
        d = resp.json()
        self.assertTrue(d['ok'], d)
        self.assertEqual(d['proposed_count'], 2)
        self.assertEqual(d['proposed_total'], 800.0)

        self.customer.refresh_from_db()
        self.assertTrue(self.customer.is_owner_alias)

        from core.models import OwnerConsumptionTransferRequest as OCTR
        pending = OCTR.objects.filter(
            business=self.biz, direction=OCTR.DIRECTION_TO_OWNER, status='PENDING',
        )
        self.assertEqual(pending.count(), 2)
        self.assertEqual({p.source_txn_id for p in pending}, {txn1.id, txn2.id})

    def test_resync_only_picks_up_newly_unpaid_debt(self):
        txn1 = self._make_debt_txn('500')
        self.client.force_login(self.owner)
        resp1 = self.client.post(f'/debt/{self.customer.id}/link-owner/')
        self.assertEqual(resp1.json()['proposed_count'], 1)

        # New debt accumulates under the same linked customer afterward.
        txn2 = self._make_debt_txn('200')
        resp2 = self.client.post(f'/debt/{self.customer.id}/link-owner/')
        d2 = resp2.json()
        self.assertTrue(d2['ok'], d2)
        self.assertEqual(d2['proposed_count'], 1)  # only the new one
        self.assertEqual(d2['proposed_total'], 200.0)

    def test_resync_after_accept_never_reproposes_already_moved_debt(self):
        """Once a proposal is ACCEPTED, the transaction's type flips to
        OwnerConsumption and it drops out of _get_customer_debt_data
        entirely — a resync must never try to re-propose it."""
        txn = self._make_debt_txn('500')
        self.client.force_login(self.owner)
        resp1 = self.client.post(f'/debt/{self.customer.id}/link-owner/')
        from core.models import OwnerConsumptionTransferRequest as OCTR
        req = OCTR.objects.get(source_txn=txn)
        req.accept()

        resp2 = self.client.post(f'/debt/{self.customer.id}/link-owner/')
        d2 = resp2.json()
        self.assertTrue(d2['ok'], d2)
        self.assertEqual(d2['proposed_count'], 0)

    def test_link_still_requires_owner_accept_never_auto_posts(self):
        """Explicit confirmation from Roy: linking must NOT skip the
        pending/accept step even though the owner himself initiated it."""
        txn = self._make_debt_txn('500')
        self.client.force_login(self.owner)
        self.client.post(f'/debt/{self.customer.id}/link-owner/')
        txn.refresh_from_db()
        self.assertEqual(txn.type, 'Issue')  # not yet reclassified
        from core.models import OwnerConsumptionTransferRequest as OCTR
        self.assertEqual(
            OCTR.objects.filter(source_txn=txn, status='PENDING').count(), 1,
        )

    def test_link_with_no_unpaid_debt_still_sets_flag(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/{self.customer.id}/link-owner/')
        d = resp.json()
        self.assertTrue(d['ok'], d)
        self.assertEqual(d['proposed_count'], 0)
        self.customer.refresh_from_db()
        self.assertTrue(self.customer.is_owner_alias)

    def test_manager_can_link(self):
        self.client.force_login(self.manager)
        resp = self.client.post(f'/debt/{self.customer.id}/link-owner/')
        self.assertTrue(resp.json()['ok'])

    def test_staff_cannot_link(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/debt/{self.customer.id}/link-owner/')
        self.assertEqual(resp.status_code, 403)
        self.customer.refresh_from_db()
        self.assertFalse(self.customer.is_owner_alias)

    def test_unlink_clears_flag_but_leaves_past_transfers_untouched(self):
        txn = self._make_debt_txn('500')
        self.client.force_login(self.owner)
        self.client.post(f'/debt/{self.customer.id}/link-owner/')
        from core.models import OwnerConsumptionTransferRequest as OCTR
        req = OCTR.objects.get(source_txn=txn)
        req.accept()

        resp = self.client.post(f'/debt/{self.customer.id}/unlink-owner/')
        self.assertTrue(resp.json()['ok'])
        self.customer.refresh_from_db()
        self.assertFalse(self.customer.is_owner_alias)

        txn.refresh_from_db()
        self.assertEqual(txn.type, 'OwnerConsumption')  # untouched by unlink

    def test_staff_cannot_unlink(self):
        self.customer.is_owner_alias = True
        self.customer.save()
        self.client.force_login(self.staff)
        resp = self.client.post(f'/debt/{self.customer.id}/unlink-owner/')
        self.assertEqual(resp.status_code, 403)

    def test_cross_business_customer_404s(self):
        other_biz = Business.objects.create(name='Other Biz CLAO')
        other_owner = User.objects.create_user(username='clao_other_owner', password='x')
        UserProfile.objects.create(user=other_owner, business=other_biz, role='owner')
        self.client.force_login(other_owner)
        resp = self.client.post(f'/debt/{self.customer.id}/link-owner/')
        self.assertEqual(resp.status_code, 404)


class OwnerAliasDebtSearchTest(TestCase):
    """2026-08-13 live request (Roy) — dedicated cross-customer search/
    bulk-transfer page: "transfer some of the other customers tabs and
    debts that those customers claimed Bosco was to pay for them" without
    opening each customer's own debt profile one at a time."""

    def setUp(self):
        self.biz, self.store, self.staff, self.item, self.barrel, self.preset = _make_keg_fixtures(
            'OADS Biz'
        )
        self.owner = User.objects.create_user(username='oads_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.item2 = Item.objects.create(
            business=self.biz, store=self.store, material_no='OADS-2',
            description='Tusker Lager', unit='bottle', selling_price=Decimal('260'),
        )

    def _make_debt_txn(self, customer_name, amount, item=None):
        Customer.objects.get_or_create(business=self.biz, name=customer_name)
        return Transaction.objects.create(
            business=self.biz, item=item or self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal(amount), payment_method='credit', recipient=customer_name,
            date=timezone.localdate(),
        )

    def test_finds_unpaid_debt_across_multiple_customers(self):
        self._make_debt_txn('Alice', '100')
        self._make_debt_txn('Bosco', '260', item=self.item2)
        self.client.force_login(self.owner)
        resp = self.client.get('/debt/owner-alias/search/')
        self.assertContains(resp, 'Alice')
        self.assertContains(resp, 'Bosco')
        self.assertContains(resp, 'Tusker Lager')

    def test_search_by_item_name_finds_it_under_the_right_customer(self):
        """A search for an ITEM name must find it under whichever customer
        actually owes it, not just customers whose NAME matches — the
        whole reason this doesn't pre-filter the Customer queryset by q."""
        self._make_debt_txn('Alice', '100')
        self._make_debt_txn('Zawadi', '260', item=self.item2)
        self.client.force_login(self.owner)
        resp = self.client.get('/debt/owner-alias/search/?q=Tusker')
        self.assertContains(resp, 'Zawadi')
        self.assertNotContains(resp, 'Alice')

    def test_search_by_customer_name(self):
        self._make_debt_txn('Alice', '100')
        self._make_debt_txn('Zawadi', '200')
        self.client.force_login(self.owner)
        resp = self.client.get('/debt/owner-alias/search/?q=Alice')
        self.assertContains(resp, 'Alice')
        self.assertNotContains(resp, 'Zawadi')

    def test_fully_paid_customer_excluded(self):
        from core.models import CustomerDebtPayment
        customer = Customer.objects.create(business=self.biz, name='Alice')
        self._make_debt_txn('Alice', '100')
        CustomerDebtPayment.objects.create(
            customer=customer, business=self.biz, amount_paid=Decimal('100'),
            payment_method='cash', source='bar',
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/debt/owner-alias/search/')
        self.assertNotContains(resp, 'Alice')

    def test_bulk_select_and_transfer_from_search_page(self):
        txn1 = self._make_debt_txn('Alice', '100')
        txn2 = self._make_debt_txn('Zawadi', '200')
        self.client.force_login(self.owner)
        resp = self.client.post('/stock/owner-consumption/transfer/to-owner/', {
            'txn_ids': f'{txn1.id},{txn2.id}',
        })
        d = resp.json()
        self.assertTrue(d['ok'], d)
        self.assertEqual(len(d['request_ids']), 2)

    def test_staff_cannot_access_search_page(self):
        self.client.force_login(self.staff)
        resp = self.client.get('/debt/owner-alias/search/')
        self.assertNotEqual(resp.status_code, 200)

    def test_open_tab_items_excluded(self):
        """An item still on an OPEN tab is not yet real debt — must not
        appear (matches _get_customer_debt_data's own exclusion)."""
        tab = BarTab.create_with_credentials(business=self.biz, customer_name='Kioko', status='OPEN', source='bar')
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('150'), payment_method='credit', recipient='Kioko',
            date=timezone.localdate(),
        )
        BarTabEntry.objects.create(tab=tab, transaction=txn, description='x', amount=Decimal('150'))
        self.client.force_login(self.owner)
        resp = self.client.get('/debt/owner-alias/search/')
        self.assertNotContains(resp, 'Kioko')


class OwnerAliasSimilarNameHintTest(TestCase):
    """2026-08-13 live request (Roy) — tab_check_api warns staff when a
    typed customer name exactly matches, or is merely similar to, a
    Customer already linked as the owner. Purely informational — never
    auto-redirects the sale itself."""

    def setUp(self):
        self.biz, self.store, self.staff, self.item, self.barrel, self.preset = _make_keg_fixtures(
            'OASH Biz'
        )
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.alias = Customer.objects.create(business=self.biz, name='Bosco', is_owner_alias=True)

    def test_exact_match_flagged(self):
        self.client.force_login(self.staff)
        resp = self.client.get('/kitchen/tab/check/?customer=Bosco')
        d = resp.json()
        self.assertEqual(d['owner_alias_match'], {'exact': True, 'name': 'Bosco'})

    def test_exact_match_case_insensitive(self):
        self.client.force_login(self.staff)
        resp = self.client.get('/kitchen/tab/check/?customer=bosco')
        d = resp.json()
        self.assertTrue(d['owner_alias_match']['exact'])

    def test_similar_but_not_exact_flagged_as_non_exact(self):
        self.client.force_login(self.staff)
        resp = self.client.get('/kitchen/tab/check/?customer=Boscoh')
        d = resp.json()
        self.assertEqual(d['owner_alias_match'], {'exact': False, 'name': 'Bosco'})

    def test_unrelated_name_no_match(self):
        self.client.force_login(self.staff)
        resp = self.client.get('/kitchen/tab/check/?customer=Zawadi')
        d = resp.json()
        self.assertIsNone(d['owner_alias_match'])

    def test_no_linked_alias_no_match_key_still_present(self):
        self.alias.delete()
        self.client.force_login(self.staff)
        resp = self.client.get('/kitchen/tab/check/?customer=Bosco')
        d = resp.json()
        self.assertIsNone(d['owner_alias_match'])


class NegativeBalanceNeverAllowedTest(TestCase):
    """2026-08-07 live report (Roy: a bottled Soda showed "Out of Stock" in
    Quick Sell while physically present — balance had drifted to -99 even
    though Quick Sell's own live checkout already blocks overselling).
    Audit found several settlement/confirmation paths with NO balance
    check anywhere in their lifetime: M-Pesa STK settlement callbacks,
    staff reconciling a stray payment, Order fulfillment, and SERVED
    table-order conversion. Roy's directive: "negative balances should
    never be there, stock is either or is not." Two treatments: paths
    still interactive BEFORE money/goods move (Kitchen Board direct
    checkout, restricted-item approval) hard-block, matching Quick Sell's
    own proven pattern; paths where money already changed hands or the
    item was already physically served (every STK settlement callback,
    Order fulfillment, table-order SERVED) cap the deduction at zero and
    flag the shortfall via BusinessException instead of silently dropping
    a confirmed payment."""

    def setUp(self):
        self.biz = Business.objects.create(name='Neg Balance Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Liquor Store', is_kitchen=False)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='nb_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='nb_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff', can_access_kitchen=True)
        self.soda = Item.objects.create(
            business=self.biz, store=self.store, description='Soda 500ml',
            material_no='NB-SODA', unit='Pcs', selling_price=Decimal('100'),
        )
        # Only 2 in stock — every scenario below asks for more than that.
        Transaction.objects.create(business=self.biz, item=self.soda, type='Receipt', qty=Decimal('2'))
        self.kuku = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Kuku',
            material_no='NB-KUKU', unit='Pcs', selling_price=Decimal('100'),
        )
        Transaction.objects.create(business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('2'))
        Shift.objects.create(
            business=self.biz, store=self.kitchen_store, staff=self.staff,
            status='OPEN', opening_float=Decimal('0'), station='kitchen',
        )

    # ── Item.capped_deduction() — direct unit tests ──────────────────────
    def test_capped_deduction_sufficient_stock_no_shortfall(self):
        deductible, shortfall = self.soda.capped_deduction(Decimal('2'))
        self.assertEqual(deductible, Decimal('2'))
        self.assertEqual(shortfall, Decimal('0'))

    def test_capped_deduction_insufficient_stock_caps_and_flags(self):
        deductible, shortfall = self.soda.capped_deduction(Decimal('5'))
        self.assertEqual(deductible, Decimal('2'))
        self.assertEqual(shortfall, Decimal('3'))

    def test_capped_deduction_already_negative_balance_deducts_nothing(self):
        Transaction.objects.create(business=self.biz, item=self.soda, type='Issue', qty=Decimal('-10'))
        deductible, shortfall = self.soda.capped_deduction(Decimal('3'))
        self.assertEqual(deductible, Decimal('0'))
        self.assertEqual(shortfall, Decimal('3'))

    # ── STK settlement callbacks — cap, never negative, flag raised ──────
    def test_settle_qs_from_payment_never_goes_negative(self):
        from core.mpesa_views import _settle_qs_from_payment
        from core.models import Payment, BusinessException
        payment = Payment.objects.create(
            business=self.biz, amount=Decimal('500'), phone='0700000000',
            status='completed',
            qs_cart=[{'item_id': self.soda.id, 'qty': 5, 'amount': 500, 'description': 'Soda'}],
        )
        _settle_qs_from_payment(payment)
        self.assertGreaterEqual(self.soda.current_balance(), 0)
        self.assertEqual(self.soda.current_balance(), 0)
        self.assertTrue(BusinessException.objects.filter(business=self.biz, kind='shrinkage').exists())

    def test_settle_kitchen_order_from_payment_never_goes_negative(self):
        from core.mpesa_views import _settle_kitchen_order_from_payment
        from core.models import Payment, BusinessException
        payment = Payment.objects.create(
            business=self.biz, amount=Decimal('500'), phone='0700000000',
            status='completed',
            kitchen_cart=[{'item_id': self.kuku.id, 'qty': 5, 'amount': 500, 'description': 'Kuku'}],
        )
        _settle_kitchen_order_from_payment(payment)
        self.assertGreaterEqual(self.kuku.current_balance(), 0)
        self.assertTrue(BusinessException.objects.filter(business=self.biz, kind='shrinkage').exists())

    def test_fulfill_order_never_goes_negative(self):
        from core.mpesa_views import _fulfill_order
        from core.models import Order, OrderLine, BusinessException
        order = Order.objects.create(
            business=self.biz, customer_name='Mteja', customer_phone='0700000000',
            status='paid',
        )
        OrderLine.objects.create(order=order, item=self.soda, quantity=5, unit_price=Decimal('100'))
        _fulfill_order(order)
        self.assertGreaterEqual(self.soda.current_balance(), 0)
        self.assertTrue(BusinessException.objects.filter(business=self.biz, kind='shrinkage').exists())

    def test_confirm_prompt_never_goes_negative_and_reports_shortfall(self):
        from core.models import PendingTransactionPrompt, BusinessException
        prompt = PendingTransactionPrompt.objects.create(
            business=self.biz, phone='0700000000', amount=Decimal('500'), status='pending',
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/mpesa/prompt/{prompt.id}/confirm/', {
            'item_id': self.soda.id, 'qty': '5',
        })
        self.assertEqual(resp.status_code, 200)
        self.soda.refresh_from_db()
        self.assertGreaterEqual(self.soda.current_balance(), 0)
        self.assertIn('pungufu', resp.json()['message'])
        self.assertTrue(BusinessException.objects.filter(business=self.biz, kind='shrinkage').exists())

    def test_served_table_order_never_goes_negative(self):
        from core.models import TableOrder, TableOrderItem, BusinessException
        from accounts.models import UserProfile as _UP
        waitress = User.objects.create_user(username='nb_waitress', password='x')
        _UP.objects.create(user=waitress, business=self.biz, role='waitress')
        order = TableOrder.objects.create(
            business=self.biz, table_label='Table 9', waitress=waitress,
            status='ACCEPTED', payment_method='cash',
        )
        TableOrderItem.objects.create(
            order=order, item=self.soda, quantity=Decimal('5'),
            unit_price=Decimal('100'), item_name='Soda',
        )
        from core.order_views import _create_transactions_for_order
        up = _UP.objects.get(user=waitress)
        _create_transactions_for_order(order, up)
        self.assertGreaterEqual(self.soda.current_balance(), 0)
        self.assertTrue(BusinessException.objects.filter(business=self.biz, kind='shrinkage').exists())

    # ── Live, interactive checkouts — hard block instead ─────────────────
    def test_kitchen_checkout_refuses_oversell(self):
        import uuid
        self.client.force_login(self.staff)
        resp = self.client.post('/kitchen/', {
            'cart': json.dumps([{'item_id': self.kuku.id, 'qty': 5, 'amount': 500, 'description': 'Kuku'}]),
            'payment_method': 'cash',
            'idempotency_token': f'nb-kb-{uuid.uuid4()}',
        })
        data = resp.json()
        self.assertFalse(data.get('ok'), data)
        self.assertEqual(self.kuku.current_balance(), 2)

    def test_decide_approval_refuses_when_stock_ran_out_since_request(self):
        from core.models import ItemSaleApproval
        approval = ItemSaleApproval.objects.create(
            business=self.biz, item=self.soda, requested_by=self.staff,
            quantity=2, payment_method='cash', status='pending',
        )
        # Stock drains to 0 between the request and the owner's decision.
        Transaction.objects.create(business=self.biz, item=self.soda, type='Issue', qty=Decimal('-2'))
        self.client.force_login(self.owner)
        resp = self.client.post(f'/approvals/{approval.id}/decide/', {'decision': 'approve'})
        approval.refresh_from_db()
        self.assertEqual(approval.status, 'pending')
        self.assertGreaterEqual(self.soda.current_balance(), 0)


class DepleteKitchenPortionItemTest(TestCase):
    """2026-08-08 live request (Roy): kitchen chicken tiles (portion-mode,
    e.g. Kuku sold via presets) had no "Imekwisha" (sold out) function —
    only KitchenBatch/ProduceBunch envelope items had one. Zeroes the
    balance via a NO-LOSS adjustment ([ADJ-NOLOSS]) since nothing was
    actually lost — the tile is simply being marked sold out for the day.
    Same shift-gated tier as kbDepleteBatch/kbDiscardBatch (any staff with
    an open shift, not owner-only)."""

    def setUp(self):
        self.biz = Business.objects.create(name='KB Portion Deplete Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='kpd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kitchen_staff = User.objects.create_user(username='kpd_kstaff', password='x')
        UserProfile.objects.create(user=self.kitchen_staff, business=self.biz, role='kitchen')
        Shift.objects.create(business=self.biz, staff=self.kitchen_staff, station='kitchen', status='OPEN')

        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='KPD-KUKU', unit='Pcs', selling_price=Decimal('150'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('7'),
        )

    def test_owner_can_deplete_portion_item(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/kitchen/item/{self.kuku.id}/deplete/')
        self.assertEqual(resp.status_code, 200)
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertEqual(data['new_balance'], '0')
        self.assertEqual(self.kuku.current_balance(), 0)

    def test_shift_staff_can_deplete_portion_item(self):
        self.client.force_login(self.kitchen_staff)
        resp = self.client.post(f'/kitchen/item/{self.kuku.id}/deplete/')
        self.assertTrue(resp.json()['ok'])
        self.assertEqual(self.kuku.current_balance(), 0)

    def test_deplete_creates_no_loss_adjustment_not_real_wastage(self):
        self.client.force_login(self.owner)
        self.client.post(f'/kitchen/item/{self.kuku.id}/deplete/')
        txn = Transaction.objects.filter(
            business=self.biz, item=self.kuku, type='Wastage',
        ).order_by('-id').first()
        self.assertIsNotNone(txn)
        self.assertEqual(txn.invoice_no, '[ADJ-NOLOSS]')
        self.assertEqual(txn.qty, Decimal('-7'))

    def test_already_zero_is_a_no_op(self):
        Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Issue', qty=Decimal('-7'),
        )
        self.assertEqual(self.kuku.current_balance(), 0)
        self.client.force_login(self.owner)
        resp = self.client.post(f'/kitchen/item/{self.kuku.id}/deplete/')
        data = resp.json()
        self.assertTrue(data['ok'])
        self.assertTrue(data.get('already_zero'))
        self.assertEqual(
            Transaction.objects.filter(business=self.biz, item=self.kuku, type='Wastage').count(), 0,
        )

    def test_cross_business_item_rejected(self):
        other_biz = Business.objects.create(name='Other Biz KPD')
        other_store = Store.objects.create(business=other_biz, name='Kitchen', is_kitchen=True)
        other_item = Item.objects.create(
            business=other_biz, store=other_store, description='Other Kuku',
            material_no='OTHER-KUKU', unit='Pcs', selling_price=Decimal('150'),
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/kitchen/item/{other_item.id}/deplete/')
        self.assertEqual(resp.status_code, 404)


class KitchenCheckoutSkippedItemFeedbackTest(TestCase):
    """2026-08-08 live report (Roy): "balances are funny... when staff is
    selling." Investigated the full chicken-preset selling pipeline
    (frontend tap handlers, cart serialization, server-side balance
    computation, authoritative preset-based deduction) end to end and
    found no role-specific divergence — the deduction math is uniform and
    server-authoritative for both staff and owner. The one concrete,
    addressable gap found: an insufficient-stock cart line was silently
    `continue`d with zero feedback to staff, easily read as "the system is
    confused." Every skip now returns a plain, visible reason."""

    def setUp(self):
        self.biz = Business.objects.create(name='KB Skip Feedback Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='ksf_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='KSF-KUKU', unit='Pcs', selling_price=Decimal('150'),
        )
        self.soda = Item.objects.create(
            business=self.biz, store=self.store, description='Soda',
            material_no='KSF-SODA', unit='Pcs', selling_price=Decimal('50'),
        )
        Transaction.objects.create(business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('2'))
        Transaction.objects.create(business=self.biz, item=self.soda, type='Receipt', qty=Decimal('10'))
        self.client.force_login(self.owner)

    def test_oversell_reports_reason_in_error_and_skipped_list(self):
        import json
        cart = json.dumps([{'item_id': self.kuku.id, 'qty': 5, 'amount': 750, 'description': 'Kuku'}])
        resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        data = resp.json()
        self.assertFalse(data.get('ok'))
        self.assertIn('Stock haitoshi', data.get('error', ''))
        self.assertEqual(len(data.get('skipped', [])), 1)
        self.assertIn('Kuku', data['skipped'][0]['description'])

    def test_partial_cart_sells_available_items_and_reports_skipped_one(self):
        import json
        cart = json.dumps([
            {'item_id': self.soda.id, 'qty': 2, 'amount': 100, 'description': 'Soda'},
            {'item_id': self.kuku.id, 'qty': 5, 'amount': 750, 'description': 'Kuku'},
        ])
        resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        data = resp.json()
        self.assertTrue(data.get('ok'), data)
        self.assertEqual(len(data.get('skipped', [])), 1)
        self.assertIn('Kuku', data['skipped'][0]['description'])
        self.assertEqual(self.soda.current_balance(), 8)
        self.assertEqual(self.kuku.current_balance(), 2)

    def test_fully_sellable_cart_has_empty_skipped_list(self):
        import json
        cart = json.dumps([{'item_id': self.soda.id, 'qty': 2, 'amount': 100, 'description': 'Soda'}])
        resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        data = resp.json()
        self.assertTrue(data.get('ok'), data)
        self.assertEqual(data.get('skipped', []), [])


class EditProduceBunchCostTest(TestCase):
    """2026-08-08 live request (Roy): no way existed to correct a
    ProduceBunch's cost (e.g. a gunia ya viazi whose cost wasn't entered
    correctly at receiving time). Mirrors edit_kitchen_batch_target's
    exact pattern — owner/manager only, since cost_price/target_revenue
    drive realized_markup()/remaining()/discard()'s wastage math. Unlike
    KitchenBatch, ProduceBunch's cost is never mirrored into
    item.cost_price (that mirror is a KitchenBatch-specific exception)."""

    def setUp(self):
        self.biz = Business.objects.create(name='PB Edit Cost Biz')
        self.store = Store.objects.create(business=self.biz, name='Main')
        self.owner = User.objects.create_user(username='pbec_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='pbec_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.staff = User.objects.create_user(username='pbec_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')

        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Viazi (Gunia)',
            material_no='PBEC-VIAZI', unit='Gorogoro', selling_price=Decimal('80'),
            is_produce=True, produce_mode='BUNCH', cost_price=Decimal('0'),
        )
        self.bunch = ProduceBunch.objects.create(
            item=self.item, business=self.biz, size='LARGE', kind='sack',
            cost_price=Decimal('1200'), target_revenue=Decimal('2000'),
        )

    def test_owner_can_correct_bunch_cost(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/produce/bunch/{self.bunch.id}/edit-cost/', {'cost_price': '1500'})
        self.assertEqual(resp.status_code, 200)
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.bunch.refresh_from_db()
        self.assertEqual(self.bunch.cost_price, Decimal('1500'))
        self.assertIn('1,200', self.bunch.note)
        self.assertIn('1,500', self.bunch.note)
        self.assertIn('pbec_owner', self.bunch.note)

    def test_does_not_mirror_into_item_cost_price(self):
        self.client.force_login(self.owner)
        self.client.post(f'/stock/produce/bunch/{self.bunch.id}/edit-cost/', {'cost_price': '1500'})
        self.item.refresh_from_db()
        self.assertEqual(self.item.cost_price, Decimal('0'))

    def test_can_also_correct_target_revenue(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/produce/bunch/{self.bunch.id}/edit-cost/', {
            'cost_price': '1500', 'target_revenue': '2600',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.bunch.refresh_from_db()
        self.assertEqual(self.bunch.target_revenue, Decimal('2600'))

    def test_manager_can_correct_bunch_cost(self):
        self.client.force_login(self.manager)
        resp = self.client.post(f'/stock/produce/bunch/{self.bunch.id}/edit-cost/', {'cost_price': '1300'})
        self.assertTrue(resp.json()['ok'])

    def test_staff_cannot_correct_bunch_cost(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/stock/produce/bunch/{self.bunch.id}/edit-cost/', {'cost_price': '1300'})
        self.assertEqual(resp.status_code, 403)
        self.bunch.refresh_from_db()
        self.assertEqual(self.bunch.cost_price, Decimal('1200'))

    def test_cannot_edit_a_depleted_bunch(self):
        self.bunch.status = 'DEPLETED'
        self.bunch.save(update_fields=['status'])
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/produce/bunch/{self.bunch.id}/edit-cost/', {'cost_price': '1300'})
        self.assertEqual(resp.status_code, 404)

    def test_rejects_non_positive_cost(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/produce/bunch/{self.bunch.id}/edit-cost/', {'cost_price': '0'})
        self.assertEqual(resp.status_code, 400)
        resp2 = self.client.post(f'/stock/produce/bunch/{self.bunch.id}/edit-cost/', {'cost_price': '-5'})
        self.assertEqual(resp2.status_code, 400)

    def test_rejects_non_numeric_cost(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/produce/bunch/{self.bunch.id}/edit-cost/', {'cost_price': 'abc'})
        self.assertEqual(resp.status_code, 400)

    def test_cross_business_bunch_rejected(self):
        other_biz = Business.objects.create(name='Other PB Biz')
        other_store = Store.objects.create(business=other_biz, name='Main')
        other_item = Item.objects.create(
            business=other_biz, store=other_store, description='Other Viazi',
            material_no='OTHER-VIAZI', unit='Gorogoro', selling_price=Decimal('80'),
            is_produce=True, produce_mode='BUNCH',
        )
        other_bunch = ProduceBunch.objects.create(
            item=other_item, business=other_biz, size='LARGE',
            cost_price=Decimal('1000'), target_revenue=Decimal('1800'),
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/produce/bunch/{other_bunch.id}/edit-cost/', {'cost_price': '1300'})
        self.assertEqual(resp.status_code, 404)


class WaitressJoinContinuousBarRevenueTest(TestCase):
    """2026-08-08 live follow-up (Roy): "the waitress just joined service,
    she is not starting one so things should go smoothly" — explicit
    confirmation that revenue must stay ONE continuous stream for the
    bartender's own shift both BEFORE and AFTER a waitress joins mid-shift,
    not two separate pieces that need reassembling. Locks in the full
    session shape end to end (sale before she joins + sale after, in one
    _reconcile() call)."""

    def test_sales_before_and_after_waitress_joins_both_count_toward_bartender(self):
        from core.shift_views import _reconcile

        business = Business.objects.create(name='Continuous Revenue Biz')
        store = Store.objects.create(business=business, name='Bar')
        item = Item.objects.create(
            business=business, store=store, material_no='CONT-1',
            description='Continuous Beer', unit='bottle',
            selling_price=Decimal('100'), cost_price=Decimal('40'),
        )
        bartender = User.objects.create_user(username='cont_bartender', password='x')
        UserProfile.objects.create(user=bartender, business=business, role='staff')
        waitress = User.objects.create_user(username='cont_waitress', password='x')
        UserProfile.objects.create(user=waitress, business=business, role='waitress')

        base = timezone.now() - timedelta(hours=5)
        bartender_shift = Shift.objects.create(
            business=business, store=store, staff=bartender, station='bar',
            opening_float=Decimal('0'), started_at=base, status='OPEN',
        )
        waitress_join = base + timedelta(hours=2)
        Shift.objects.create(
            business=business, store=store, staff=waitress, station='bar',
            opening_float=Decimal('0'), started_at=waitress_join, status='OPEN',
        )

        # Sale BEFORE the waitress joined.
        Transaction.objects.create(
            business=business, item=item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('400'), payment_method='cash',
            created_at=base + timedelta(minutes=30),
        )
        # Sale AFTER the waitress joined — must count just the same, no reset.
        Transaction.objects.create(
            business=business, item=item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('600'), payment_method='mpesa',
            created_at=waitress_join + timedelta(hours=1),
        )

        rec = _reconcile(bartender_shift)
        self.assertAlmostEqual(rec['cash_sales'], 400.0, places=1)
        self.assertAlmostEqual(rec['mpesa_sales'], 600.0, places=1)
        self.assertAlmostEqual(rec['confirmed_sales'], 1000.0, places=1,
            msg="Revenue before AND after a waitress joins must be one continuous total for the bartender's shift")
        # Elapsed time must span the whole 5h uninterrupted — no segment gap.
        self.assertGreater(rec['elapsed_mins'], 4 * 60)


class PresetStockTrackingTetherTest(TestCase):
    """2026-08-09 live correction (Roy): the 2026-08-05 "cut visibility"
    mechanism (only show a preset as sellable when what it represents was
    actually received) broke for a preset that's never itself received
    under its own name — e.g. "Half Chicken Leg" is always cut from a
    "Full Chicken Leg" that WAS received. ItemPortionPreset.tracks_stock_of
    links the two so both received and sold totals are grouped by one
    shared anchor."""

    def setUp(self):
        self.biz = Business.objects.create(name='Tether Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='tether_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='TETHER-KUKU', unit='Pcs', selling_price=Decimal('0'),
        )
        self.full_leg = ItemPortionPreset.objects.create(
            item=self.kuku, label='Full Chicken Leg', price=Decimal('250'),
            quantity_consumed=Decimal('1'),
        )
        self.half_leg = ItemPortionPreset.objects.create(
            item=self.kuku, label='Half Chicken Leg', price=Decimal('150'),
            quantity_consumed=Decimal('0.5'), tracks_stock_of=self.full_leg,
        )
        self.wing = ItemPortionPreset.objects.create(
            item=self.kuku, label='Wing', price=Decimal('70'),
            quantity_consumed=Decimal('0.125'),
        )
        self.client.force_login(self.owner)

    def test_stock_tracking_anchor_id(self):
        self.assertEqual(self.full_leg.stock_tracking_anchor_id(), self.full_leg.id)
        self.assertEqual(self.half_leg.stock_tracking_anchor_id(), self.full_leg.id)
        self.assertEqual(self.wing.stock_tracking_anchor_id(), self.wing.id)

    def _receive_full_legs(self, qty=12, cost=200):
        import uuid
        return self.client.post('/kitchen/receive/', {
            'item_id': self.kuku.id, 'mode': 'portion',
            'qty': str(qty), 'cost_price': str(cost * qty),
            'preset_id': str(self.full_leg.id),
            'idempotency_token': f'rcv-{uuid.uuid4()}',
        })

    def _portion_items_blob(self, body):
        import json as _json
        start = body.index('var _portionItems')
        eq = body.index('=', start)
        end = body.index(';\n', eq)
        return _json.loads(body[eq + 1:end].strip())

    def test_receiving_full_leg_creates_stock_receipt_line_and_sets_preset_cost(self):
        resp = self._receive_full_legs(qty=12, cost=200)
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.full_leg.refresh_from_db()
        self.assertEqual(self.full_leg.cost_price, Decimal('200.00'))
        self.assertEqual(
            KitchenStockReceiptLine.objects.filter(item=self.kuku, preset=self.full_leg).count(), 1,
        )
        self.assertEqual(self.kuku.current_balance(), 12)

    def test_wing_hidden_when_only_legs_received(self):
        self._receive_full_legs(qty=12, cost=200)
        resp = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        labels = [p['label'] for p in kuku['presets']]
        self.assertIn('Full Chicken Leg', labels)
        self.assertIn('Half Chicken Leg', labels)
        self.assertNotIn('Wing', labels)

    def test_half_leg_sale_decrements_full_legs_own_tally(self):
        self._receive_full_legs(qty=12, cost=200)
        # Sell one half-leg at a custom price — must decrement the FULL LEG
        # anchor's own received-vs-sold tally by 0.5, not leave it untouched.
        import json as _json
        cart = _json.dumps([{
            'item_id': self.kuku.id, 'preset_id': self.half_leg.id,
            'qty': 0.5, 'amount': 150, 'description': 'Kuku — Half Chicken Leg',
        }])
        resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        self.assertTrue(resp.json().get('ok'), resp.json())
        resp2 = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp2.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        labels = [p['label'] for p in kuku['presets']]
        # Full Chicken Leg must still show (11.5 of 12 remaining under the
        # anchor), and stock balance overall must reflect the 0.5 sold.
        self.assertIn('Full Chicken Leg', labels)
        self.kuku.refresh_from_db()
        self.assertEqual(self.kuku.current_balance(), Decimal('11.5'))

    def test_selling_enough_half_legs_hides_both_presets(self):
        self._receive_full_legs(qty=1, cost=200)
        import json as _json
        # Sell the equivalent of the whole received leg via two halves.
        for _i in range(2):
            cart = _json.dumps([{
                'item_id': self.kuku.id, 'preset_id': self.half_leg.id,
                'qty': 0.5, 'amount': 150, 'description': 'Kuku — Half Chicken Leg',
            }])
            resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
            self.assertTrue(resp.json().get('ok'), resp.json())
        resp2 = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp2.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        labels = [p['label'] for p in kuku['presets']]
        self.assertNotIn('Full Chicken Leg', labels)
        self.assertNotIn('Half Chicken Leg', labels)

    def test_all_presets_always_offered_for_receiving_regardless_of_current_stock(self):
        # Wing has never been received — but it must still be offered as a
        # RECEIVE option (that's exactly how it would ever get stock).
        resp = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        all_labels = [p['label'] for p in kuku['all_presets']]
        self.assertIn('Wing', all_labels)
        self.assertIn('Full Chicken Leg', all_labels)

    def test_tethered_preset_never_offered_in_receive_picker(self):
        """2026-08-09, same-day correction (Roy): "Half Chicken Leg" tracks_
        stock_of "Full Chicken Leg" — it has no independent physical
        existence to receive, so it must never appear in the RECEIVE
        modal's picker, only the anchor it's tethered to. It should still
        appear in the ordinary sell-tile presets list."""
        resp = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        all_labels = [p['label'] for p in kuku['all_presets']]
        self.assertNotIn('Half Chicken Leg', all_labels)
        self.assertIn('Full Chicken Leg', all_labels)
        # Sell-tile presets are unaffected — Half Chicken Leg still sells.
        sell_labels = [p['label'] for p in kuku['presets']]
        self.assertIn('Half Chicken Leg', sell_labels)

    def test_stock_receipt_create_resolves_tethered_preset_to_anchor(self):
        """2026-08-09 defense-in-depth: the Stock Receipt modal's own
        "Chagua Bidhaa" picker (a second, separate receive-cost entry point
        from the +Pata Stok modal covered above) is likewise fixed to never
        offer a tethered preset — but if a stale client still submits one
        (e.g. Half Chicken Leg's id), the server must resolve it to its
        anchor preset (Full Chicken Leg) rather than writing cost_price
        onto the tethered preset itself."""
        import json as _json
        import uuid
        resp = self.client.post('/kitchen/stock-receipt/create/', {
            'supplier': 'Meatco', 'invoice_no': 'A999',
            'lines': _json.dumps([{
                'item_id': self.kuku.id, 'preset_id': self.half_leg.id,
                'qty': '12', 'cost': '2400',
            }]),
            'idempotency_token': str(uuid.uuid4()),
        })
        data = resp.json()
        self.assertTrue(data.get('ok'), data)
        self.full_leg.refresh_from_db()
        self.half_leg.refresh_from_db()
        self.assertEqual(self.full_leg.cost_price, Decimal('200.00'))
        self.assertIsNone(self.half_leg.cost_price)
        line = KitchenStockReceiptLine.objects.get(item=self.kuku)
        self.assertEqual(line.preset_id, self.full_leg.id)

    def test_edit_item_saves_tracks_stock_of(self):
        resp = self.client.post(f'/stock/edit/{self.wing.item_id}/', {
            'description': 'Kuku', 'unit': 'Pcs', 'selling_price': '0',
            'store': self.store.id, 'reorder_level': '0', 'reorder_quantity': '0',
            'is_produce': '', 'is_kitchen_batch': '',
            'preset_id': [str(self.full_leg.id), str(self.half_leg.id), str(self.wing.id)],
            'preset_label': ['Full Chicken Leg', 'Half Chicken Leg', 'Wing'],
            'preset_price': ['250', '150', '70'],
            'preset_qty_consumed': ['1', '0.5', '0.125'],
            'preset_serving_type': ['cup', 'cup', 'cup'],
            'preset_khaki_type': ['NONE', 'NONE', 'NONE'],
            'tracks_of_preset_id': [str(self.wing.id)],
            'tracks_of_target_id': [str(self.full_leg.id)],
        })
        self.assertIn(resp.status_code, (200, 302))
        self.wing.refresh_from_db()
        self.assertEqual(self.wing.tracks_stock_of_id, self.full_leg.id)

    def test_edit_item_rejects_self_reference(self):
        resp = self.client.post(f'/stock/edit/{self.wing.item_id}/', {
            'description': 'Kuku', 'unit': 'Pcs', 'selling_price': '0',
            'store': self.store.id, 'reorder_level': '0', 'reorder_quantity': '0',
            'is_produce': '', 'is_kitchen_batch': '',
            'preset_id': [str(self.full_leg.id), str(self.half_leg.id), str(self.wing.id)],
            'preset_label': ['Full Chicken Leg', 'Half Chicken Leg', 'Wing'],
            'preset_price': ['250', '150', '70'],
            'preset_qty_consumed': ['1', '0.5', '0.125'],
            'preset_serving_type': ['cup', 'cup', 'cup'],
            'preset_khaki_type': ['NONE', 'NONE', 'NONE'],
            'tracks_of_preset_id': [str(self.wing.id)],
            'tracks_of_target_id': [str(self.wing.id)],
        })
        self.assertIn(resp.status_code, (200, 302))
        self.wing.refresh_from_db()
        self.assertIsNone(self.wing.tracks_stock_of_id)

    def test_topping_up_same_preset_adds_to_existing_tally_not_a_separate_batch(self):
        """Roy: 'add more from a specific batch... but they are from the
        same received stock not a different one.' There is no discrete
        batch object — receiving again for the SAME preset just adds to
        the running received total, so a recount correction is
        indistinguishable from 'the same batch', by construction."""
        self._receive_full_legs(qty=10, cost=200)
        # Staff undercounted — 2 more legs found from the same delivery.
        import uuid
        resp = self.client.post('/kitchen/receive/', {
            'item_id': self.kuku.id, 'mode': 'portion',
            'qty': '2', 'cost_price': '0',
            'preset_id': str(self.full_leg.id),
            'idempotency_token': f'rcv-topup-{uuid.uuid4()}',
        })
        self.assertTrue(resp.json()['ok'])
        self.assertEqual(
            KitchenStockReceiptLine.objects.filter(item=self.kuku, preset=self.full_leg).count(), 2,
            "a top-up correction is a second line, not a second batch object",
        )
        self.kuku.refresh_from_db()
        self.assertEqual(self.kuku.current_balance(), 12)

    def test_ledger_drift_hides_rather_than_fabricates(self):
        """2026-08-09 live report (Roy): a same-day 'show every preset as a
        fallback' patch (meant to fix presets vanishing entirely) backfired
        into a WORSE bug — it surfaced Wing/Drumstick tiles that were never
        actually received, once the received-vs-sold ledger drifted from
        the item's real balance (e.g. a plain Receipt with no preset
        attached, growing real stock without touching the anchor tally).
        Removed. A drift must now correctly HIDE the affected preset rather
        than fabricate extra ones that were never received — hiding a real
        preset is a diagnosable, honest gap; showing a fake one is not."""
        self._receive_full_legs(qty=1, cost=200)
        Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('20'),
            recorded_by=self.owner, invoice_no='PLAIN-TOPUP',
        )
        self.kuku.refresh_from_db()
        self.assertEqual(self.kuku.current_balance(), Decimal('21'))
        import json as _json
        cart = _json.dumps([{
            'item_id': self.kuku.id, 'preset_id': self.half_leg.id,
            'qty': 0.5, 'amount': 150, 'description': 'Kuku — Half Chicken Leg',
        }])
        for _i in range(2):
            resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
            self.assertTrue(resp.json().get('ok'), resp.json())
        self.kuku.refresh_from_db()
        self.assertEqual(self.kuku.current_balance(), Decimal('20'), "real stock remains")
        resp2 = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp2.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        labels = [p['label'] for p in kuku['presets']]
        self.assertNotIn('Wing', labels, "must never fabricate a preset that was never received")
        self.assertNotIn('Drumstick', labels)

    def test_ever_received_preset_stays_sellable_when_net_anchor_drifts_negative(self):
        """2026-08-21 live report #2, same day as the Gawa Kuku fix (Roy,
        Monsoon Inn, live and mid-service, blocked from selling chicken at
        all): "this going in circles everytime we change something really
        sucks." The received-vs-sold NET anchor tally
        (test_selling_enough_half_legs_hides_both_presets above) has too
        many independent ways to legitimately drift negative while the
        item's own real, authoritative balance stays positive — every fix
        so far has only taught the gate about one more receiving source
        (KitchenStockReceiptLine, then PortioningEventLine), which just
        delays the next drift-triggered outage instead of closing the
        class of bug. Decisive fix: a preset that has EVER been genuinely
        received (`ever_received`) now stays sellable for as long as
        item.current_balance() is still positive — the net tally no longer
        gates the sell button at all, only the owner-only diagnostic.
        Reproduces the drift directly: extra stock arrives via a route the
        per-preset ledger doesn't track (a plain Receipt with no preset —
        the exact same drift source as test_ledger_drift_hides_rather_than_
        fabricates above), then enough is sold via the tethered preset to
        push the net tally negative while real balance stays positive."""
        self._receive_full_legs(qty=1, cost=200)
        Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('5'),
            recorded_by=self.owner, invoice_no='PLAIN-TOPUP-2',
        )
        self.kuku.refresh_from_db()
        self.assertEqual(self.kuku.current_balance(), Decimal('6'))
        import json as _json
        cart = _json.dumps([{
            'item_id': self.kuku.id, 'preset_id': self.half_leg.id,
            'qty': 0.5, 'amount': 150, 'description': 'Kuku — Half Chicken Leg',
        }])
        for _i in range(3):
            resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
            self.assertTrue(resp.json().get('ok'), resp.json())
        self.kuku.refresh_from_db()
        self.assertEqual(self.kuku.current_balance(), Decimal('4.5'), "real stock still sits unsold")

        resp2 = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp2.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        labels = [p['label'] for p in kuku['presets']]
        self.assertIn('Full Chicken Leg', labels, "must not vanish while real stock (4.5) sits unsold")
        self.assertIn('Half Chicken Leg', labels)
        # Wing was never received at all — still correctly hidden, unchanged.
        self.assertNotIn('Wing', labels)

    def test_genuinely_depleted_item_still_hides_all_presets(self):
        """The fully-sold case correctly hides every preset."""
        self._receive_full_legs(qty=1, cost=200)
        import json as _json
        cart = _json.dumps([{
            'item_id': self.kuku.id, 'preset_id': self.half_leg.id,
            'qty': 0.5, 'amount': 150, 'description': 'Kuku — Half Chicken Leg',
        }])
        for _i in range(2):
            resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
            self.assertTrue(resp.json().get('ok'), resp.json())
        self.kuku.refresh_from_db()
        self.assertEqual(self.kuku.current_balance(), Decimal('0'))
        resp2 = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp2.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        labels = [p['label'] for p in kuku['presets']]
        self.assertEqual(labels, [])

    def test_owner_sees_received_sold_diagnostic_numbers(self):
        """2026-08-09 — owner/manager get the raw received/sold numbers
        behind the cut-visibility gate on every preset dict for an item
        that's ever had a preset-attributed receipt, so a real ledger
        mismatch can be diagnosed from real numbers instead of guessed at.
        Staff never see this (it's diagnostic clutter for them, not a
        selling concern)."""
        self._receive_full_legs(qty=12, cost=200)
        resp = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        full_leg = next(p for p in kuku['presets'] if p['label'] == 'Full Chicken Leg')
        self.assertEqual(full_leg['_received'], 12.0)
        self.assertEqual(full_leg['_sold'], 0.0)

        staff = User.objects.create_user(username='tether_staff', password='x')
        UserProfile.objects.create(
            user=staff, business=self.biz, role='kitchen', can_access_kitchen=True,
        )
        self.client.force_login(staff)
        resp2 = self.client.get('/kitchen/')
        items2 = self._portion_items_blob(resp2.content.decode())
        kuku2 = next(i for i in items2 if i['id'] == self.kuku.id)
        full_leg2 = next(p for p in kuku2['presets'] if p['label'] == 'Full Chicken Leg')
        self.assertNotIn('_received', full_leg2)
        self.assertNotIn('_sold', full_leg2)

    def test_hidden_presets_excludes_currently_visible_ones(self):
        """2026-08-11 — a preset that IS still sellable (Full/Half Chicken
        Leg here) must never also appear in hidden_presets — only Wing
        (never received at all, correctly hidden from day one) does."""
        self._receive_full_legs(qty=12, cost=200)
        resp = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        hidden_labels = [p['label'] for p in kuku['hidden_presets']]
        self.assertNotIn('Full Chicken Leg', hidden_labels)
        self.assertNotIn('Half Chicken Leg', hidden_labels)
        self.assertIn('Wing', hidden_labels)

    def test_hidden_presets_shows_real_numbers_for_owner_when_all_presets_vanish(self):
        """2026-08-11 live report (Roy): "why are the presets not showing up
        when i press the Kuku tile" — this is the exact scenario
        test_selling_enough_half_legs_hides_both_presets already covers for
        `presets` (both go empty); hidden_presets must surface the real
        received/sold/remaining figures behind that wipe-out instead of
        leaving the owner with nothing to look at."""
        self._receive_full_legs(qty=1, cost=200)
        import json as _json
        for _i in range(2):
            cart = _json.dumps([{
                'item_id': self.kuku.id, 'preset_id': self.half_leg.id,
                'qty': 0.5, 'amount': 150, 'description': 'Kuku — Half Chicken Leg',
            }])
            resp = self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
            self.assertTrue(resp.json().get('ok'), resp.json())

        resp2 = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp2.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        # The sell-tile list is still correctly empty (unchanged behavior).
        self.assertEqual(kuku['presets'], [])
        hidden_labels = [p['label'] for p in kuku['hidden_presets']]
        self.assertIn('Full Chicken Leg', hidden_labels)
        self.assertIn('Half Chicken Leg', hidden_labels)
        full_leg = next(p for p in kuku['hidden_presets'] if p['label'] == 'Full Chicken Leg')
        self.assertEqual(full_leg['_received'], 1.0)
        self.assertEqual(full_leg['_sold'], 1.0)
        self.assertEqual(full_leg['_remaining'], 0.0)
        half_leg = next(p for p in kuku['hidden_presets'] if p['label'] == 'Half Chicken Leg')
        self.assertEqual(half_leg['tethered_to'], 'Full Chicken Leg')

    def test_hidden_presets_only_lists_backdated_context_via_real_sold_total(self):
        """Roy's own added context on the live report: the presets vanished
        for the same receipt he'd made BACKDATED sales against for a
        previous date. Backdated sales must count toward `_sold` exactly
        like an ordinary sale (they're real depletion, whenever recorded) —
        locked in here so a future session doesn't "fix" this to exclude
        backdated transactions from the tally, which would be wrong."""
        self._receive_full_legs(qty=2, cost=200)
        import json as _json
        from django.utils import timezone
        cart = _json.dumps([{
            'item_id': self.kuku.id, 'preset_id': self.full_leg.id,
            'qty': 1, 'amount': 250, 'description': 'Kuku — Full Chicken Leg',
        }])
        yesterday = (timezone.localdate() - timezone.timedelta(days=1)).isoformat()
        resp = self.client.post('/kitchen/', {
            'cart': cart, 'payment_method': 'cash',
            'backdated_at': yesterday + 'T12:00',
        })
        self.assertTrue(resp.json().get('ok'), resp.json())
        resp2 = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp2.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        full_leg = next(p for p in kuku['presets'] if p['label'] == 'Full Chicken Leg')
        self.assertEqual(full_leg['_sold'], 1.0)


class KitchenBackdatedCheckoutTest(TestCase):
    """2026-08-09 live urgent request (Roy) — Kitchen Board's own checkout
    had no backdate support (unlike Quick Sell's whole-cart catch-up
    toggle, 2026-08-07), blocking same-day correction of missed chicken
    sales from two prior business days. Originally excluded food_tab/
    bar_tab; widened to include them 2026-08-21 (see
    test_backdated_food_tab_sale_uses_the_given_timestamp) — see
    QuickSellCatchUpBackdateTest's matching docstring for why."""

    def setUp(self):
        self.biz = Business.objects.create(name='KB Backdate Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='kbbd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='KBBD-KUKU', unit='Pcs', selling_price=Decimal('150'),
        )
        Transaction.objects.create(business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('10'))
        # Batch item (Chipo) + grill-batch item — 2026-08-12 same-day
        # follow-up: Roy's backdate toggle had no effect on either of these,
        # only on the plain portion-item branch above.
        self.chipo = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='KBBD-CHIPO', unit='Batch', selling_price=Decimal('100'),
            is_kitchen_batch=True,
        )
        self.chipo_batch = KitchenBatch.objects.create(
            business=self.biz, store=self.store, item=self.chipo,
            cost_total=Decimal('1000'), status='OPEN', recorded_by=self.owner,
        )
        self.smokies = Item.objects.create(
            business=self.biz, store=self.store, description='Smokies',
            material_no='KBBD-SMOKIES', unit='Batch', selling_price=Decimal('40'),
            is_produce=True, produce_mode='BUNCH',
        )
        self.bunch = ProduceBunch.objects.create(
            item=self.smokies, business=self.biz, size='LARGE',
            cost_price=Decimal('300'), target_revenue=Decimal('500'),
        )
        self.client.force_login(self.owner)

    def test_backdated_cash_sale_uses_the_given_timestamp(self):
        import json as _json
        # backdated_at is parsed as LOCAL time (Africa/Nairobi) by the view,
        # matching Quick Sell's own backdate parsing — format the naive
        # local wall-clock string, not a raw UTC-aware timezone.now().
        past_local = timezone.localtime(timezone.now() - timedelta(days=2)).replace(microsecond=0)
        cart = _json.dumps([{'item_id': self.kuku.id, 'qty': 1, 'amount': 150, 'description': 'Kuku'}])
