class KitchenBatchOpenBatchReceivedOnTest(TestCase):
    """2026-08-12 live request (Roy) — the OTHER half of the same complaint:
    "+Pata Stok" for a batch item (raw-material draw or plain manual cost)
    had no way to backdate the batch itself, always landing on today with
    no correction path — blocking re-entering Chipo history from a chosen
    date the same way the Stock Receipt tool already supports for portion
    items."""

    def setUp(self):
        self.biz = Business.objects.create(name='KB Received On Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='kbro_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.raw_potatoes = Item.objects.create(
            business=self.biz, store=self.store, description='Raw Potatoes',
            material_no='KBRO-RAW', unit='Ndoo', selling_price=Decimal('0'),
            cost_price=Decimal('100'),
        )
        Transaction.objects.create(business=self.biz, item=self.raw_potatoes, type='Receipt', qty=Decimal('20'))
        self.chipo = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='KBRO-CHIPO', unit='Batch', selling_price=Decimal('100'),
            is_kitchen_batch=True, raw_material_source=self.raw_potatoes,
        )
        self.stew = Item.objects.create(
            business=self.biz, store=self.store, description='Stew',
            material_no='KBRO-STEW', unit='Batch', selling_price=Decimal('150'),
            is_kitchen_batch=True,
        )
        self.client.force_login(self.owner)

    # ── Model layer ──────────────────────────────────────────────────────

    def test_open_batch_with_received_on_stamps_batch_and_draw_transaction(self):
        past_date = timezone.localdate() - timedelta(days=5)
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.chipo,
            recorded_by=self.owner, draw_qty=Decimal('5'), received_on=past_date,
        )
        self.assertEqual(batch.received_on, past_date)
        draw_txn = Transaction.objects.filter(item=self.raw_potatoes, type='Draw').first()
        self.assertIsNotNone(draw_txn)
        self.assertEqual(timezone.localtime(draw_txn.created_at).date(), past_date)

    def test_open_batch_without_received_on_defaults_to_today(self):
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.stew,
            recorded_by=self.owner, cost_total=Decimal('500'),
        )
        self.assertEqual(batch.received_on, timezone.localdate())

    # ── View layer ───────────────────────────────────────────────────────

    def test_kitchen_receive_draw_mode_honours_received_on(self):
        past_date = timezone.localdate() - timedelta(days=5)
        resp = self.client.post('/kitchen/receive/', {
            'item_id': self.chipo.id, 'mode': 'kitchen_batch',
            'draw_qty': '5', 'received_on': past_date.isoformat(),
            'idempotency_token': 'kbro-tok-1',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        batch = KitchenBatch.objects.get(id=data['batch']['id'])
        self.assertEqual(batch.received_on, past_date)

    def test_kitchen_receive_manual_mode_honours_received_on(self):
        past_date = timezone.localdate() - timedelta(days=3)
        resp = self.client.post('/kitchen/receive/', {
            'item_id': self.stew.id, 'mode': 'kitchen_batch',
            'cost_total': '500', 'received_on': past_date.isoformat(),
            'idempotency_token': 'kbro-tok-2',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        batch = KitchenBatch.objects.get(id=data['batch']['id'])
        self.assertEqual(batch.received_on, past_date)

    def test_kitchen_receive_blank_received_on_defaults_to_today(self):
        resp = self.client.post('/kitchen/receive/', {
            'item_id': self.stew.id, 'mode': 'kitchen_batch',
            'cost_total': '500', 'received_on': '',
            'idempotency_token': 'kbro-tok-3',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        batch = KitchenBatch.objects.get(id=data['batch']['id'])
        self.assertEqual(batch.received_on, timezone.localdate())

    def test_kitchen_receive_invalid_received_on_falls_back_to_today(self):
        resp = self.client.post('/kitchen/receive/', {
            'item_id': self.stew.id, 'mode': 'kitchen_batch',
            'cost_total': '500', 'received_on': 'not-a-date',
            'idempotency_token': 'kbro-tok-4',
        })
        data = resp.json()
        self.assertTrue(data['ok'], data)
        batch = KitchenBatch.objects.get(id=data['batch']['id'])
        self.assertEqual(batch.received_on, timezone.localdate())


class RawMaterialSourcePencilBugTest(TestCase):
    """2026-08-09 live report (Roy) — tapping the pencil on "Raw Potatoes"
    (a raw_material_source item feeding Chipo's KitchenBatch draw) opened
    the custom SELL price flow, even though "the sack of potatoes are not
    been sold, only the output which is chipo." kitchen_board() now flags
    such items so the template can swap in a cost-correction affordance
    instead."""

    def setUp(self):
        self.biz = Business.objects.create(name='RawMat Pencil Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='rmp_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.raw_potatoes = Item.objects.create(
            business=self.biz, store=self.store, description='Raw Potatoes',
            material_no='RMP-RAW', unit='Ndoo', selling_price=Decimal('0'),
            cost_price=Decimal('100'),
        )
        self.chipo = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='RMP-CHIPO', unit='Batch', selling_price=Decimal('100'),
            is_kitchen_batch=True, raw_material_source=self.raw_potatoes,
        )
        Transaction.objects.create(business=self.biz, item=self.raw_potatoes, type='Receipt', qty=Decimal('6'))
        self.client.force_login(self.owner)

    def _portion_items_blob(self, body):
        import json as _json
        start = body.index('var _portionItems')
        eq = body.index('=', start)
        end = body.index(';\n', eq)
        return _json.loads(body[eq + 1:end].strip())

    def test_raw_material_source_flagged_in_portion_items(self):
        resp = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp.content.decode())
        raw = next(i for i in items if i['id'] == self.raw_potatoes.id)
        self.assertTrue(raw['is_raw_material_source'])

    def test_ordinary_portion_item_not_flagged(self):
        soda = Item.objects.create(
            business=self.biz, store=self.store, description='Soda',
            material_no='RMP-SODA', unit='Pcs', selling_price=Decimal('50'),
        )
        Transaction.objects.create(business=self.biz, item=soda, type='Receipt', qty=Decimal('10'))
        resp = self.client.get('/kitchen/')
        items = self._portion_items_blob(resp.content.decode())
        soda_item = next(i for i in items if i['id'] == soda.id)
        self.assertFalse(soda_item['is_raw_material_source'])


class RenameSettledTabTest(TestCase):
    """2026-08-09 live request (Roy) — "a way of editing the name of a
    recently paid bill but the staff did not have the name before and the
    receipt should reconcile accordingly." update_tab_name() previously
    only accepted an OPEN tab; now also accepts a SETTLED (fully paid) one
    and syncs the tab's own master Receipt.customer_name too."""

    def setUp(self):
        self.biz = Business.objects.create(name='Rename Settled Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='rst_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='rst_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        Shift.objects.create(business=self.biz, staff=self.staff, status='OPEN')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker',
            material_no='RST-01', unit='Pcs', selling_price=Decimal('250'),
        )
        self.tab = BarTab.objects.create(
            business=self.biz, customer_name='Table 4', status='SETTLED', source='bar',
            store=self.store, settled_at=timezone.now(),
        )
        self.txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('250'), payment_method='cash',
            recipient='Table 4',
        )
        self.entry = BarTabEntry.objects.create(
            tab=self.tab, transaction=self.txn, description='Tusker',
            amount=Decimal('250'), is_paid=True, payment_method='cash',
        )
        self.receipt = Receipt.objects.create(
            business=self.biz, receipt_number=1, token='rst-token-1',
            customer_name='Table 4', payment_method='cash', total=Decimal('250'),
            meta={'tab_id': self.tab.id},
        )

    def test_owner_can_rename_settled_tab(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/tabs/{self.tab.id}/rename/', {'name': 'Bosco'})
        self.assertEqual(resp.status_code, 200)
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.tab.refresh_from_db()
        self.assertEqual(self.tab.customer_name, 'Bosco')

    def test_rename_settled_tab_syncs_transaction_recipient(self):
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{self.tab.id}/rename/', {'name': 'Bosco'})
        self.txn.refresh_from_db()
        self.assertEqual(self.txn.recipient, 'Bosco')

    def test_rename_settled_tab_syncs_master_receipt(self):
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{self.tab.id}/rename/', {'name': 'Bosco'})
        self.receipt.refresh_from_db()
        self.assertEqual(self.receipt.customer_name, 'Bosco')

    def test_shift_staff_can_rename_settled_tab(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/bar/tabs/{self.tab.id}/rename/', {'name': 'Bosco'})
        self.assertTrue(resp.json()['ok'])

    def test_settled_tab_rename_never_merges_into_an_open_tab(self):
        """Merging only makes sense for a still-accumulating OPEN tab —
        renaming a DONE, settled tab to match an unrelated open tab's name
        must never move already-paid money into that open tab."""
        open_tab = BarTab.objects.create(
            business=self.biz, customer_name='Bosco', status='OPEN', source='bar', store=self.store,
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/tabs/{self.tab.id}/rename/', {'name': 'Bosco'})
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertFalse(data.get('merged'))
        self.tab.refresh_from_db()
        self.assertEqual(self.tab.customer_name, 'Bosco')
        self.assertEqual(self.tab.entries.count(), 1, "the settled entry must stay on its own tab, not move into open_tab")
        open_tab.refresh_from_db()
        self.assertEqual(open_tab.entries.count(), 0)

    def test_void_tab_still_rejected(self):
        self.tab.status = 'VOID'
        self.tab.save(update_fields=['status'])
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/tabs/{self.tab.id}/rename/', {'name': 'Bosco'})
        self.assertEqual(resp.status_code, 404)

    def test_open_tab_rename_still_syncs_receipt_too(self):
        """Regression: the receipt sync is unconditional, so an ordinary
        OPEN-tab rename (the pre-existing feature) picks it up for free."""
        open_tab = BarTab.objects.create(
            business=self.biz, customer_name='Tab #999', status='OPEN', source='bar', store=self.store,
        )
        open_receipt = Receipt.objects.create(
            business=self.biz, receipt_number=2, token='rst-token-2',
            customer_name='Tab #999', payment_method='tab', total=Decimal('0'),
            meta={'tab_id': open_tab.id},
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/tabs/{open_tab.id}/rename/', {'name': 'Mary'})
        self.assertTrue(resp.json()['ok'])
        open_receipt.refresh_from_db()
        self.assertEqual(open_receipt.customer_name, 'Mary')


class RenameConsolidatesReceiptAndFindableTest(TestCase):
    """2026-08-09 same-day live follow-up (Roy) — renaming an already-paid
    "Table 4" tab to "Charles" (a name another, separate tab/receipt
    already used) left TWO disconnected "Charles" — the wall-scan QR
    search couldn't find him at all, and the rename produced a second,
    unlinked receipt instead of joining his existing one."""

    def setUp(self):
        self.biz = Business.objects.create(name='Rename Consolidate Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='rc_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker',
            material_no='RC-01', unit='Pcs', selling_price=Decimal('250'),
        )

    def _make_settled_tab_with_receipt(self, name, amount, receipt_number, token):
        tab = BarTab.objects.create(
            business=self.biz, customer_name=name, status='SETTLED', source='bar',
            store=self.store, settled_at=timezone.now(), tab_receipt_token=token,
        )
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=amount, payment_method='cash', recipient=name,
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Tusker',
            amount=amount, is_paid=True, payment_method='cash',
        )
        receipt = Receipt.objects.create(
            business=self.biz, receipt_number=receipt_number, token=f'rc-tok-{token}',
            customer_name=name, payment_method='cash', total=amount,
            meta={'tab_id': tab.id},
        )
        return tab, receipt

    def test_rename_to_existing_name_links_into_that_receipt(self):
        charles_tab, charles_receipt = self._make_settled_tab_with_receipt(
            'Charles', Decimal('1150'), 1, 'charles',
        )
        table4_tab, table4_receipt = self._make_settled_tab_with_receipt(
            'Table 4', Decimal('150'), 2, 'table4',
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/tabs/{table4_tab.id}/rename/', {'name': 'Charles'})
        self.assertTrue(resp.json()['ok'], resp.json())

        charles_receipt.refresh_from_db()
        table4_receipt.refresh_from_db()
        # The renamed tab must now be linked into Charles's EXISTING receipt.
        self.assertIn(table4_tab.id, charles_receipt.meta.get('linked_tab_ids', []))
        # Its own old receipt must release its direct claim on that tab, so
        # lookups fall through to the consolidated one instead of the stale
        # first receipt.
        self.assertNotEqual(table4_receipt.meta.get('tab_id'), table4_tab.id)

    def test_renamed_tab_resolves_to_the_consolidated_receipt_via_own_receipt_first(self):
        """meta.tab_id (direct ownership) is checked BEFORE linked_tab_ids —
        this part of resolution works identically on SQLite and Postgres,
        so it's exercised as a genuine end-to-end check. The linked_tab_ids
        fallback itself (the OTHER tab's own resolution) uses a JSONField
        `contains` lookup Postgres-only (see _safe_linked_query's own
        docstring) — degrades to "no match" on SQLite, same documented,
        pre-existing constraint CrossCounterReceiptLinkingTest already
        works around by asserting on meta state directly rather than the
        full URL round trip; production (Postgres) resolves it live."""
        charles_tab, charles_receipt = self._make_settled_tab_with_receipt(
            'Charles', Decimal('1150'), 1, 'charles2',
        )
        table4_tab, table4_receipt = self._make_settled_tab_with_receipt(
            'Table 4', Decimal('150'), 2, 'table4-2',
        )
        self.client.force_login(self.owner)
        self.client.post(f'/bar/tabs/{table4_tab.id}/rename/', {'name': 'Charles'})

        from core.keg_views import _resolve_tab_public_url
        # Charles's own tab still resolves correctly to its own receipt.
        self.assertEqual(_resolve_tab_public_url(charles_tab), f'/r/{charles_receipt.token}/')
        # The renamed tab's OWN former direct claim is gone — it must
        # never resolve back to its own stale receipt.
        table4_receipt.refresh_from_db()
        charles_receipt.refresh_from_db()
        self.assertNotEqual(table4_receipt.meta.get('tab_id'), table4_tab.id)
        self.assertIn(table4_tab.id, charles_receipt.meta.get('linked_tab_ids', []))

    def test_wall_scan_search_finds_a_recently_paid_settled_tab_by_name(self):
        """2026-08-09, same-day follow-up (Roy): "customers just want to
        search their name... that is just it" — a RECENT, fully-paid
        settled tab (nothing left owing) must be findable by name, no PIN
        needed. This endpoint is still PUBLIC with no login (the wall-
        mounted bar QR page) — see FINDABLE_BY_NAME_DAYS / _findable_tabs_qs
        for how this stays bounded rather than reopening the earlier,
        reverted unrestricted-history exposure."""
        tab, receipt = self._make_settled_tab_with_receipt('Charles', Decimal('1150'), 1, 'charles3')
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/?q=Charles')
        data = resp.json()
        self.assertEqual(len(data['tabs']), 1)
        self.assertEqual(data['tabs'][0]['url'], f'/r/{receipt.token}/')

    def test_void_tab_never_findable_by_name(self):
        tab, receipt = self._make_settled_tab_with_receipt('Ghost', Decimal('100'), 1, 'ghost')
        tab.status = 'VOID'
        tab.save(update_fields=['status'])
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/?q=Ghost')
        self.assertEqual(resp.json()['tabs'], [])

    def test_rename_with_no_existing_receipt_under_new_name_keeps_old_behavior(self):
        table4_tab, table4_receipt = self._make_settled_tab_with_receipt(
            'Table 4', Decimal('150'), 1, 'table4-solo',
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/tabs/{table4_tab.id}/rename/', {'name': 'Brand New Name'})
        self.assertTrue(resp.json()['ok'])
        table4_receipt.refresh_from_db()
        self.assertEqual(table4_receipt.customer_name, 'Brand New Name')
        self.assertEqual(table4_receipt.meta.get('tab_id'), table4_tab.id)

    def test_renaming_to_a_different_customers_name_never_merges_receipts(self):
        """2026-08-16 live report (Roy, Monsoon Inn) — the ACTUAL confirmed
        root cause of a real production incident, found via diagnose_receipt:
        a tab renamed to 'Peter' (already resolved to one Customer record)
        got silently folded into a WEEK-OLD, already-settled receipt for a
        DIFFERENT 'Peter' (a different Customer record) — this consolidation
        search has no date bound and, unlike resolve_master_receipt(), never
        checked whether the two records agree on WHICH customer at all."""
        peter_a = Customer.objects.create(business=self.biz, name='Peter')
        peter_b = Customer.objects.create(business=self.biz, name='Peter')
        old_tab, old_receipt = self._make_settled_tab_with_receipt(
            'Peter', Decimal('150'), 1, 'peter-old',
        )
        old_tab.customer = peter_a
        old_tab.save(update_fields=['customer'])

        new_tab = BarTab.objects.create(
            business=self.biz, customer_name='Suzzie', customer=peter_b,
            status='OPEN', source='qs', store=self.store,
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/bar/tabs/{new_tab.id}/rename/', {'name': 'Peter'})
        self.assertTrue(resp.json()['ok'], resp.json())

        old_receipt.refresh_from_db()
        self.assertNotIn(
            new_tab.id, old_receipt.meta.get('linked_tab_ids', []),
            'a tab belonging to a DIFFERENT Customer must never be folded '
            "into another customer's already-settled receipt just because "
            'the typed name matches',
        )
        self.assertEqual(
            Receipt.objects.filter(business=self.biz, customer_name='Peter').count(), 1,
            'the new tab must NOT get a receipt linked from the old one — '
            'no receipt exists for it yet since it has no entries',
        )


class SearchFindsReceiptsRegardlessOfAgeTest(TestCase):
    """2026-08-09, two live requests the same day, both correct, in
    tension: (1) "find a receipt regardless of when the bill was settled"
    — a fully unrestricted widening was tried and reverted within hours,
    since find_tab_search is a PUBLIC, unauthenticated endpoint (the
    wall-mounted bar QR page) and no date bound meant anyone could browse
    a customer's ENTIRE payment history forever by guessing a name; (2)
    the follow-up — "customers just want to search their name... that is
    just it" — no PIN, no extra step, even for an already-paid bill.
    _findable_tabs_qs() resolves both: a tab that genuinely still owes
    money stays findable regardless of age (an active, unresolved balance
    is real accountability, not historical browsing — unchanged, locked in
    below), and a PAID tab is ALSO findable by name for
    FINDABLE_BY_NAME_DAYS after it opened, then ages out — bounding how
    much of a stranger's guess-a-name attempt can ever expose."""

    def setUp(self):
        self.biz = Business.objects.create(name='Age Search Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker',
            material_no='AGE-01', unit='Pcs', selling_price=Decimal('250'),
        )

    def test_a_plain_settled_tab_from_90_days_ago_is_not_publicly_findable(self):
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Old Timer', status='SETTLED', source='bar',
            store=self.store, settled_at=timezone.now() - timedelta(days=90),
            tab_receipt_token='old-timer-tok',
        )
        BarTab.objects.filter(id=tab.id).update(opened_at=timezone.now() - timedelta(days=90))
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('250'), payment_method='cash',
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Tusker',
            amount=Decimal('250'), is_paid=True, payment_method='cash',
        )
        Receipt.objects.create(
            business=self.biz, receipt_number=1, token='old-timer-receipt',
            customer_name='Old Timer', payment_method='cash', total=Decimal('250'),
            meta={'tab_id': tab.id},
        )
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/?q=Old Timer')
        self.assertEqual(resp.json()['tabs'], [])

    def test_a_debt_converted_tab_from_months_ago_is_still_findable(self):
        """The un-settled (still-owing) side of Roy's ask — a tab converted
        to debt long ago must still be found, matching _findable_tabs_qs()'s
        own existing debt-converted-SETTLED handling."""
        tab = BarTab.objects.create(
            business=self.biz, customer_name='Old Debtor', status='SETTLED', source='bar',
            store=self.store, settled_at=timezone.now() - timedelta(days=60),
            tab_receipt_token='old-debtor-tok',
        )
        BarTab.objects.filter(id=tab.id).update(opened_at=timezone.now() - timedelta(days=60))
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('400'), payment_method='credit',
            recipient='Old Debtor',
        )
        BarTabEntry.objects.create(
            tab=tab, transaction=txn, description='Tusker',
            amount=Decimal('400'), is_paid=False,
        )
        receipt = Receipt.objects.create(
            business=self.biz, receipt_number=2, token='old-debtor-receipt',
            customer_name='Old Debtor', payment_method='credit', total=Decimal('400'),
            meta={'tab_id': tab.id},
        )
        resp = self.client.get(f'/bar/find-tab/{self.biz.id}/search/?q=Old Debtor')
        data = resp.json()
        self.assertEqual(len(data['tabs']), 1, data['tabs'])
        self.assertEqual(data['tabs'][0]['url'], f'/r/{receipt.token}/')


class DuplicateCustomerDebtDoubleDisplayTest(TestCase):
    """2026-08-09 live report (Roy) — "two Eugenes with the same amount and
    same items" in the debt dashboard, and a receipt showing a debt as
    cleared while the debt tracker still showed it open. Root cause:
    _get_customer_debt_data() matches Transactions by
    Transaction.recipient=customer.name (a plain string, never the
    Customer FK) — so two duplicate Customer rows sharing a name both
    independently display the SAME underlying unpaid transactions as their
    own outstanding balance, and a payment recorded against one (FK-scoped
    via CustomerDebtPayment.customer) never clears the other."""

    def setUp(self):
        self.biz = Business.objects.create(name='Dup Debt Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='dupdebt_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Keg Gold',
            material_no='DD-01', unit='Cup', selling_price=Decimal('80'),
        )
        self.eugene1 = Customer.objects.create(business=self.biz, name='Eugene', credit_approved=True)
        self.eugene2 = Customer.objects.create(business=self.biz, name='Eugene', credit_approved=True)
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-6'),
            sale_amount=Decimal('480'), payment_method='credit', recipient='Eugene',
        )

    def test_both_duplicate_customers_independently_show_the_same_debt(self):
        from core.debt_views import _get_customer_debt_data
        data1 = _get_customer_debt_data(self.eugene1, self.biz, scope='all')
        data2 = _get_customer_debt_data(self.eugene2, self.biz, scope='all')
        self.assertEqual(data1['outstanding'], 480.0)
        self.assertEqual(data2['outstanding'], 480.0, "confirms the double-display bug — same debt, two customers")

    def test_paying_off_one_duplicate_does_not_clear_the_other(self):
        CustomerDebtPayment.objects.create(
            business=self.biz, customer=self.eugene1, amount_paid=Decimal('480'), source='bar',
        )
        from core.debt_views import _get_customer_debt_data
        data1 = _get_customer_debt_data(self.eugene1, self.biz, scope='all')
        data2 = _get_customer_debt_data(self.eugene2, self.biz, scope='all')
        self.assertEqual(data1['outstanding'], 0.0, "eugene1 correctly shows cleared")
        self.assertEqual(data2['outstanding'], 480.0, "eugene2 (the duplicate) still shows the same debt as open")

    def test_debt_dashboard_lists_both_duplicates_separately(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/debt/')
        rows = resp.context['rows']
        eugene_rows = [r for r in rows if r['customer'].name == 'Eugene']
        self.assertEqual(len(eugene_rows), 2)

    def test_debt_dashboard_flags_the_duplicate_group(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/debt/')
        groups = resp.context['duplicate_groups']
        self.assertEqual(len(groups), 1)
        self.assertEqual(len(groups[0]), 2)
        ids = {e['customer'].id for e in groups[0]}
        self.assertEqual(ids, {self.eugene1.id, self.eugene2.id})

    def test_merging_the_duplicates_fixes_the_double_display_with_no_stock_change(self):
        item_balance_before = self.item.current_balance()
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/{self.eugene1.id}/merge/', {'absorb_id': str(self.eugene2.id)})
        self.assertEqual(resp.status_code, 302)
        self.assertFalse(Customer.objects.filter(id=self.eugene2.id).exists())
        from core.debt_views import _get_customer_debt_data
        data1 = _get_customer_debt_data(self.eugene1, self.biz, scope='all')
        self.assertEqual(data1['outstanding'], 480.0)
        self.item.refresh_from_db()
        self.assertEqual(self.item.current_balance(), item_balance_before,
            "merging must never touch stock — same physical items, only the customer record changed")

    def test_no_false_positive_for_two_genuinely_different_customers(self):
        Customer.objects.create(business=self.biz, name='Bosco', credit_approved=True)
        Customer.objects.create(business=self.biz, name='Charles', credit_approved=True)
        from core.debt_views import _find_duplicate_customer_groups
        groups = _find_duplicate_customer_groups(self.biz)
        self.assertEqual(len(groups), 1)
        names = {c.name for c in groups[0]}
        self.assertEqual(names, {'Eugene'})

    def test_case_insensitive_duplicate_detection(self):
        Customer.objects.create(business=self.biz, name='eugene ', credit_approved=True)
        from core.debt_views import _find_duplicate_customer_groups
        groups = _find_duplicate_customer_groups(self.biz)
        self.assertEqual(len(groups), 1)
        self.assertEqual(len(groups[0]), 3)

    def test_non_owner_never_sees_duplicate_groups(self):
        staff = User.objects.create_user(username='dupdebt_staff', password='x')
        UserProfile.objects.create(user=staff, business=self.biz, role='staff')
        self.client.force_login(staff)
        resp = self.client.get('/debt/')
        self.assertEqual(resp.context['duplicate_groups'], [])


class CombinedLedgerDebtAttributionTest(TestCase):
    """2026-08-09 live report (Roy) — on a combo bar+kitchen business, the
    customer debt profile's "Unpaid Credit Transactions" table could show a
    kitchen item as still owed even though the Kitchen Ledger tile right
    above it correctly said "All paid", while the genuinely-still-owed bar
    item didn't appear at all. Root cause: _get_customer_debt_data(scope=
    'all') ran ONE FIFO pass over every bar+kitchen credit transaction
    sorted purely by date, applying the SUM of every payment regardless of
    which ledger CustomerDebtPayment.source actually tagged it for — so a
    kitchen-tagged payment could get consumed against an older BAR
    transaction just because it came first chronologically."""

    def setUp(self):
        self.biz = Business.objects.create(name='Combo Ledger Biz', has_kitchen=True)
        self.bar_store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.kitchen_store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='cld_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.bar_item = Item.objects.create(
            business=self.biz, store=self.bar_store, description='Keg Gold',
            material_no='CLD-BAR-01', unit='Cup', selling_price=Decimal('100'),
        )
        self.kitchen_item = Item.objects.create(
            business=self.biz, store=self.kitchen_store, description='Kuku',
            material_no='CLD-KIT-01', unit='Pcs', selling_price=Decimal('100'),
        )
        self.customer = Customer.objects.create(business=self.biz, name='Genro', credit_approved=True)

        today = timezone.localdate()
        # Bar item sold FIRST (older) — never paid.
        self.bar_txn = Transaction.objects.create(
            business=self.biz, item=self.bar_item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='credit', recipient='Genro',
            date=today - timedelta(days=5),
        )
        # Kitchen item sold LATER (newer) — fully paid via a kitchen-tagged payment.
        self.kitchen_txn = Transaction.objects.create(
            business=self.biz, item=self.kitchen_item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='credit', recipient='Genro',
            date=today - timedelta(days=2),
        )
        CustomerDebtPayment.objects.create(
            business=self.biz, customer=self.customer, amount_paid=Decimal('100'),
            source='kitchen', payment_method='mpesa',
        )

    def test_kitchen_ledger_correctly_shows_fully_paid(self):
        from core.debt_views import _get_customer_debt_data
        kitchen_data = _get_customer_debt_data(self.customer, self.biz, scope='kitchen')
        self.assertEqual(kitchen_data['outstanding'], 0.0)
        self.assertEqual(kitchen_data['unpaid_transactions'], [])

    def test_bar_ledger_correctly_shows_still_owed(self):
        from core.debt_views import _get_customer_debt_data
        bar_data = _get_customer_debt_data(self.customer, self.biz, scope='bar')
        self.assertEqual(bar_data['outstanding'], 100.0)
        self.assertEqual(len(bar_data['unpaid_transactions']), 1)
        self.assertEqual(bar_data['unpaid_transactions'][0]['txn'].id, self.bar_txn.id)

    def test_combined_scope_attributes_unpaid_item_to_the_correct_ledger(self):
        """The core regression lock: before the fix, this would have shown
        the KITCHEN item as unpaid (wrong — it was fully covered by its own
        kitchen-tagged payment) and hidden the BAR item (actually still
        owed) — because the combined FIFO consumed whichever transaction
        was chronologically OLDEST (the bar one) using money that was
        actually earmarked for kitchen."""
        from core.debt_views import _get_customer_debt_data
        data = _get_customer_debt_data(self.customer, self.biz, scope='all')
        self.assertEqual(data['outstanding'], 100.0)
        self.assertEqual(len(data['unpaid_transactions']), 1)
        self.assertEqual(
            data['unpaid_transactions'][0]['txn'].id, self.bar_txn.id,
            "combined view must attribute the unpaid item to the BAR transaction, "
            "not the already-kitchen-paid one",
        )

    def test_combined_totals_match_sum_of_both_ledgers(self):
        from core.debt_views import _get_customer_debt_data
        bar_data = _get_customer_debt_data(self.customer, self.biz, scope='bar')
        kitchen_data = _get_customer_debt_data(self.customer, self.biz, scope='kitchen')
        data = _get_customer_debt_data(self.customer, self.biz, scope='all')
        self.assertEqual(data['total_credit'], bar_data['total_credit'] + kitchen_data['total_credit'])
        self.assertEqual(data['total_paid'], bar_data['total_paid'] + kitchen_data['total_paid'])
        self.assertEqual(data['outstanding'], round(bar_data['outstanding'] + kitchen_data['outstanding'], 2))

    def test_customer_profile_page_renders_consistent_unpaid_list(self):
        self.client.force_login(self.owner)
        resp = self.client.get(f'/debt/{self.customer.id}/')
        self.assertEqual(resp.status_code, 200)
        unpaid = resp.context['unpaid_transactions']
        self.assertEqual(len(unpaid), 1)
        self.assertEqual(unpaid[0]['txn'].id, self.bar_txn.id)

    def test_evaluate_credit_sees_the_correct_overdue_state_on_combo_business(self):
        """evaluate_credit() (Quick Sell's own credit gate) defaults to
        scope='all'. Window=3 days: the bar txn (5 days old, still unpaid)
        is genuinely overdue; the kitchen txn (2 days old) is fully paid.
        Before the fix, the combined FIFO would have marked the BAR txn as
        "paid" (oldest consumed first) and the KITCHEN txn as "unpaid" —
        which is within the 3-day window, so has_overdue would wrongly be
        False and this customer would wrongly be allowed more credit."""
        from core.credit_policy import evaluate_credit
        self.biz.credit_window_days = 3
        self.biz.save(update_fields=['credit_window_days'])
        decision = evaluate_credit(self.biz, self.customer)
        self.assertFalse(decision.allowed)
        self.assertEqual(decision.tier, 'blocked')


class DebtPaymentBackdateTest(TestCase):
    """2026-08-09 live request (Roy): "debts that were already paid but a
    long time ago but were not recorded at the time/day they were paid" —
    optional paid_date field on Record Payment lets staff record the real
    historical date instead of always stamping "now"."""

    def setUp(self):
        self.biz = Business.objects.create(name='Backdate Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='backdate_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker',
            material_no='BD-01', unit='Bottle', selling_price=Decimal('200'),
        )
        self.customer = Customer.objects.create(business=self.biz, name='Kamau', credit_approved=True)
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('200'), payment_method='credit', recipient='Kamau',
            date=timezone.localdate() - timedelta(days=20),
        )

    def test_backdated_payment_records_the_given_date(self):
        import uuid
        self.client.force_login(self.owner)
        real_date = (timezone.localdate() - timedelta(days=15)).isoformat()
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'cash', 'notes': '',
            'paid_date': real_date,
            'idempotency_token': str(uuid.uuid4()),
        })
        self.assertEqual(resp.status_code, 302)
        payment = CustomerDebtPayment.objects.get(customer=self.customer)
        self.assertEqual(timezone.localtime(payment.paid_at).date().isoformat(), real_date)

    def test_blank_paid_date_still_defaults_to_now(self):
        import uuid
        self.client.force_login(self.owner)
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'cash', 'notes': '',
            'idempotency_token': str(uuid.uuid4()),
        })
        self.assertEqual(resp.status_code, 302)
        payment = CustomerDebtPayment.objects.get(customer=self.customer)
        self.assertEqual(timezone.localtime(payment.paid_at).date(), timezone.localdate())

    def test_future_paid_date_is_ignored_not_blocked(self):
        """A correction feature must never itself block the payment — an
        invalid/future date silently falls back to now rather than
        rejecting the whole submission."""
        import uuid
        self.client.force_login(self.owner)
        future_date = (timezone.localdate() + timedelta(days=5)).isoformat()
        resp = self.client.post(f'/debt/{self.customer.id}/payment/', {
            'amount_paid': '200', 'payment_method': 'cash', 'notes': '',
            'paid_date': future_date,
            'idempotency_token': str(uuid.uuid4()),
        })
        self.assertEqual(resp.status_code, 302)
        payment = CustomerDebtPayment.objects.get(customer=self.customer)
        self.assertEqual(timezone.localtime(payment.paid_at).date(), timezone.localdate())


class AdHocExpenseTest(TestCase):
    """2026-08-09 live request (Roy), from Kitchen Board's own reconciliation
    area: "can I record expenses for a certain day" — followed by an
    explicit design decision: "it should not touch today's expected drawer
    just for that specified day." Deliberately separate from Petty Cash (a
    till drawdown, always "now") — this is a bookkeeping-only
    BusinessExpense, backdatable, optionally station-tagged, that must
    never be read by till_expected_cash()/_reconcile()."""

    def setUp(self):
        self.biz = Business.objects.create(name='Ad Hoc Expense Biz', has_kitchen=True)
        self.owner = User.objects.create_user(username='adhoc_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='adhoc_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.staff = User.objects.create_user(username='adhoc_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='kitchen')

    def _record(self, user, **overrides):
        import uuid
        self.client.force_login(user)
        payload = {
            'amount': '500', 'description': 'Kuni za kupikia',
            'category': 'supplies', 'station': 'kitchen',
            'date': timezone.localdate().isoformat(), 'notes': '',
            'idempotency_token': str(uuid.uuid4()),
        }
        payload.update(overrides)
        return self.client.post('/expenses/record/', payload)

    def test_owner_can_record_expense(self):
        resp = self._record(self.owner)
        data = resp.json()
        self.assertTrue(data['ok'], data)
        expense = BusinessExpense.objects.get(business=self.biz)
        self.assertEqual(expense.amount, Decimal('500'))
        self.assertEqual(expense.description, 'Kuni za kupikia')
        self.assertEqual(expense.category, 'supplies')
        self.assertEqual(expense.station, 'kitchen')
        self.assertEqual(expense.recorded_by, self.owner)

    def test_manager_can_record_expense(self):
        resp = self._record(self.manager)
        self.assertTrue(resp.json()['ok'])

    def test_plain_staff_blocked(self):
        # 2026-08-21: was a decorator-driven HTML redirect (302) — now an
        # inline, JSON-friendly 403 (see record_ad_hoc_expense's own
        # docstring for why the redirect was wrong for this AJAX endpoint).
        resp = self._record(self.staff)
        self.assertEqual(resp.status_code, 403)
        self.assertFalse(resp.json()['ok'])
        self.assertFalse(BusinessExpense.objects.filter(business=self.biz).exists())

    def test_delegated_staff_can_record_expense(self):
        # 2026-08-21 live request (Roy, on-site at Monsoon Inn — "the staff
        # have no way of back dating expenses... I have been left with lots
        # of recordings of both yesterday and today"): UserProfile.
        # can_record_expenses lets an owner delegate this to a trusted
        # staffer, matching can_adjust_stock/can_manage_kegs.
        self.staff.userprofile.can_record_expenses = True
        self.staff.userprofile.save()
        from core.shift_views import Shift
        Shift.objects.create(business=self.biz, staff=self.staff, status='OPEN', station='kitchen')
        resp = self._record(self.staff)
        self.assertTrue(resp.json()['ok'], resp.json())
        expense = BusinessExpense.objects.get(business=self.biz)
        self.assertEqual(expense.recorded_by, self.staff)

    def test_delegated_staff_without_open_shift_blocked(self):
        self.staff.userprofile.can_record_expenses = True
        self.staff.userprofile.save()
        resp = self._record(self.staff)
        self.assertEqual(resp.status_code, 403)
        self.assertTrue(resp.json().get('shift_required'))
        self.assertFalse(BusinessExpense.objects.filter(business=self.biz).exists())

    def test_backdate_still_works_for_delegated_staff(self):
        self.staff.userprofile.can_record_expenses = True
        self.staff.userprofile.save()
        from core.shift_views import Shift
        Shift.objects.create(business=self.biz, staff=self.staff, status='OPEN', station='kitchen')
        real_date = (timezone.localdate() - timedelta(days=2)).isoformat()
        resp = self._record(self.staff, date=real_date)
        self.assertTrue(resp.json()['ok'], resp.json())
        expense = BusinessExpense.objects.get(business=self.biz)
        self.assertEqual(expense.date.isoformat(), real_date)

    def test_ad_hoc_expenses_list_open_to_delegated_staff_not_plain_staff(self):
        self.client.force_login(self.owner)
        BusinessExpense.objects.create(
            business=self.biz, description='Test', amount=Decimal('300'),
            category='other', date=timezone.localdate(), station='kitchen',
            recorded_by=self.owner,
        )
        self.client.logout()
        # Plain staff: gets an empty list, not an error/crash.
        self.client.force_login(self.staff)
        resp = self.client.get('/expenses/list/', {'station': 'kitchen'})
        self.assertEqual(resp.json()['expenses'], [])
        self.client.logout()
        # Delegated staff: sees the real list.
        self.staff.userprofile.can_record_expenses = True
        self.staff.userprofile.save()
        self.client.force_login(self.staff)
        resp = self.client.get('/expenses/list/', {'station': 'kitchen'})
        self.assertEqual(len(resp.json()['expenses']), 1)

    def test_backdated_expense_records_the_given_date(self):
        real_date = (timezone.localdate() - timedelta(days=10)).isoformat()
        resp = self._record(self.owner, date=real_date)
        self.assertTrue(resp.json()['ok'])
        expense = BusinessExpense.objects.get(business=self.biz)
        self.assertEqual(expense.date.isoformat(), real_date)

    def test_future_date_falls_back_to_today_not_blocked(self):
        future_date = (timezone.localdate() + timedelta(days=5)).isoformat()
        resp = self._record(self.owner, date=future_date)
        self.assertTrue(resp.json()['ok'])
        expense = BusinessExpense.objects.get(business=self.biz)
        self.assertEqual(expense.date, timezone.localdate())

    def test_invalid_amount_rejected(self):
        resp = self._record(self.owner, amount='0')
        self.assertFalse(resp.json()['ok'])
        resp2 = self._record(self.owner, amount='not-a-number')
        self.assertFalse(resp2.json()['ok'])

    def test_blank_description_rejected(self):
        resp = self._record(self.owner, description='')
        self.assertFalse(resp.json()['ok'])

    def test_invalid_category_falls_back_to_other(self):
        resp = self._record(self.owner, category='not-a-real-category')
        self.assertTrue(resp.json()['ok'])
        expense = BusinessExpense.objects.get(business=self.biz)
        self.assertEqual(expense.category, 'other')

    def test_invalid_station_falls_back_to_blank(self):
        resp = self._record(self.owner, station='not-a-real-station')
        self.assertTrue(resp.json()['ok'])
        expense = BusinessExpense.objects.get(business=self.biz)
        self.assertEqual(expense.station, '')

    def test_duplicate_token_blocked(self):
        import uuid
        token = str(uuid.uuid4())
        self.client.force_login(self.owner)
        resp1 = self.client.post('/expenses/record/', {
            'amount': '300', 'description': 'X', 'category': 'other',
            'station': 'kitchen', 'date': timezone.localdate().isoformat(),
            'idempotency_token': token,
        })
        resp2 = self.client.post('/expenses/record/', {
            'amount': '300', 'description': 'X', 'category': 'other',
            'station': 'kitchen', 'date': timezone.localdate().isoformat(),
            'idempotency_token': token,
        })
        self.assertTrue(resp1.json()['ok'])
        self.assertEqual(resp2.status_code, 409)
        self.assertEqual(BusinessExpense.objects.filter(business=self.biz).count(), 1)

    def test_day_total_api_sums_station_scoped_expenses(self):
        self._record(self.owner, amount='300')
        self._record(self.owner, amount='200')
        self._record(self.owner, amount='999', station='bar')  # different station
        self.client.force_login(self.owner)
        resp = self.client.get('/expenses/day-total/', {'station': 'kitchen'})
        data = resp.json()
        self.assertEqual(data['total'], 500.0)

    def test_day_total_api_scoped_to_the_given_date(self):
        old_date = (timezone.localdate() - timedelta(days=3)).isoformat()
        self._record(self.owner, amount='700', date=old_date)
        self.client.force_login(self.owner)
        resp_today = self.client.get('/expenses/day-total/', {'station': 'kitchen'})
        resp_old = self.client.get('/expenses/day-total/', {'station': 'kitchen', 'date': old_date})
        self.assertEqual(resp_today.json()['total'], 0.0)
        self.assertEqual(resp_old.json()['total'], 700.0)

    def test_day_total_api_invalid_station_returns_zero(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/expenses/day-total/')
        self.assertEqual(resp.json()['total'], 0)

    def test_ad_hoc_expense_never_affects_till_expected_cash(self):
        """The core regression lock matching Roy's own explicit requirement:
        recording an ad-hoc expense for today must leave till_expected_
        cash()'s figure completely unchanged — this is a pure bookkeeping
        record, never a till drawdown."""
        from core.shift_views import till_expected_cash
        store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        Shift.objects.create(
            business=self.biz, store=store, staff=self.staff,
            opening_float=Decimal('0'), status='CLOSED', station='kitchen',
            started_at=timezone.now() - timedelta(hours=5),
            ended_at=timezone.now() - timedelta(hours=4),
            closing_cash_counted=Decimal('1000'),
        )
        before = till_expected_cash(self.biz, 'kitchen')
        self._record(self.owner, amount='5000')  # a large expense — would be obvious if it leaked in
        after = till_expected_cash(self.biz, 'kitchen')
        self.assertEqual(before['expected_cash'], after['expected_cash'])
        self.assertTrue(after['anchor_established'])


class AdHocExpenseDayReconciliationTest(TestCase):
    """2026-08-09, same-day follow-up (Roy, explicit confirmation to "both
    shift history and z report"): a same-day ad-hoc expense reconciles
    against Shift History and the Z-report for the SPECIFIC DAY it's dated
    for — additively, at display time — while till_expected_cash() and the
    LIVE in-progress shift panel (active_shift_api, close_shift) stay
    completely untouched. See shift_views._ad_hoc_expense_total_for_shift()."""

    def setUp(self):
        self.biz = Business.objects.create(name='Ad Hoc Recon Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='adhocrecon_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='adhocrecon_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker',
            material_no='AHR-01', unit='Bottle', selling_price=Decimal('200'),
        )

    def _record_expense(self, **overrides):
        import uuid
        self.client.force_login(self.owner)
        payload = {
            'amount': '400', 'description': 'Firewood', 'category': 'supplies',
            'station': 'bar', 'date': timezone.localdate().isoformat(), 'notes': '',
            'idempotency_token': str(uuid.uuid4()),
        }
        payload.update(overrides)
        return self.client.post('/expenses/record/', payload)

    def _make_closed_shift(self, cash=1000, counted=1000, station='bar', staff=None):
        staff = staff or self.staff
        # Anchored to mid-morning TODAY (not `now() - timedelta(hours=N)`) —
        # same day-boundary flakiness class documented elsewhere in this file
        # (PettyCashReviewUndoTest, BarZReportOverlappingShiftsTest): a
        # relative offset can slip into YESTERDAY when the suite happens to
        # run in the first few hours after local midnight, while the sibling
        # `_record_expense()` call always dates itself `timezone.localdate()`
        # (today) — the two then land on different calendar days and every
        # same-day reconciliation assertion in this class fails, unrelated to
        # the actual feature under test.
        today_10am = timezone.localtime().replace(hour=10, minute=0, second=0, microsecond=0)
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=staff,
            opening_float=Decimal('0'), status='CLOSED', station=station,
            started_at=today_10am,
            ended_at=today_10am + timedelta(hours=1),
            closing_cash_counted=Decimal(str(counted)),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal(str(cash)),
            payment_method='cash', created_at=shift.started_at,
        )
        return shift

    def test_ad_hoc_expense_total_for_shift_same_day(self):
        from core.shift_views import _ad_hoc_expense_total_for_shift
        shift = self._make_closed_shift()
        self._record_expense(amount='400')
        self.assertAlmostEqual(_ad_hoc_expense_total_for_shift(shift), 400.0, places=1)

    def test_ad_hoc_expense_total_for_shift_different_day_excluded(self):
        from core.shift_views import _ad_hoc_expense_total_for_shift
        shift = self._make_closed_shift()
        old_date = (timezone.localdate() - timedelta(days=5)).isoformat()
        self._record_expense(amount='400', date=old_date)
        self.assertAlmostEqual(_ad_hoc_expense_total_for_shift(shift), 0.0, places=1)

    def test_ad_hoc_expense_total_for_shift_station_scoped(self):
        from core.shift_views import _ad_hoc_expense_total_for_shift
        shift = self._make_closed_shift(station='bar')
        self._record_expense(amount='700', station='kitchen')
        self.assertAlmostEqual(_ad_hoc_expense_total_for_shift(shift), 0.0, places=1)

    def test_shift_history_shows_adjusted_expected_cash_and_variance(self):
        self._make_closed_shift(cash=1000, counted=1000)
        self._record_expense(amount='300')
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/shift/history/')
        self.assertEqual(resp.status_code, 200)
        rec = resp.context['rows'][0]['rec']
        self.assertEqual(rec['ad_hoc_expenses'], 300.0)
        # Expected cash 1000 - 300 expense = 700; counted 1000 → variance +300
        self.assertEqual(rec['expected_cash_after_expenses'], 700.0)
        self.assertEqual(rec['variance_after_expenses'], 300.0)
        self.assertEqual(rec['variance'], 0.0)  # original, un-adjusted variance untouched

    def test_shift_history_backdated_expense_only_affects_its_own_day(self):
        """A shift closed TODAY must not be adjusted by an expense dated for
        a DIFFERENT (past) day — even if recorded today."""
        shift = self._make_closed_shift(cash=1000, counted=1000)
        old_date = (timezone.localdate() - timedelta(days=5)).isoformat()
        self._record_expense(amount='999', date=old_date)
        from core.shift_views import _reconcile, _ad_hoc_expense_total_for_shift
        rec = _reconcile(shift)
        self.assertEqual(_ad_hoc_expense_total_for_shift(shift), 0.0)
        self.assertEqual(rec['expected_cash'], 1000.0)

    def test_bar_z_report_shows_day_ad_hoc_expenses(self):
        self._make_closed_shift(cash=1000, counted=1000)
        self._record_expense(amount='250')
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/z-report/')
        self.assertEqual(resp.status_code, 200)
        self.assertEqual(resp.context['day_ad_hoc_expenses'], 250.0)
        # day_expected_cash = 1000 (cash) - 250 (expense) = 750
        self.assertEqual(resp.context['day_expected_cash'], 750.0)

    def test_bar_z_report_backdated_expense_does_not_affect_todays_report(self):
        self._make_closed_shift(cash=1000, counted=1000)
        old_date = (timezone.localdate() - timedelta(days=5)).isoformat()
        self._record_expense(amount='999', date=old_date)
        self.client.force_login(self.owner)
        resp_today = self.client.get('/bar/z-report/')
        self.assertEqual(resp_today.context['day_ad_hoc_expenses'], 0.0)
        self.assertEqual(resp_today.context['day_expected_cash'], 1000.0)
        resp_old = self.client.get('/bar/z-report/', {'date': old_date})
        self.assertEqual(resp_old.context['day_ad_hoc_expenses'], 999.0)

    def test_live_shift_panel_and_close_shift_unaffected_by_same_day_expense(self):
        """Regression lock: _reconcile() itself must stay completely
        untouched — the live in-progress shift panel (active_shift_api) and
        the moment-of-close comparison must keep showing the ORIGINAL,
        un-adjusted expected_cash even when a same-day ad-hoc expense
        exists, per Roy's explicit "should not touch the live drawer"
        instruction. Only Shift History / Z-report (display-time, separate
        helper) fold it in."""
        from core.shift_views import _reconcile
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff,
            opening_float=Decimal('0'), status='OPEN', station='bar',
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('1000'),
            payment_method='cash', created_at=shift.started_at,
        )
        self._record_expense(amount='400')
        rec = _reconcile(shift)
        self.assertEqual(rec['expected_cash'], 1000.0)

        self.client.force_login(self.staff)
        resp = self.client.get('/bar/shift/active/')
        data = resp.json()
        self.assertEqual(data['shift']['expected_cash'], 1000.0)

    def test_bar_z_report_dedup_across_overlapping_shifts_owner_view(self):
        """The DAY-level ad-hoc expense figure must be a single deduped
        query, never summed per-overlapping-shift — mirrors the existing
        day_cash/day_mpesa dedup fix for two staff sharing one till."""
        self._make_closed_shift(cash=500, counted=500, staff=self.staff)
        staff2 = User.objects.create_user(username='adhocrecon_staff2', password='x')
        UserProfile.objects.create(user=staff2, business=self.biz, role='staff')
        self._make_closed_shift(cash=500, counted=500, staff=staff2)
        self._record_expense(amount='300')
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/z-report/')
        # Must be exactly 300 (deduped), not 600 (double-counted across two shifts)
        self.assertEqual(resp.context['day_ad_hoc_expenses'], 300.0)


class PettyCashBackdateTest(TestCase):
    """2026-08-21 live report (Roy, re-entering a two-day paper log — "the
    counter cash backdate plus matumizi is not there on the staff's
    side"): PettyCash.created_at is auto_now_add=True — Django enforces
    this at the DB layer, so it can NEVER be backdated, and the live till
    figures (_reconcile()/till_expected_cash()) correctly keep reading it
    unchanged. PettyCash.date is now settable from the request and
    reconciles ADDITIVELY against Shift History/Z-report for the day it's
    actually dated for — mirroring AdHocExpenseDayReconciliationTest's own
    already-proven pattern exactly, with the one real difference PettyCash
    forces: a same-day (non-backdated) entry is ALREADY counted by
    _reconcile()'s own created_at-based query, so the new fold-in must
    exclude it or double-count."""

    def setUp(self):
        self.biz = Business.objects.create(name='PC Backdate Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='pcbd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='pcbd_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker',
            material_no='PCBD-01', unit='Bottle', selling_price=Decimal('200'),
        )

    def _record_petty_cash(self, user=None, **overrides):
        self.client.force_login(user or self.owner)
        payload = {'amount': '200', 'reason': 'electricity', 'description': '', 'station': 'bar', 'date': ''}
        payload.update(overrides)
        return self.client.post('/petty-cash/record/', payload)

    def _make_closed_shift(self, cash=1000, counted=1000, station='bar', staff=None):
        staff = staff or self.staff
        today_10am = timezone.localtime().replace(hour=10, minute=0, second=0, microsecond=0)
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=staff,
            opening_float=Decimal('0'), status='CLOSED', station=station,
            started_at=today_10am,
            ended_at=today_10am + timedelta(hours=1),
            closing_cash_counted=Decimal(str(counted)),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal(str(cash)),
            payment_method='cash', created_at=shift.started_at,
        )
        return shift

    def _make_petty_cash(self, created_at, **kwargs):
        """PettyCash.created_at is auto_now_add=True — Django silently
        ignores any explicit value passed to .create()/.__init__(), always
        stamping the real "now" instead (the same enforced behaviour this
        whole feature relies on for the live till figures). A test that
        needs to simulate an entry recorded at a SPECIFIC past/different
        real moment must create it normally, then force the timestamp via
        a raw .update() — which bypasses auto_now_add's special-casing
        entirely, unlike .save()/.create()."""
        entry = PettyCash.objects.create(**kwargs)
        PettyCash.objects.filter(id=entry.id).update(created_at=created_at)
        entry.refresh_from_db()
        return entry

    def test_staff_can_record_a_backdated_entry(self):
        old_date = (timezone.localdate() - timedelta(days=2)).isoformat()
        resp = self._record_petty_cash(user=self.staff, amount='150', date=old_date)
        self.assertTrue(resp.json()['ok'], resp.json())
        entry = PettyCash.objects.get(business=self.biz)
        self.assertEqual(entry.date.isoformat(), old_date)
        self.assertEqual(entry.recorded_by, self.staff)
        # created_at genuinely cannot be backdated (auto_now_add) — it's
        # the real moment this was entered, always "now".
        self.assertGreater(entry.created_at, timezone.now() - timedelta(minutes=5))

    def test_no_date_param_defaults_to_today(self):
        resp = self._record_petty_cash(amount='100')
        self.assertTrue(resp.json()['ok'])
        entry = PettyCash.objects.get(business=self.biz)
        self.assertEqual(entry.date, timezone.localdate())

    def test_future_date_falls_back_to_today_not_blocked(self):
        future = (timezone.localdate() + timedelta(days=3)).isoformat()
        resp = self._record_petty_cash(amount='100', date=future)
        self.assertTrue(resp.json()['ok'])
        entry = PettyCash.objects.get(business=self.biz)
        self.assertEqual(entry.date, timezone.localdate())

    def test_backdated_total_for_shift_excludes_already_counted_same_day_entry(self):
        from core.shift_views import _backdated_petty_cash_total_for_shift
        shift = self._make_closed_shift()
        # Recorded live, during the shift's own window — already counted by
        # _reconcile()'s own created_at-based query; must NOT double-count.
        self._make_petty_cash(
            shift.started_at + timedelta(minutes=5),
            business=self.biz, amount=Decimal('120'), reason='fuel', station='bar',
            recorded_by=self.staff, status='approved', date=timezone.localdate(),
        )
        self.assertAlmostEqual(_backdated_petty_cash_total_for_shift(shift), 0.0, places=1)

    def test_backdated_total_for_shift_counts_a_genuinely_backdated_entry(self):
        from core.shift_views import _backdated_petty_cash_total_for_shift
        shift = self._make_closed_shift()
        # Dated for the shift's own day, but recorded at a real, LATER
        # moment (well after the shift's own window) — the genuine
        # backdated-catch-up case.
        self._make_petty_cash(
            shift.ended_at + timedelta(hours=3),
            business=self.biz, amount=Decimal('180'), reason='fuel', station='bar',
            recorded_by=self.staff, status='approved',
            date=timezone.localtime(shift.started_at).date(),
        )
        self.assertAlmostEqual(_backdated_petty_cash_total_for_shift(shift), 180.0, places=1)

    def test_pending_or_rejected_backdated_entry_not_counted(self):
        from core.shift_views import _backdated_petty_cash_total_for_shift
        shift = self._make_closed_shift()
        for status in ('pending', 'rejected'):
            self._make_petty_cash(
                shift.ended_at + timedelta(hours=3),
                business=self.biz, amount=Decimal('999'), reason='fuel', station='bar',
                recorded_by=self.staff, status=status,
                date=timezone.localtime(shift.started_at).date(),
            )
        self.assertAlmostEqual(_backdated_petty_cash_total_for_shift(shift), 0.0, places=1)

    def test_backdated_entry_for_a_different_day_excluded(self):
        from core.shift_views import _backdated_petty_cash_total_for_shift
        shift = self._make_closed_shift()
        old_day = timezone.localtime(shift.started_at).date() - timedelta(days=10)
        self._make_petty_cash(
            shift.ended_at + timedelta(hours=3),
            business=self.biz, amount=Decimal('999'), reason='fuel', station='bar',
            recorded_by=self.staff, status='approved', date=old_day,
        )
        self.assertAlmostEqual(_backdated_petty_cash_total_for_shift(shift), 0.0, places=1)

    def test_shift_history_shows_adjusted_expected_cash_for_backdated_entry(self):
        shift = self._make_closed_shift(cash=1000, counted=1000)
        self._make_petty_cash(
            shift.ended_at + timedelta(hours=3),
            business=self.biz, amount=Decimal('300'), reason='fuel', station='bar',
            recorded_by=self.staff, status='approved',
            date=timezone.localtime(shift.started_at).date(),
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/shift/history/')
        rec = resp.context['rows'][0]['rec']
        self.assertEqual(rec['backdated_petty_cash'], 300.0)
        # Expected cash 1000 - 300 backdated petty cash = 700; counted 1000 → variance +300
        self.assertEqual(rec['expected_cash_after_expenses'], 700.0)
        self.assertEqual(rec['variance_after_expenses'], 300.0)
        self.assertEqual(rec['variance'], 0.0)  # original, un-adjusted variance untouched

    def test_bar_z_report_shows_day_backdated_petty_cash(self):
        # A real backdated-catch-up scenario needs a shift from a PAST day
        # (staff catching up TODAY on a shift that closed yesterday) — an
        # entry dated for TODAY but genuinely created a few hours later
        # SAME day (as in the per-shift tests above) is correctly treated
        # as an ordinary same-day entry at the DAY level (already counted
        # by day_petty_cash's own created_at__range=today query), not a
        # backdated one — the day-level window is the WHOLE day, wider
        # than any one shift's own narrow segment.
        past_day = timezone.localdate() - timedelta(days=1)
        past_10am = timezone.make_aware(
            timezone.datetime.combine(past_day, timezone.datetime.min.time().replace(hour=10))
        )
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff,
            opening_float=Decimal('0'), status='CLOSED', station='bar',
            started_at=past_10am, ended_at=past_10am + timedelta(hours=1),
            closing_cash_counted=Decimal('1000'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('1000'),
            payment_method='cash', created_at=shift.started_at,
        )
        # Recorded normally TODAY (created_at naturally defaults to now —
        # no forcing needed) but dated for YESTERDAY, the real catch-up shape.
        PettyCash.objects.create(
            business=self.biz, amount=Decimal('250'), reason='fuel', station='bar',
            recorded_by=self.staff, status='approved', date=past_day,
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/z-report/', {'date': past_day.isoformat()})
        self.assertEqual(resp.context['day_backdated_petty_cash'], 250.0)
        self.assertEqual(resp.context['day_expected_cash'], 750.0)
        # Today's OWN report must show none of it.
        resp_today = self.client.get('/bar/z-report/')
        self.assertEqual(resp_today.context['day_backdated_petty_cash'], 0.0)

    def test_live_shift_panel_and_close_shift_unaffected_by_backdated_entry(self):
        """Regression lock, same contract as ad-hoc expenses: _reconcile()
        itself (the live in-progress panel + moment-of-close comparison)
        must stay completely untouched by a genuinely backdated entry."""
        from core.shift_views import _reconcile
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff,
            opening_float=Decimal('0'), status='OPEN', station='bar',
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('1000'),
            payment_method='cash', created_at=shift.started_at,
        )
        self._make_petty_cash(
            timezone.now() - timedelta(days=1),
            business=self.biz, amount=Decimal('400'), reason='fuel', station='bar',
            recorded_by=self.staff, status='approved',
            date=timezone.localtime(shift.started_at).date(),
        )
        rec = _reconcile(shift)
        self.assertEqual(rec['expected_cash'], 1000.0)
        self.client.force_login(self.staff)
        resp = self.client.get('/bar/shift/active/')
        data = resp.json()
        self.assertEqual(data['shift']['expected_cash'], 1000.0)


class AdHocExpenseEditRecoverTest(TestCase):
    """2026-08-09, same-day follow-up (Roy): "can i recover a counter cash
    entry placed on a wrong date mistakenly" — confirmed this means the
    ad-hoc expense (Matumizi) tool. edit_ad_hoc_expense() lets an
    owner/manager correct an already-recorded entry (most often its date);
    ad_hoc_expenses_list() is how the entry is found in the first place.
    No separate "recompute" step is needed for Shift History/Z-report to
    pick up the correction — both already read BusinessExpense fresh on
    every render (see the AdHocExpenseDayReconciliationTest class above)."""

    def setUp(self):
        import uuid
        self.biz = Business.objects.create(name='Ad Hoc Edit Biz')
        self.owner = User.objects.create_user(username='adhocedit_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='adhocedit_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.staff = User.objects.create_user(username='adhocedit_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='staff')
        self.client.force_login(self.owner)
        wrong_date = (timezone.localdate() - timedelta(days=3)).isoformat()
        resp = self.client.post('/expenses/record/', {
            'amount': '500', 'description': 'Firewood', 'category': 'supplies',
            'station': 'bar', 'date': wrong_date, 'notes': '',
            'idempotency_token': str(uuid.uuid4()),
        })
        self.expense_id = resp.json()['expense']['id']
        self.wrong_date = wrong_date

    def test_owner_can_correct_the_date(self):
        real_date = (timezone.localdate() - timedelta(days=1)).isoformat()
        resp = self.client.post(f'/expenses/{self.expense_id}/edit/', {
            'amount': '500', 'description': 'Firewood', 'category': 'supplies',
            'station': 'bar', 'date': real_date, 'notes': '',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        expense = BusinessExpense.objects.get(id=self.expense_id)
        self.assertEqual(expense.date.isoformat(), real_date)

    def test_editing_moves_it_between_days_reconciliation(self):
        """The literal point of the feature: after correcting the date, the
        entry disappears from the WRONG day's Z-report and appears on the
        CORRECT day's — with zero extra action, since both reports read
        BusinessExpense fresh on every render."""
        real_date = (timezone.localdate() - timedelta(days=1)).isoformat()
        self.client.post(f'/expenses/{self.expense_id}/edit/', {
            'amount': '500', 'description': 'Firewood', 'category': 'supplies',
            'station': 'bar', 'date': real_date, 'notes': '',
        })
        resp_wrong = self.client.get('/bar/z-report/', {'date': self.wrong_date})
        resp_right = self.client.get('/bar/z-report/', {'date': real_date})
        self.assertEqual(resp_wrong.context['day_ad_hoc_expenses'], 0.0)
        self.assertEqual(resp_right.context['day_ad_hoc_expenses'], 500.0)

    def test_manager_can_edit(self):
        self.client.force_login(self.manager)
        resp = self.client.post(f'/expenses/{self.expense_id}/edit/', {
            'amount': '600', 'description': 'Firewood', 'category': 'supplies',
            'station': 'bar', 'date': self.wrong_date, 'notes': '',
        })
        self.assertTrue(resp.json()['ok'])

    def test_plain_staff_blocked(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/expenses/{self.expense_id}/edit/', {
            'amount': '600', 'description': 'X', 'category': 'other',
            'station': 'bar', 'date': self.wrong_date, 'notes': '',
        })
        self.assertEqual(resp.status_code, 302)
        expense = BusinessExpense.objects.get(id=self.expense_id)
        self.assertEqual(expense.amount, Decimal('500'))

    def test_cross_business_expense_not_editable(self):
        other_biz = Business.objects.create(name='Other Biz')
        other_owner = User.objects.create_user(username='adhocedit_other', password='x')
        UserProfile.objects.create(user=other_owner, business=other_biz, role='owner')
        self.client.force_login(other_owner)
        resp = self.client.post(f'/expenses/{self.expense_id}/edit/', {
            'amount': '999', 'description': 'X', 'category': 'other',
            'station': 'bar', 'date': self.wrong_date, 'notes': '',
        })
        self.assertEqual(resp.status_code, 404)
        expense = BusinessExpense.objects.get(id=self.expense_id)
        self.assertEqual(expense.amount, Decimal('500'))

    def test_invalid_amount_rejected_leaves_original_unchanged(self):
        resp = self.client.post(f'/expenses/{self.expense_id}/edit/', {
            'amount': '0', 'description': 'Firewood', 'category': 'supplies',
            'station': 'bar', 'date': self.wrong_date, 'notes': '',
        })
        self.assertFalse(resp.json()['ok'])
        expense = BusinessExpense.objects.get(id=self.expense_id)
        self.assertEqual(expense.amount, Decimal('500'))

    def test_future_date_falls_back_to_existing_date_not_today(self):
        """Distinct from record's own fallback (which falls back to TODAY) —
        an edit that submits a bad/future date must not silently move an
        otherwise-correct entry to today; it keeps the entry's own existing
        date instead."""
        future_date = (timezone.localdate() + timedelta(days=5)).isoformat()
        resp = self.client.post(f'/expenses/{self.expense_id}/edit/', {
            'amount': '700', 'description': 'Firewood', 'category': 'supplies',
            'station': 'bar', 'date': future_date, 'notes': '',
        })
        self.assertTrue(resp.json()['ok'])
        expense = BusinessExpense.objects.get(id=self.expense_id)
        self.assertEqual(expense.date.isoformat(), self.wrong_date)
        self.assertEqual(expense.amount, Decimal('700'))

    def test_list_scoped_to_station_and_date(self):
        resp = self.client.get('/expenses/list/', {'station': 'bar', 'date': self.wrong_date})
        data = resp.json()
        self.assertEqual(len(data['expenses']), 1)
        self.assertEqual(data['expenses'][0]['id'], self.expense_id)

    def test_list_empty_for_wrong_station(self):
        resp = self.client.get('/expenses/list/', {'station': 'kitchen', 'date': self.wrong_date})
        self.assertEqual(resp.json()['expenses'], [])

    def test_list_blocked_for_plain_staff(self):
        # 2026-08-21: ad_hoc_expenses_list() was decorator-driven (302
        # redirect) — now an inline, JSON-friendly check (empty list, 200)
        # matching the widened can_record_expenses delegation, same as
        # record_ad_hoc_expense's own docstring explains.
        self.client.force_login(self.staff)
        resp = self.client.get('/expenses/list/', {'station': 'bar', 'date': self.wrong_date})
        self.assertEqual(resp.status_code, 200)
        self.assertEqual(resp.json()['expenses'], [])


class KitchenBoardRevenueConfirmedCreditSplitTest(TestCase):
    """2026-08-09 live report (Roy, Monsoon Inn): the "🍽 Leo" header tile
    on Kitchen Board showed KES 2550 while the currently-open shift's own
    cash/mpesa were both KES 0 — "i have not [rung/confirmed] today's
    entries so that amount is inaccurate". Root cause: kitchen_board()'s
    kitchen_revenue_today blended cash+mpesa+credit into one number with
    no distinction — the same "confirmed vs unpaid revenue" conflation bug
    already fixed elsewhere (daily_sales, home, stock_list, close-shift
    result panel) on 2026-07-31, but never extended to this specific tile
    (a genuinely separate code path that never calls _reconcile())."""

    def setUp(self):
        self.biz = Business.objects.create(name='Kitchen Revenue Split Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='kbrev_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='KBREV-01', unit='Plate', selling_price=Decimal('100'),
        )
        self.client.force_login(self.owner)

    def _make_txn(self, payment_method, amount='100', invoice_no=''):
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal(amount),
            payment_method=payment_method, date=timezone.localdate(),
            invoice_no=invoice_no,
        )

    def test_svq_corrective_transaction_excluded_from_leo(self):
        """2026-08-09, same-day follow-up: a second, independent gap in the
        same query — a stock-take variance-accept's corrective cash/mpesa
        transaction (tagged invoice_no='[SVQ]') was never excluded here,
        unlike every other 'today's revenue' surface in the app (home(),
        the dashboard poll, the revenue-target bar, _reconcile()). A same-
        day stock count correction must never look like a real sale."""
        self._make_txn('cash', '400')
        self._make_txn('cash', '2150', invoice_no='[SVQ]')
        resp = self.client.get('/kitchen/')
        self.assertEqual(resp.context['kitchen_revenue_today'], Decimal('400'))

    def test_svq_corrective_transaction_excluded_from_stats_api(self):
        self._make_txn('cash', '400')
        self._make_txn('mpesa', '2150', invoice_no='[SVQ]')
        resp = self.client.get('/kitchen/stats/')
        self.assertEqual(resp.json()['revenue_today'], 400.0)

    def test_credit_excluded_from_leo_headline(self):
        self._make_txn('cash', '400')
        self._make_txn('credit', '2150')  # matches the live report's shape
        resp = self.client.get('/kitchen/')
        self.assertEqual(resp.context['kitchen_revenue_today'], Decimal('400'))
        self.assertEqual(resp.context['kitchen_revenue_credit'], Decimal('2150'))

    def test_no_credit_leaves_leo_unchanged(self):
        self._make_txn('cash', '300')
        self._make_txn('mpesa', '200')
        resp = self.client.get('/kitchen/')
        self.assertEqual(resp.context['kitchen_revenue_today'], Decimal('500'))
        self.assertEqual(resp.context['kitchen_revenue_credit'], Decimal('0'))

    def test_credit_badge_hidden_when_zero(self):
        self._make_txn('cash', '100')
        resp = self.client.get('/kitchen/')
        body = resp.content.decode()
        self.assertIn('display:none;', body.split('kb-revenue-credit-badge')[1][:200])

    def test_credit_badge_shown_when_present(self):
        self._make_txn('credit', '2150')
        resp = self.client.get('/kitchen/')
        body = resp.content.decode()
        self.assertIn('KES 2150', body)

    def test_kitchen_stats_api_matches_split(self):
        self._make_txn('cash', '400')
        self._make_txn('credit', '2150')
        resp = self.client.get('/kitchen/stats/')
        data = resp.json()
        self.assertEqual(data['revenue_today'], 400.0)
        self.assertEqual(data['revenue_credit'], 2150.0)

    def test_void_still_excluded(self):
        self._make_txn('cash', '500')
        self._make_txn('void', '999')
        resp = self.client.get('/kitchen/')
        self.assertEqual(resp.context['kitchen_revenue_today'], Decimal('500'))


class KitchenStockReceiptRevenuePrecisionTest(TestCase):
    """2026-08-09 — total_revenue() is the plain, original item-level match:
    any Issue-type sale of an item this receipt received counts toward its
    Mapato, regardless of which preset (if any) the sale went through.

    History: a same-day attempt narrowed this to per-preset attribution
    (only count sales of the exact preset a receipt line covers, e.g. "Full
    Chicken Leg" vs "Wing" on the same shared Kuku item) plus a preset=None
    historical-sale fallback, chasing a real precision problem. It never
    fully resolved what Roy was seeing and added complexity during an
    already long session — reverted back to this simple form the same day
    per Roy's own explicit call: "if you can't fix the receipt issue based
    on the recordings of previous days when it comes to stock count and
    sales, just leave it be." Known, accepted limitation: a stock-count
    correction (Rekebisha) never creates revenue here — Rekebisha has no
    concept of a selling price, only a physical count.

    Also covers the reopen() safety net for a receipt closed before all its
    sales were rung up."""

    def setUp(self):
        self.biz = Business.objects.create(name='KSR Precision Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='ksrprec_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='ksrprec_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='kitchen')
        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='KSRPREC-01', unit='Pcs', selling_price=Decimal('0'),
        )
        self.full_leg = ItemPortionPreset.objects.create(
            item=self.kuku, label='Full Chicken Leg', price=Decimal('250'), quantity_consumed=Decimal('1'),
        )
        self.wing = ItemPortionPreset.objects.create(
            item=self.kuku, label='Wing', price=Decimal('70'), quantity_consumed=Decimal('0.125'),
        )
        self.client.force_login(self.owner)
        self.receipt = KitchenStockReceipt.objects.create(business=self.biz, store=self.store)
        KitchenStockReceiptLine.objects.create(
            receipt=self.receipt, item=self.kuku, preset=self.full_leg,
            qty_received=Decimal('23'), line_cost=Decimal('3700'),
        )

    def _sell(self, preset, amount, invoice_no=''):
        Transaction.objects.create(
            business=self.biz, item=self.kuku, preset=preset, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal(amount),
            payment_method='cash', invoice_no=invoice_no,
            created_at=timezone.now(),
        )

    def test_any_preset_sale_of_the_item_counts(self):
        """Item-level match: a Wing sale counts toward the receipt just
        like a Full Chicken Leg sale does — both are the same shared item,
        and this receipt covers the item, not one specific preset."""
        self._sell(self.wing, '70')
        self.assertEqual(self.receipt.total_revenue(), Decimal('70'))

    def test_matching_preset_sale_counted(self):
        self._sell(self.full_leg, '250')
        self.assertEqual(self.receipt.total_revenue(), Decimal('250'))

    def test_no_preset_historical_sale_still_counted(self):
        self._sell(None, '250')
        self.assertEqual(self.receipt.total_revenue(), Decimal('250'))

    def test_plain_item_line_counts_every_preset(self):
        """A line with NO preset (plain item, no per-cut cost split) keeps
        the original behaviour — every sale of that item counts, regardless
        of which preset (if any) it went through."""
        plain_item = Item.objects.create(
            business=self.biz, store=self.store, description='Smokie',
            material_no='KSRPREC-02', unit='Pcs', selling_price=Decimal('30'),
        )
        plain_receipt = KitchenStockReceipt.objects.create(business=self.biz, store=self.store)
        KitchenStockReceiptLine.objects.create(
            receipt=plain_receipt, item=plain_item, preset=None,
            qty_received=Decimal('10'), line_cost=Decimal('200'),
        )
        Transaction.objects.create(
            business=self.biz, item=plain_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('30'),
            payment_method='cash', created_at=timezone.now(),
        )
        self.assertEqual(plain_receipt.total_revenue(), Decimal('30'))

    def test_reopen_extends_window_for_new_sales(self):
        """The literal live scenario: a receipt closed while it still
        showed KES 0 revenue must be able to earn real sales again once
        reopened."""
        self.receipt.close(self.owner)
        self.assertEqual(self.receipt.status, 'DONE')
        self.assertIsNotNone(self.receipt.closed_at)
        # A sale made AFTER close must not count while still closed.
        self._sell(self.full_leg, '250')
        self.assertEqual(self.receipt.total_revenue(), Decimal('0'))

        self.receipt.reopen()
        self.receipt.refresh_from_db()
        self.assertEqual(self.receipt.status, 'OPEN')
        self.assertIsNone(self.receipt.closed_at)
        self.assertIsNone(self.receipt.closed_by)
        # Now the same sale (already recorded, still within [created_at, now])
        # counts, since the window extends to now() again.
        self.assertEqual(self.receipt.total_revenue(), Decimal('250'))

    def test_reopen_already_open_is_noop(self):
        self.receipt.reopen()
        self.assertEqual(self.receipt.status, 'OPEN')

    def test_backdated_sale_before_created_at_but_after_received_on_now_counts(self):
        """2026-08-11 live report (Roy), confirmed via the hidden-presets
        diagnostic: a receipt he'd just typed in showed KES 0 Mapato despite
        32.5 units of genuinely recorded backdated sales — because the old
        window floor was created_at (the moment the RECEIPT ROW was typed
        in, always "now"), and a catch-up posting's whole point is a
        created_at pointing to BEFORE that. The literal reported scenario:
        receipt typed in today, sale backdated to yesterday (still on/after
        received_on, which also defaults to today here) — must now count."""
        yesterday = timezone.now() - timedelta(days=1)
        Transaction.objects.create(
            business=self.biz, item=self.kuku, preset=self.full_leg, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('250'),
            payment_method='cash', created_at=yesterday,
        )
        # received_on defaults to today; yesterday's backdated sale is BEFORE
        # the receipt's own created_at (also "now") but must still count
        # because it's on/after received_on's own start-of-day... except
        # here received_on IS today, so tighten the receipt's received_on
        # to genuinely predate the sale, matching the real live scenario
        # (delivery arrived a few days ago, sales backdated to catch up).
        self.receipt.received_on = (timezone.now() - timedelta(days=3)).date()
        self.receipt.save(update_fields=['received_on'])
        self.assertEqual(self.receipt.total_revenue(), Decimal('250'))

    def test_sale_genuinely_before_received_on_does_not_count(self):
        """A sale dated before the stock this receipt covers ever physically
        arrived cannot be a sale of THIS delivery — correctly excluded."""
        self.receipt.received_on = timezone.localdate()
        self.receipt.save(update_fields=['received_on'])
        before_delivery = timezone.now() - timedelta(days=5)
        Transaction.objects.create(
            business=self.biz, item=self.kuku, preset=self.full_leg, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('250'),
            payment_method='cash', created_at=before_delivery,
        )
        self.assertEqual(self.receipt.total_revenue(), Decimal('0'))

    def test_reopen_view_owner_only(self):
        self.receipt.close(self.owner)
        resp = self.client.post(f'/kitchen/stock-receipt/{self.receipt.id}/reopen/')
        self.assertTrue(resp.json()['ok'], resp.json())
        self.receipt.refresh_from_db()
        self.assertEqual(self.receipt.status, 'OPEN')

    def test_reopen_view_blocks_plain_staff(self):
        self.receipt.close(self.owner)
        self.client.force_login(self.staff)
        resp = self.client.post(f'/kitchen/stock-receipt/{self.receipt.id}/reopen/')
        self.assertEqual(resp.status_code, 403)
        self.receipt.refresh_from_db()
        self.assertEqual(self.receipt.status, 'DONE')

    def test_reopen_view_cross_business_rejected(self):
        other_biz = Business.objects.create(name='Other KSR Biz')
        other_owner = User.objects.create_user(username='ksrprec_other', password='x')
        UserProfile.objects.create(user=other_owner, business=other_biz, role='owner')
        self.receipt.close(self.owner)
        self.client.force_login(other_owner)
        resp = self.client.post(f'/kitchen/stock-receipt/{self.receipt.id}/reopen/')
        self.assertEqual(resp.status_code, 404)
        self.receipt.refresh_from_db()
        self.assertEqual(self.receipt.status, 'DONE')


class EditRawMaterialCostTest(TestCase):
    """2026-08-09 live report (Roy): "the pencil icon is directing me to
    the add transaction, that is bogus... it represents the 6 buckets
    equivalent to a whole sack division, it is easier that way" — a
    direct sack-cost ÷ units-per-sack entry for a raw-material-source
    item's own cost_price, replacing the old hand-off to Add Transaction."""

    def setUp(self):
        _make_kitchen_setup(self, biz_suffix='rawcost')
        self.raw_item = Item.objects.create(
            business=self.biz, store=self.store, description='Raw Potatoes',
            unit='Ndoo', material_no='RAWCOST-01', cost_price=Decimal('0'),
            opening_bin_balance=6,
        )
        self.item.raw_material_source = self.raw_item
        self.item.save(update_fields=['raw_material_source'])
        self.staff_user = User.objects.create_user(username='rawcost_staff', password='x')
        UserProfile.objects.create(user=self.staff_user, business=self.biz, role='kitchen')
        self.client.force_login(self.owner_user)

    def _edit(self, sack_cost='1200', units_per_sack='6', item_id=None):
        return self.client.post(
            f'/kitchen/item/{item_id or self.raw_item.id}/edit-raw-cost/',
            {'sack_cost': sack_cost, 'units_per_sack': units_per_sack},
        )

    def test_divides_sack_cost_by_units_per_sack(self):
        resp = self._edit(sack_cost='1200', units_per_sack='6')
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertEqual(data['item']['cost_price'], 200.0)
        self.raw_item.refresh_from_db()
        self.assertEqual(self.raw_item.cost_price, Decimal('200.00'))

    def _open_batch_at_placeholder_cost(self, draw_qty='4'):
        """open_batch() rejects a literal 0 cost outright — Roy's real
        scenario is a wrong/placeholder cost entered before the real sack
        price was known (e.g. KES 10/Ndoo, a guess), not literally unset."""
        self.raw_item.cost_price = Decimal('10')
        self.raw_item.save(update_fields=['cost_price'])
        return KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.item,
            recorded_by=self.owner_user, draw_qty=Decimal(draw_qty),
        )

    def test_correcting_cost_retroactively_updates_open_batch(self):
        """2026-08-09, same-day follow-up (Roy): "i had not put in the cost
        price for the gunia before, i put it just a few moments ago...
        i expected it to adjust in a certain way, not to stay the way it
        was before" — a batch already drawn BEFORE the correction (at the
        old, wrong placeholder raw cost) must have its own cost_total (and
        therefore its Faida) retroactively recomputed, not stay frozen."""
        batch = self._open_batch_at_placeholder_cost()
        self.assertEqual(batch.cost_total, Decimal('40.00'))  # 4 × 10 (placeholder)

        resp = self._edit(sack_cost='1200', units_per_sack='6')  # → KES 200/Ndoo
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertIn(self.item.description, resp.json()['updated_batches'])

        batch.refresh_from_db()
        self.assertEqual(batch.cost_total, Decimal('800.00'))  # 4 Ndoo × 200
        self.item.refresh_from_db()
        self.assertEqual(self.item.cost_price, Decimal('800.00'))

    def test_correction_never_touches_revenue_collected(self):
        """Only cost_total changes — revenue_collected reflects real sales
        and must be completely unaffected by a cost correction."""
        batch = self._open_batch_at_placeholder_cost()
        batch.record_sale(Decimal('500'), payment_method='cash', recorded_by=self.owner_user)
        self._edit(sack_cost='1200', units_per_sack='6')
        batch.refresh_from_db()
        self.assertEqual(batch.revenue_collected, Decimal('500'))

    def test_closed_batch_not_retroactively_updated(self):
        """A CLOSED batch's cost_total is historical record — only OPEN
        batches (still selling, still representing a live decision) get
        the retroactive correction."""
        batch = self._open_batch_at_placeholder_cost()
        batch.status = 'DEPLETED'
        batch.save(update_fields=['status'])
        self._edit(sack_cost='1200', units_per_sack='6')
        batch.refresh_from_db()
        self.assertEqual(batch.cost_total, Decimal('40.00'))

    def test_batch_with_no_open_batches_reports_none_updated(self):
        resp = self._edit(sack_cost='1200', units_per_sack='6')
        self.assertEqual(resp.json()['updated_batches'], [])

    def test_future_kitchen_batch_draws_use_corrected_cost(self):
        """The whole point: fixing THIS item's cost_price makes the next
        KitchenBatch draw price correctly, with zero further action."""
        self._edit(sack_cost='1200', units_per_sack='6')
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.item,
            recorded_by=self.owner_user, draw_qty=Decimal('2'),
        )
        self.assertEqual(batch.cost_total, Decimal('400.00'))

    def test_rejects_item_that_is_not_a_raw_material_source(self):
        plain_item = Item.objects.create(
            business=self.biz, store=self.store, description='Smokie',
            material_no='RAWCOST-02', unit='Pcs', selling_price=Decimal('30'),
        )
        resp = self._edit(item_id=plain_item.id)
        self.assertEqual(resp.status_code, 400)
        plain_item.refresh_from_db()
        self.assertEqual(plain_item.cost_price, None)

    def test_invalid_amount_rejected(self):
        resp = self._edit(sack_cost='0', units_per_sack='6')
        self.assertEqual(resp.status_code, 400)
        resp2 = self._edit(sack_cost='1200', units_per_sack='0')
        self.assertEqual(resp2.status_code, 400)
        resp3 = self._edit(sack_cost='not-a-number', units_per_sack='6')
        self.assertEqual(resp3.status_code, 400)

    def test_plain_staff_blocked(self):
        self.client.force_login(self.staff_user)
        resp = self._edit()
        self.assertEqual(resp.status_code, 403)
        self.raw_item.refresh_from_db()
        self.assertEqual(self.raw_item.cost_price, Decimal('0'))

    def test_cross_business_item_rejected(self):
        other_biz = Business.objects.create(name='Other Rawcost Biz')
        other_owner = User.objects.create_user(username='rawcost_other', password='x')
        UserProfile.objects.create(user=other_owner, business=other_biz, role='owner')
        self.client.force_login(other_owner)
        resp = self._edit()
        self.assertEqual(resp.status_code, 404)
        self.raw_item.refresh_from_db()
        self.assertEqual(self.raw_item.cost_price, Decimal('0'))

    def _kitchen_batches_blob(self, body):
        import json as _json
        start = body.index('var _kitchenBatches')
        eq = body.index('=', start)
        end = body.index(';\n', eq)
        return _json.loads(body[eq + 1:end].strip())

    def test_pre_link_batch_stays_editable_regardless_of_later_item_link(self):
        """2026-08-09 live report (Roy): "i did tap the edit icon in the raw
        potatoes tiles and input the cost but nothing changed." Root cause:
        the batch tile's own 'Hariri Gharama' button was hiding itself
        based on the ITEM's CURRENT raw_material_source setting, not on
        whether THIS SPECIFIC batch was actually opened via a linked draw.
        A batch opened BEFORE the raw-material link existed has
        source_item_id=None (from_draw=False) forever — _batch_to_dict
        must keep reporting that accurately even after the item is later
        linked, and the manual per-batch editor must stay reachable for
        exactly that batch."""
        self.item.raw_material_source = None
        self.item.save(update_fields=['raw_material_source'])
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.item,
            recorded_by=self.owner_user, cost_total=Decimal('500'),
        )
        self.item.raw_material_source = self.raw_item
        self.item.save(update_fields=['raw_material_source'])

        resp = self.client.get('/kitchen/')
        batches = self._kitchen_batches_blob(resp.content.decode())
        chipo = next(b for b in batches if b['id'] == self.item.id)
        ob = chipo['open_batches'][0]
        self.assertEqual(ob['id'], batch.id)
        self.assertFalse(ob['from_draw'], "batch predates the raw-material link")

        # edit_raw_material_cost() correctly cannot reach this batch.
        edit_resp = self._edit(sack_cost='1200', units_per_sack='6')
        self.assertTrue(edit_resp.json()['ok'], edit_resp.json())
        self.assertNotIn(self.item.description, edit_resp.json()['updated_batches'])
        batch.refresh_from_db()
        self.assertEqual(batch.cost_total, Decimal('500.00'), "unreachable via the raw-item edit")

        # But the manual per-batch editor still works for this exact batch.
        manual_resp = self.client.post(
            f'/kitchen/batch/{batch.id}/edit-target/', {'cost_total': '600'},
        )
        self.assertTrue(manual_resp.json()['ok'], manual_resp.json())
        batch.refresh_from_db()
        self.assertEqual(batch.cost_total, Decimal('600.00'))

    def test_linked_batch_from_draw_true(self):
        """The positive case: a batch opened via a real linked draw reports
        from_draw=True, correctly hiding the manual editor in favor of
        correcting the raw item's own cost."""
        batch = self._open_batch_at_placeholder_cost()
        resp = self.client.get('/kitchen/')
        batches = self._kitchen_batches_blob(resp.content.decode())
        chipo = next(b for b in batches if b['id'] == self.item.id)
        ob = chipo['open_batches'][0]
        self.assertEqual(ob['id'], batch.id)
        self.assertTrue(ob['from_draw'])


class KitchenStockReceiptRawMaterialForTest(TestCase):
    """2026-08-12 live report (Roy): "ensure the chipo receipt tracks sales
    as well, as you can see I have sold on it and it has reflected in the
    tile but not in the receipt." A raw-material receipt (Raw Potatoes)
    always shows Mapato KES 0 — CORRECTLY, since the raw item itself is
    never sold directly, only drawn into a batch. _kitchen_stock_receipt_to_
    dict() now surfaces the linked finished product's (Chipo) own already-
    correct open-batch figures alongside it, clearly labelled as belonging
    to Chipo — never folded into the receipt's own (always-zero) total."""

    def setUp(self):
        self.biz = Business.objects.create(name='KSR Raw Material Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='ksrraw_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.raw_potatoes = Item.objects.create(
            business=self.biz, store=self.store, description='Raw Potatoes',
            material_no='KSRRAW-RAW', unit='Ndoo', selling_price=Decimal('0'),
            cost_price=Decimal('100'),
        )
        self.chipo = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='KSRRAW-CHIPO', unit='Batch', selling_price=Decimal('100'),
            is_kitchen_batch=True, raw_material_source=self.raw_potatoes,
        )
        self.client.force_login(self.owner)

    def _create_raw_receipt(self, qty='6', cost='680'):
        import json, uuid
        return self.client.post('/kitchen/stock-receipt/create/', {
            'supplier': 'Market', 'invoice_no': '',
            'lines': json.dumps([{'item_id': self.raw_potatoes.id, 'qty': qty, 'cost': cost}]),
            'idempotency_token': str(uuid.uuid4()),
        })

    def test_receipt_with_no_open_batch_has_empty_raw_material_for(self):
        resp = self._create_raw_receipt()
        receipt_id = resp.json()['receipt']['id']
        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        r = next(x for x in listing['open'] if x['id'] == receipt_id)
        self.assertEqual(r['total_revenue'], 0.0, 'A raw material is never sold directly — always 0, correctly')
        self.assertEqual(r['raw_material_for'], [])

    def test_receipt_surfaces_linked_open_batch_revenue(self):
        self._create_raw_receipt()
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.chipo,
            recorded_by=self.owner, draw_qty=Decimal('5'),
        )
        batch.record_sale(Decimal('100'), payment_method='cash')
        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        r = listing['open'][0]
        self.assertEqual(r['total_revenue'], 0.0, 'The receipt\'s OWN total must stay untouched by this')
        self.assertEqual(len(r['raw_material_for']), 1)
        linked = r['raw_material_for'][0]
        self.assertEqual(linked['item_name'], 'Chipo')
        self.assertEqual(linked['open_batch_count'], 1)
        self.assertEqual(linked['cost'], float(batch.cost_total))
        self.assertEqual(linked['revenue'], 100.0)
        self.assertEqual(linked['profit'], 100.0 - float(batch.cost_total))

    def test_closed_batch_now_counted_in_raw_material_for(self):
        """2026-08-21, same-day follow-up (Roy — "how when 5 buckets have
        been sold... each bucket shows the chipo profit"): the original
        "only OPEN batches count" rule silently dropped a sack's own
        already-sold-and-closed history, making a mostly-successful sack
        look like a loss because only its one lagging leftover batch was
        ever shown. Reversed: a DEPLETED batch drawn from this receipt's
        own delivery is now counted too — a depleted batch has real
        recorded profit, not nothing."""
        self._create_raw_receipt()
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.chipo,
            recorded_by=self.owner, draw_qty=Decimal('5'),
        )
        batch.record_sale(Decimal('300'), payment_method='cash')
        batch.deplete()
        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        r = listing['open'][0]
        linked = r['raw_material_for'][0]
        self.assertEqual(linked['batch_count'], 1)
        self.assertEqual(linked['open_batch_count'], 0)
        self.assertEqual(linked['cost'], float(batch.cost_total))
        self.assertEqual(linked['revenue'], 300.0)
        self.assertEqual(linked['profit'], 300.0 - float(batch.cost_total))

    def test_multiple_open_batches_summed_correctly(self):
        """2026-08-12 live report (Roy): the Chipo tile only ever displays
        the NEWEST open batch (open_batches[0]) — the multi-pot case is a
        deliberate, allowed scenario (see KitchenBatchOpenBatchDrawTest), so
        this must never be blocked, but a second still-open batch's own
        cost/revenue was invisible on the tile. raw_material_for must SUM
        across every open batch, not just the newest, so the receipt view
        never silently drops one."""
        self._create_raw_receipt(qty='10', cost='1000')
        batch1 = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.chipo,
            recorded_by=self.owner, draw_qty=Decimal('5'),
        )
        batch1.record_sale(Decimal('100'), payment_method='cash')
        batch2 = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.chipo,
            recorded_by=self.owner, draw_qty=Decimal('3'),
        )
        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        r = listing['open'][0]
        linked = r['raw_material_for'][0]
        self.assertEqual(linked['open_batch_count'], 2)
        self.assertEqual(linked['cost'], float(batch1.cost_total + batch2.cost_total))
        self.assertEqual(linked['revenue'], 100.0, 'Only batch1 has a sale so far')
        self.assertEqual(linked['profit'], 100.0 - float(batch1.cost_total + batch2.cost_total))

    def test_unrelated_item_never_shows_raw_material_for(self):
        soda = Item.objects.create(
            business=self.biz, store=self.store, description='Soda',
            material_no='KSRRAW-SODA', unit='Pcs', selling_price=Decimal('50'),
        )
        import json, uuid
        self.client.post('/kitchen/stock-receipt/create/', {
            'supplier': 'Market', 'invoice_no': '',
            'lines': json.dumps([{'item_id': soda.id, 'qty': '10', 'cost': '400'}]),
            'idempotency_token': str(uuid.uuid4()),
        })
        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        r = listing['open'][0]
        self.assertEqual(r['raw_material_for'], [])

    def test_raw_material_for_reflects_post_split_batch(self):
        """2026-08-16 live follow-up (Roy), right after the Gawanya split
        crash was fixed: "ensure also the respective stock receipt adjusts
        accordingly" — once split_by_date_locked() closes the ORIGINAL
        batch (DEPLETED) and opens a NEW one (OPEN, with its own fresh
        raw-material draw + recomputed cost/revenue), the Stock Receipt
        card's "→ Chipo" cross-reference must reflect BOTH: the now-closed
        original batch's real recorded profit AND the new batch's own
        ongoing figures — updated 2026-08-21 alongside the reversal of the
        old "only OPEN batches count" rule (both batches were drawn from
        the SAME sack/receipt, so both belong in its own total)."""
        resp = self._create_raw_receipt(qty='10', cost='1000')
        from datetime import datetime as _dt
        day1 = timezone.make_aware(_dt(2026, 8, 10, 9, 0))
        # Backdate the receipt itself to before the batch's own draw date —
        # the new receipt-to-receipt windowing (2026-08-21) filters batches
        # by received_on relative to the receipt's own delivery date, so
        # the two must agree for this fixture to still exercise the split
        # mechanic it's actually testing.
        from core.models import KitchenStockReceipt as _KSR
        _KSR.objects.filter(id=resp.json()['receipt']['id']).update(received_on=day1.date())
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.chipo,
            recorded_by=self.owner, draw_qty=Decimal('1'),
            received_on=day1.date(),
        )
        # Two sales before the cutoff (stay on the original, now-closed
        # batch) and one after (belongs to the new split-off batch).
        txn1 = Transaction.objects.create(
            business=self.biz, item=self.chipo, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), kitchen_batch=batch, date=day1.date(),
        )
        Transaction.objects.filter(id=txn1.id).update(created_at=day1 + timedelta(hours=1))
        batch.revenue_collected = Decimal('100')
        batch.save(update_fields=['revenue_collected'])

        pre_split = self.client.get('/kitchen/stock-receipt/list/').json()['open'][0]
        self.assertEqual(pre_split['raw_material_for'][0]['open_batch_count'], 1)
        self.assertEqual(pre_split['raw_material_for'][0]['revenue'], 100.0)

        cutoff = day1 + timedelta(days=1)
        new_txn = Transaction.objects.create(
            business=self.biz, item=self.chipo, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('250'), kitchen_batch=batch, date=cutoff.date(),
        )
        Transaction.objects.filter(id=new_txn.id).update(created_at=cutoff + timedelta(hours=1))

        batches = KitchenBatch.split_by_date_locked(
            batch.id, self.biz, [cutoff], self.owner,
        )
        original, new_batch = batches
        self.assertEqual(original.status, 'DEPLETED')
        self.assertEqual(new_batch.status, 'OPEN')
        self.assertEqual(new_batch.source_item_id, self.raw_potatoes.id)

        post_split = self.client.get('/kitchen/stock-receipt/list/').json()['open'][0]
        linked = post_split['raw_material_for']
        self.assertEqual(len(linked), 1, 'Still one row for Chipo — both batches summed into it')
        self.assertEqual(linked[0]['batch_count'], 2)
        self.assertEqual(linked[0]['open_batch_count'], 1, 'Only the new batch is still OPEN')
        expected_cost = float(original.cost_total + new_batch.cost_total)
        self.assertEqual(linked[0]['cost'], expected_cost)
        self.assertEqual(linked[0]['revenue'], 350.0, "Both batches' revenue — 100 (original) + 250 (new)")
        self.assertEqual(linked[0]['profit'], 350.0 - expected_cost)

    def test_receipt_line_current_balance_tracks_the_whole_gunia_drawdown(self):
        """2026-08-16 live follow-up (Roy): "what about raw potatoes/whole
        gunia tracking from which the chipo is drawn from" — the receipt's
        own KES total is (correctly) the FIXED cost of what was originally
        delivered, never live; the LIVE remaining-balance figure lives on
        each line's current_balance field instead (Item.current_balance()
        sums every real Transaction — the Receipt that brought the gunia
        in, AND every Draw a batch/split has taken from it since — with no
        type filter, so a Draw genuinely depletes it same as a sale would
        for an ordinary item). This locks in that the whole chain actually
        moves the number: receive 6, open one batch (draws 2), split it
        (draws another 2 for the fresh segment) → 2 left, visible on the
        receipt line, not just buried in the item's own stock list."""
        self._create_raw_receipt(qty='6', cost='6800')
        self.assertEqual(self.raw_potatoes.current_balance(), Decimal('6'))

        from datetime import datetime as _dt
        day1 = timezone.make_aware(_dt(2026, 8, 10, 9, 0))
        batch = KitchenBatch.open_batch(
            business=self.biz, store=self.store, item=self.chipo,
            recorded_by=self.owner, draw_qty=Decimal('2'), received_on=day1.date(),
        )
        self.assertEqual(self.raw_potatoes.current_balance(), Decimal('4'))

        cutoff = day1 + timedelta(days=1)
        txn = Transaction.objects.create(
            business=self.biz, item=self.chipo, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), kitchen_batch=batch, date=cutoff.date(),
        )
        Transaction.objects.filter(id=txn.id).update(created_at=cutoff + timedelta(hours=1))
        KitchenBatch.split_by_date_locked(batch.id, self.biz, [cutoff], self.owner)
        self.assertEqual(self.raw_potatoes.current_balance(), Decimal('2'))

        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        line = listing['open'][0]['lines'][0]
        self.assertEqual(line['current_balance'], 2.0)
        self.assertEqual(line['line_cost'], 6800.0, "the receipt's own KES total stays the fixed original delivery")

    def test_is_all_raw_material_flag_true_for_raw_only_receipt(self):
        resp = self._create_raw_receipt()
        receipt_id = resp.json()['receipt']['id']
        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        r = next(x for x in listing['open'] if x['id'] == receipt_id)
        self.assertTrue(r['is_all_raw_material'])
        self.assertTrue(r['lines'][0]['is_raw_material_source'])

    def test_is_all_raw_material_flag_false_for_ordinary_receipt(self):
        import json, uuid
        wing = Item.objects.create(
            business=self.biz, store=self.store, description='Wing',
            material_no='KSRRAW-WING', unit='Pcs', selling_price=Decimal('0'),
        )
        resp = self.client.post('/kitchen/stock-receipt/create/', {
            'supplier': 'Meatco', 'invoice_no': '',
            'lines': json.dumps([{'item_id': wing.id, 'qty': '20', 'cost': '1960'}]),
            'idempotency_token': str(uuid.uuid4()),
        })
        receipt_id = resp.json()['receipt']['id']
        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        r = next(x for x in listing['open'] if x['id'] == receipt_id)
        self.assertFalse(r['is_all_raw_material'])
        self.assertFalse(r['lines'][0]['is_raw_material_source'])

    def test_batch_from_before_this_receipt_excluded(self):
        """The receipt-to-receipt windowing: a batch drawn BEFORE this
        receipt's own delivery date belongs to whichever earlier delivery
        was active then, not this one."""
        from datetime import datetime as _dt
        early_batch = KitchenBatch.objects.create(
            business=self.biz, store=self.store, item=self.chipo,
            source_item_id=self.raw_potatoes.id, cost_total=Decimal('50'),
            revenue_collected=Decimal('80'), status='DEPLETED',
            received_on=_dt(2026, 1, 1).date(),
        )
        resp = self._create_raw_receipt()
        receipt_id = resp.json()['receipt']['id']
        # Re-date the receipt itself to well after the early batch.
        from core.models import KitchenStockReceipt as _KSR
        _KSR.objects.filter(id=receipt_id).update(received_on=_dt(2026, 6, 1).date())
        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        r = next(x for x in listing['open'] if x['id'] == receipt_id)
        self.assertEqual(r['raw_material_for'], [], 'The pre-dated batch belongs to an earlier delivery, not this one')

    def test_batch_from_after_next_receipt_excluded(self):
        """A batch drawn during a LATER delivery's own window must not
        bleed backward into this (earlier, already-superseded) receipt."""
        from datetime import datetime as _dt
        resp = self._create_raw_receipt()
        first_id = resp.json()['receipt']['id']
        from core.models import KitchenStockReceipt as _KSR
        _KSR.objects.filter(id=first_id).update(received_on=_dt(2026, 1, 1).date())

        second_resp = self._create_raw_receipt()
        second_id = second_resp.json()['receipt']['id']
        _KSR.objects.filter(id=second_id).update(received_on=_dt(2026, 2, 1).date())

        KitchenBatch.objects.create(
            business=self.biz, store=self.store, item=self.chipo,
            source_item_id=self.raw_potatoes.id, cost_total=Decimal('50'),
            revenue_collected=Decimal('80'), status='OPEN',
            received_on=_dt(2026, 2, 10).date(),  # after the SECOND receipt
        )
        listing = self.client.get('/kitchen/stock-receipt/list/').json()
        first = next(x for x in listing['closed'] + listing['open'] if x['id'] == first_id)
        second = next(x for x in listing['closed'] + listing['open'] if x['id'] == second_id)
        self.assertEqual(first['raw_material_for'], [], 'The batch belongs to the SECOND delivery, not the first')
        self.assertEqual(len(second['raw_material_for']), 1)
        self.assertEqual(second['raw_material_for'][0]['batch_count'], 1)


class KitchenStockReceiptDeleteTest(TestCase):
    """2026-08-09 live report (Roy): "you have made the previous receipt
    which was a mistake show up, I do not need it" — a mistaken
    KitchenStockReceipt bookkeeping record must be fully removable, WITHOUT
    touching the real stock-adding Transaction its line created."""

    def setUp(self):
        self.biz = Business.objects.create(name='KSR Delete Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='ksrdel_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='ksrdel_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='kitchen')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='KSRDEL-01', unit='Pcs', selling_price=Decimal('0'),
        )
        self.receipt = KitchenStockReceipt.objects.create(business=self.biz, store=self.store)
        self.txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt',
            qty=Decimal('23'), payment_method='cash',
        )
        self.line = KitchenStockReceiptLine.objects.create(
            receipt=self.receipt, item=self.item, qty_received=Decimal('23'),
            line_cost=Decimal('3700'), transaction=self.txn,
        )
        self.client.force_login(self.owner)

    def test_owner_can_delete_receipt(self):
        resp = self.client.post(f'/kitchen/stock-receipt/{self.receipt.id}/delete/')
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertFalse(KitchenStockReceipt.objects.filter(id=self.receipt.id).exists())

    def test_owner_can_delete_a_still_open_receipt(self):
        """2026-08-11 same-day correction (Roy, real duplicate-delivery
        report): the endpoint never required CLOSED status — only the
        frontend button used to hide until a receipt was closed, which
        blocked deleting a genuine duplicate discovered while it's still
        OPEN. Locks in that the backend has always allowed this."""
        self.assertEqual(self.receipt.status, 'OPEN')
        resp = self.client.post(f'/kitchen/stock-receipt/{self.receipt.id}/delete/')
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertFalse(KitchenStockReceipt.objects.filter(id=self.receipt.id).exists())

    def test_delete_never_touches_underlying_transaction_or_stock(self):
        """The whole point: the real stock-adding Transaction must survive,
        so the item's stock balance is completely unaffected."""
        balance_before = self.item.current_balance()
        self.client.post(f'/kitchen/stock-receipt/{self.receipt.id}/delete/')
        self.assertTrue(Transaction.objects.filter(id=self.txn.id).exists())
        self.item.refresh_from_db()
        self.assertEqual(self.item.current_balance(), balance_before)

    def test_delete_removes_lines_too(self):
        self.client.post(f'/kitchen/stock-receipt/{self.receipt.id}/delete/')
        self.assertFalse(KitchenStockReceiptLine.objects.filter(id=self.line.id).exists())

    def test_plain_staff_blocked(self):
        self.client.force_login(self.staff)
        resp = self.client.post(f'/kitchen/stock-receipt/{self.receipt.id}/delete/')
        self.assertEqual(resp.status_code, 403)
        self.assertTrue(KitchenStockReceipt.objects.filter(id=self.receipt.id).exists())

    def test_cross_business_receipt_rejected(self):
        other_biz = Business.objects.create(name='Other KSR Delete Biz')
        other_owner = User.objects.create_user(username='ksrdel_other', password='x')
        UserProfile.objects.create(user=other_owner, business=other_biz, role='owner')
        self.client.force_login(other_owner)
        resp = self.client.post(f'/kitchen/stock-receipt/{self.receipt.id}/delete/')
        self.assertEqual(resp.status_code, 404)
        self.assertTrue(KitchenStockReceipt.objects.filter(id=self.receipt.id).exists())


class KitchenItemResetTest(TestCase):
    """2026-08-11 live request (Roy, Monsoon Inn): a ledger drift on Kuku
    (preset-tracked portion item) and Chipo (KitchenBatch item) that no
    normal correction could untangle — wipe sales/receiving history for
    ONE item since a chosen cutoff, so the owner can re-enter from the
    staff's paper sales book with proper backdating. Mirrors the "Reset
    Sales & Analytics" pattern: backup-first, typed confirmation, atomic,
    logged via SalesResetLog."""

    def setUp(self):
        self.biz = Business.objects.create(name='Kitchen Reset Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='kir_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='kir_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='kitchen')

        # Portion item (Kuku) with a preset-attributed receipt + sales.
        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='KIR-KUKU', unit='Pcs', selling_price=Decimal('0'),
        )
        self.full_leg = ItemPortionPreset.objects.create(
            item=self.kuku, label='Full Chicken Leg', price=Decimal('250'), quantity_consumed=Decimal('1'),
        )
        self.receipt = KitchenStockReceipt.objects.create(
            business=self.biz, store=self.store, supplier='Kamau',
            received_on=timezone.localdate() - timedelta(days=5),
        )
        KitchenStockReceiptLine.objects.create(
            receipt=self.receipt, item=self.kuku, preset=self.full_leg,
            qty_received=Decimal('23'), line_cost=Decimal('3700'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('23'),
            payment_method='cash', created_at=timezone.now() - timedelta(days=5),
        )
        for _i in range(3):
            Transaction.objects.create(
                business=self.biz, item=self.kuku, preset=self.full_leg, type='Issue',
                qty=Decimal('-1'), sale_amount=Decimal('250'), payment_method='cash',
                created_at=timezone.now() - timedelta(days=2),
            )
        # A sale from BEFORE the cutoff — must survive the reset.
        Transaction.objects.create(
            business=self.biz, item=self.kuku, preset=self.full_leg, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('250'), payment_method='cash',
            created_at=timezone.now() - timedelta(days=10),
        )

        # KitchenBatch item (Chipo).
        self.chipo = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='KIR-CHIPO', unit='Batch', selling_price=Decimal('100'),
            is_kitchen_batch=True,
        )
        self.chipo_preset = ItemPortionPreset.objects.create(
            item=self.chipo, label='Ya 100', price=Decimal('100'), quantity_consumed=Decimal('1'),
        )
        self.batch = KitchenBatch.objects.create(
            business=self.biz, store=self.store, item=self.chipo,
            cost_total=Decimal('1000'), status='OPEN',
            received_on=timezone.localdate() - timedelta(days=3), recorded_by=self.owner,
        )
        self.batch.record_sale(Decimal('100'), payment_method='cash', preset=self.chipo_preset)

        self.client.force_login(self.owner)

    def _cutoff(self, days_ago):
        return (timezone.localdate() - timedelta(days=days_ago)).isoformat()

    # ── Portion item (Kuku) ──────────────────────────────────────────────

    def test_intro_preview_shows_correct_scope_for_portion_item(self):
        resp = self.client.get(f'/kitchen/item-reset/{self.kuku.id}/?cutoff={self._cutoff(6)}')
        self.assertEqual(resp.status_code, 200)
        scope = resp.context['scope']
        # Receipt txn (day-5) + 3 sales at day-2 count; the day-10 sale is out of scope.
        self.assertEqual(scope['txn_count'], 4)
        self.assertEqual(scope['receipt_count'], 1)
        self.assertEqual(scope['total_revenue'], 750.0)

    def test_confirm_requires_backup_first(self):
        resp = self.client.post(f'/kitchen/item-reset/{self.kuku.id}/confirm/', {
            'cutoff': self._cutoff(6), 'confirm_text': self.kuku.description,
        })
        self.assertRedirects(resp, f'/kitchen/item-reset/{self.kuku.id}/?cutoff={self._cutoff(6)}')
        self.assertEqual(Transaction.objects.filter(item=self.kuku).count(), 5)

    def test_confirm_requires_exact_name_match(self):
        self.client.get(f'/kitchen/item-reset/{self.kuku.id}/backup/?cutoff={self._cutoff(6)}')
        resp = self.client.post(f'/kitchen/item-reset/{self.kuku.id}/confirm/', {
            'cutoff': self._cutoff(6), 'confirm_text': 'Wrong Name',
        })
        self.assertRedirects(resp, f'/kitchen/item-reset/{self.kuku.id}/?cutoff={self._cutoff(6)}')
        self.assertEqual(Transaction.objects.filter(item=self.kuku).count(), 5)

    def test_confirm_deletes_since_cutoff_keeps_earlier_history(self):
        self.client.get(f'/kitchen/item-reset/{self.kuku.id}/backup/?cutoff={self._cutoff(6)}')
        resp = self.client.post(f'/kitchen/item-reset/{self.kuku.id}/confirm/', {
            'cutoff': self._cutoff(6), 'confirm_text': self.kuku.description, 'reason': 'ledger drift',
        })
        self.assertRedirects(resp, f'/kitchen/item-reset/{self.kuku.id}/complete/')
        # The 4 in-scope transactions (receipt txn + 3 sales) are gone; only
        # the day-10 sale (older than the cutoff) survives.
        remaining = Transaction.objects.filter(item=self.kuku)
        self.assertEqual(remaining.count(), 1)
        self.assertTrue(remaining.filter(created_at__lt=timezone.now() - timedelta(days=8)).exists())
        self.assertFalse(KitchenStockReceipt.objects.filter(id=self.receipt.id).exists())

    def test_confirm_creates_audit_log(self):
        from core.models import SalesResetLog
        self.client.get(f'/kitchen/item-reset/{self.kuku.id}/backup/?cutoff={self._cutoff(6)}')
        self.client.post(f'/kitchen/item-reset/{self.kuku.id}/confirm/', {
            'cutoff': self._cutoff(6), 'confirm_text': self.kuku.description, 'reason': 'ledger drift',
        })
        log = SalesResetLog.objects.filter(business=self.biz).order_by('-created_at').first()
        self.assertIsNotNone(log)
        self.assertIn('Kuku', log.reason)
        self.assertEqual(log.counts_snapshot['transactions_deleted'], 4)
        self.assertEqual(log.counts_snapshot['receipts_deleted'], 1)

    def test_default_cutoff_is_earliest_activity_not_most_recent_receipt(self):
        """2026-08-11 same-day correction: a reset run with NO ?cutoff=
        override must default to the item's EARLIEST-ever activity (the
        day-10 backdated sale, which predates the receipt itself), not the
        most recent receipt (day-5) — the original default anchor. Roy's
        real workflow backdates catch-up sales to before the day he enters
        the receipt, so a "most recent receipt" cutoff structurally always
        leaves those exact sales behind, letting the same drift recur every
        time the tool is used with its own default."""
        resp = self.client.get(f'/kitchen/item-reset/{self.kuku.id}/')
        self.assertEqual(resp.status_code, 200)
        expected = (timezone.localdate() - timedelta(days=10)).isoformat()
        self.assertEqual(resp.context['cutoff_date'].isoformat(), expected)

    def test_default_cutoff_full_flow_wipes_pre_receipt_backdated_sale(self):
        """End-to-end reproduction of the recurring-drift bug: with no
        cutoff override at all, backup + confirm must wipe every kuku
        transaction/receipt, including the day-10 sale that predates the
        receipt — this is the exact leftover that kept surviving every
        reset run before this fix."""
        intro = self.client.get(f'/kitchen/item-reset/{self.kuku.id}/')
        cutoff_str = intro.context['cutoff_date'].isoformat()
        self.assertEqual(cutoff_str, (timezone.localdate() - timedelta(days=10)).isoformat())

        self.client.get(f'/kitchen/item-reset/{self.kuku.id}/backup/')
        resp = self.client.post(f'/kitchen/item-reset/{self.kuku.id}/confirm/', {
            'cutoff': cutoff_str, 'confirm_text': self.kuku.description,
        })
        self.assertRedirects(resp, f'/kitchen/item-reset/{self.kuku.id}/complete/')
        self.assertEqual(Transaction.objects.filter(item=self.kuku).count(), 0)
        self.assertFalse(KitchenStockReceipt.objects.filter(id=self.receipt.id).exists())

    def test_default_cutoff_for_batch_item_is_earliest_batch(self):
        old_batch = KitchenBatch.objects.create(
            business=self.biz, store=self.store, item=self.chipo,
            cost_total=Decimal('500'), status='DEPLETED',
            received_on=timezone.localdate() - timedelta(days=20),
        )
        resp = self.client.get(f'/kitchen/item-reset/{self.chipo.id}/')
        expected = (timezone.localdate() - timedelta(days=20)).isoformat()
        self.assertEqual(resp.context['cutoff_date'].isoformat(), expected)
        self.assertTrue(KitchenBatch.objects.filter(id=old_batch.id).exists())

    def test_tab_linked_sale_excluded_from_deletion(self):
        tab = BarTab.objects.create(business=self.biz, customer_name='Table 3', status='OPEN', source='kitchen')
        tab_txn = Transaction.objects.create(
            business=self.biz, item=self.kuku, preset=self.full_leg, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('250'), payment_method='credit',
            created_at=timezone.now() - timedelta(days=2),
        )
        BarTabEntry.objects.create(tab=tab, transaction=tab_txn, description='Kuku', amount=Decimal('250'))

        resp = self.client.get(f'/kitchen/item-reset/{self.kuku.id}/?cutoff={self._cutoff(6)}')
        self.assertEqual(resp.context['scope']['tab_linked_count'], 1)

        self.client.get(f'/kitchen/item-reset/{self.kuku.id}/backup/?cutoff={self._cutoff(6)}')
        self.client.post(f'/kitchen/item-reset/{self.kuku.id}/confirm/', {
            'cutoff': self._cutoff(6), 'confirm_text': self.kuku.description,
        })
        self.assertTrue(Transaction.objects.filter(id=tab_txn.id).exists())
        self.assertTrue(BarTabEntry.objects.filter(transaction_id=tab_txn.id).exists())

    # ── KitchenBatch item (Chipo) ────────────────────────────────────────

    def test_intro_preview_shows_correct_scope_for_batch_item(self):
        resp = self.client.get(f'/kitchen/item-reset/{self.chipo.id}/?cutoff={self._cutoff(4)}')
        scope = resp.context['scope']
        self.assertEqual(scope['batch_count'], 1)
        self.assertEqual(scope['txn_count'], 1)  # the one record_sale() Issue txn
        self.assertEqual(scope['total_revenue'], 100.0)

    def test_confirm_deletes_batch_and_its_sales(self):
        self.client.get(f'/kitchen/item-reset/{self.chipo.id}/backup/?cutoff={self._cutoff(4)}')
        self.client.post(f'/kitchen/item-reset/{self.chipo.id}/confirm/', {
            'cutoff': self._cutoff(4), 'confirm_text': self.chipo.description,
        })
        self.assertFalse(KitchenBatch.objects.filter(id=self.batch.id).exists())
        self.assertEqual(Transaction.objects.filter(kitchen_batch_id=self.batch.id).count(), 0)

    def test_batch_before_cutoff_untouched(self):
        old_batch = KitchenBatch.objects.create(
            business=self.biz, store=self.store, item=self.chipo,
            cost_total=Decimal('500'), status='DEPLETED',
            received_on=timezone.localdate() - timedelta(days=20),
        )
        self.client.get(f'/kitchen/item-reset/{self.chipo.id}/backup/?cutoff={self._cutoff(4)}')
        self.client.post(f'/kitchen/item-reset/{self.chipo.id}/confirm/', {
            'cutoff': self._cutoff(4), 'confirm_text': self.chipo.description,
        })
        self.assertTrue(KitchenBatch.objects.filter(id=old_batch.id).exists())

    # ── Access control ───────────────────────────────────────────────────

    def test_plain_staff_blocked_from_intro(self):
        self.client.force_login(self.staff)
        resp = self.client.get(f'/kitchen/item-reset/{self.kuku.id}/')
        self.assertNotEqual(resp.status_code, 200)

    def test_plain_staff_blocked_from_confirm(self):
        self.client.force_login(self.staff)
        self.client.get(f'/kitchen/item-reset/{self.kuku.id}/backup/?cutoff={self._cutoff(4)}')
        resp = self.client.post(f'/kitchen/item-reset/{self.kuku.id}/confirm/', {
            'cutoff': self._cutoff(4), 'confirm_text': self.kuku.description,
        })
        # Redirected away, never actually deleted.
        self.assertEqual(Transaction.objects.filter(item=self.kuku).count(), 5)

    def test_cross_business_item_rejected(self):
        other_biz = Business.objects.create(name='Other Kitchen Reset Biz')
        other_owner = User.objects.create_user(username='kir_other', password='x')
        UserProfile.objects.create(user=other_owner, business=other_biz, role='owner')
        self.client.force_login(other_owner)
        resp = self.client.get(f'/kitchen/item-reset/{self.kuku.id}/')
        self.assertEqual(resp.status_code, 404)

    # ── restock_anchor_at side effect (2026-08-12) ───────────────────────

    def test_confirm_stamps_restock_anchor_on_anchor_preset_only(self):
        """The reset's confirm step must ALSO stamp ItemPortionPreset.
        restock_anchor_at on the item's own anchor preset(s) — a pure
        visibility cursor, side by side with (not instead of) the actual
        deletion. A tethered preset (none configured on Kuku in THIS
        fixture) would never get its own field touched; here full_leg is a
        standalone anchor (tracks_stock_of=None), so it's the one that
        should get stamped."""
        self.client.get(f'/kitchen/item-reset/{self.kuku.id}/backup/?cutoff={self._cutoff(6)}')
        self.client.post(f'/kitchen/item-reset/{self.kuku.id}/confirm/', {
            'cutoff': self._cutoff(6), 'confirm_text': self.kuku.description,
        })
        self.full_leg.refresh_from_db()
        self.assertIsNotNone(self.full_leg.restock_anchor_at)
        expected_date = timezone.localdate() - timedelta(days=6)
        self.assertEqual(timezone.localtime(self.full_leg.restock_anchor_at).date(), expected_date)

    def test_batch_item_reset_never_touches_portion_presets(self):
        """A KitchenBatch item (Chipo) has no ItemPortionPreset anchor
        concept for this mechanism — the reset's anchor-stamping branch must
        skip it entirely, never crash, never touch chipo_preset."""
        self.client.get(f'/kitchen/item-reset/{self.chipo.id}/backup/?cutoff={self._cutoff(2)}')
        resp = self.client.post(f'/kitchen/item-reset/{self.chipo.id}/confirm/', {
            'cutoff': self._cutoff(2), 'confirm_text': self.chipo.description,
        })
        self.assertRedirects(resp, f'/kitchen/item-reset/{self.chipo.id}/complete/')
        self.chipo_preset.refresh_from_db()
        self.assertIsNone(self.chipo_preset.restock_anchor_at)

    def test_reset_then_fresh_receipt_ignores_preserved_older_sold_history(self):
        """End-to-end reproduction of Roy's exact live scenario: after the
        reset, a NEW preset-attributed receipt correctly shows as sellable
        even though genuinely-preserved older sold history for the SAME
        anchor (the day-10 sale, deliberately kept — older than the cutoff)
        still exists in the database. Without the anchor stamp this would
        still show Iliyobaki <= 0 forever, no matter how much fresh stock
        comes in."""
        self.client.get(f'/kitchen/item-reset/{self.kuku.id}/backup/?cutoff={self._cutoff(6)}')
        self.client.post(f'/kitchen/item-reset/{self.kuku.id}/confirm/', {
            'cutoff': self._cutoff(6), 'confirm_text': self.kuku.description,
        })
        # The day-10 sale (older than cutoff) genuinely survives, deliberately.
        self.assertTrue(
            Transaction.objects.filter(item=self.kuku, preset=self.full_leg, type='Issue').exists(),
            'The deliberately-preserved older sale must still exist',
        )
        # Fresh receipt of 23 legs, dated today — nothing sold against it yet.
        # 2026-08-21: mirror kitchen_stock_receipt_create()'s own real
        # behaviour exactly — a receiving line is always paired with a real
        # stock-adding Transaction; a bare KitchenStockReceiptLine with no
        # Transaction (the original version of this fixture) never actually
        # grows item.current_balance(), which the 2026-08-21 "decisive fix"
        # for the recurring hidden-presets bug now correctly requires (real
        # physical stock, not just a receiving-bookkeeping row).
        new_receipt = KitchenStockReceipt.objects.create(
            business=self.biz, store=self.store, supplier='Kamau (fresh)',
            received_on=timezone.localdate(),
        )
        KitchenStockReceiptLine.objects.create(
            receipt=new_receipt, item=self.kuku, preset=self.full_leg,
            qty_received=Decimal('23'), line_cost=Decimal('3700'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('23'),
            preset=self.full_leg, payment_method='cash',
            invoice_no='Kamau (fresh)', recorded_by=self.owner,
        )
        resp = self.client.get('/kitchen/')
        import json as _json
        body = resp.content.decode()
        start = body.index('var _portionItems')
        eq = body.index('=', start)
        end = body.index(';\n', eq)
        items = _json.loads(body[eq + 1:end].strip())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        labels = [p['label'] for p in kuku['presets']]
        self.assertIn('Full Chicken Leg', labels,
                       'Old preserved history must not suppress a fresh restock once the anchor is stamped')
        full_leg = next(p for p in kuku['presets'] if p['label'] == 'Full Chicken Leg')
        self.assertEqual(full_leg['_received'], 23.0)
        self.assertEqual(full_leg['_sold'], 0.0)


class ResetPresetRestockAnchorTest(TestCase):
    """2026-08-12 live report (Roy, Monsoon Inn): a lighter, NON-destructive
    sibling of Kitchen Item Reset — "I do not want to delete all the
    transactions made from a long time ago... put a receipt for last week
    and start putting in sales till date... the presets received should
    show." After a genuine fresh restock (nothing sold against it yet), the
    tile still hid every preset because old, deliberately-preserved sold
    history for the same anchor (esp. once a tether groups it in) still
    counted toward the lifetime received-vs-sold tally. This endpoint
    stamps ItemPortionPreset.restock_anchor_at = now() with zero deletion —
    no backup, no typed confirmation needed, since nothing is destroyed."""

    def setUp(self):
        self.biz = Business.objects.create(name='Restock Anchor Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='ra_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager = User.objects.create_user(username='ra_manager', password='x')
        UserProfile.objects.create(user=self.manager, business=self.biz, role='manager')
        self.staff = User.objects.create_user(username='ra_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='kitchen')

        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='RA-KUKU', unit='Pcs', selling_price=Decimal('0'),
        )
        self.full_leg = ItemPortionPreset.objects.create(
            item=self.kuku, label='Full Chicken Leg', price=Decimal('250'), quantity_consumed=Decimal('1'),
        )
        self.half_leg = ItemPortionPreset.objects.create(
            item=self.kuku, label='Half Chicken Leg', price=Decimal('150'),
            quantity_consumed=Decimal('0.5'), tracks_stock_of=self.full_leg,
        )
        self.chipo = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='RA-CHIPO', unit='Batch', selling_price=Decimal('100'),
            is_kitchen_batch=True,
        )
        self.client.force_login(self.owner)

    def _post(self, item_id, token=None):
        import uuid as _uuid
        return self.client.post(
            f'/kitchen/item/{item_id}/reset-restock-anchor/',
            {'idempotency_token': token or f'ra-tok-{_uuid.uuid4()}'},
        )

    def test_stamps_anchor_on_standalone_preset(self):
        before = timezone.now()
        resp = self._post(self.kuku.id)
        data = resp.json()
        self.assertTrue(data['ok'], data)
        self.assertEqual(data['updated'], 1)  # only full_leg is an anchor (tracks_stock_of=None)
        self.full_leg.refresh_from_db()
        self.half_leg.refresh_from_db()
        self.assertIsNotNone(self.full_leg.restock_anchor_at)
        self.assertGreaterEqual(self.full_leg.restock_anchor_at, before)
        self.assertIsNone(self.half_leg.restock_anchor_at, 'A tethered preset never gets its own field stamped')

    def test_resolves_drift_without_deleting_anything(self):
        """Reproduce the exact live scenario: a chunk of old SOLD history
        exists for this anchor with no matching RECEIVED-side record at all
        (e.g. sales recorded before the tether/receipt-line tracking ever
        existed for this cut — the real mechanism traced from Roy's live
        report) — deliberately preserved, never deleted.

        2026-08-21 update (Roy, same day, still blocked live — "this going
        in circles everytime we change something really sucks"): the
        received-vs-sold NET tally no longer gates sell-tile VISIBILITY at
        all (see kitchen_views.py's `_is_visible()`, decisively rewritten
        same day) — only real `item.current_balance()` does, once a preset
        has EVER been genuinely received under this item's regime. So the
        preset here is now correctly visible as soon as real physical stock
        is positive, with no dependency on stamping this anchor at all —
        stamping only ever affects the owner-only DIAGNOSTIC `_sold`/
        `_received` numbers (locked in below), never whether staff can
        actually sell it. This is a deliberate, more robust simplification,
        not a regression of the 2026-08-12 feature's own delete-nothing
        guarantee (also re-verified below)."""
        Transaction.objects.create(
            business=self.biz, item=self.kuku, preset=self.half_leg, type='Issue',
            qty=Decimal('-30'), sale_amount=Decimal('9000'), payment_method='cash',
            created_at=timezone.now() - timedelta(days=29),
        )

        # Fresh restock: 40 new legs (more than the old-sold 30, so real
        # balance goes positive — mirrors kitchen_stock_receipt_create()'s
        # own real behaviour, which always pairs a KitchenStockReceiptLine
        # with a real stock-adding Transaction; nothing sold against it yet.
        new_receipt = KitchenStockReceipt.objects.create(
            business=self.biz, store=self.store, supplier='Kamau', received_on=timezone.localdate(),
        )
        KitchenStockReceiptLine.objects.create(
            receipt=new_receipt, item=self.kuku, preset=self.full_leg,
            qty_received=Decimal('40'), line_cost=Decimal('6400'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('40'),
            preset=self.full_leg, payment_method='cash', invoice_no='Kamau', recorded_by=self.owner,
        )
        self.kuku.refresh_from_db()
        self.assertEqual(self.kuku.current_balance(), Decimal('10'), "real stock is genuinely positive")
        txn_count_before = Transaction.objects.filter(item=self.kuku).count()
        receipt_count_before = KitchenStockReceiptLine.objects.filter(item=self.kuku).count()

        # Before stamping: already visible — real balance (10) is positive
        # and this anchor has genuinely been received before. The lifetime
        # `_sold` diagnostic still reflects the old drift (30), unaffected.
        resp = self.client.get('/kitchen/')
        import json as _json
        def _blob(body):
            start = body.index('var _portionItems')
            eq = body.index('=', start)
            end = body.index(';\n', eq)
            return _json.loads(body[eq + 1:end].strip())
        items = _blob(resp.content.decode())
        kuku = next(i for i in items if i['id'] == self.kuku.id)
        self.assertIn('Full Chicken Leg', [p['label'] for p in kuku['presets']])
        full_leg_before = next(p for p in kuku['presets'] if p['label'] == 'Full Chicken Leg')
        self.assertEqual(full_leg_before['_sold'], 30.0)

        # Stamp the anchor — no deletion.
        resp2 = self._post(self.kuku.id)
        self.assertTrue(resp2.json()['ok'], resp2.json())
        self.assertEqual(Transaction.objects.filter(item=self.kuku).count(), txn_count_before,
                          'Stamping the anchor must never delete a single transaction')
        self.assertEqual(KitchenStockReceiptLine.objects.filter(item=self.kuku).count(), receipt_count_before,
                          'Stamping the anchor must never delete a single receipt line')

        resp3 = self.client.get('/kitchen/')
        items3 = _blob(resp3.content.decode())
        kuku3 = next(i for i in items3 if i['id'] == self.kuku.id)
        self.assertIn('Full Chicken Leg', [p['label'] for p in kuku3['presets']],
                       'Fresh restock must stay sellable once the anchor is stamped')
        full_leg = next(p for p in kuku3['presets'] if p['label'] == 'Full Chicken Leg')
        self.assertEqual(full_leg['_received'], 40.0)
        self.assertEqual(full_leg['_sold'], 0.0, "the windowed diagnostic now excludes the pre-anchor old sale")

    def test_manager_may_stamp_anchor(self):
        self.client.force_login(self.manager)
        resp = self._post(self.kuku.id)
        self.assertTrue(resp.json()['ok'], resp.json())

    def test_staff_blocked(self):
        self.client.force_login(self.staff)
        resp = self._post(self.kuku.id)
        self.assertEqual(resp.status_code, 403)
        self.full_leg.refresh_from_db()
        self.assertIsNone(self.full_leg.restock_anchor_at)

    def test_batch_item_rejected(self):
        resp = self._post(self.chipo.id)
        self.assertEqual(resp.status_code, 400)

    def test_cross_business_item_rejected(self):
        other_biz = Business.objects.create(name='Other Restock Anchor Biz')
        other_owner = User.objects.create_user(username='ra_other', password='x')
        UserProfile.objects.create(user=other_owner, business=other_biz, role='owner')
        self.client.force_login(other_owner)
        resp = self._post(self.kuku.id)
        self.assertEqual(resp.status_code, 404)

    def test_duplicate_idempotency_token_blocked(self):
        r1 = self._post(self.kuku.id, token='ra-dup-1')
        self.assertTrue(r1.json()['ok'])
        r2 = self._post(self.kuku.id, token='ra-dup-1')
        self.assertEqual(r2.status_code, 409)


class KitchenRevenueBreakdownTest(TestCase):
    """2026-08-09, second same-day follow-up (Roy — "for Leo to adjust
    from 2550 to today's figures... is that too hard surely"): owner/
    manager get a line-by-line breakdown of what "Leo" is actually
    summing, so the real transactions can be inspected directly."""

    def setUp(self):
        self.biz = Business.objects.create(name='KB Breakdown Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='kbbrk_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='kbbrk_staff', password='x')
        UserProfile.objects.create(user=self.staff, business=self.biz, role='kitchen')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='KBBRK-01', unit='Plate', selling_price=Decimal('100'),
        )
        self.client.force_login(self.owner)

    def _sell(self, amount='100', payment_method='cash'):
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal(amount),
            payment_method=payment_method, date=timezone.localdate(),
        )

    def test_owner_sees_breakdown_lines(self):
        self._sell('400')
        resp = self.client.get('/kitchen/')
        import json as _json
        lines = _json.loads(resp.context['kitchen_revenue_lines'])
        self.assertEqual(len(lines), 1)
        self.assertEqual(lines[0]['label'], 'Chipo')
        self.assertEqual(lines[0]['amount'], 400.0)
        self.assertEqual(lines[0]['payment_method'], 'cash')

    def test_breakdown_empty_when_no_sales(self):
        resp = self.client.get('/kitchen/')
        import json as _json
        lines = _json.loads(resp.context['kitchen_revenue_lines'])
        self.assertEqual(lines, [])

    def test_staff_does_not_get_breakdown_lines(self):
        self._sell('400')
        self.client.force_login(self.staff)
        resp = self.client.get('/kitchen/')
        import json as _json
        lines = _json.loads(resp.context['kitchen_revenue_lines'])
        self.assertEqual(lines, [])


class CanManageKegsPermissionTest(TestCase):
    """2026-08-11 live request (Roy — a barrel physically ran out mid-shift
    with no owner present, staff had no way to tap the next sealed barrel
    or close the finished one): UserProfile.can_manage_kegs lets a trusted
    staffer tap/deplete a barrel without full owner/manager status, still
    gated on an open shift like every other staff stock action.

    2026-08-12 (Roy, standing principle — "whenever we set a permission
    toggle the function should be exactly as it is to the one who has it"):
    discard_barrel (Tupa) and receive_barrel (Pokea) were originally kept
    owner/manager-only, deliberately excluded from can_manage_kegs — that
    exclusion is now REVERSED to match the same standard already applied to
    Rekebisha's "not a real loss" checkbox. Both now accept a can_manage_kegs
    staffer with an open shift, same two-step gate as tap/deplete."""

    def setUp(self):
        self.biz = Business.objects.create(name='CMK Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.owner = User.objects.create_user(username='cmk_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='cmk_staff', password='x')
        self.staff_profile = UserProfile.objects.create(
            user=self.staff, business=self.biz, role='staff', can_manage_kegs=False,
        )
        # Two separate items — tap_barrel() enforces one TAPPED barrel per
        # item, so a sealed-to-tap fixture and an already-tapped fixture
        # can't share one item.
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Keg Gold',
            material_no='CMK-01', unit='Ml', is_keg=True,
            selling_price=Decimal('80'), cost_price=Decimal('12000'),
        )
        self.sealed = KegBarrel.objects.create(
            business=self.biz, store=self.store, item=self.item,
            cost_price=Decimal('12000'), target_revenue=Decimal('20000'),
            status='SEALED',
        )
        self.item2 = Item.objects.create(
            business=self.biz, store=self.store, description='Keg Dark',
            material_no='CMK-02', unit='Ml', is_keg=True,
            selling_price=Decimal('80'), cost_price=Decimal('12000'),
        )
        self.tapped = KegBarrel.objects.create(
            business=self.biz, store=self.store, item=self.item2,
            cost_price=Decimal('12000'), target_revenue=Decimal('20000'),
            status='TAPPED',
        )

    def _open_shift(self, user):
        Shift.objects.create(
            business=self.biz, store=self.store, staff=user,
            status='OPEN', opening_float=Decimal('0'),
        )

    # ── tap_barrel ───────────────────────────────────────────────────────

    def test_owner_can_always_tap(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/bar/tap/{self.sealed.id}/')
        self.assertTrue(resp.json()['ok'], resp.json())
        self.sealed.refresh_from_db()
        self.assertEqual(self.sealed.status, 'TAPPED')
        self.assertEqual(self.sealed.tapped_by_id, self.owner.id)

    def test_tap_blocked_while_another_barrel_already_selling_names_the_button(self):
        """2026-08-11 same-day follow-up (Roy — staff confused by the
        original vague 'close it first' message): error now explicitly
        names the ✓ Imekwisha button to press first."""
        second_sealed = KegBarrel.objects.create(
            business=self.biz, store=self.store, item=self.item2,
            cost_price=Decimal('12000'), target_revenue=Decimal('20000'),
            status='SEALED',
        )
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/bar/tap/{second_sealed.id}/')
        self.assertFalse(resp.json()['ok'])
        self.assertIn('Imekwisha', resp.json()['error'])
        second_sealed.refresh_from_db()
        self.assertEqual(second_sealed.status, 'SEALED')

    def test_plain_staff_blocked_from_tap(self):
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/bar/tap/{self.sealed.id}/')
        self.assertEqual(resp.status_code, 403)
        self.sealed.refresh_from_db()
        self.assertEqual(self.sealed.status, 'SEALED')

    def test_can_manage_kegs_staff_with_shift_may_tap(self):
        self.staff_profile.can_manage_kegs = True
        self.staff_profile.save(update_fields=['can_manage_kegs'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/bar/tap/{self.sealed.id}/')
        self.assertTrue(resp.json()['ok'], resp.json())
        self.sealed.refresh_from_db()
        self.assertEqual(self.sealed.status, 'TAPPED')
        self.assertEqual(self.sealed.tapped_by_id, self.staff.id)

    def test_can_manage_kegs_staff_without_shift_blocked(self):
        self.staff_profile.can_manage_kegs = True
        self.staff_profile.save(update_fields=['can_manage_kegs'])
        self.client.force_login(self.staff)
        resp = self.client.post(f'/stock/bar/tap/{self.sealed.id}/')
        self.assertEqual(resp.status_code, 403)
        self.assertTrue(resp.json().get('shift_required'))
        self.sealed.refresh_from_db()
        self.assertEqual(self.sealed.status, 'SEALED')

    # ── deplete_barrel ───────────────────────────────────────────────────

    def test_owner_can_always_deplete(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/bar/deplete/{self.tapped.id}/')
        self.assertTrue(resp.json()['ok'], resp.json())
        self.tapped.refresh_from_db()
        self.assertEqual(self.tapped.status, 'DEPLETED')
        self.assertEqual(self.tapped.closed_by_id, self.owner.id)

    def test_plain_staff_blocked_from_deplete(self):
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/bar/deplete/{self.tapped.id}/')
        self.assertEqual(resp.status_code, 403)
        self.tapped.refresh_from_db()
        self.assertEqual(self.tapped.status, 'TAPPED')

    def test_can_manage_kegs_staff_with_shift_may_deplete(self):
        self.staff_profile.can_manage_kegs = True
        self.staff_profile.save(update_fields=['can_manage_kegs'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/bar/deplete/{self.tapped.id}/')
        self.assertTrue(resp.json()['ok'], resp.json())
        self.tapped.refresh_from_db()
        self.assertEqual(self.tapped.status, 'DEPLETED')
        self.assertEqual(self.tapped.closed_by_id, self.staff.id)

    def test_can_manage_kegs_staff_without_shift_blocked_from_deplete(self):
        self.staff_profile.can_manage_kegs = True
        self.staff_profile.save(update_fields=['can_manage_kegs'])
        self.client.force_login(self.staff)
        resp = self.client.post(f'/stock/bar/deplete/{self.tapped.id}/')
        self.assertEqual(resp.status_code, 403)
        self.tapped.refresh_from_db()
        self.assertEqual(self.tapped.status, 'TAPPED')

    # ── discard_barrel / receive_barrel — widened 2026-08-12 ──────────────

    def test_can_manage_kegs_staff_with_shift_may_discard(self):
        self.staff_profile.can_manage_kegs = True
        self.staff_profile.save(update_fields=['can_manage_kegs'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/bar/discard/{self.tapped.id}/', {'reason': 'test'})
        self.assertTrue(resp.json()['ok'], resp.json())
        self.tapped.refresh_from_db()
        self.assertEqual(self.tapped.status, 'RETURNED')

    def test_can_manage_kegs_staff_without_shift_blocked_from_discard(self):
        self.staff_profile.can_manage_kegs = True
        self.staff_profile.save(update_fields=['can_manage_kegs'])
        self.client.force_login(self.staff)
        resp = self.client.post(f'/stock/bar/discard/{self.tapped.id}/', {'reason': 'test'})
        self.assertEqual(resp.status_code, 403)
        self.tapped.refresh_from_db()
        self.assertEqual(self.tapped.status, 'TAPPED')

    def test_plain_staff_still_blocked_from_discard(self):
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/bar/discard/{self.tapped.id}/', {'reason': 'test'})
        self.assertEqual(resp.status_code, 403)

    def test_can_manage_kegs_staff_with_shift_may_receive(self):
        self.staff_profile.can_manage_kegs = True
        self.staff_profile.save(update_fields=['can_manage_kegs'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post('/stock/bar/receive/', {
            'item_id': self.item.id, 'count': '2', 'cost_per_barrel': '12000',
            'idempotency_token': 'tok-cmk-recv-1',
        })
        self.assertTrue(resp.json()['ok'], resp.json())

    def test_can_manage_kegs_staff_without_shift_blocked_from_receive(self):
        self.staff_profile.can_manage_kegs = True
        self.staff_profile.save(update_fields=['can_manage_kegs'])
        self.client.force_login(self.staff)
        resp = self.client.post('/stock/bar/receive/', {
            'item_id': self.item.id, 'count': '2', 'cost_per_barrel': '12000',
            'idempotency_token': 'tok-cmk-recv-2',
        })
        self.assertEqual(resp.status_code, 403)

    def test_plain_staff_still_blocked_from_receive(self):
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post('/stock/bar/receive/', {
            'item_id': self.item.id, 'count': '2', 'cost_per_barrel': '12000',
            'idempotency_token': 'tok-cmk-recv-3',
        })
        self.assertEqual(resp.status_code, 403)

    # ── cross-business isolation ──────────────────────────────────────────

    def test_cross_business_barrel_rejected(self):
        other_biz = Business.objects.create(name='Other CMK Biz')
        other_owner = User.objects.create_user(username='cmk_other', password='x')
        UserProfile.objects.create(user=other_owner, business=other_biz, role='owner')
        self.client.force_login(other_owner)
        resp = self.client.post(f'/stock/bar/tap/{self.sealed.id}/')
        self.assertEqual(resp.status_code, 404)

    # ── accountability trail surfaced on the board API ────────────────────

    def test_board_api_shows_tapped_by_and_last_closed_by(self):
        self.tapped.tapped_by = self.owner
        self.tapped.save(update_fields=['tapped_by'])
        self.client.force_login(self.owner)
        resp = self.client.get('/stock/bar/board/')
        data = resp.json()
        row = next(k for k in data['kegs'] if k['item_id'] == self.item2.id)
        self.assertEqual(row['tapped_by_name'], 'cmk_owner')

        # Close it, then confirm the item's no-tap tile shows last_closed_by_name
        self.tapped.status = 'DEPLETED'
        self.tapped.closed_at = timezone.now()
        self.tapped.closed_by = self.staff
        self.tapped.save(update_fields=['status', 'closed_at', 'closed_by'])
        resp2 = self.client.get('/stock/bar/board/')
        data2 = resp2.json()
        row2 = next(k for k in data2['kegs'] if k['item_id'] == self.item2.id)
        self.assertEqual(row2['last_closed_by_name'], 'cmk_staff')


class AdjustStockPermissionTest(TestCase):
    """2026-08-11 live request (Roy — "in the event the manager or business
    owner is not around"): UserProfile.can_adjust_stock lets a trusted
    staffer use ⚖️ Rekebisha, closing a real pre-existing gap — the view had
    NO permission gate at all despite its own docstring's "owner/manager"
    claim. Still requires an open shift.

    2026-08-12 (Roy, standing principle): the "not a real loss" judgment
    call, originally kept owner/manager-only, is now ALSO honored from a
    can_adjust_stock-delegated staffer — a granted toggle carries the full
    function, not a restricted subset of it."""

    def setUp(self):
        self.biz = Business.objects.create(name='ASP Biz')
        self.store = Store.objects.create(business=self.biz, name='Shop')
        self.owner = User.objects.create_user(username='asp_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff = User.objects.create_user(username='asp_staff', password='x')
        self.staff_profile = UserProfile.objects.create(
            user=self.staff, business=self.biz, role='staff', can_adjust_stock=False,
        )
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Whisky 750ml',
            material_no='ASP-01', unit='Btl', selling_price=Decimal('1500'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('10'),
        )

    def _open_shift(self, user):
        Shift.objects.create(
            business=self.biz, store=self.store, staff=user,
            status='OPEN', opening_float=Decimal('0'),
        )

    def test_owner_can_adjust_without_toggle(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '7'})
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertEqual(self.item.current_balance(), Decimal('7'))

    def test_plain_staff_blocked_without_toggle(self):
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '7'})
        self.assertEqual(resp.status_code, 403)
        self.assertEqual(self.item.current_balance(), Decimal('10'))

    def test_can_adjust_stock_staff_with_shift_may_adjust(self):
        self.staff_profile.can_adjust_stock = True
        self.staff_profile.save(update_fields=['can_adjust_stock'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '7'})
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertEqual(self.item.current_balance(), Decimal('7'))

    def test_can_adjust_stock_staff_without_shift_blocked(self):
        self.staff_profile.can_adjust_stock = True
        self.staff_profile.save(update_fields=['can_adjust_stock'])
        self.client.force_login(self.staff)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '7'})
        self.assertEqual(resp.status_code, 403)
        self.assertTrue(resp.json().get('shift_required'))
        self.assertEqual(self.item.current_balance(), Decimal('10'))

    def test_no_real_loss_honored_for_delegated_staff(self):
        """2026-08-12: the 'not a real loss' judgment is now honored from a
        can_adjust_stock-delegated staffer, exactly like owner/manager."""
        self.staff_profile.can_adjust_stock = True
        self.staff_profile.save(update_fields=['can_adjust_stock'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {
            'actual_count': '6', 'no_real_loss': '1',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        txn = Transaction.objects.filter(item=self.item, type='Wastage').order_by('-id').first()
        self.assertEqual(txn.invoice_no, '[ADJ-NOLOSS]')

    def test_no_real_loss_still_ignored_without_toggle(self):
        """A plain staffer somehow reaching this endpoint (shouldn't happen —
        the main gate blocks them) still can't flag no_real_loss even if the
        gate were bypassed; regression lock via a staffer with NEITHER
        can_adjust_stock nor owner/manager status never reaching this far."""
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {
            'actual_count': '6', 'no_real_loss': '1',
        })
        self.assertEqual(resp.status_code, 403)

    def test_owner_no_real_loss_still_works(self):
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {
            'actual_count': '6', 'no_real_loss': '1',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        txn = Transaction.objects.filter(item=self.item, type='Wastage').order_by('-id').first()
        self.assertEqual(txn.invoice_no, '[ADJ-NOLOSS]')

    def test_delegated_staff_correction_notifies_owner(self):
        """2026-08-25 (Roy — "ensure stock variance during staff stock take
        is accurate so that we catch this theft that has been happening"):
        Rekebisha is the single most theft-relevant lever in the app but
        never notified the owner at all, for either direction, whether the
        actor was the owner or a delegated staffer. A dishonest delegated
        staffer could quietly correct their own shortfall with zero
        visibility. This locks in that the owner now gets an in-app
        notification whenever a DELEGATED staffer (never the owner
        correcting their own item) performs a correction."""
        from core.models import Notification
        self.staff_profile.can_adjust_stock = True
        self.staff_profile.save(update_fields=['can_adjust_stock'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {
            'actual_count': '6', 'note': 'Physical recount',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        notes = Notification.objects.filter(user=self.owner, title='⚖️ Marekebisho ya Stock')
        self.assertEqual(notes.count(), 1)
        self.assertIn('Whisky 750ml', notes.first().message)
        self.assertIn('asp_staff', notes.first().message)

    def test_delegated_staff_no_real_loss_flagged_in_notification(self):
        """The owner must be told when 'not a real loss' was ticked, since
        that flag suppresses the correction from every loss/P&L figure —
        exactly the kind of thing an owner needs visibility into, not
        silence on."""
        from core.models import Notification
        self.staff_profile.can_adjust_stock = True
        self.staff_profile.save(update_fields=['can_adjust_stock'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {
            'actual_count': '6', 'no_real_loss': '1',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        note = Notification.objects.filter(user=self.owner, title='⚖️ Marekebisho ya Stock').first()
        self.assertIsNotNone(note)
        self.assertIn('sio hasara halisi', note.message)

    def test_owner_correcting_own_item_does_not_self_notify(self):
        """An owner/manager correcting their own item needs no notification
        about their own action — this is pure visibility for DELEGATED
        staff, not a general audit log of every correction."""
        from core.models import Notification
        self.client.force_login(self.owner)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '7'})
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertEqual(
            Notification.objects.filter(title='⚖️ Marekebisho ya Stock').count(), 0,
        )

    def test_no_change_never_notifies(self):
        """A recount that exactly matches the book balance is a no-op —
        must never fire a notification (or create a transaction) at all."""
        from core.models import Notification
        self.staff_profile.can_adjust_stock = True
        self.staff_profile.save(update_fields=['can_adjust_stock'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '10'})
        self.assertTrue(resp.json().get('no_change'))
        self.assertEqual(
            Notification.objects.filter(title='⚖️ Marekebisho ya Stock').count(), 0,
        )

    def test_surplus_correction_also_notifies(self):
        """Both directions are worth owner visibility, not just shortages —
        a surplus could equally be a red flag (unrecorded stock quietly
        being 'found')."""
        from core.models import Notification
        self.staff_profile.can_adjust_stock = True
        self.staff_profile.save(update_fields=['can_adjust_stock'])
        self.client.force_login(self.staff)
        self._open_shift(self.staff)
        resp = self.client.post(f'/stock/items/{self.item.id}/adjust/', {'actual_count': '13'})
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertEqual(
            Notification.objects.filter(user=self.owner, title='⚖️ Marekebisho ya Stock').count(), 1,
        )


class WaitressConvertToDebtPermissionTest(TestCase):
    """2026-08-11 live request (Roy): UserProfile.can_convert_tabs_to_debt
    lets a specific waitress convert an EXISTING open tab's unpaid balance
    to debt (Geuza Deni / bulk shift-close conversion). Deliberately does
    NOT touch the separate, unconditional rule that a waitress can never
    PLACE new credit directly at checkout — that's regression-locked here
    too, with the toggle ON, to prove the two rules stay independent."""

    def setUp(self):
        self.biz = Business.objects.create(name='WCD Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar Counter')
        self.owner = User.objects.create_user(username='wcd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.waitress = User.objects.create_user(username='wcd_waitress', password='x')
        self.waitress_profile = UserProfile.objects.create(
            user=self.waitress, business=self.biz, role='waitress',
            can_convert_tabs_to_debt=False,
        )
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='WCD Keg Item',
            material_no='WCD-01', unit='Cup', selling_price=Decimal('100'), is_keg=True,
        )
        self.barrel = KegBarrel.objects.create(
            business=self.biz, store=self.store, item=self.item, status='TAPPED',
            cost_price=Decimal('1000'), target_revenue=Decimal('2000'),
            tare_weight_kg=Decimal('5'), gross_weight_kg=Decimal('15'),
        )
        self.preset = ItemPortionPreset.objects.create(
            item=self.item, label='Cup', price=Decimal('180'), quantity_consumed=Decimal('0.3'),
        )

    def _open_tab(self, name='WCD Customer'):
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-0.3'), sale_amount=Decimal('180'),
            payment_method='credit', recipient=name, keg_barrel=self.barrel,
            date=timezone.localdate(),
        )
        tab = BarTab.objects.create(business=self.biz, customer_name=name, status='OPEN')
        BarTabEntry.objects.create(tab=tab, transaction=txn, description='Cup', amount=Decimal('180'))
        return tab

    def test_waitress_without_toggle_blocked_from_convert(self):
        tab = self._open_tab()
        self.client.force_login(self.waitress)
        resp = self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': tab.customer_name})
        self.assertEqual(resp.status_code, 403)
        tab.refresh_from_db()
        self.assertEqual(tab.status, 'OPEN')

    def test_waitress_with_toggle_may_convert(self):
        self.waitress_profile.can_convert_tabs_to_debt = True
        self.waitress_profile.save(update_fields=['can_convert_tabs_to_debt'])
        Shift.objects.create(
            business=self.biz, store=self.store, staff=self.waitress,
            status='OPEN', opening_float=Decimal('0'), station='bar',
        )
        tab = self._open_tab()
        self.client.force_login(self.waitress)
        resp = self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': tab.customer_name})
        self.assertTrue(resp.json()['ok'], resp.json())

    def test_waitress_with_toggle_but_no_shift_blocked_from_convert(self):
        self.waitress_profile.can_convert_tabs_to_debt = True
        self.waitress_profile.save(update_fields=['can_convert_tabs_to_debt'])
        tab = self._open_tab()
        self.client.force_login(self.waitress)
        resp = self.client.post(f'/bar/tabs/{tab.id}/debt/', {'customer_name': tab.customer_name})
        self.assertEqual(resp.status_code, 403)
        self.assertTrue(resp.json().get('shift_required'))

    def test_waitress_with_toggle_still_blocked_from_bulk_convert_without_toggle_off(self):
        # Sanity: toggle OFF still blocks bulk convert.
        tab = self._open_tab()
        self.client.force_login(self.waitress)
        resp = self.client.post('/bar/tabs/bulk-convert-to-debt/', {
            'tab_ids': json.dumps([tab.id]),
        })
        self.assertEqual(resp.status_code, 403)

    def test_waitress_with_toggle_may_bulk_convert(self):
        self.waitress_profile.can_convert_tabs_to_debt = True
        self.waitress_profile.save(update_fields=['can_convert_tabs_to_debt'])
        tab = self._open_tab()
        self.client.force_login(self.waitress)
        resp = self.client.post('/bar/tabs/bulk-convert-to-debt/', {
            'tab_ids': json.dumps([tab.id]),
        })
        self.assertTrue(resp.json()['ok'], resp.json())

    def test_waitress_with_toggle_still_blocked_from_placing_new_credit_directly(self):
        """The toggle only affects CONVERTING an existing tab — a waitress
        must still never be able to place NEW credit directly at checkout
        (the partial-debt checkout shortcut), regardless of this toggle."""
        self.waitress_profile.can_convert_tabs_to_debt = True
        self.waitress_profile.save(update_fields=['can_convert_tabs_to_debt'])
        Shift.objects.create(
            business=self.biz, store=self.store, staff=self.waitress,
            status='OPEN', opening_float=Decimal('0'), station='bar',
        )
        self.client.force_login(self.waitress)
        resp = self.client.post('/bar/', {
            'keg_cart': json.dumps([{'barrel_id': self.barrel.id, 'preset_id': self.preset.id, 'qty': 1}]),
            'payment_method': 'tab',
            'tab_customer': 'Waitress New Credit',
            'partial_cash': '120',
            'partial_mpesa': '0',
            'idempotency_token': 'wcd-block-1',
        })
        self.assertEqual(resp.status_code, 302)
        self.assertFalse(
            BarTab.objects.filter(business=self.biz, customer_name='Waitress New Credit').exists()
        )


