class WaitressLiveShiftTimerTest(TestCase):
    """2026-08-12 live request (Roy): a NEW, plain wall-clock 'time since I
    opened' figure for the waitress, deliberately separate from the
    accountability elapsed/Muda figure (which stays reduced by any
    overlapping custodian shift, per _shift_active_segments())."""

    def setUp(self):
        self.biz = Business.objects.create(name='WT Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.waitress = User.objects.create_user(username='wt_waitress', password='x')
        UserProfile.objects.create(user=self.waitress, business=self.biz, role='waitress')

    def test_no_open_shift_no_started_at(self):
        self.client.force_login(self.waitress)
        resp = self.client.get('/bar/orders/')
        self.assertIsNone(resp.context['my_open_shift_started_at'])

    def test_own_open_shift_returns_started_at(self):
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.waitress,
            status='OPEN', opening_float=Decimal('0'),
        )
        self.client.force_login(self.waitress)
        resp = self.client.get('/bar/orders/')
        self.assertEqual(
            resp.context['my_open_shift_started_at'], shift.started_at.isoformat(),
        )

    def test_accountability_elapsed_unaffected(self):
        """Regression lock: adding the new timer must never touch what
        active_shift_api()'s 'elapsed' field computes — still custodian-
        overlap-subtracted for a waitress, per its own established design."""
        bartender = User.objects.create_user(username='wt_bartender', password='x')
        UserProfile.objects.create(user=bartender, business=self.biz, role='staff')
        Shift.objects.create(
            business=self.biz, store=self.store, staff=bartender,
            status='OPEN', opening_float=Decimal('0'), station='bar',
        )
        Shift.objects.create(
            business=self.biz, store=self.store, staff=self.waitress,
            status='OPEN', opening_float=Decimal('0'), station='bar',
        )
        self.client.force_login(self.waitress)
        resp = self.client.get('/bar/shift/active/')
        data = resp.json()
        # Fully overlapped by the bartender's custodian shift — elapsed
        # stays at 0h regardless of real wall-clock time, exactly the
        # existing, deliberate accountability design.
        self.assertEqual(data['shift']['elapsed'], '0h 00m')

    def test_all_shifts_payload_carries_started_at_iso_for_owner_dashboard(self):
        """2026-08-13 live report (Roy): the owner's home-dashboard 'Active
        Shifts' meter showed a waitress's Muda permanently stuck at 0h 00m
        with no explanation (correct per the accountability design above,
        but looked broken with nothing to distinguish it from a frozen
        clock). all_shifts_data must carry a real, parseable timestamp so
        the dashboard can show a genuine wall-clock duration alongside it."""
        owner = User.objects.create_user(username='wt_owner', password='x')
        UserProfile.objects.create(user=owner, business=self.biz, role='owner')
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.waitress,
            status='OPEN', opening_float=Decimal('0'), station='bar',
        )
        self.client.force_login(owner)
        resp = self.client.get('/bar/shift/active/')
        data = resp.json()
        row = next(s for s in data['all_shifts'] if s['id'] == shift.id)
        self.assertEqual(row['started_at_iso'], shift.started_at.isoformat())
        self.assertEqual(row['staff_role'], 'waitress')


class ShiftHistorySearchTest(TestCase):
    """2026-08-12 live request (Roy): shift_history() had zero filter params
    — always the last 60 shifts. New preset/date-range/status/staff_id
    filters, staff-grouping for owner/manager, and a raised cap (500) only
    when a filter is actually active."""

    def setUp(self):
        self.biz = Business.objects.create(name='SHS Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.owner = User.objects.create_user(username='shs_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff_a = User.objects.create_user(username='shs_staff_a', password='x')
        UserProfile.objects.create(user=self.staff_a, business=self.biz, role='staff')
        self.staff_b = User.objects.create_user(username='shs_staff_b', password='x')
        UserProfile.objects.create(user=self.staff_b, business=self.biz, role='staff')

        today = timezone.localdate()
        self.today_shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff_a, status='CLOSED',
            opening_float=Decimal('0'),
            started_at=timezone.make_aware(timezone.datetime.combine(today, timezone.datetime.min.time().replace(hour=9))),
        )
        old_date = today - timezone.timedelta(days=20)
        self.old_shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff_b, status='CLOSED',
            opening_float=Decimal('0'),
            started_at=timezone.make_aware(timezone.datetime.combine(old_date, timezone.datetime.min.time().replace(hour=9))),
        )

    def test_preset_today_excludes_old_shift(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/shift/history/?preset=today')
        ids = [row['shift'].id for row in resp.context['rows'] if not row.get('is_group_header')]
        self.assertIn(self.today_shift.id, ids)
        self.assertNotIn(self.old_shift.id, ids)

    def test_custom_date_range(self):
        self.client.force_login(self.owner)
        today = timezone.localdate()
        old_date = today - timezone.timedelta(days=20)
        resp = self.client.get(
            f'/bar/shift/history/?date_from={old_date}&date_to={old_date}'
        )
        ids = [row['shift'].id for row in resp.context['rows'] if not row.get('is_group_header')]
        self.assertIn(self.old_shift.id, ids)
        self.assertNotIn(self.today_shift.id, ids)

    def test_status_filter(self):
        Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff_a, status='OPEN',
            opening_float=Decimal('0'),
        )
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/shift/history/?status=OPEN')
        rows = [row for row in resp.context['rows'] if not row.get('is_group_header')]
        self.assertTrue(all(row['shift'].status == 'OPEN' for row in rows))

    def test_staff_id_filter_owner_only(self):
        self.client.force_login(self.owner)
        resp = self.client.get(f'/bar/shift/history/?staff_id={self.staff_a.id}')
        ids = [row['shift'].id for row in resp.context['rows'] if not row.get('is_group_header')]
        self.assertIn(self.today_shift.id, ids)
        self.assertNotIn(self.old_shift.id, ids)

    def test_non_owner_staff_id_filter_ignored_stays_self_scoped(self):
        """A non-owner passing a foreign staff_id must NOT widen their view
        beyond their own shifts — regression lock on the existing identity
        scoping."""
        self.client.force_login(self.staff_a)
        resp = self.client.get(f'/bar/shift/history/?staff_id={self.staff_b.id}')
        ids = [row['shift'].id for row in resp.context['rows'] if not row.get('is_group_header')]
        self.assertNotIn(self.old_shift.id, ids)  # staff_b's shift never leaks in
        self.assertIn(self.today_shift.id, ids)   # staff_a's own shift still shows

    def test_owner_view_grouped_by_staff(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/shift/history/')
        headers = list(resp.context['grouped_rows'].keys())
        self.assertIn('shs_staff_a', headers)
        self.assertIn('shs_staff_b', headers)

    def test_default_view_unfiltered_unchanged(self):
        self.client.force_login(self.owner)
        resp = self.client.get('/bar/shift/history/')
        ids = [row['shift'].id for row in resp.context['rows'] if not row.get('is_group_header')]
        self.assertIn(self.today_shift.id, ids)
        self.assertIn(self.old_shift.id, ids)


class NotificationTimeoutTest(TestCase):
    """2026-08-12 live incident — every SMS/email send previously used the
    SDK's own generous default timeout (AT ~12s worst case, Resend 30s),
    letting a burst of a few notification-triggering actions occupy every
    available gunicorn thread long enough to miss Render's /health/ check.
    Both send_sms_notification() and send_email_notification() now pass an
    explicit, much shorter timeout — verify it's actually threaded through
    to the underlying SDK call, not just documented in a comment."""

    def test_sms_send_passes_shortened_timeout(self):
        from core import notifications
        with patch('africastalking.initialize'), \
             patch('africastalking.SMS') as mock_sms:
            mock_sms.send.return_value = {
                'SMSMessageData': {'Recipients': [{'status': 'Success'}]}
            }
            ok, detail = notifications.send_sms_notification('hi', '0712345678')
        self.assertTrue(ok)
        mock_sms.send.assert_called_once()
        _, kwargs = mock_sms.send.call_args
        self.assertEqual(kwargs.get('timeout'), (3, 5))

    def test_email_send_uses_shortened_timeout_client(self):
        from core import notifications
        from django.test import override_settings
        with override_settings(RESEND_API_KEY='test-key'):
            with patch('resend.Emails.send') as mock_send:
                mock_send.return_value = {'id': 'abc'}
                ok = notifications.send_email_notification(
                    'x@example.com', 'Subject', '<p>Hi</p>',
                )
        self.assertTrue(ok)
        import resend
        self.assertEqual(resend.default_http_client._timeout, 8)


class NotificationAsyncDispatchTest(TestCase):
    """2026-08-12 same-day follow-up — the deeper fix: make every SMS/email
    send genuinely non-blocking (fire-and-forget via a background daemon
    thread) rather than only shortening the network timeout, since even a
    shortened worst-case call can still tie up a request thread the health
    check needs. send_sms_notification()/send_email_notification() make no
    ORM calls at all, so unlike notify_transaction_async()'s own worker
    thread, there is no DB-connection-per-thread risk here."""

    def test_sms_async_returns_immediately_and_dispatches_in_background(self):
        from core import notifications
        import threading

        call_event = threading.Event()

        def slow_send(message, phone_number):
            call_event.wait(timeout=2)
            return True, ''

        with patch('core.notifications.send_sms_notification', side_effect=slow_send):
            start = timezone.now()
            notifications.send_sms_notification_async('hi', '0712345678')
            elapsed = (timezone.now() - start).total_seconds()
        # The caller must not have waited for the (still-blocked) send.
        self.assertLess(elapsed, 1.0)
        call_event.set()

    def test_email_async_returns_immediately_and_dispatches_in_background(self):
        from core import notifications
        import threading

        call_event = threading.Event()

        def slow_send(to_email, subject, html_message, text_message=None):
            call_event.wait(timeout=2)
            return True

        with patch('core.notifications.send_email_notification', side_effect=slow_send):
            start = timezone.now()
            notifications.send_email_notification_async('x@example.com', 'Subj', '<p>hi</p>')
            elapsed = (timezone.now() - start).total_seconds()
        self.assertLess(elapsed, 1.0)
        call_event.set()

    def test_sms_async_actually_dispatches_the_real_function(self):
        from core import notifications
        import time
        with patch('core.notifications.send_sms_notification') as mock_send:
            mock_send.return_value = (True, '')
            notifications.send_sms_notification_async('hi', '0712345678')
            # Background daemon thread — give it a moment to actually run.
            for _ in range(20):
                if mock_send.called:
                    break
                time.sleep(0.05)
        mock_send.assert_called_once_with('hi', '0712345678')

    def test_email_async_actually_dispatches_the_real_function(self):
        from core import notifications
        import time
        with patch('core.notifications.send_email_notification') as mock_send:
            mock_send.return_value = True
            notifications.send_email_notification_async('x@example.com', 'Subj', '<p>hi</p>')
            for _ in range(20):
                if mock_send.called:
                    break
                time.sleep(0.05)
        mock_send.assert_called_once_with('x@example.com', 'Subj', '<p>hi</p>', None)

    def test_sms_async_swallows_exceptions_without_crashing(self):
        from core import notifications
        import time
        with patch('core.notifications.send_sms_notification', side_effect=RuntimeError('boom')):
            # Must not raise — the whole point is the caller never blocks on
            # or is affected by the background send's own failure.
            notifications.send_sms_notification_async('hi', '0712345678')
            time.sleep(0.1)


class SlowRequestLoggingMiddlewareTest(TestCase):
    """2026-08-18 live incident (Roy, repeated 502s — "why does this keep
    happening, what else am I to do"): every prior fix was a good-faith
    guess from the health-check-timeout SIGNATURE alone — no production
    log ever showed which specific request was actually slow. This
    middleware closes that gap: any request taking >= 3s gets a
    "SLOW REQUEST" WARNING log line with its path and duration, so the
    NEXT incident is diagnosable from real evidence instead of another
    guess."""

    def test_slow_request_is_logged(self):
        from core.middleware import SlowRequestLoggingMiddleware
        import time as _time

        def slow_get_response(request):
            from django.http import HttpResponse
            return HttpResponse('ok')

        mw = SlowRequestLoggingMiddleware(slow_get_response)
        request = type('R', (), {'method': 'GET', 'get_full_path': lambda self: '/slow/'})()

        calls = iter([1000.0, 1004.5])  # 4.5s apart — over the 3s threshold
        with patch.object(_time, 'monotonic', lambda: next(calls)), \
             self.assertLogs('core.middleware', level='WARNING') as log_ctx:
            mw(request)
        self.assertTrue(any('SLOW REQUEST' in m for m in log_ctx.output))
        self.assertTrue(any('/slow/' in m for m in log_ctx.output))

    def test_fast_request_is_not_logged(self):
        from core.middleware import SlowRequestLoggingMiddleware
        import time as _time
        import logging

        def fast_get_response(request):
            from django.http import HttpResponse
            return HttpResponse('ok')

        mw = SlowRequestLoggingMiddleware(fast_get_response)
        request = type('R', (), {'method': 'GET', 'get_full_path': lambda self: '/fast/'})()

        calls = iter([1000.0, 1000.2])  # 0.2s — under the threshold
        logger = logging.getLogger('core.middleware')
        handler = logging.Handler()
        records = []
        handler.emit = records.append
        logger.addHandler(handler)
        try:
            with patch.object(_time, 'monotonic', lambda: next(calls)):
                mw(request)
        finally:
            logger.removeHandler(handler)
        self.assertFalse(any('SLOW REQUEST' in r.getMessage() for r in records))

    def test_end_to_end_real_request_is_fast_and_unlogged(self):
        """Sanity check against a real view through the real middleware
        stack — an ordinary page load must not trip this at all."""
        biz = Business.objects.create(name='Slow MW Biz')
        owner = User.objects.create_user(username='slowmw_owner', password='x')
        UserProfile.objects.create(user=owner, business=biz, role='owner')
        self.client.force_login(owner)
        with self.assertNoLogs('core.middleware', level='WARNING'):
            resp = self.client.get('/')
        self.assertEqual(resp.status_code, 200)


class DebtDashboardDuplicateComputationTest(TestCase):
    """2026-08-18, same live-incident investigation: debt_dashboard()
    computes _get_customer_debt_data() once per customer (itself not
    cheap — recurses into two full sub-computations for scope='all') and
    then, for owner/manager, recomputed it AGAIN from scratch for every
    customer appearing in a duplicate-name group — pure wasted work.
    Fixed to reuse the already-computed result. Flagged (not confirmed)
    as a credible contributor to the live slow-request/502 pattern for a
    business with a real customer base; this is a safe, mechanical
    dedup fix regardless."""

    def setUp(self):
        self.biz = Business.objects.create(name='Debt Dash Dup Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='ddd_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker',
            material_no='DDD-01', unit='Pcs', selling_price=Decimal('250'),
        )
        # Two Customer rows sharing a name — the duplicate-group scenario.
        self.cust_a = Customer.objects.create(business=self.biz, name='Peter')
        self.cust_b = Customer.objects.create(business=self.biz, name='Peter')
        for cust in (self.cust_a, self.cust_b):
            Transaction.objects.create(
                business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
                sale_amount=Decimal('250'), payment_method='credit', recipient=cust.name,
            )

    def test_get_customer_debt_data_called_at_most_once_per_customer(self):
        """_get_customer_debt_data(scope='all') recurses into itself once for
        'bar' and once for 'kitchen' — that recursion is real, unavoidable
        work, not the bug. What must NOT happen is a SECOND top-level
        (scope='all') call for a customer already computed in the main
        loop, so only scope='all' invocations are counted here."""
        from core import debt_views
        top_level_call_counts = {}
        original = debt_views._get_customer_debt_data

        def counting_wrapper(customer, business, scope='all'):
            if scope == 'all':
                top_level_call_counts[customer.id] = top_level_call_counts.get(customer.id, 0) + 1
            return original(customer, business, scope)

        self.client.force_login(self.owner)
        with patch('core.debt_views._get_customer_debt_data', side_effect=counting_wrapper):
            resp = self.client.get('/debt/')
        self.assertEqual(resp.status_code, 200)
        for cust_id, count in top_level_call_counts.items():
            self.assertEqual(
                count, 1,
                f'customer {cust_id} had {count} top-level (scope=\'all\') computations — '
                'duplicate-group lookup must reuse the already-computed result',
            )

    def test_duplicate_groups_still_show_correct_outstanding(self):
        # Both Customer rows share the name "Peter", and debt is matched by
        # recipient name (not the Customer FK) — so each row's own
        # _get_customer_debt_data() correctly sums BOTH transactions (this
        # is the real, documented duplicate-name behavior this app already
        # has a merge tool for, not something this fix changes).
        self.client.force_login(self.owner)
        resp = self.client.get('/debt/')
        groups = resp.context['duplicate_groups']
        self.assertEqual(len(groups), 1)
        outstandings = sorted(e['outstanding'] for e in groups[0])
        self.assertEqual(outstandings, [500.0, 500.0])


class TransactionDateCreatedAtSyncTest(TestCase):
    """2026-08-12 live report (Roy): "I backdated everything from 7th to
    11th... kitchen staff has not yet made sales but the system is showing
    as if it had." Root cause: Transaction.date defaults to timezone.now()
    AT CREATION TIME — a plain, independently-defaulted DateField,
    completely decoupled from any created_at= override — so every
    backdated sale (Quick Sell 2026-08-07, Kitchen Board 2026-08-09/12)
    silently kept date=today even though created_at correctly reflected
    the historical date. Kitchen Board's own "Leo" tile filtered on `date`,
    not `created_at`, so a week of backdated catch-up sales all counted as
    if they'd just happened. Fixed at both the write side (every backdating
    call site now sets date= alongside created_at=) and the read side
    (Kitchen Board's tile now uses the same created_at-anchored window
    home()'s dashboard already uses)."""

    def setUp(self):
        self.biz = Business.objects.create(name='Date Sync Biz', has_kitchen=True)
        self.store = Store.objects.create(business=self.biz, name='Kitchen', is_kitchen=True)
        self.owner = User.objects.create_user(username='dsync_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.kuku = Item.objects.create(
            business=self.biz, store=self.store, description='Kuku',
            material_no='DSYNC-KUKU', unit='Pcs', selling_price=Decimal('150'),
        )
        Transaction.objects.create(business=self.biz, item=self.kuku, type='Receipt', qty=Decimal('10'))
        self.chipo = Item.objects.create(
            business=self.biz, store=self.store, description='Chipo',
            material_no='DSYNC-CHIPO', unit='Batch', selling_price=Decimal('100'),
            is_kitchen_batch=True,
        )
        self.chipo_batch = KitchenBatch.objects.create(
            business=self.biz, store=self.store, item=self.chipo,
            cost_total=Decimal('1000'), status='OPEN', recorded_by=self.owner,
        )
        self.smokies = Item.objects.create(
            business=self.biz, store=self.store, description='Smokies',
            material_no='DSYNC-SMOKIES', unit='Batch', selling_price=Decimal('40'),
            is_produce=True, produce_mode='BUNCH',
        )
        self.bunch = ProduceBunch.objects.create(
            item=self.smokies, business=self.biz, size='LARGE',
            cost_price=Decimal('300'), target_revenue=Decimal('500'),
        )
        self.client.force_login(self.owner)

    def test_backdated_portion_sale_date_matches_created_at(self):
        import json as _json
        past_local = timezone.localtime(timezone.now() - timedelta(days=5)).replace(microsecond=0)
        cart = _json.dumps([{'item_id': self.kuku.id, 'qty': 1, 'amount': 150, 'description': 'Kuku'}])
        resp = self.client.post('/kitchen/', {
            'cart': cart, 'payment_method': 'cash',
            'backdated_at': past_local.strftime('%Y-%m-%dT%H:%M'),
        })
        self.assertTrue(resp.json().get('ok'), resp.json())
        txn = Transaction.objects.filter(business=self.biz, item=self.kuku, type='Issue').first()
        self.assertEqual(txn.date, past_local.date())

    def test_backdated_batch_sale_date_matches_created_at(self):
        import json as _json
        past_local = timezone.localtime(timezone.now() - timedelta(days=5)).replace(microsecond=0)
        cart = _json.dumps([{'batch_id': self.chipo_batch.id, 'qty': 1, 'amount': 100, 'description': 'Chipo — Ya 100'}])
        resp = self.client.post('/kitchen/', {
            'cart': cart, 'payment_method': 'cash',
            'backdated_at': past_local.strftime('%Y-%m-%dT%H:%M'),
        })
        self.assertTrue(resp.json().get('ok'), resp.json())
        txn = Transaction.objects.filter(business=self.biz, kitchen_batch=self.chipo_batch, type='Issue').first()
        self.assertEqual(txn.date, past_local.date())

    def test_backdated_bunch_sale_date_matches_created_at(self):
        import json as _json
        past_local = timezone.localtime(timezone.now() - timedelta(days=5)).replace(microsecond=0)
        cart = _json.dumps([{'bunch_id': self.bunch.id, 'qty': 1, 'amount': 40, 'description': 'Smokies — Ya 40'}])
        resp = self.client.post('/kitchen/', {
            'cart': cart, 'payment_method': 'cash',
            'backdated_at': past_local.strftime('%Y-%m-%dT%H:%M'),
        })
        self.assertTrue(resp.json().get('ok'), resp.json())
        txn = Transaction.objects.filter(business=self.biz, produce_bunch=self.bunch, type='Issue').first()
        self.assertEqual(txn.date, past_local.date())

    def test_kitchen_leo_tile_excludes_backdated_sale_entered_today(self):
        """The literal reported bug: a sale backdated to 5 days ago, entered
        right now (today), must NOT count toward Kitchen Board's own live
        "Leo" (today) revenue tile."""
        import json as _json
        past_local = timezone.localtime(timezone.now() - timedelta(days=5)).replace(microsecond=0)
        cart = _json.dumps([{'item_id': self.kuku.id, 'qty': 1, 'amount': 150, 'description': 'Kuku'}])
        self.client.post('/kitchen/', {
            'cart': cart, 'payment_method': 'cash',
            'backdated_at': past_local.strftime('%Y-%m-%dT%H:%M'),
        })
        resp = self.client.get('/kitchen/')
        self.assertEqual(resp.context['kitchen_revenue_today'], 0)

        resp2 = self.client.get('/kitchen/stats/')
        self.assertEqual(resp2.json()['revenue_today'], 0.0)

    def test_kitchen_leo_tile_still_shows_a_genuinely_todays_sale(self):
        """Regression lock — the fix must not also hide a REAL today sale."""
        import json as _json
        cart = _json.dumps([{'item_id': self.kuku.id, 'qty': 1, 'amount': 150, 'description': 'Kuku'}])
        self.client.post('/kitchen/', {'cart': cart, 'payment_method': 'cash'})
        resp = self.client.get('/kitchen/')
        self.assertEqual(resp.context['kitchen_revenue_today'], 150.0)


class TransactionDateBackfillCommandTest(TestCase):
    """Backfill for historical rows created before the 2026-08-12
    date/created_at sync fix — corrects Transaction.date to match
    created_at for every row that still disagrees."""

    def setUp(self):
        self.biz = Business.objects.create(name='Backfill Date Biz')
        self.store = Store.objects.create(business=self.biz, name='Shop')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Widget',
            material_no='BFD-1', unit='pcs', selling_price=Decimal('100'),
        )

    def test_dry_run_reports_but_does_not_change(self):
        from django.core.management import call_command
        import io
        past = timezone.now() - timedelta(days=5)
        drifted = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash', created_at=past,
        )
        self.assertNotEqual(drifted.date, past.date())
        out = io.StringIO()
        call_command('backfill_transaction_date_from_created_at', '--dry-run', stdout=out)
        drifted.refresh_from_db()
        self.assertNotEqual(drifted.date, timezone.localtime(past).date())
        self.assertIn('DRY RUN', out.getvalue())

    def test_corrects_drifted_rows(self):
        from django.core.management import call_command
        import io
        past = timezone.now() - timedelta(days=5)
        drifted = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash', created_at=past,
        )
        already_correct = Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('5'),
        )
        out = io.StringIO()
        call_command('backfill_transaction_date_from_created_at', stdout=out)
        drifted.refresh_from_db()
        already_correct.refresh_from_db()
        self.assertEqual(drifted.date, timezone.localtime(past).date())
        # Untouched row's date must not have been perturbed.
        self.assertEqual(already_correct.date, timezone.localtime(already_correct.created_at).date())
        self.assertIn('Corrected 1 transaction', out.getvalue())

    def test_rerun_is_a_no_op(self):
        from django.core.management import call_command
        import io
        past = timezone.now() - timedelta(days=5)
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=Decimal('100'), payment_method='cash', created_at=past,
        )
        call_command('backfill_transaction_date_from_created_at', stdout=io.StringIO())
        out2 = io.StringIO()
        call_command('backfill_transaction_date_from_created_at', stdout=out2)
        self.assertIn('Corrected 0 transaction', out2.getvalue())


class OwnerFacilitatedSalesAttributionTest(TestCase):
    """2026-08-22 (Roy Q&A + explicit confirmation, same-day): while a
    staffer's shift is open, the owner may also sell on the same counter
    (the owner never needs an open shift to sell at all) — those sales
    correctly blend into cash_sales/mpesa_sales/credit_sales/expected_cash
    (a real till doesn't care who rang it up). Roy's own precise framing
    once he confirmed the direction: the owner's share must be a pure
    attribution GUIDE ("of that KES 500, KES 200 was the owner") — already
    included in the figures shown, NEVER a second number added on top
    (his own worked example: cash 500 with owner 200 inside it, not 500 +
    200 = 700). Same-day follow-ups widened this from cash/mpesa/credit to
    also cover debt recovery ("debt placement and recovery too") and the
    dashboard's own revenue tiles/till breakdown ("im short every
    transactional aspect of the shift modal+revenue count on the
    dashboard") — see _reconcile(), till_expected_cash(), and
    station_revenue_window_info() in core/shift_views.py."""

    def setUp(self):
        self.biz = Business.objects.create(name='Owner Facilitated Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='ofa_owner', password='x')
        self.owner_profile = UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff_user = User.objects.create_user(username='ofa_staff', password='x')
        UserProfile.objects.create(user=self.staff_user, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker',
            material_no='OFA-01', unit='Bottle', selling_price=Decimal('200'),
        )

    def _open_shift(self, staff=None):
        staff = staff or self.staff_user
        shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=staff,
            opening_float=Decimal('0'), status='OPEN', station='bar',
            started_at=timezone.now() - timedelta(minutes=30),
        )
        return shift

    def _sale(self, amount, payment_method='cash', by=None, when=None, store=None):
        return Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal(str(amount)),
            payment_method=payment_method, recorded_by=by,
            created_at=when or timezone.now(),
        )

    def test_owner_sale_blends_into_totals_and_is_reported_as_a_guide(self):
        from core.shift_views import _reconcile
        shift = self._open_shift()
        self._sale(300, 'cash', by=self.staff_user)
        self._sale(200, 'cash', by=self.owner)
        rec = _reconcile(shift)
        # Blended total — the owner's sale is inside cash_sales, not beside it.
        self.assertAlmostEqual(rec['cash_sales'], 500.0, places=1)
        # Guide: exactly the owner's own share, never added a second time.
        self.assertAlmostEqual(rec['owner_facilitated_cash'], 200.0, places=1)
        self.assertAlmostEqual(rec['owner_facilitated_total'], 200.0, places=1)
        # The literal invariant Roy's own example demands: 500 total, never 700.
        self.assertLessEqual(rec['owner_facilitated_cash'], rec['cash_sales'])

    def test_mpesa_and_credit_also_guided_not_additive(self):
        from core.shift_views import _reconcile
        shift = self._open_shift()
        self._sale(150, 'mpesa', by=self.owner)
        self._sale(400, 'mpesa', by=self.staff_user)
        self._sale(90, 'credit', by=self.owner)
        rec = _reconcile(shift)
        self.assertAlmostEqual(rec['mpesa_sales'], 550.0, places=1)
        self.assertAlmostEqual(rec['owner_facilitated_mpesa'], 150.0, places=1)
        self.assertAlmostEqual(rec['credit_sales'], 90.0, places=1)
        self.assertAlmostEqual(rec['owner_facilitated_credit'], 90.0, places=1)
        self.assertAlmostEqual(
            rec['owner_facilitated_total'],
            rec['owner_facilitated_cash'] + rec['owner_facilitated_mpesa'] + rec['owner_facilitated_credit'],
            places=1,
        )

    def test_owner_sale_before_shift_started_excluded(self):
        from core.shift_views import _reconcile
        shift = self._open_shift()
        # Owner sold an hour before this staffer's shift even opened.
        self._sale(500, 'cash', by=self.owner, when=shift.started_at - timedelta(hours=1))
        rec = _reconcile(shift)
        self.assertAlmostEqual(rec['cash_sales'], 0.0, places=1)
        self.assertAlmostEqual(rec['owner_facilitated_cash'], 0.0, places=1)

    def test_owners_own_shift_never_self_attributes(self):
        from core.shift_views import _reconcile
        owner_shift = self._open_shift(staff=self.owner)
        self._sale(300, 'cash', by=self.owner)
        rec = _reconcile(owner_shift)
        self.assertAlmostEqual(rec['cash_sales'], 300.0, places=1)
        self.assertAlmostEqual(rec['owner_facilitated_cash'], 0.0, places=1)
        self.assertAlmostEqual(rec['owner_facilitated_total'], 0.0, places=1)

