class RevertDirectSaleToTabReceiptDisplayTest(TestCase):
    """2026-08-25 live audit (Roy: "when an item sold mode of payment is
    reverted or adjusted... does it effectively adjust everywhere the money
    touches and displays... in real time?"). Traced _live_direct_lines()
    and found a real gap: a revert_direct_sale_to_tab correction was
    invisible to it entirely — the whole-sale case mutates the ORIGINAL
    transaction in place (payment_method -> 'credit', not 'void'), so it
    hit neither the void-drop check nor the split-child path, and rendered
    on the original receipt exactly like a normal, fully-paid, complete
    sale forever, with no indication the item now sits UNPAID on a
    (possibly different-named) customer's open tab. The partial case DID
    route through the same split mechanism as Gawanya, but its synthesized
    child line carried no status marker either, looking identical to an
    ordinary paid line. Fixed: any transaction (parent or split child) that
    now has a live BarTabEntry is marked `moved_to_tab` (with the tab's
    customer name) while still unpaid, excluded from the receipt's own
    total, and self-heals to `is_paid=True` (counted normally again) once
    that tab entry is later settled through the ordinary tab mechanisms."""

    def setUp(self):
        self.biz = Business.objects.create(name='RTT Receipt Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='rttr_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.seller = User.objects.create_user(username='rttr_seller', password='x')
        UserProfile.objects.create(user=self.seller, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Whitecap',
            material_no='RTTR-1', unit='Pcs', selling_price=Decimal('100'),
            cost_price=Decimal('60'),
        )

    def _make_receipt_and_txn(self, sale_amount=Decimal('100')):
        txn = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue', qty=Decimal('-1'),
            sale_amount=sale_amount, payment_method='mpesa', recorded_by=self.seller,
        )
        receipt = Receipt.objects.create(
            business=self.biz, customer_name='Walk-in',
            lines=[{'name': 'Whitecap', 'qty': 1, 'subtotal': float(sale_amount), 'txn_id': txn.id}],
            total=sale_amount, payment_method='mpesa',
            token='rttr-tok', receipt_number=1,
        )
        return receipt, txn

    def test_whole_sale_revert_marks_line_moved_to_tab(self):
        """The zero-paid (paid_amount<=0) revert case — no split at all,
        the original transaction is mutated in place. Before this fix,
        _live_direct_lines() returned None here (nothing it recognised as
        changed), so the stale static line kept showing as a normal,
        fully-paid sale."""
        from core.receipt_views import _live_direct_lines, _direct_lines_total
        receipt, txn = self._make_receipt_and_txn()
        Transaction.revert_direct_sale_to_tab_locked(
            txn_id=txn.id, business=self.biz, paid_amount=0, customer_name='Bosco',
        )
        live_lines = _live_direct_lines(receipt)
        self.assertIsNotNone(live_lines, 'must now detect the moved line as a real change')
        self.assertEqual(len(live_lines), 1)
        self.assertEqual(live_lines[0]['moved_to_tab'], 'Bosco')
        self.assertNotIn('is_paid', live_lines[0])
        self.assertEqual(_direct_lines_total(live_lines), 0.0, 'not part of this receipt\'s own total until settled')

    def test_partial_revert_marks_only_the_owed_child_line(self):
        """The paid_amount>0 case — routes through the same split
        mechanism as Gawanya. The PAID portion must display and count
        normally; only the split-off OWED child gets moved_to_tab."""
        from core.receipt_views import _live_direct_lines, _direct_lines_total
        receipt, txn = self._make_receipt_and_txn()
        Transaction.revert_direct_sale_to_tab_locked(
            txn_id=txn.id, business=self.biz, paid_amount=40, customer_name='Bosco',
        )
        live_lines = _live_direct_lines(receipt)
        self.assertIsNotNone(live_lines)
        self.assertEqual(len(live_lines), 2)
        paid_line = next(l for l in live_lines if 'moved_to_tab' not in l)
        owed_line = next(l for l in live_lines if 'moved_to_tab' in l)
        self.assertEqual(paid_line['subtotal'], 40.0)
        self.assertEqual(owed_line['moved_to_tab'], 'Bosco')
        self.assertEqual(owed_line['subtotal'], 60.0)
        # Total counts the genuinely-paid 40 but not the still-owed 60.
        self.assertEqual(_direct_lines_total(live_lines), 40.0)

    def test_line_self_heals_to_paid_once_the_tab_entry_is_settled(self):
        """Once Bosco's tab entry for this item is later settled through
        the ordinary tab mechanisms, the ORIGINAL receipt must reflect
        that too — money genuinely collected, just via a different final
        path — matching every other live-recomputed state in this file."""
        from core.receipt_views import _live_direct_lines, _direct_lines_total
        receipt, txn = self._make_receipt_and_txn()
        _, owed_txn, tab, entry = Transaction.revert_direct_sale_to_tab_locked(
            txn_id=txn.id, business=self.biz, paid_amount=0, customer_name='Bosco',
        )
        entry.is_paid = True
        entry.save(update_fields=['is_paid'])
        live_lines = _live_direct_lines(receipt)
        self.assertIsNotNone(live_lines)
        self.assertTrue(live_lines[0].get('is_paid'))
        self.assertNotIn('moved_to_tab', live_lines[0])
        self.assertEqual(_direct_lines_total(live_lines), 100.0, 'now genuinely collected, counted again')

    def test_public_receipt_endpoint_reflects_moved_line_live(self):
        """End-to-end through the real public_receipt() view — not just
        the helper function in isolation."""
        receipt, txn = self._make_receipt_and_txn()
        Transaction.revert_direct_sale_to_tab_locked(
            txn_id=txn.id, business=self.biz, paid_amount=0, customer_name='Bosco',
        )
        resp = self.client.get(f'/r/{receipt.token}/')
        self.assertEqual(resp.status_code, 200)
        self.assertContains(resp, 'Bosco')
        self.assertContains(resp, 'bado inadaiwa')

    def test_receipt_live_status_poll_reflects_moved_line(self):
        """End-to-end through the real receipt_live_status() poll endpoint
        (the 20s live poll) — confirms the SAME fix applies there, not
        just the initial page render, per Roy's own "in real time" ask."""
        receipt, txn = self._make_receipt_and_txn()
        Transaction.revert_direct_sale_to_tab_locked(
            txn_id=txn.id, business=self.biz, paid_amount=0, customer_name='Bosco',
        )
        resp = self.client.get(f'/r/{receipt.token}/live/')
        self.assertEqual(resp.status_code, 200)
        d = resp.json()
        self.assertEqual(d['total'], 0.0)
        self.assertEqual(d['lines'][0]['moved_to_tab'], 'Bosco')

    def test_gawanya_split_receipt_display_unaffected(self):
        """Regression lock: an ORDINARY Gawanya split (both resulting
        transactions genuinely paid, just via two different channels — no
        tab involved at all) must never be marked moved_to_tab, and both
        halves must still count fully toward the total, exactly as before
        this fix."""
        from core.receipt_views import _live_direct_lines, _direct_lines_total
        receipt, txn = self._make_receipt_and_txn()
        Transaction.split_payment_method_locked(
            txn_id=txn.id, business=self.biz, split_amount=Decimal('30'), new_method='cash',
        )
        live_lines = _live_direct_lines(receipt)
        self.assertIsNotNone(live_lines)
        for l in live_lines:
            self.assertNotIn('moved_to_tab', l)
        self.assertEqual(_direct_lines_total(live_lines), 100.0)

    def test_void_line_still_dropped_entirely_unaffected(self):
        """Regression lock: the pre-existing void-drop behavior (2026-08-21)
        must be completely unchanged by this fix."""
        from core.receipt_views import _live_direct_lines
        receipt, txn = self._make_receipt_and_txn()
        self.client.force_login(self.owner)
        self.client.post(f'/bar/transactions/{txn.id}/void/', {'reason': 'mistake'})
        live_lines = _live_direct_lines(receipt)
        self.assertIsNotNone(live_lines)
        self.assertEqual(live_lines, [])


class StockVarianceTheftVerdictTest(TestCase):
    """2026-08-26 (Roy, live — "the purpose of this level of scrutiny is to
    capture theft"): full redesign of review_variance()'s dismiss ('Kataa')
    action. Before: dismiss meant only "I don't believe this explanation" —
    the book balance was never corrected and nothing distinguished an
    innocent mistake from something deliberate. After: dismiss now means "I
    believe this was NOT innocent" — the SAME kind of corrective transaction
    'accept' already created is created immediately and permanently
    (tagged '[THEFT]'), but the row enters a DISPUTED appeal window
    (Business.variance_dispute_window_hours) before the ACCUSATION against
    the staffer (never the stock correction itself) becomes permanent. The
    owner can finalize early, or reconsider (accept<->dismiss) at any point
    — reconsidering only ever flips owner_accepted/compliance_noted/status,
    never touching the already-created corrective_txn or the stock balance
    it moved.
    """

    def setUp(self):
        from core.models import StockVarianceQuery, StockTake
        self.StockVarianceQuery = StockVarianceQuery
        self.StockTake = StockTake

        self.biz = Business.objects.create(name='Theft Verdict Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='theft_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.manager_user = User.objects.create_user(username='theft_manager', password='x')
        UserProfile.objects.create(user=self.manager_user, business=self.biz, role='manager')
        self.staff_user = User.objects.create_user(
            username='theft_staff', password='x', first_name='Aisha',
        )
        self.staff_profile = UserProfile.objects.create(
            user=self.staff_user, business=self.biz, role='staff', phone='0711222333',
        )
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Theft Verdict Item',
            material_no='THEFT-01', unit='pcs', selling_price=Decimal('100'),
            cost_price=Decimal('60'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('20'),
        )
        self.stock_take = StockTake.objects.create(business=self.biz, store=self.store)
        self.client.force_login(self.owner)

    def _make_variance(self, direction=None, book=Decimal('20'), actual=Decimal('15')):
        return self.StockVarianceQuery.objects.create(
            stock_take=self.stock_take, item=self.item, item_name_cache=self.item.description,
            book_balance=book, actual_count=actual,
            direction=direction or self.StockVarianceQuery.DECREASE,
            queried_staff=self.staff_profile,
        )

    def _dismiss(self, svq, note=''):
        return self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'dismiss', 'owner_response_note': note,
        })

    def _accept(self, svq, note=''):
        return self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'wastage', 'owner_response_note': note,
        })

    # ── First-time dismiss: the physical correction happens immediately ──

    def test_first_dismiss_creates_corrective_wastage_transaction_immediately(self):
        svq = self._make_variance()
        balance_before = self.item.current_balance()
        resp = self._dismiss(svq, note='Muundo wa wizi unaonekana')
        self.assertTrue(resp.json()['ok'], resp.json())
        svq.refresh_from_db()
        self.assertIsNotNone(svq.corrective_txn)
        self.assertEqual(svq.corrective_txn.type, 'Wastage')
        self.assertEqual(svq.corrective_txn.invoice_no, '[THEFT]')
        self.assertEqual(svq.corrective_txn.qty, Decimal('-5'))
        # "the business owner cannot fail to replenish stock" — balance is
        # corrected to the physical count immediately, same as accept would.
        self.assertEqual(self.item.current_balance(), balance_before - Decimal('5'))
        self.assertEqual(self.item.current_balance(), Decimal('15'))

    def _make_increase_variance(self, book=Decimal('20'), actual=Decimal('25')):
        return self._make_variance(direction=self.StockVarianceQuery.INCREASE, book=book, actual=actual)

    # ── INCREASE direction (2026-08-26, same-day redesign): never theft —
    # always reasoned about as an unrecorded RECEIPT. ──────────────────────

    def test_increase_accept_creates_receipt_with_default_cost_price(self):
        # No owner_cost_price given — falls back to the item's CURRENT
        # cost_price ("like the previous receipt"), per Roy's own wording.
        svq = self._make_increase_variance()
        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'receipt',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        svq.refresh_from_db()
        self.assertEqual(svq.corrective_txn.type, 'Receipt')
        self.assertEqual(svq.corrective_txn.qty, Decimal('5'))
        self.assertEqual(self.item.current_balance(), Decimal('25'))
        self.item.refresh_from_db()
        self.assertEqual(self.item.cost_price, Decimal('60'))  # unchanged, already the default
        self.assertFalse(svq.compliance_noted)
        self.assertEqual(svq.status, self.StockVarianceQuery.RESOLVED)

    def test_increase_accept_with_explicit_cost_price_updates_item(self):
        svq = self._make_increase_variance()
        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'receipt', 'owner_cost_price': '75.50',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        self.item.refresh_from_db()
        self.assertEqual(self.item.cost_price, Decimal('75.50'))

    def test_increase_accept_never_asks_for_sale_type(self):
        # The old (pre-2026-08-26) code path used to ignore direction and
        # always create a Receipt regardless of owner_response_type — this
        # locks in that cash/mpesa/credit language plays no role at all.
        svq = self._make_increase_variance()
        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'cash',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        svq.refresh_from_db()
        self.assertEqual(svq.corrective_txn.type, 'Receipt')
        self.assertEqual(svq.corrective_txn.payment_method, '')

    def test_increase_dismiss_creates_no_correction_and_no_theft_consequence(self):
        svq = self._make_increase_variance()
        balance_before = self.item.current_balance()
        resp = self._dismiss(svq, note='Sikuamini kuwa kilipokewa')
        self.assertTrue(resp.json()['ok'], resp.json())
        svq.refresh_from_db()
        self.assertIsNone(svq.corrective_txn)
        self.assertFalse(svq.owner_accepted)
        self.assertFalse(svq.compliance_noted)  # never a theft/performance strike
        self.assertEqual(svq.status, self.StockVarianceQuery.RESOLVED)
        self.assertIsNone(svq.dispute_deadline)  # never enters DISPUTED
        self.assertEqual(self.item.current_balance(), balance_before)  # stock untouched

    def test_increase_dismiss_never_tagged_theft_or_disputed(self):
        from core.stock_take_views import item_has_pending_variance
        svq = self._make_increase_variance()
        self._dismiss(svq)
        svq.refresh_from_db()
        self.assertNotEqual(svq.status, self.StockVarianceQuery.DISPUTED)
        # Item unlocks immediately regardless.
        self.assertFalse(item_has_pending_variance(self.item.id))

    def test_increase_dismiss_notifies_staff_without_theft_wording(self):
        svq = self._make_increase_variance()
        self._dismiss(svq)
        notif = Notification.objects.filter(
            user=self.staff_user, title__icontains='Hesabu Haikukubaliwa',
        ).first()
        self.assertIsNotNone(notif)
        self.assertIn('SI tofauti ya wizi', notif.message)

    @patch('core.stock_take_views.send_sms_notification_async')
    def test_increase_dismiss_never_sends_sms(self, mock_sms):
        # Unlike the decrease theft verdict (which SMSes urgently), a
        # neutral "not accepted" carries no urgency.
        svq = self._make_increase_variance()
        self._dismiss(svq)
        self.assertFalse(mock_sms.called)

    def test_increase_dismiss_after_accept_never_reverses_the_receipt(self):
        # Owner accepted (Receipt created), later reconsiders to "not
        # accepted" — Roy's "never touch the stock a second time" rule
        # applies here too, even without any theft framing to walk back.
        svq = self._make_increase_variance()
        self._accept(svq)
        svq.refresh_from_db()
        original_txn_id = svq.corrective_txn_id
        balance_after_accept = self.item.current_balance()

        resp = self._dismiss(svq, note='Nimebadilisha wazo')
        self.assertTrue(resp.json()['ok'], resp.json())
        svq.refresh_from_db()
        self.assertFalse(svq.owner_accepted)
        self.assertFalse(svq.compliance_noted)
        self.assertEqual(svq.corrective_txn_id, original_txn_id)  # never reversed
        self.assertEqual(self.item.current_balance(), balance_after_accept)

    def test_increase_accept_after_dismiss_performs_the_deferred_receipt(self):
        # First dismiss (no correction created), then reconsider to accept
        # — the Receipt must be created NOW, since none exists yet. This is
        # exactly why `has_correction` (not `owner_accepted is not None`)
        # is the real signal for whether 'accept' still needs to DO the
        # correction.
        svq = self._make_increase_variance()
        self._dismiss(svq)
        svq.refresh_from_db()
        self.assertIsNone(svq.corrective_txn)
        balance_before = self.item.current_balance()

        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'receipt', 'owner_cost_price': '65',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertIn('MAREKEBISHO', resp.json()['message'])
        svq.refresh_from_db()
        self.assertIsNotNone(svq.corrective_txn)
        self.assertEqual(svq.corrective_txn.type, 'Receipt')
        self.assertTrue(svq.owner_accepted)
        self.assertEqual(self.item.current_balance(), balance_before + Decimal('5'))
        self.item.refresh_from_db()
        self.assertEqual(self.item.cost_price, Decimal('65'))

    def test_increase_never_reaches_finalize_now(self):
        svq = self._make_increase_variance()
        self._dismiss(svq)
        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {'action': 'finalize_now'})
        self.assertFalse(resp.json()['ok'])

    def test_theft_tagged_transaction_counts_as_a_real_loss_unlike_adj_noloss(self):
        # Deliberately NOT excluded from P&L/analytics — a real loss, unlike
        # the [ADJ-NOLOSS] convention for a phantom-balance correction.
        svq = self._make_variance()
        self._dismiss(svq)
        svq.refresh_from_db()
        self.assertNotEqual(svq.corrective_txn.invoice_no, '[ADJ-NOLOSS]')
        self.assertEqual(svq.corrective_txn.loss_value(), Decimal('300'))  # 5 * cost_price 60

    def test_first_dismiss_sets_disputed_status_with_deadline(self):
        svq = self._make_variance()
        before = timezone.now()
        self._dismiss(svq)
        svq.refresh_from_db()
        self.assertEqual(svq.status, self.StockVarianceQuery.DISPUTED)
        self.assertFalse(svq.owner_accepted)
        self.assertTrue(svq.compliance_noted)
        self.assertIsNotNone(svq.dispute_deadline)
        # Default window is 48h.
        expected = before + timedelta(hours=48)
        self.assertAlmostEqual(
            (svq.dispute_deadline - expected).total_seconds(), 0, delta=10,
        )

    def test_disputed_window_uses_business_configured_hours(self):
        self.biz.variance_dispute_window_hours = 6
        self.biz.save(update_fields=['variance_dispute_window_hours'])
        svq = self._make_variance()
        before = timezone.now()
        self._dismiss(svq)
        svq.refresh_from_db()
        expected = before + timedelta(hours=6)
        self.assertAlmostEqual(
            (svq.dispute_deadline - expected).total_seconds(), 0, delta=10,
        )

    def test_item_sellable_again_immediately_on_dismiss_not_waiting_for_window(self):
        from core.stock_take_views import item_has_pending_variance
        svq = self._make_variance()
        self.assertTrue(item_has_pending_variance(self.item.id))
        self._dismiss(svq)
        # "another staff's mess should not affect her normal operations" —
        # unblocked the instant the owner decides, never waiting for the
        # appeal window to close.
        self.assertFalse(item_has_pending_variance(self.item.id))

    def test_accused_staffer_notified_with_deadline_and_sms(self):
        svq = self._make_variance()
