class VarianceLossKesDisputedExclusionTest(TestCase):
    """2026-08-26 companion to VarianceLossKesAffirmationTest: a DISPUTED row
    (a theft verdict still within its appeal window) must not yet count
    against the staffer's own recognition/Haki record — only once it's
    genuinely RESOLVED (finalized, whether by timeout, 'Thibitisha Sasa', or
    staying firm after a response) does Roy's "the verdict now becomes
    permanent" framing actually take effect."""

    def setUp(self):
        from core.models import Shift, StockTake, StockVarianceQuery
        self.StockVarianceQuery = StockVarianceQuery
        self.biz = Business.objects.create(name='VL Disputed Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar', is_kitchen=False)
        self.staff_user = User.objects.create_user(username='vld_staff', password='x')
        self.staff_profile = UserProfile.objects.create(user=self.staff_user, business=self.biz, role='staff')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='VLD Item',
            material_no='VLD-01', unit='pcs', selling_price=Decimal('100'),
        )
        self.shift = Shift.objects.create(
            business=self.biz, store=self.store, staff=self.staff_user,
            started_at=timezone.now() - timedelta(hours=2), status='OPEN',
        )
        self.stock_take = StockTake.objects.create(business=self.biz, shift=self.shift, conducted_by=self.staff_user)

    def _make_variance(self, estimated_revenue, status, owner_accepted=False):
        from core.models import StockVarianceQuery
        return StockVarianceQuery.objects.create(
            stock_take=self.stock_take, item=self.item, item_name_cache=self.item.description,
            book_balance=Decimal('10'), actual_count=Decimal('8'), direction='decrease',
            estimated_revenue=Decimal(str(estimated_revenue)),
            queried_staff=self.staff_profile, attributed_shift=self.shift,
            owner_accepted=owner_accepted, compliance_noted=True, status=status,
        )

    def test_disputed_row_excluded_while_appeal_window_open(self):
        self._make_variance(600, status=self.StockVarianceQuery.DISPUTED)
        contrib = _staff_contribution_helper(self.staff_profile, self.biz)
        self.assertEqual(contrib['variance_loss_kes'], 0)
        self.assertEqual(len(contrib['unaffirmed_variances']), 0)

    def test_same_row_counts_once_finalized_resolved(self):
        svq = self._make_variance(600, status=self.StockVarianceQuery.DISPUTED)
        self.StockVarianceQuery.objects.filter(id=svq.id).update(
            status=self.StockVarianceQuery.RESOLVED, dispute_deadline=None,
        )
        contrib = _staff_contribution_helper(self.staff_profile, self.biz)
        self.assertEqual(contrib['variance_loss_kes'], 600)
        self.assertEqual(len(contrib['unaffirmed_variances']), 1)

    def test_mixed_disputed_and_resolved_sums_only_resolved(self):
        self._make_variance(300, status=self.StockVarianceQuery.DISPUTED)   # excluded (still disputed)
        self._make_variance(400, status=self.StockVarianceQuery.RESOLVED)   # counts (finalized theft)
        contrib = _staff_contribution_helper(self.staff_profile, self.biz)
        self.assertEqual(contrib['variance_loss_kes'], 400)
        self.assertEqual(len(contrib['unaffirmed_variances']), 1)


class IncreaseVariancePresetMatchingTest(TestCase):
    """2026-08-26 same-day follow-up (Roy, live — Blue Ice showing a +0.06
    increase variance and offered a flat 'accept as receipt' with no regard
    for presets): 'the cost price division should be according to preset'
    — a variance matching a configured preset's own quantity_consumed
    (a portion of a bottle, e.g. Robo=0.25) routes the accept-time cost
    into THAT preset's own cost_price, never the item's flat whole-bottle
    cost_price. A variance matching NOTHING (a whole number, or an odd
    fraction like the reported 0.06 — very likely accumulated preset-
    fraction drift, see diagnose_stock_shortfalls' own 2026-08-21 finding)
    falls back to the original flat item.cost_price behaviour."""

    def setUp(self):
        from core.models import StockVarianceQuery, StockTake
        self.StockVarianceQuery = StockVarianceQuery
        self.biz = Business.objects.create(name='Preset Match Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='pmatch_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Blue Ice',
            material_no='PMATCH-01', unit='btl', selling_price=Decimal('200'),
            cost_price=Decimal('1200'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('20'),
        )
        self.robo = ItemPortionPreset.objects.create(
            item=self.item, label='Robo', price=Decimal('350'),
            quantity_consumed=Decimal('0.25'),
        )
        self.nusu = ItemPortionPreset.objects.create(
            item=self.item, label='Nusu', price=Decimal('650'),
            quantity_consumed=Decimal('0.5'),
        )
        self.stock_take = StockTake.objects.create(business=self.biz, store=self.store)
        self.client.force_login(self.owner)

    def _make_variance(self, book, actual):
        return self.StockVarianceQuery.objects.create(
            stock_take=self.stock_take, item=self.item, item_name_cache=self.item.description,
            book_balance=book, actual_count=actual,
            direction=self.StockVarianceQuery.INCREASE,
        )

    # ── _matching_preset_for_increase() — unit coverage ───────────────────

    def test_matches_exact_preset_fraction(self):
        from core.stock_take_views import _matching_preset_for_increase
        result = _matching_preset_for_increase(self.item, Decimal('0.25'))
        self.assertEqual(result.id, self.robo.id)

    def test_matches_within_small_tolerance(self):
        from core.stock_take_views import _matching_preset_for_increase
        result = _matching_preset_for_increase(self.item, Decimal('0.248'))
        self.assertEqual(result.id, self.robo.id)

    def test_no_match_for_whole_number(self):
        from core.stock_take_views import _matching_preset_for_increase
        result = _matching_preset_for_increase(self.item, Decimal('1'))
        self.assertIsNone(result)

    def test_no_match_for_odd_non_preset_fraction(self):
        # The literal reported figure — matches nothing.
        from core.stock_take_views import _matching_preset_for_increase
        result = _matching_preset_for_increase(self.item, Decimal('0.06'))
        self.assertIsNone(result)

    def test_closest_match_wins_when_two_presets_are_close(self):
        from core.stock_take_views import _matching_preset_for_increase
        farther = ItemPortionPreset.objects.create(
            item=self.item, label='Farther', price=Decimal('900'),
            quantity_consumed=Decimal('0.745'),  # diff 0.005 from target
        )
        closer = ItemPortionPreset.objects.create(
            item=self.item, label='Closer', price=Decimal('900'),
            quantity_consumed=Decimal('0.752'),  # diff 0.002 from target
        )
        result = _matching_preset_for_increase(self.item, Decimal('0.75'))
        self.assertEqual(result.id, closer.id)

    def test_no_presets_at_all_returns_none(self):
        from core.stock_take_views import _matching_preset_for_increase
        bare_item = Item.objects.create(
            business=self.biz, store=self.store, description='No Presets Here',
            material_no='PMATCH-02', unit='pcs', selling_price=Decimal('10'),
        )
        result = _matching_preset_for_increase(bare_item, Decimal('0.25'))
        self.assertIsNone(result)

    # ── review_variance() accept — routes cost into the matched preset ────

    def test_accept_matching_preset_sets_preset_cost_not_item_cost(self):
        svq = self._make_variance(book=Decimal('20'), actual=Decimal('20.25'))
        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'receipt', 'owner_cost_price': '80',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        svq.refresh_from_db()
        self.assertEqual(svq.corrective_txn.preset_id, self.robo.id)
        self.robo.refresh_from_db()
        self.assertEqual(self.robo.cost_price, Decimal('80'))
        self.item.refresh_from_db()
        self.assertEqual(self.item.cost_price, Decimal('1200'))  # untouched

    def test_accept_matching_preset_with_no_cost_given_defaults_to_item_cost_price(self):
        # Preset has no cost_price of its own yet — falls back to the
        # item's whole-bottle cost_price (same per-whole-unit basis).
        svq = self._make_variance(book=Decimal('20'), actual=Decimal('20.5'))
        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'receipt',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        self.nusu.refresh_from_db()
        self.assertEqual(self.nusu.cost_price, Decimal('1200'))
        self.item.refresh_from_db()
        self.assertEqual(self.item.cost_price, Decimal('1200'))  # untouched either way

    def test_accept_matching_preset_reuses_its_own_existing_cost_price_as_default(self):
        self.robo.cost_price = Decimal('310')
        self.robo.save(update_fields=['cost_price'])
        svq = self._make_variance(book=Decimal('20'), actual=Decimal('20.25'))
        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'receipt',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        self.robo.refresh_from_db()
        self.assertEqual(self.robo.cost_price, Decimal('310'))  # left as its own value

    def test_accept_whole_number_variance_still_updates_item_cost_price(self):
        # Regression lock: a genuine whole-bottle delivery is completely
        # unaffected by the preset-matching logic.
        svq = self._make_variance(book=Decimal('20'), actual=Decimal('21'))
        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'receipt', 'owner_cost_price': '1350',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        svq.refresh_from_db()
        self.assertIsNone(svq.corrective_txn.preset_id)
        self.item.refresh_from_db()
        self.assertEqual(self.item.cost_price, Decimal('1350'))
        self.robo.refresh_from_db()
        self.nusu.refresh_from_db()
        self.assertIsNone(self.robo.cost_price)
        self.assertIsNone(self.nusu.cost_price)

    def test_accept_odd_fraction_falls_back_to_item_cost_price(self):
        svq = self._make_variance(book=Decimal('20'), actual=Decimal('20.06'))
        resp = self.client.post(f'/stock/variances/{svq.id}/review/', {
            'action': 'accept', 'owner_response_type': 'receipt',
        })
        self.assertTrue(resp.json()['ok'], resp.json())
        svq.refresh_from_db()
        self.assertIsNone(svq.corrective_txn.preset_id)
        self.robo.refresh_from_db()
        self.assertIsNone(self.robo.cost_price)

    # ── pending_variances() view context — matched_preset/looks_like_drift ──

    def test_view_context_attaches_matched_preset_for_pending_row(self):
        self._make_variance(book=Decimal('20'), actual=Decimal('20.25'))
        resp = self.client.get('/stock/variances/')
        self.assertEqual(resp.status_code, 200)
        row = resp.context['pending'][0]
        self.assertEqual(row.matched_preset.id, self.robo.id)
        self.assertFalse(row.looks_like_drift)

    def test_view_context_flags_looks_like_drift_for_unmatched_fraction(self):
        self._make_variance(book=Decimal('20'), actual=Decimal('20.06'))
        resp = self.client.get('/stock/variances/')
        row = resp.context['pending'][0]
        self.assertIsNone(row.matched_preset)
        self.assertTrue(row.looks_like_drift)

    def test_view_context_no_drift_flag_for_whole_number(self):
        self._make_variance(book=Decimal('20'), actual=Decimal('21'))
        resp = self.client.get('/stock/variances/')
        row = resp.context['pending'][0]
        self.assertIsNone(row.matched_preset)
        self.assertFalse(row.looks_like_drift)

    def test_pending_page_renders_matched_preset_hint(self):
        self._make_variance(book=Decimal('20'), actual=Decimal('20.25'))
        resp = self.client.get('/stock/variances/')
        self.assertContains(resp, 'Robo')

    def test_pending_page_renders_drift_warning(self):
        self._make_variance(book=Decimal('20'), actual=Decimal('20.06'))
        resp = self.client.get('/stock/variances/')
        self.assertContains(resp, 'si kipimo')

    def test_decrease_direction_never_gets_matched_preset(self):
        svq = self.StockVarianceQuery.objects.create(
            stock_take=self.stock_take, item=self.item, item_name_cache=self.item.description,
            book_balance=Decimal('20'), actual_count=Decimal('19.75'),
            direction=self.StockVarianceQuery.DECREASE,
        )
        resp = self.client.get('/stock/variances/')
        row = [r for r in resp.context['pending'] if r.id == svq.id][0]
        self.assertIsNone(row.matched_preset)
        self.assertFalse(row.looks_like_drift)


class DiagnoseStockShortfallsPresetDumpTest(TestCase):
    """2026-08-26 — diagnose_stock_shortfalls now dumps an item's CURRENT
    preset configuration up front, since 'presets never picked up' could
    mean zero presets are saved against THIS item id at all (a config
    problem Quick Sell/Bar Board would show as a plain tile with no
    picker) rather than a balance-math problem."""

    def setUp(self):
        self.biz = Business.objects.create(name='Preset Dump Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')

    def test_no_presets_prints_none_and_a_hint(self):
        from io import StringIO
        from django.core.management import call_command
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Bare Spirit',
            material_no='PDUMP-01', unit='btl', selling_price=Decimal('200'),
        )
        out = StringIO()
        call_command('diagnose_stock_shortfalls', business='Preset Dump Biz', item='Bare Spirit', stdout=out)
        output = out.getvalue()
        self.assertIn('Portion presets configured for THIS item id (0)', output)
        self.assertIn('NONE.', output)

    def test_presets_are_listed_with_their_fields(self):
        from io import StringIO
        from django.core.management import call_command
        item = Item.objects.create(
            business=self.biz, store=self.store, description='Configured Spirit',
            material_no='PDUMP-02', unit='btl', selling_price=Decimal('200'),
        )
        ItemPortionPreset.objects.create(
            item=item, label='Robo', price=Decimal('350'),
            quantity_consumed=Decimal('0.25'), cost_price=Decimal('80'),
        )
        out = StringIO()
        call_command('diagnose_stock_shortfalls', business='Preset Dump Biz', item='Configured Spirit', stdout=out)
        output = out.getvalue()
        self.assertIn("'Robo'", output)
        self.assertIn('quantity_consumed=0.2500', output)
        self.assertIn('cost_price=80.00', output)

    def test_duplicate_item_listing_shows_preset_count(self):
        from io import StringIO
        from django.core.management import call_command
        item1 = Item.objects.create(
            business=self.biz, store=self.store, description='Twin Spirit',
            material_no='PDUMP-03', unit='btl', selling_price=Decimal('200'),
        )
        item2 = Item.objects.create(
            business=self.biz, store=self.store, description='Twin Spirit',
            material_no='PDUMP-04', unit='btl', selling_price=Decimal('200'),
        )
        ItemPortionPreset.objects.create(
            item=item2, label='Robo', price=Decimal('350'), quantity_consumed=Decimal('0.25'),
        )
        out = StringIO()
        call_command('diagnose_stock_shortfalls', business='Preset Dump Biz', item='Twin Spirit', stdout=out)
        output = out.getvalue()
        self.assertIn(f'item#{item2.id}', output)
        self.assertIn('presets=1', output)


class RevertVarianceMiscountTest(TestCase):
    """2026-08-28 urgent live request (Roy — Chrome Vodka physically 4.75,
    system 0.75 after a -4 theft-verdict Wastage correction): DIFFERENT
    from the existing accept-reconsideration ('Badilisha kuwa Sahihi',
    which deliberately never touches stock) — this is for when the owner
    determines the ORIGINAL PHYSICAL COUNT was itself wrong, so there was
    never a real deficit at all. Reverses the correction via a compensating
    transaction (never deletes/mutates the original's qty), retags the
    original Wastage '[ADJ-NOLOSS]' so it stops counting as a real P&L
    loss, and tells the staffer plainly it was a counting error, not
    something on their record."""

    def setUp(self):
        from core.models import StockVarianceQuery, StockTake
        self.StockVarianceQuery = StockVarianceQuery
        self.biz = Business.objects.create(name='Revert Miscount Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='revmis_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.staff_user = User.objects.create_user(username='revmis_staff', password='x', first_name='Recheal')
        self.staff_profile = UserProfile.objects.create(
            user=self.staff_user, business=self.biz, role='staff', phone='0711222333',
        )
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Chrome Vodka 250 ML',
            material_no='REVMIS-01', unit='btl', selling_price=Decimal('300'),
            cost_price=Decimal('700'),
        )
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Receipt', qty=Decimal('4.75'),
        )
        self.stock_take = StockTake.objects.create(business=self.biz, store=self.store)
        self.svq = self.StockVarianceQuery.objects.create(
            stock_take=self.stock_take, item=self.item, item_name_cache=self.item.description,
            book_balance=Decimal('4.75'), actual_count=Decimal('0.75'),
            direction=self.StockVarianceQuery.DECREASE, queried_staff=self.staff_profile,
        )
        self.client.force_login(self.owner)
        # Dismiss it first — the real starting state (a DISPUTED theft
        # verdict with a -4 corrective Wastage transaction), matching
        # Roy's actual screenshot.
        resp = self.client.post(f'/stock/variances/{self.svq.id}/review/', {'action': 'dismiss'})
        self.assertTrue(resp.json()['ok'])
        self.svq.refresh_from_db()
        self.assertEqual(self.item.current_balance(), Decimal('0.75'))

    def _revert(self, note=''):
        return self.client.post(f'/stock/variances/{self.svq.id}/review/', {
            'action': 'revert_miscount', 'owner_response_note': note,
        })

    def test_revert_restores_the_physical_balance(self):
        resp = self._revert('Recheal alihesabu vibaya')
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertEqual(self.item.current_balance(), Decimal('4.75'))

    def test_revert_creates_a_compensating_transaction_never_mutates_original_qty(self):
        orig_txn = self.svq.corrective_txn
        orig_qty = orig_txn.qty
        self._revert()
        orig_txn.refresh_from_db()
        self.assertEqual(orig_txn.qty, orig_qty)  # never mutated
        reversal = Transaction.objects.filter(item=self.item, invoice_no='[SVQ-REVERT]').first()
        self.assertIsNotNone(reversal)
        self.assertEqual(reversal.type, 'Receipt')
        self.assertEqual(reversal.qty, Decimal('4'))

    def test_revert_retags_original_as_adj_noloss_excluding_it_from_pl(self):
        # loss_value() itself always computes the raw figure regardless of
        # tag — the exclusion happens at the AGGREGATE query level (every
        # P&L/Haki wastage consumer already does .exclude(invoice_no=
        # '[ADJ-NOLOSS]')), exactly mirroring the established Rekebisha
        # "sio hasara halisi" convention this reuses.
        orig_txn = self.svq.corrective_txn
        self.assertEqual(orig_txn.invoice_no, '[THEFT]')
        self._revert()
        orig_txn.refresh_from_db()
        self.assertEqual(orig_txn.invoice_no, '[ADJ-NOLOSS]')
        still_counted = Transaction.objects.filter(
            business=self.biz, type='Wastage',
        ).exclude(invoice_no='[ADJ-NOLOSS]')
        self.assertNotIn(orig_txn, list(still_counted))

    def test_revert_sets_accepted_no_compliance_note_resolved(self):
        self._revert()
        self.svq.refresh_from_db()
        self.assertTrue(self.svq.owner_accepted)
        self.assertFalse(self.svq.compliance_noted)
        self.assertEqual(self.svq.status, self.StockVarianceQuery.RESOLVED)
        self.assertIsNone(self.svq.dispute_deadline)

    def test_revert_never_counts_toward_staff_variance_loss(self):
        self._revert()
        from core.haki_views import _staff_contribution
        today = timezone.localdate()
        contrib = _staff_contribution(
            self.staff_profile, self.biz, today - timedelta(days=1), today + timedelta(days=1),
        )
        self.assertEqual(contrib['variance_loss_kes'], 0)

    def test_revert_notifies_staff_it_is_not_on_their_record(self):
        self._revert('Recheal alihesabu vibaya')
        notif = Notification.objects.filter(
            user=self.staff_user, title__icontains='Kosa la Kuhesabu',
        ).first()
        self.assertIsNotNone(notif)
        self.assertIn('HAITAHESABIKA', notif.message)

    def test_revert_item_immediately_sellable(self):
        from core.stock_take_views import item_has_pending_variance
        self._revert()
        self.assertFalse(item_has_pending_variance(self.item.id))

    def test_revert_requires_a_correction_to_exist(self):
        fresh_svq = self.StockVarianceQuery.objects.create(
            stock_take=self.stock_take, item=self.item, item_name_cache=self.item.description,
            book_balance=Decimal('10'), actual_count=Decimal('8'),
            direction=self.StockVarianceQuery.DECREASE,
        )
        resp = self.client.post(f'/stock/variances/{fresh_svq.id}/review/', {'action': 'revert_miscount'})
        self.assertFalse(resp.json()['ok'])

    def test_revert_works_after_finalization_too(self):
        # Even once the appeal window has run out and the verdict is
        # RESOLVED (not just DISPUTED), the owner can still discover a
        # miscount and revert it.
        self.client.post(f'/stock/variances/{self.svq.id}/review/', {'action': 'finalize_now'})
        self.svq.refresh_from_db()
        self.assertEqual(self.svq.status, self.StockVarianceQuery.RESOLVED)
        resp = self._revert()
        self.assertTrue(resp.json()['ok'], resp.json())
        self.assertEqual(self.item.current_balance(), Decimal('4.75'))

    def test_revert_blank_note_uses_default_wording(self):
        resp = self._revert('')
        self.assertTrue(resp.json()['ok'], resp.json())
        reversal = Transaction.objects.filter(item=self.item, invoice_no='[SVQ-REVERT]').first()
        self.assertIn('kosa la kuhesabu', reversal.recipient.lower())

    def test_staff_cannot_revert_miscount(self):
        self.client.force_login(self.staff_user)
        resp = self._revert()
        self.assertEqual(resp.status_code, 302)
        self.assertEqual(self.item.current_balance(), Decimal('0.75'))


class BackfillVoidSplitSiblingsTest(TestCase):
    """core/management/commands/backfill_void_split_siblings.py — the
    2026-08-26 companion to void_direct_transaction()'s split-group
    cascade fix (Roy: "audit if futa from recent sales adjusts stock
    balance ... assist in the backfill"). Repairs any historical case
    where a direct-sale split (✂️ Gawanya/🤝 Deni) ROOT was voided alone,
    pre-fix, leaving a still-live sibling's revenue standing for an item
    the stock ledger now says never left the shelf.

    Builds the pre-fix broken state directly via the ORM (never through
    the endpoint, which — post-fix — can no longer produce it), matching
    this app's own established pattern for a backfill whose bug the live
    code path no longer reproduces."""

    def setUp(self):
        self.biz = Business.objects.create(name='Backfill Void Biz')
        self.store = Store.objects.create(business=self.biz, name='Bar')
        self.owner = User.objects.create_user(username='bvs_owner', password='x')
        UserProfile.objects.create(user=self.owner, business=self.biz, role='owner')
        self.item = Item.objects.create(
            business=self.biz, store=self.store, description='Tusker',
            material_no='BVS-01', unit='Pcs', selling_price=Decimal('200'),
            cost_price=Decimal('150'), opening_bin_balance=Decimal('20'),
        )

    def _broken_group(self, item=None, total=Decimal('500'), split=Decimal('300')):
        """Build the exact pre-fix broken shape: a split root that's
        already void (as the OLD void_direct_transaction would have left
        it) while its sibling is still fully live."""
        item = item or self.item
        root = Transaction.objects.create(
            business=self.biz, item=item, type='Issue',
            qty=Decimal('-1'), sale_amount=total, payment_method='cash',
        )
        from core.models import Transaction as _Txn
        _orig, sibling = _Txn.split_payment_method_locked(
            txn_id=root.id, business=self.biz, split_amount=split, new_method='mpesa',
        )
        root.refresh_from_db()
        root.payment_method = 'void'
        root.qty = Decimal('0')
        root.save(update_fields=['payment_method', 'qty'])
        return root, sibling

    def test_dry_run_reports_but_saves_nothing(self):
        from django.core.management import call_command
        from io import StringIO
        root, sibling = self._broken_group()
        out = StringIO()
        call_command('backfill_void_split_siblings', dry_run=True, stdout=out)
        sibling.refresh_from_db()
        self.assertEqual(sibling.payment_method, 'mpesa', 'dry-run must write nothing')
        self.assertIn('would void', out.getvalue())

    def test_voids_the_live_sibling_and_reverses_its_own_share(self):
        from django.core.management import call_command
        from io import StringIO
        root, sibling = self._broken_group()
        call_command('backfill_void_split_siblings', stdout=StringIO())
        sibling.refresh_from_db()
        self.assertEqual(sibling.payment_method, 'void')
        self.assertEqual(sibling.qty, Decimal('0'), 'a split sibling never carried real qty to begin with')
        self.assertIn('[FUTWA:', sibling.recipient)

    def test_never_touches_stock_further_root_already_restored_it(self):
        """The root's own void already restored the whole physical unit
        (pre-fix) — the backfill must never restore it a second time; a
        sibling always carried qty=0, so voiding it moves nothing more."""
        from django.core.management import call_command
        from io import StringIO
        self.assertEqual(self.item.current_balance(), Decimal('20'))
        root, sibling = self._broken_group()
        self.assertEqual(self.item.current_balance(), Decimal('20'), 'root void already restored it (pre-fix behaviour)')
        call_command('backfill_void_split_siblings', stdout=StringIO())
        self.assertEqual(self.item.current_balance(), Decimal('20'), 'backfill must not move stock a second time')

    def test_credit_sibling_never_auto_voided_only_flagged(self):
        from django.core.management import call_command
        from io import StringIO
        root = Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('500'), payment_method='cash',
        )
        from core.models import Transaction as _Txn
        _orig, credit_sibling = _Txn.split_payment_method_locked(
            txn_id=root.id, business=self.biz, split_amount=Decimal('300'),
            new_method='credit', recipient='Bosco',
        )
        root.refresh_from_db()
        root.payment_method = 'void'
        root.qty = Decimal('0')
        root.save(update_fields=['payment_method', 'qty'])

        out = StringIO()
        call_command('backfill_void_split_siblings', stdout=out)
        credit_sibling.refresh_from_db()
        self.assertEqual(credit_sibling.payment_method, 'credit', 'a credit fragment must never be auto-voided')
        self.assertIn('NOT auto-voided', out.getvalue())

    def test_business_scoping_never_leaks_across_businesses(self):
        from django.core.management import call_command
        from io import StringIO
        other_biz = Business.objects.create(name='Other Backfill Void Biz')
        other_store = Store.objects.create(business=other_biz, name='Bar')
        other_item = Item.objects.create(
            business=other_biz, store=other_store, description='Foreign',
            material_no='BVS-FOREIGN', unit='Pcs', selling_price=Decimal('200'),
        )
        root_a, sibling_a = self._broken_group()
        root_b = Transaction.objects.create(
            business=other_biz, item=other_item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('400'), payment_method='cash',
        )
        from core.models import Transaction as _Txn
        _orig_b, sibling_b = _Txn.split_payment_method_locked(
            txn_id=root_b.id, business=other_biz, split_amount=Decimal('150'), new_method='mpesa',
        )
        root_b.refresh_from_db()
        root_b.payment_method = 'void'
        root_b.qty = Decimal('0')
        root_b.save(update_fields=['payment_method', 'qty'])

        call_command('backfill_void_split_siblings', business=self.biz.name, stdout=StringIO())
        sibling_a.refresh_from_db()
        sibling_b.refresh_from_db()
        self.assertEqual(sibling_a.payment_method, 'void', 'the named business must be fixed')
        self.assertEqual(sibling_b.payment_method, 'mpesa', 'a different business must be left completely untouched')

    def test_idempotent_second_run_finds_nothing_left(self):
        from django.core.management import call_command
        from io import StringIO
        root, sibling = self._broken_group()
        call_command('backfill_void_split_siblings', stdout=StringIO())
        out = StringIO()
        call_command('backfill_void_split_siblings', stdout=out)
        self.assertIn('Split groups affected: 0', out.getvalue())

    def test_unaffected_business_reports_zero(self):
        from django.core.management import call_command
        from io import StringIO
        # A completely ordinary, never-split, never-voided sale.
        Transaction.objects.create(
            business=self.biz, item=self.item, type='Issue',
            qty=Decimal('-1'), sale_amount=Decimal('200'), payment_method='cash',
        )
        out = StringIO()
        call_command('backfill_void_split_siblings', stdout=out)
        self.assertIn('Split groups affected: 0', out.getvalue())
